A.j2i=s(["\ubbfc\uc218 \uc528\ub294 \uc544\uc9c1 \uc791\uc5c5 \uc21c\uc11c\ub97c \ubaa8\ub985\ub2c8\ub2e4.","\ubbfc\uc218 \uc528\ub294 \uacbd\ud5d8\uc744 \uc313\uc73c\uba74\uc11c \uc2e4\uc218\uac00 \uc904\uc5c8\uc2b5\ub2c8\ub2e4.","\ubbfc\uc218 \uc528\ub294 \ud68c\uc0ac\ub97c \uadf8\ub9cc\ub480\uc2b5\ub2c8\ub2e4.","\ubbfc\uc218 \uc528\ub294 \uc77c\uc744 \ucc98\uc74c \uc2dc\uc791\ud588\uc2b5\ub2c8\ub2e4."],t.s)
A.bBp=new B.af("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\ubbfc\uc218 \uc528\ub294 \ucc98\uc74c \ud68c\uc0ac\uc5d0 \ub4e4\uc5b4\uac14\uc744 \ub54c \uc791\uc5c5 \uacbd\ud5d8\uc774 \ubd80\uc871\ud574\uc11c \uc2e4\uc218\ub97c \ub9ce\uc774 \ud588\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uac19\uc740 \uc77c\uc744 \uacc4\uc18d \ud558\ub2e4 \ubcf4\ub2c8 \uc791\uc5c5 \uc21c\uc11c\ub97c \uc798 \uc774\ud574\ud558\uac8c \ub418\uc5c8\uace0 \uc2e4\uc218\ub3c4 \ub9ce\uc774 \uc904\uc5c8\uc2b5\ub2c8\ub2e4. \uc9c0\uae08\uc740 \uc0c8\ub85c \ub4e4\uc5b4\uc628 \uc9c1\uc6d0\uc5d0\uac8c \uc791\uc5c5 \ubc29\ubc95\uc744 \uc124\uba85\ud574 \uc8fc\uace0 \uc788\uc2b5\ub2c8\ub2e4.",A.j2i,1,"\u0110o\u1ea1n v\u0103n n\xf3i khi t\xedch l\u0169y kinh nghi\u1ec7m th\xec l\u1ed7i \u0111\xe3 gi\u1ea3m.","\uc77d\uae30")
A.js3=s(["\ub3cc\uc774\ucf1c\ubcf4\ub2e4","\uc785\uae08\ud558\ub2e4","\uacac\uc778\ud558\ub2e4","\uc608\uc57d\ud558\ub2e4"],t.s)
A.bAO=new B.af("\uacfc\uac70\uc758 \uc77c\uc744 \ub2e4\uc2dc \uc0dd\uac01\ud574 \ubcf4\ub294 \uac83\uc744 \uac00\uc7a5 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ud45c\ud604\ud55c \uac83\uc740?",A.js3,0,"\ub3cc\uc774\ucf1c\ubcf4\ub2e4 = nh\xecn l\u1ea1i qu\xe1 kh\u1ee9.","\uc5b4\ud718")
A.iNt=s(["\uc0c1\ud669 \u2192 \ub0b4\uac00 \ud55c \ud589\ub3d9 \u2192 \uacb0\uacfc \u2192 \ubc30\uc6b4 \uc810","\ubc30\uc6b4 \uc810 \u2192 \uc544\ubb34 \uc774\uc720 \uc5c6\ub294 \uacb0\ub860","\uacb0\uacfc\ub9cc \ub9d0\ud55c\ub2e4.","\ub2e4\ub978 \uc0ac\ub78c \uc774\uc57c\uae30\ub9cc \ud55c\ub2e4."],t.s)
A.bDi=new B.af("\uba74\uc811\uc5d0\uc11c \uc790\uc2e0\uc758 \uacbd\ud5d8\uc744 \uc124\uba85\ud558\ub294 \uc21c\uc11c\ub85c \uac00\uc7a5 \uc88b\uc740 \uac83\uc740?",A.iNt,0,"K\u1ec3 tr\u1ea3i nghi\u1ec7m r\xf5 r\xe0ng nh\u1ea5t khi c\xf3 t\xecnh hu\u1ed1ng, h\xe0nh \u0111\u1ed9ng, k\u1ebft qu\u1ea3 v\xe0 b\xe0i h\u1ecdc.","\uc2e4\uc81c \uc0c1\ud669")
A.jc5=s(["\uac19\uc740 \uc2e4\uc218\ub97c \uacc4\uc18d \ubc18\ubcf5\ud55c\ub2e4.","\uacfc\uac70\ub9cc \uc0dd\uac01\ud558\uace0 \uc544\ubb34\uac83\ub3c4 \ud558\uc9c0 \uc54a\ub294\ub2e4.","\uacbd\ud5d8\uc5d0\uc11c \ubc30\uc6b4 \uc810\uc744 \ucc3e\uc544 \ub2e4\uc74c \ud589\ub3d9\uc744 \ubc14\uafbc\ub2e4.","\uc2e4\uc218\ub97c \ubaa8\ub450 \ub2e4\ub978 \uc0ac\ub78c \ud0d3\uc73c\ub85c \ub3cc\ub9b0\ub2e4."],t.s)
A.bE2=new B.af("\ud6c4\ud68c\uc5d0 \ub300\ud55c \ud0dc\ub3c4\ub85c \uac00\uc7a5 \ubc14\ub78c\uc9c1\ud55c \uac83\uc740?",A.jc5,2,"\u0110i\u1ec1u quan tr\u1ecdng l\xe0 bi\u1ebfn tr\u1ea3i nghi\u1ec7m v\xe0 h\u1ed1i ti\u1ebfc th\xe0nh b\xe0i h\u1ecdc cho h\xe0nh \u0111\u1ed9ng sau.","\uc885\ud569")
