A.l6l=s(["\ub2e4\uc2dc \ubb3b\ub2e4","\ud655\uc778\ud558\ub2e4","\uc124\uba85","\ud300\uc7a5\ub2d8","\uc2e4\uc218"],t.s)
A.bH0=new B.db("\uc5c5\ubb34 \uc9c0\uc2dc\ub97c \uc798 \uc774\ud574\ud558\uc9c0 \ubabb\ud558\uba74 \uc5b4\ub5bb\uac8c \ud569\ub2c8\uae4c?","\uc5c5\ubb34 \uc9c0\uc2dc\ub97c \uc798 \uc774\ud574\ud558\uc9c0 \ubabb\ud558\uba74 \ubc14\ub85c \ub2e4\uc2dc \ubb3c\uc5b4\ubd05\ub2c8\ub2e4. \uc81c\uac00 \uc774\ud574\ud55c \ub0b4\uc6a9\uc744 \ub2e4\uc2dc \ub9d0\ud558\uba74\uc11c \ub9de\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4. \uc815\ud655\ud788 \ud655\uc778\ud558\uc9c0 \uc54a\uace0 \uc791\uc5c5\ud558\uba74 \uc2e4\uc218\uac00 \uc0dd\uae38 \uc218 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.")
A.l6Y=s(["\uc9c4\ud589 \uc0c1\ud669","\uc6d0\uc778","\uc644\ub8cc","\uc608\uc0c1","\ubcf4\uace0\ud558\ub2e4"],t.s)
A.bGx=new B.db("\uc791\uc5c5\uc774 \ub2a6\uc5b4\uc9c0\uace0 \uc788\uc744 \ub54c \uc5b4\ub5bb\uac8c \ubcf4\uace0\ud574\uc57c \ud569\ub2c8\uae4c?","\uc791\uc5c5\uc774 \ub2a6\uc5b4\uc9c0\uba74 \uba3c\uc800 \ud604\uc7ac \uc9c4\ud589 \uc0c1\ud669\uc744 \ubcf4\uace0\ud574\uc57c \ud569\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \uc65c \ub2a6\uc5b4\uc9c0\uace0 \uc788\ub294\uc9c0 \uc6d0\uc778\uc744 \uc124\uba85\ud558\uace0 \uc5b8\uc81c\uae4c\uc9c0 \uc644\ub8cc\ud560 \uc218 \uc788\ub294\uc9c0\ub3c4 \ud568\uaed8 \ub9d0\uc500\ub4dc\ub9ac\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.")
A.l4r=s(["\uc815\ud655\ud558\ub2e4","\ud655\uc778\ud558\ub2e4","\ubcf4\uace0\ud558\ub2e4","\ub4e3\ub2e4","\ubc30\ub824\ud558\ub2e4"],t.s)
A.bHn=new B.db("\uc88b\uc740 \uc9c1\uc7a5 \uc758\uc0ac\uc18c\ud1b5\uc744 \uc704\ud574 \ubb34\uc5c7\uc774 \uc911\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\uae4c?","\uc9c1\uc7a5\uc5d0\uc11c\ub294 \uc815\ud655\ud558\uac8c \ub4e3\uace0 \uc804\ub2ec\ud558\ub294 \uac83\uc774 \uac00\uc7a5 \uc911\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ubaa8\ub974\ub294 \uac83\uc774 \uc788\uc73c\uba74 \ub2e4\uc2dc \ud655\uc778\ud558\uace0 \ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \ubc14\ub85c \ubcf4\uace0\ud574\uc57c \ud569\ub2c8\ub2e4. \ub610\ud55c \uc0c1\ub300\ubc29\uc758 \uc758\uacac\uc744 \uc798 \ub4e3\ub294 \uac83\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.iZJ=s([A.bH0,A.bGx,A.bHn],t.Pe)
A.l5l=s(["\uc5b4\ub5a4 \uc0c1\ud669\uc774\uc5c8\ub294\uc9c0 \uc4f0\uc138\uc694.","\uc65c \ubb38\uc81c\uac00 \uc0dd\uacbc\ub294\uc9c0 \uc124\uba85\ud558\uc138\uc694.","\uc5b4\ub5bb\uac8c \ud574\uacb0\ud588\ub294\uc9c0 \uc4f0\uc138\uc694.","-\ub294 \ubc14\ub78c\uc5d0 \ub610\ub294 -\ub2e4\uace0 \ud558\ub2e4\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.bQ5=new B.e6("\uc9c1\uc7a5\uc5d0\uc11c \uc758\uc0ac\uc18c\ud1b5 \ub54c\ubb38\uc5d0 \uc0dd\uae34 \ubb38\uc81c\ub97c \uc368 \ubcf4\uc138\uc694.","\uc804\uc5d0 \ud68c\uc0ac\uc5d0\uc11c \uc791\uc5c5 \uc2dc\uac04\uc774 \ubcc0\uacbd\ub410\ub294\ub370 \uc77c\ubd80 \uc9c1\uc6d0\ub4e4\uc774 \ubcc0\uacbd\ub41c \ub0b4\uc6a9\uc744 \ub4e3\uc9c0 \ubabb\ud55c \uc801\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc804\ub2ec \uacfc\uc815\uc5d0\uc11c \ub0b4\uc6a9\uc774 \ub204\ub77d\ub418\ub294 \ubc14\ub78c\uc5d0 \uba87 \uba85\uc774 \uc6d0\ub798 \uc2dc\uac04\uc5d0 \uc791\uc5c5\uc7a5\uc5d0 \uc654\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \ud300\uc7a5\ub2d8\uaed8 \uc0c1\ud669\uc744 \ubcf4\uace0\ud558\uace0 \ub2e8\uccb4 \ucc44\ud305\ubc29\uc5d0 \ubcc0\uacbd\ub41c \uc2dc\uac04\uc744 \ub2e4\uc2dc \uc804\ub2ec\ud588\uc2b5\ub2c8\ub2e4. \uadf8 \ud6c4\uc5d0\ub294 \uc911\uc694\ud55c \ubcc0\uacbd \uc0ac\ud56d\uc774 \uc788\uc73c\uba74 \ucc44\ud305\ubc29\uacfc \uad6c\ub450\ub85c \ubaa8\ub450 \uc804\ub2ec\ud558\ub3c4\ub85d \ud588\uc2b5\ub2c8\ub2e4.","Tr\u01b0\u1edbc \u0111\xe2y \u1edf c\xf4ng ty c\xf3 l\u1ea7n th\u1eddi gian l\xe0m vi\u1ec7c thay \u0111\u1ed5i nh\u01b0ng m\u1ed9t s\u1ed1 nh\xe2n vi\xean kh\xf4ng nh\u1eadn \u0111\u01b0\u1ee3c n\u1ed9i dung thay \u0111\u1ed5i. V\xec th\xf4ng tin b\u1ecb b\u1ecf s\xf3t trong qu\xe1 tr\xecnh truy\u1ec1n \u0111\u1ea1t n\xean v\xe0i ng\u01b0\u1eddi \u0111\xe3 \u0111\u1ebfn n\u01a1i l\xe0m vi\u1ec7c theo gi\u1edd c\u0169. V\xec v\u1eady t\xf4i b\xe1o c\xe1o t\xecnh h\xecnh v\u1edbi tr\u01b0\u1edfng nh\xf3m v\xe0 g\u1eedi l\u1ea1i th\u1eddi gian thay \u0111\u1ed5i trong ph\xf2ng chat nh\xf3m. Sau \u0111\xf3, n\u1ebfu c\xf3 thay \u0111\u1ed5i quan tr\u1ecdng, ch\xfang t\xf4i truy\u1ec1n \u0111\u1ea1t c\u1ea3 trong ph\xf2ng chat l\u1eabn b\u1eb1ng l\u1eddi n\xf3i.")
A.l8q=s(["\uc9c0\uc2dc\ub97c \ub4e4\uc744 \ub54c \ud574\uc57c \ud560 \uc77c\uc744 \uc4f0\uc138\uc694.","\ubcc0\uacbd \uc0ac\ud56d\uc774 \uc788\uc744 \ub54c \ud574\uc57c \ud560 \uc77c\uc744 \uc4f0\uc138\uc694.","\ubb38\uc81c\uac00 \uc0dd\uacbc\uc744 \ub54c \uc5b4\ub5bb\uac8c \ubcf4\uace0\ud560\uc9c0 \uc4f0\uc138\uc694.","-\ub294\uc9c0 \ud655\uc778\ud558\ub2e4 \ub610\ub294 -\ub3c4\ub85d \ud558\ub2e4\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.bQz=new B.e6("\uc815\ud655\ud55c \uc5c5\ubb34 \uc804\ub2ec\uc744 \uc704\ud574 \ud544\uc694\ud55c \ubc29\ubc95\uc744 \uc368 \ubcf4\uc138\uc694.","\uc5c5\ubb34\ub97c \uc815\ud655\ud558\uac8c \uc804\ub2ec\ud558\ub824\uba74 \uba3c\uc800 \uc0c1\ub300\ubc29\uc758 \ub9d0\uc744 \ub05d\uae4c\uc9c0 \uc798 \ub4e4\uc5b4\uc57c \ud569\ub2c8\ub2e4. \uc774\ud574\ud558\uc9c0 \ubabb\ud55c \ubd80\ubd84\uc774 \uc788\uc73c\uba74 \ubc14\ub85c \ub2e4\uc2dc \ubb3c\uc5b4\ubcf4\uace0 \uc81c\uac00 \uc774\ud574\ud55c \ub0b4\uc6a9\uc774 \ub9de\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \uc77c\uc815\uc774\ub098 \uc791\uc5c5 \ubc29\ubc95\uc774 \ubcc0\uacbd\ub418\uba74 \uad00\ub828\ub41c \ubaa8\ub4e0 \uc0ac\ub78c\uc5d0\uac8c \ub0b4\uc6a9\uc744 \uc804\ub2ec\ud574\uc57c \ud569\ub2c8\ub2e4. \ub610\ud55c \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud588\uc744 \ub54c\ub294 \ud63c\uc790 \ud574\uacb0\ud558\ub824\uace0 \ud558\uae30\ubcf4\ub2e4 \ud300\uc7a5\ub2d8\uaed8 \ubc14\ub85c \ubcf4\uace0\ud558\ub3c4\ub85d \ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\u0110\u1ec3 truy\u1ec1n \u0111\u1ea1t c\xf4ng vi\u1ec7c ch\xednh x\xe1c, tr\u01b0\u1edbc ti\xean c\u1ea7n nghe h\u1ebft l\u1eddi c\u1ee7a \u0111\u1ed1i ph\u01b0\u01a1ng. N\u1ebfu c\xf3 ph\u1ea7n ch\u01b0a hi\u1ec3u th\xec ph\u1ea3i h\u1ecfi l\u1ea1i ngay v\xe0 x\xe1c nh\u1eadn xem n\u1ed9i dung m\xecnh hi\u1ec3u c\xf3 \u0111\xfang kh\xf4ng. N\u1ebfu l\u1ecbch ho\u1eb7c ph\u01b0\u01a1ng ph\xe1p l\xe0m vi\u1ec7c thay \u0111\u1ed5i th\xec c\u1ea7n truy\u1ec1n \u0111\u1ea1t n\u1ed9i dung cho t\u1ea5t c\u1ea3 ng\u01b0\u1eddi li\xean quan. Ngo\xe0i ra khi x\u1ea3y ra v\u1ea5n \u0111\u1ec1, thay v\xec c\u1ed1 t\u1ef1 gi\u1ea3i quy\u1ebft m\u1ed9t m\xecnh th\xec vi\u1ec7c b\xe1o c\xe1o ngay v\u1edbi tr\u01b0\u1edfng nh\xf3m l\xe0 quan tr\u1ecdng.")
A.jaf=s([A.bQ5,A.bQz],t.vH)
A.iHk=s(["\uc5c5\ubb34 \uc9c0\uc2dc","\uc9c0\uc2dc\ub97c \ubc1b\ub2e4","\uc804\ub2ec\ud558\ub2e4","\uc804\ub2ec \uc0ac\ud56d","\ubcf4\uace0\ud558\ub2e4","\uc9c4\ud589 \uc0c1\ud669","\ubcf4\uace0\uc11c","\ud655\uc778\ud558\ub2e4","\uc7ac\ud655\uc778\ud558\ub2e4","\uc124\uba85\ud558\ub2e4","\ub2e4\uc2dc \ubb3b\ub2e4","\uc798\ubabb \uc774\ud574\ud558\ub2e4","\uc694\uccad\ud558\ub2e4","\ubd80\ud0c1\ud558\ub2e4","\ud611\uc870\ud558\ub2e4","\uc758\uacac","\uc81c\uc548\ud558\ub2e4","\ub3d9\uc758\ud558\ub2e4","\ubc18\ub300\ud558\ub2e4","\uc77c\uc815 \ubcc0\uacbd","\ucc29\uc624","\ub204\ub77d\ub418\ub2e4"],t.s)
