A.bEb=new B.af("\ud314\ub358 \uc0c1\ud488\uc774 \ubaa8\ub450 \uc5c6\uc5b4\uc838\uc11c \ub354 \uc774\uc0c1 \uc0b4 \uc218 \uc5c6\ub294 \uc0c1\ud0dc\ub294?",A.i9j,0,"\ud488\uc808 = h\u1ebft h\xe0ng.","\uc5b4\ud718")
A.ihn=s(["\uaddc\uc815\uc744 \ud655\uc778\ud558\uc9c0 \uc54a\ub294\ub2e4.","\uad6c\ub9e4 \uc804\uc5d0 \uad50\ud658\xb7\ud658\ubd88 \uc870\uac74\uc744 \ud655\uc778\ud55c\ub2e4.","\uc601\uc218\uc99d\uc744 \ubc14\ub85c \ubc84\ub9b0\ub2e4.","\uc0c1\ud488 \uc0c1\ud0dc\ub97c \ud655\uc778\ud558\uc9c0 \uc54a\ub294\ub2e4."],t.s)
A.bDY=new B.af("\ud560\uc778 \uc0c1\ud488\uc744 \uad6c\ub9e4\ud558\ub824\uace0 \ud569\ub2c8\ub2e4. \ub098\uc911\uc5d0 \uad50\ud658\ud560 \uac00\ub2a5\uc131\uc774 \uc788\ub2e4\uba74 \uac00\uc7a5 \uc88b\uc740 \ud589\ub3d9\uc740?",A.ihn,1,"N\xean ki\u1ec3m tra \u0111i\u1ec1u ki\u1ec7n \u0111\u1ed5i/tr\u1ea3 tr\u01b0\u1edbc khi mua.","\uc2e4\uc81c \uc0c1\ud669")
A.hat=s(["\ubb38\uc81c \ud655\uc778 \u2192 \uc8fc\ubb38 \ub0b4\uc5ed \ud655\uc778 \u2192 \uc99d\uac70 \ubcf4\uad00 \u2192 \ud310\ub9e4\uc790/\uace0\uac1d\uc13c\ud130 \ubb38\uc758","\uc0c1\ud488 \ubc84\ub9ac\uae30 \u2192 \uc8fc\ubb38 \ubc88\ud638 \uc0ad\uc81c\ud558\uae30","\uc544\ubb34 \ud655\uc778 \uc5c6\uc774 \ud658\ubd88\ub9cc \uc694\uad6c\ud558\uae30","\ubb38\uc81c\ub97c \uc228\uae30\uace0 \uacc4\uc18d \uc0ac\uc6a9\ud558\uae30"],t.s)
A.bBx=new B.af("\uc628\ub77c\uc778 \uc1fc\ud551 \ud6c4 \ubb38\uc81c\uac00 \uc0dd\uacbc\uc744 \ub54c \uac00\uc7a5 \uc88b\uc740 \ucc98\ub9ac \uc21c\uc11c\ub294?",A.hat,0,"X\xe1c nh\u1eadn v\u1ea5n \u0111\u1ec1, ki\u1ec3m tra \u0111\u01a1n, l\u01b0u b\u1eb1ng ch\u1ee9ng r\u1ed3i li\xean h\u1ec7 l\xe0 c\xe1ch x\u1eed l\xfd r\xf5 r\xe0ng.","\uc885\ud569")
