A.bGL=new B.db("\ud300\uc7a5\ub2d8\uc5d0\uac8c \uc624\ub298 \uc791\uc5c5 \uc9c4\ud589 \uc0c1\ud669\uc744 \ubcf4\uace0\ud574 \ubcf4\uc138\uc694.","\uc624\ub298 \uc791\uc5c5 \uc218\ub7c9\uc740 \ucd1d 300\uac1c\uc785\ub2c8\ub2e4. \ud604\uc7ac 220\uac1c\uae4c\uc9c0 \uc644\ub8cc\ud588\uace0 \ub098\uba38\uc9c0 80\uac1c\ub294 \uc9c4\ud589 \uc911\uc785\ub2c8\ub2e4. \ud2b9\ubcc4\ud55c \ubb38\uc81c\uac00 \uc5c6\uc73c\uba74 \uc624\ud6c4 4\uc2dc 30\ubd84\uae4c\uc9c0 \ubaa8\ub450 \uc644\ub8cc\ud560 \uc608\uc815\uc785\ub2c8\ub2e4. \uc791\uc5c5\uc774 \ub05d\ub098\ub294 \ub300\ub85c \ub2e4\uc2dc \ubcf4\uace0\ud558\uaca0\uc2b5\ub2c8\ub2e4.")
A.l5U=s(["\ubd88\ub7c9","\uc218\ub7c9","\uc791\uc5c5 \uc911\uc9c0","\uc6d0\uc778","\uc870\uce58"],t.s)
A.bGN=new B.db("\uc81c\ud488\uc5d0\uc11c \ubd88\ub7c9\uc774 \ubc1c\uacac\ub410\uc744 \ub54c \uc5b4\ub5bb\uac8c \ubcf4\uace0\ud558\uaca0\uc2b5\ub2c8\uae4c?","A\uc81c\ud488\uc744 \uac80\uc0ac\ud558\ub294 \uc911\uc5d0 \ubd88\ub7c9\uc774 3\uac1c \ubc1c\uacac\ub410\uc2b5\ub2c8\ub2e4. \uce58\uc218\uac00 \uae30\uc900\ubcf4\ub2e4 \ud06c\uac8c \ub098\uc640\uc11c \ud604\uc7ac \uc791\uc5c5\uc744 \uc911\uc9c0\ud588\uc2b5\ub2c8\ub2e4. \ubd88\ub7c9\ud488\uc740 \ub530\ub85c \ubd84\ub9ac\ud574 \ub193\uc558\uace0 \uc9c0\uae08 \uc6d0\uc778\uc744 \ud655\uc778\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc6d0\uc778\uc774 \ud655\uc778\ub418\ub294 \ub300\ub85c \ub2e4\uc2dc \ubcf4\uace0\ud558\uaca0\uc2b5\ub2c8\ub2e4.")
A.l7W=s(["\uc608\uc0c1\ubcf4\ub2e4","\uc9c0\uc5f0","\uc6d0\uc778","\uc2dc\uac04","\uc644\ub8cc"],t.s)
A.bH5=new B.db("\uc791\uc5c5\uc774 \ub2a6\uc5b4\uc9c8 \ub54c \uc0c1\uc0ac\uc5d0\uac8c \uc5b4\ub5bb\uac8c \ub9d0\ud558\uaca0\uc2b5\ub2c8\uae4c?","\uc8c4\uc1a1\ud558\uc9c0\ub9cc \uc608\uc0c1\ubcf4\ub2e4 \uc791\uc5c5\uc774 \uc870\uae08 \uc9c0\uc5f0\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uae30\uacc4 \uc810\uac80\uc5d0 \uc2dc\uac04\uc774 \uac78\ub824\uc11c \ud604\uc7ac \uc57d 30\ubd84 \uc815\ub3c4 \ub2a6\uc5b4\uc84c\uc2b5\ub2c8\ub2e4. \uc624\ud6c4 5\uc2dc\uae4c\uc9c0\ub294 \uc644\ub8cc\ud560 \uc218 \uc788\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4.")
