A.jdO=s(["\uae30\uacc4\uc5d0\uc11c \ud3c9\uc18c\uc640 \ub2e4\ub978 \uc18c\ub9ac\uac00 \ub098\uc11c \ud604\uc7ac \uc0c1\ud0dc\ub97c \ud655\uc778\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.","\uae30\uacc4\uac00 \uc2eb\uc5b4\uc694.","\ub098\uc911\uc5d0 \uadf8\ub0e5 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4.","\uc544\ub9c8 \uad1c\ucc2e\uc744 \uac81\ub2c8\ub2e4. \uacc4\uc18d \ud558\uaca0\uc2b5\ub2c8\ub2e4."],t.s)
A.bCt=new B.af("\uae30\uacc4\uc5d0\uc11c \ud3c9\uc18c\uc640 \ub2e4\ub978 \uc18c\ub9ac\uac00 \ub098\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uac00\uc7a5 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \ubcf4\uace0\ub294?",A.jdO,0,"N\xean m\xf4 t\u1ea3 ch\xednh x\xe1c hi\u1ec7n t\u01b0\u1ee3ng v\xe0 tr\u1ea1ng th\xe1i x\u1eed l\xfd hi\u1ec7n t\u1ea1i.","\uc2e4\uc81c \uc0c1\ud669")
A.hpZ=s(["\ubd88\ub7c9\ud488\uc744 \uc228\uae34\ub2e4.","\uc0dd\uc0b0\ub7c9\ub9cc \ub298\ub9b0\ub2e4.","\uadfc\ubcf8 \uc6d0\uc778\uc744 \ubd84\uc11d\ud558\uace0 \uc7ac\ubc1c \ubc29\uc9c0 \ub300\ucc45\uc744 \uc138\uc6b4\ub2e4.","\uc544\ubb34 \uc870\uce58 \uc5c6\uc774 \uae30\ub2e4\ub9b0\ub2e4."],t.s)
A.bD8=new B.af("\uac19\uc740 \ubd88\ub7c9\uc774 \ubc18\ubcf5\ub420 \ub54c \ud544\uc694\ud55c \uac83\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740?",A.hpZ,2,"Khi l\u1ed7i l\u1eb7p l\u1ea1i c\u1ea7n ph\xe2n t\xedch nguy\xean nh\xe2n t\u1eadn g\u1ed1c v\xe0 l\u1eadp bi\u1ec7n ph\xe1p ph\xf2ng ng\u1eeba.","\uc885\ud569")
