A.hZV=s(["\uac80\uc0ac\ud300 \uc778\uc6d0\uc740 \uc6d0\ub798 \ub450 \uba85\uc774\uc5c8\uc2b5\ub2c8\ub2e4.","\ucd9c\ud558 \uc77c\uc815\uc740 \uc774\ubbf8 \ucde8\uc18c\ub410\uc2b5\ub2c8\ub2e4.","\ub2f4\ub2f9\uc790\ub294 \ubb38\uc81c\ub97c \ubbf8\ub9ac \ubcf4\uace0\ud558\uace0 \uc9c0\uc6d0\uc744 \uc694\uccad\ud588\uc2b5\ub2c8\ub2e4.","\uac80\uc0ac \uc5c5\ubb34\ub294 \ubaa8\ub450 \ub05d\ub0ac\uc2b5\ub2c8\ub2e4."],t.s)
A.cCM=new B.ag("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\uc624\ub298 \uc624\uc804\uc5d0 \uac80\uc0ac \ubb3c\ub7c9\uc774 \uc608\uc0c1\ubcf4\ub2e4 \ub9ce\uc774 \ub298\uc5c8\uc2b5\ub2c8\ub2e4. \uac80\uc0ac\ud300\uc740 \uc6d0\ub798 \uc138 \uba85\uc774 \uadfc\ubb34\ud560 \uc608\uc815\uc774\uc5c8\uc9c0\ub9cc \ud55c \uba85\uc774 \uacb0\uadfc\ud588\uc2b5\ub2c8\ub2e4. \ud604\uc7ac \uc18d\ub3c4\ub85c \uc791\uc5c5\ud560 \uacbd\uc6b0 \uc624\ud6c4 \ucd9c\ud558 \uc77c\uc815\uc774 \ub2a6\uc5b4\uc9c8 \uac00\ub2a5\uc131\uc774 \uc788\uc2b5\ub2c8\ub2e4. \ub2f4\ub2f9\uc790\ub294 \uc624\uc804 10\uc2dc\uc5d0 \ud300\uc7a5\uc5d0\uac8c \uc0c1\ud669\uc744 \ubcf4\uace0\ud588\uace0 \uc0dd\uc0b0\ud300\uc5d0\uc11c \ud55c \uba85\uc744 \uc9c0\uc6d0\ubc1b\uae30\ub85c \ud588\uc2b5\ub2c8\ub2e4.",A.hZV,2,"Ng\u01b0\u1eddi ph\u1ee5 tr\xe1ch \u0111\xe3 b\xe1o s\u1edbm t\xecnh h\xecnh v\xe0 nh\u1eadn h\u1ed7 tr\u1ee3 t\u1eeb \u0111\u1ed9i s\u1ea3n xu\u1ea5t.","\uc77d\uae30")
A.irb=s(["\uadf8\ub0e5 \ud558\uace0 \uc788\uc5b4\uc694.","\ud604\uc7ac \uc57d 70\ud37c\uc13c\ud2b8 \uc644\ub8cc\ud588\uace0 \uc624\ud6c4 \uc138 \uc2dc\ucbe4 \ub9c8\uce60 \uc608\uc815\uc785\ub2c8\ub2e4.","\ubab0\ub77c\uc694.","\ub2e4\ub978 \uc0ac\ub78c\uc774 \ud560 \uac70\uc608\uc694."],t.s)
A.cCd=new B.ag("\ud300\uc7a5\uc774 \u201c\uc9c4\ud589 \uc0c1\ud669\uc774 \uc5b4\ub5bb\uac8c \ub410\uc5b4\uc694?\u201d\ub77c\uace0 \ubb3c\uc5c8\uc2b5\ub2c8\ub2e4. \uac00\uc7a5 \uc88b\uc740 \ub300\ub2f5\uc740?",A.irb,1,"B\xe1o ti\u1ebfn \u0111\u1ed9 t\u1ed1t n\xean c\xf3 m\u1ee9c ho\xe0n th\xe0nh v\xe0 th\u1eddi gian d\u1ef1 ki\u1ebfn.","\uc2e4\uc81c \uc0c1\ud669")
A.hDT=s(["\ub2f4\ub2f9\uc790\ub97c \uba85\ud655\ud558\uac8c \uc815\ud55c\ub2e4.","\uc9c4\ud589 \uc0c1\ud669\uc744 \uacf5\uc720\ud55c\ub2e4.","\ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \uad00\ub828\uc790\uc640 \ud611\uc758\ud55c\ub2e4.","\ubb38\uc81c\uac00 \uc0dd\uaca8\ub3c4 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc601\ud5a5\uc744 \uc904 \ub54c\uae4c\uc9c0 \uc54c\ub9ac\uc9c0 \uc54a\ub294\ub2e4."],t.s)
A.cDY=new B.ag("\ud6a8\uc728\uc801\uc778 \ud611\uc5c5 \ubc29\ubc95\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud558\uc9c0 \uc54a\uc740 \uac83\uc740?",A.hDT,3,"Che gi\u1ea5u th\xf4ng tin \u0111\u1ebfn khi \u1ea3nh h\u01b0\u1edfng ng\u01b0\u1eddi kh\xe1c s\u1ebd l\xe0m ph\u1ed1i h\u1ee3p k\xe9m h\u01a1n.","\uc885\ud569")
A.j_7=s([A.cF4,A.cB9,A.cAP,A.cBj,A.cDh,A.cDV,A.cCT,A.cAs,A.cDH,A.cCu,A.cBO,A.cAJ,A.cCM,A.cCd,A.cDY],t.VX)
A.l6k=s(["\uc5c5\ubb34\ub7c9","\ub2f4\ub2f9","\uac80\uc0ac","\uc0dd\uc0b0","\uae30\ub85d","\ub9c8\uac10"],t.s)
A.cGF=new B.cu("\ud300\uc6d0\ub4e4\uacfc \uc5c5\ubb34\ub97c \ub098\ub204\ub294 \uc0c1\ud669\uc744 \ub9d0\ud574 \ubcf4\uc138\uc694.","\uc624\ub298\uc740 \uc791\uc5c5\ub7c9\uc774 \ub9ce\uae30 \ub54c\ubb38\uc5d0 \uba3c\uc800 \uc5ed\ud560\uc744 \ub098\ub204\ub294 \uac83\uc774 \uc88b\uaca0\uc2b5\ub2c8\ub2e4. \uc800\ub294 \uc0dd\uc0b0 \uae30\ub85d\uacfc \ucd5c\uc885 \uacb0\uacfc\ub97c \uc815\ub9ac\ud558\uaca0\uc2b5\ub2c8\ub2e4. \ubbfc\uc218 \uc528\ub294 1\ud638 \ub77c\uc778\uc758 \uc791\uc5c5 \uc0c1\ud0dc\ub97c \ud655\uc778\ud574 \uc8fc\uc138\uc694. \uc9c0\ud604 \uc528\ub294 \uac80\uc0ac \uc5c5\ubb34\ub97c \ub2f4\ub2f9\ud574 \uc8fc\uc2dc\uba74 \uc88b\uaca0\uc2b5\ub2c8\ub2e4. \uc624\ud6c4 \ub450 \uc2dc\uc5d0 \ud55c\ubc88 \uc9c4\ud589 \uc0c1\ud669\uc744 \uacf5\uc720\ud558\uace0 \uc77c\uc815\uc774 \ub2a6\uc5b4\uc9c8 \uac00\ub2a5\uc131\uc774 \uc788\uc73c\uba74 \uadf8\ub54c \uc5c5\ubb34\ub97c \ub2e4\uc2dc \uc870\uc815\ud558\uaca0\uc2b5\ub2c8\ub2e4.")
A.l5S=s(["\ud604\uc7ac \uc0c1\ud669","\uc5c5\ubb34\ub7c9","\uc9c4\ucc99\ub3c4","\ub9c8\uac10","\uc9c0\uc6d0 \uc694\uccad"],t.s)
A.cH6=new B.cu("\uc5c5\ubb34\uac00 \ub108\ubb34 \ub9ce\uc544\uc11c \uc9c0\uc6d0\uc774 \ud544\uc694\ud55c \uc0c1\ud669\uc744 \uc124\uba85\ud574 \ubcf4\uc138\uc694.","\ud604\uc7ac \uac80\uc0ac\ud574\uc57c \ud560 \uc81c\ud488\uc774 \uc608\uc0c1\ubcf4\ub2e4 \ub9ce\uc774 \uc313\uc5ec \uc788\uc2b5\ub2c8\ub2e4. \uc6d0\ub798 \uc138 \uba85\uc774 \uc791\uc5c5\ud560 \uc608\uc815\uc774\uc5c8\ub294\ub370 \ud55c \uba85\uc774 \uacb0\uadfc\ud55c \ub370\ub2e4\uac00 \uae34\uae09 \uac80\uc0ac \ubb3c\ub7c9\ub3c4 \ucd94\uac00\ub410\uc2b5\ub2c8\ub2e4. \ud604\uc7ac \uc9c4\ucc99\ub3c4\ub294 \uc57d 50\ud37c\uc13c\ud2b8\uc774\uace0 \uc774\ub300\ub85c \uc9c4\ud589\ud558\uba74 \uc624\ud6c4 \ucd9c\ud558 \uc77c\uc815\uc774 \ub2a6\uc5b4\uc9c8 \uac00\ub2a5\uc131\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uac00\ub2a5\ud558\ub2e4\uba74 \ud55c \uba85 \uc815\ub3c4\ub97c \ub450 \uc2dc\uac04 \ub3d9\uc548 \uc9c0\uc6d0\ubc1b\uc744 \uc218 \uc788\uc744\uc9c0 \uc694\uccad\ub4dc\ub9ac\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.")
A.l5Y=s(["\uc644\ub8cc \uc5c5\ubb34","\ubbf8\uc644\ub8cc \uc5c5\ubb34","\uc124\ube44","\uc774\uc0c1","\ucd94\uac00 \ud655\uc778","\ub2f4\ub2f9\uc790"],t.s)
A.cGi=new B.cu("\uad50\ub300 \uadfc\ubb34\uc790\uc5d0\uac8c \uc778\uc218\uc778\uacc4\ub97c \ud574 \ubcf4\uc138\uc694.","\ud604\uc7ac \uc0dd\uc0b0 \uacc4\ud68d\uc758 \uc57d 80\ud37c\uc13c\ud2b8\uae4c\uc9c0 \uc644\ub8cc\ud588\uc2b5\ub2c8\ub2e4. 1\ud638 \uc124\ube44\ub294 \uc815\uc0c1\uc801\uc73c\ub85c \uac00\ub3d9 \uc911\uc785\ub2c8\ub2e4. 2\ud638 \uc124\ube44\ub294 \uc624\ud6c4\uc5d0 \uc774\uc0c1 \uc18c\uc74c\uc774 \ubc1c\uc0dd\ud574\uc11c \ud604\uc7ac \uc815\uc9c0 \uc0c1\ud0dc\uc774\uba70 \uc720\uc9c0\ubcf4\uc218\ud300\uc5d0 \uc774\ubbf8 \uc804\ub2ec\ud588\uc2b5\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \uc624\ub298 \uc0dd\uc0b0\ud55c \uc81c\ud488 \uc911 \ub2e4\uc12f \uac1c\ub294 \ucd94\uac00 \uce58\uc218 \uac80\uc0ac\uac00 \ud544\uc694\ud569\ub2c8\ub2e4. \ud574\ub2f9 \uc81c\ud488\uc740 \ub530\ub85c \ud45c\uc2dc\ud574 \ub450\uc5c8\uc73c\ub2c8 \uc57c\uac04\uc870\uc5d0\uc11c \ud655\uc778\ud574 \uc8fc\uc138\uc694. \uc810\uac80 \uacb0\uacfc\uac00 \ub098\uc624\uba74 \ud300\uc7a5\ub2d8\uaed8\ub3c4 \uacf5\uc720 \ubd80\ud0c1\ub4dc\ub9bd\ub2c8\ub2e4.")
A.l4O=s(["\uc911\ubcf5","\ub2f4\ub2f9 \ubc94\uc704","\ud655\uc778","\uc5ed\ud560 \ubd84\ub2f4","\uacf5\uc720"],t.s)
A.cGX=new B.cu("\uc5c5\ubb34\uac00 \uc911\ubcf5\ub410\uc744 \ub54c \ub3d9\ub8cc\uc640 \uc870\uc728\ud558\ub294 \ub300\ud654\ub97c \ud574 \ubcf4\uc138\uc694.","\ubbfc\uc218 \uc528, \uc81c\uac00 \uc9c0\uae08 \uc0dd\uc0b0 \uc2e4\uc801 \uc790\ub8cc\ub97c \uc815\ub9ac\ud558\uace0 \uc788\ub294\ub370 \ubbfc\uc218 \uc528\ub3c4 \uac19\uc740 \uc790\ub8cc\ub97c \ub9cc\ub4e4\uace0 \uc788\ub294 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \uc5c5\ubb34\uac00 \uc911\ubcf5\ub41c \uac83 \uac19\uc544\uc11c \ub2f4\ub2f9 \ubc94\uc704\ub97c \ud55c\ubc88 \ud655\uc778\ud558\uba74 \uc88b\uaca0\uc2b5\ub2c8\ub2e4. \uc81c\uac00 \uc0dd\uc0b0 \uc218\ub7c9\uacfc \ubd88\ub7c9 \uc218\ub7c9\uc744 \uc815\ub9ac\ud560 \ud14c\ub2c8\uae4c \ubbfc\uc218 \uc528\ub294 \uc124\ube44 \uc815\uc9c0 \uc2dc\uac04\uacfc \uc6d0\uc778\uc744 \uc815\ub9ac\ud574 \uc8fc\uc2dc\uba74 \uc5b4\ub5a8\uae4c\uc694? \ub9c8\uc9c0\ub9c9\uc5d0 \ub450 \uc790\ub8cc\ub97c \ud569\uccd0\uc11c \ud300\uc7a5\ub2d8\uaed8 \ubcf4\uace0\ud558\uba74 \ub420 \uac83 \uac19\uc2b5\ub2c8\ub2e4.")
A.hbO=s([A.cGF,A.cH6,A.cGi,A.cGX],t.uf)
A.l4W=s(["\uc5c5\ubb34\ub7c9\uc744 \ud655\uc778\ud558\ub294 \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","\ub2f4\ub2f9\uc790\ub97c \uc815\ud558\ub294 \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","\uc6b0\uc120\uc21c\uc704\ub97c \uc4f0\uc138\uc694.","\uc9c4\ud589 \uc0c1\ud669 \uacf5\uc720\ub97c \uc4f0\uc138\uc694.","\ubb38\uc81c\uac00 \uc0dd\uacbc\uc744 \ub54c \uc870\uc815 \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","V-\ub3c4\ub85d\uacfc V-\ub294 \ub9cc\ud07c\uc744 \uc0ac\uc6a9\ud574 \ubcf4\uc138\uc694."],t.s)
A.cUH=new B.dc("\ud6a8\uc728\uc801\uc73c\ub85c \uc5c5\ubb34\ub97c \ubd84\ub2f4\ud558\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574 \uc368 \ubcf4\uc138\uc694.","\uc5ec\ub7ec \uc0ac\ub78c\uc774 \ud568\uaed8 \uc77c\ud560 \ub54c\ub294 \uc5c5\ubb34\ub97c \uc2dc\uc791\ud558\uae30 \uc804\uc5d0 \uc804\uccb4 \uc791\uc5c5\ub7c9\uacfc \ub9c8\uac10 \uc2dc\uac04\uc744 \uba3c\uc800 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \uadf8\ub2e4\uc74c \uac01 \uc791\uc5c5\uc758 \ub09c\uc774\ub3c4\uc640 \ud300\uc6d0\uc758 \uacbd\ud5d8\uc744 \uace0\ub824\ud574\uc11c \ub2f4\ub2f9\uc790\ub97c \uc815\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 \uae09\ud55c \uc5c5\ubb34\uc640 \ub2e4\uc74c \uacf5\uc815\uc5d0 \uc601\ud5a5\uc744 \uc8fc\ub294 \uc5c5\ubb34\ub294 \uc6b0\uc120\uc21c\uc704\ub97c \ub192\uac8c \ub450\uc5b4\uc57c \ud569\ub2c8\ub2e4. \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ud568\uaed8 \ud558\ub294 \ub9cc\ud07c \uc9c4\ud589 \uc0c1\ud669\uc744 \uc815\uae30\uc801\uc73c\ub85c \uacf5\uc720\ud558\ub294 \uac83\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4. \uc5c5\ubb34\uac00 \uc911\ubcf5\ub418\uac70\ub098 \ub204\ub77d\ub418\uc9c0 \uc54a\ub3c4\ub85d \ub2f4\ub2f9 \ubc94\uc704\ub97c \uba85\ud655\ud558\uac8c \uc815\ud558\uace0, \uc608\uc0c1\ubcf4\ub2e4 \uc791\uc5c5\uc774 \ub2a6\uc5b4\uc9c8 \uacbd\uc6b0\uc5d0\ub294 \ubb38\uc81c\uac00 \ucee4\uc9c0\uae30 \uc804\uc5d0 \uc778\uc6d0\uc744 \ub2e4\uc2dc \ubc30\uc815\ud558\uac70\ub098 \uc77c\uc815\uc744 \uc870\uc815\ud574\uc57c \ud569\ub2c8\ub2e4.","Khi nhi\u1ec1u ng\u01b0\u1eddi c\xf9ng l\xe0m vi\u1ec7c, tr\u01b0\u1edbc khi b\u1eaft \u0111\u1ea7u c\u1ea7n ki\u1ec3m tra t\u1ed5ng l\u01b0\u1ee3ng c\xf4ng vi\u1ec7c v\xe0 th\u1eddi h\u1ea1n. Sau \u0111\xf3 n\xean x\xe1c \u0111\u1ecbnh ng\u01b0\u1eddi ph\u1ee5 tr\xe1ch d\u1ef1a tr\xean \u0111\u1ed9 kh\xf3 c\u1ee7a t\u1eebng vi\u1ec7c v\xe0 kinh nghi\u1ec7m c\u1ee7a th\xe0nh vi\xean. \u0110\u1eb7c bi\u1ec7t nh\u1eefng vi\u1ec7c g\u1ea5p ho\u1eb7c \u1ea3nh h\u01b0\u1edfng c\xf4ng \u0111o\u1ea1n sau c\u1ea7n \u0111\u01b0\u1ee3c \u0111\u1eb7t \u01b0u ti\xean cao. V\xec nhi\u1ec1u ng\u01b0\u1eddi c\xf9ng l\xe0m n\xean vi\u1ec7c chia s\u1ebb ti\u1ebfn \u0111\u1ed9 \u0111\u1ecbnh k\u1ef3 c\u0169ng quan tr\u1ecdng. C\u1ea7n x\xe1c \u0111\u1ecbnh r\xf5 ph\u1ea1m vi ph\u1ee5 tr\xe1ch \u0111\u1ec3 c\xf4ng vi\u1ec7c kh\xf4ng b\u1ecb tr\xf9ng ho\u1eb7c b\u1ecf s\xf3t, v\xe0 n\u1ebfu c\xf4ng vi\u1ec7c ch\u1eadm h\u01a1n d\u1ef1 ki\u1ebfn th\xec c\u1ea7n ph\xe2n b\u1ed5 l\u1ea1i nh\xe2n l\u1ef1c ho\u1eb7c \u0111i\u1ec1u ch\u1ec9nh l\u1ecbch tr\u01b0\u1edbc khi v\u1ea5n \u0111\u1ec1 l\u1edbn l\xean.")
A.l8_=s(["\uad50\ub300 \uadfc\ubb34 \uc0c1\ud669\uc744 \uc4f0\uc138\uc694.","\ub204\ub77d \uc704\ud5d8\uc744 \uc4f0\uc138\uc694.","\ubbf8\uc644\ub8cc \uc5c5\ubb34\ub97c \uc4f0\uc138\uc694.","\uc124\ube44 \uc774\uc0c1\uc774\ub098 \ud488\uc9c8 \ubb38\uc81c\ub97c \uc4f0\uc138\uc694.","\uc88b\uc740 \uc778\uc218\uc778\uacc4 \ubc29\ubc95\uc744 \uc81c\uc548\ud558\uc138\uc694.","V-\ub2e4\uac00\ub294\uc744 \uc0ac\uc6a9\ud574 \ubcf4\uc138\uc694."],t.s)
A.cUi=new B.dc("\uc778\uc218\uc778\uacc4\uac00 \uc911\uc694\ud55c \uc774\uc720\ub97c \uc368 \ubcf4\uc138\uc694.","\uad50\ub300 \uadfc\ubb34\ub97c \ud558\ub294 \ud68c\uc0ac\uc5d0\uc11c\ub294 \uc778\uc218\uc778\uacc4\uac00 \ub9e4\uc6b0 \uc911\uc694\ud569\ub2c8\ub2e4. \uc774\uc804 \uadfc\ubb34\uc790\uac00 \uc5b4\ub5a4 \uc791\uc5c5\uc744 \uc644\ub8cc\ud588\uace0 \uc5b4\ub5a4 \uc791\uc5c5\uc774 \uc544\uc9c1 \ub0a8\uc544 \uc788\ub294\uc9c0 \ub2e4\uc74c \uadfc\ubb34\uc790\uac00 \uc54c\uc544\uc57c \uc5c5\ubb34\ub97c \uc774\uc5b4\uc11c \ud560 \uc218 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \ud2b9\ud788 \uc124\ube44 \uc774\uc0c1\uc774\ub098 \ud488\uc9c8 \ubb38\uc81c\uac00 \uc788\uc5c8\ub294\ub370 \uadf8 \ub0b4\uc6a9\uc744 \uc815\ud655\ud558\uac8c \uc804\ub2ec\ud558\uc9c0 \uc54a\ub2e4\uac00\ub294 \uac19\uc740 \ubb38\uc81c\uac00 \ubc18\ubcf5\ub418\uac70\ub098 \uc0ac\uace0\ub85c \uc774\uc5b4\uc9c8 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc778\uc218\uc778\uacc4\ub97c \ud560 \ub54c\ub294 \uc644\ub8cc\ub41c \uc5c5\ubb34, \ubbf8\uc644\ub8cc \uc5c5\ubb34, \uc774\uc0c1 \ubc1c\uc0dd \ub0b4\uc6a9, \uc870\uce58 \uacb0\uacfc\uc640 \ucd94\uac00 \ud655\uc778 \uc0ac\ud56d\uc744 \uad6c\ubd84\ud574\uc11c \uc804\ub2ec\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \uc911\uc694\ud55c \ub0b4\uc6a9\uc740 \ub9d0\ub85c\ub9cc \uc804\ub2ec\ud558\uc9c0 \ub9d0\uace0 \uae30\ub85d\uc73c\ub85c\ub3c4 \ub0a8\uaca8\uc57c \ud569\ub2c8\ub2e4.","\u1ede c\xf4ng ty l\xe0m theo ca, b\xe0n giao c\xf4ng vi\u1ec7c r\u1ea5t quan tr\u1ecdng. Ng\u01b0\u1eddi l\xe0m ca ti\u1ebfp theo c\u1ea7n bi\u1ebft ca tr\u01b0\u1edbc \u0111\xe3 ho\xe0n th\xe0nh vi\u1ec7c g\xec v\xe0 c\xf2n vi\u1ec7c g\xec \u0111\u1ec3 ti\u1ebfp t\u1ee5c c\xf4ng vi\u1ec7c. \u0110\u1eb7c bi\u1ec7t n\u1ebfu \u0111\xe3 c\xf3 b\u1ea5t th\u01b0\u1eddng thi\u1ebft b\u1ecb ho\u1eb7c v\u1ea5n \u0111\u1ec1 ch\u1ea5t l\u01b0\u1ee3ng m\xe0 kh\xf4ng truy\u1ec1n \u0111\u1ea1t ch\xednh x\xe1c th\xec c\xf9ng v\u1ea5n \u0111\u1ec1 c\xf3 th\u1ec3 l\u1eb7p l\u1ea1i ho\u1eb7c th\u1eadm ch\xed d\u1eabn t\u1edbi tai n\u1ea1n. V\xec v\u1eady khi b\xe0n giao n\xean ph\xe2n bi\u1ec7t r\xf5 c\xf4ng vi\u1ec7c \u0111\xe3 ho\xe0n th\xe0nh, ch\u01b0a ho\xe0n th\xe0nh, n\u1ed9i dung b\u1ea5t th\u01b0\u1eddng, k\u1ebft qu\u1ea3 x\u1eed l\xfd v\xe0 ph\u1ea7n c\u1ea7n ki\u1ec3m tra th\xeam. N\u1ed9i dung quan tr\u1ecdng kh\xf4ng n\xean ch\u1ec9 truy\u1ec1n \u0111\u1ea1t b\u1eb1ng l\u1eddi m\xe0 c\u1ea7n \u0111\u1ec3 l\u1ea1i ghi ch\xe9p.")
A.l7E=s(["\ucc45\uc784\uac10\uc744 \uc4f0\uc138\uc694.","\uc815\ubcf4 \uacf5\uc720\ub97c \uc4f0\uc138\uc694.","\uc9c0\uc6d0\uacfc \ud611\ub825\uc744 \uc4f0\uc138\uc694.","\uc5ed\ud560 \ubd84\ub2f4\uc744 \uc4f0\uc138\uc694.","\ubb38\uc81c\uac00 \ubc1c\uc0dd\ud588\uc744 \ub54c\uc758 \ud0dc\ub3c4\ub97c \uc4f0\uc138\uc694.","V-(\uc73c)\u3139 \ud14c\ub2c8\uae4c\uc640 V-\ub294 \ub300\uc2e0\uc5d0\ub97c \uc0ac\uc6a9\ud574 \ubcf4\uc138\uc694."],t.s)
A.cU7=new B.dc("\uc88b\uc740 \ud300\uc6cc\ud06c\ub97c \uc704\ud574 \ud544\uc694\ud55c \ud0dc\ub3c4\uc5d0 \ub300\ud574 \uc368 \ubcf4\uc138\uc694.","\uc88b\uc740 \ud300\uc6cc\ud06c\ub97c \uc704\ud574\uc11c\ub294 \uba3c\uc800 \uac01\uc790\uac00 \uc790\uc2e0\uc758 \ub2f4\ub2f9 \uc5c5\ubb34\uc5d0 \ucc45\uc784\uac10\uc744 \uac00\uc838\uc57c \ud569\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \uc790\uae30 \uc77c\ub9cc \ud558\uba74 \ub41c\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub429\ub2c8\ub2e4. \ub2e4\ub978 \ud300\uc6d0\uc758 \uc5c5\ubb34\uac00 \uc9c0\uc5f0\ub418\uba74 \uc804\uccb4 \uc77c\uc815\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uae30 \ub54c\ubb38\uc5d0 \ud544\uc694\ud55c \uacbd\uc6b0 \uc11c\ub85c \uc9c0\uc6d0\ud574\uc57c \ud569\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \uc81c\uac00 \uac80\uc0ac \uc5c5\ubb34\ub97c \ub3c4\uc6b8 \ud14c\ub2c8\uae4c \ub3d9\ub8cc\uac00 \uc0dd\uc0b0 \uae30\ub85d\uc744 \uc815\ub9ac\ud558\ub3c4\ub85d \uc5ed\ud560\uc744 \ub098\ub20c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub610\ud55c \ud55c \uc0ac\ub78c\uc774 \ubaa8\ub4e0 \uc77c\uc744 \ub9e1\ub294 \ub300\uc2e0\uc5d0 \uac01\uc790\uc758 \uac15\uc810\uc5d0 \ub9de\uac8c \uc5c5\ubb34\ub97c \ub098\ub204\uba74 \ud6a8\uc728\uc744 \ub192\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud588\uc744 \ub54c\ub294 \ucc45\uc784\uc744 \ubbf8\ub8e8\uae30\ubcf4\ub2e4 \uc815\ubcf4\ub97c \ubc14\ub85c \uacf5\uc720\ud558\uace0 \ud568\uaed8 \ud574\uacb0 \ubc29\ubc95\uc744 \ucc3e\ub294 \ud0dc\ub3c4\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.","\u0110\u1ec3 c\xf3 tinh th\u1ea7n l\xe0m vi\u1ec7c nh\xf3m t\u1ed1t, tr\u01b0\u1edbc h\u1ebft m\u1ed7i ng\u01b0\u1eddi c\u1ea7n c\xf3 tr\xe1ch nhi\u1ec7m v\u1edbi c\xf4ng vi\u1ec7c m\xecnh ph\u1ee5 tr\xe1ch. Tuy nhi\xean kh\xf4ng n\xean ngh\u0129 ch\u1ec9 c\u1ea7n l\xe0m vi\u1ec7c c\u1ee7a m\xecnh. N\u1ebfu c\xf4ng vi\u1ec7c c\u1ee7a th\xe0nh vi\xean kh\xe1c b\u1ecb ch\u1eadm th\xec c\xf3 th\u1ec3 \u1ea3nh h\u01b0\u1edfng c\u1ea3 l\u1ecbch chung, v\xec v\u1eady khi c\u1ea7n c\u1ea7n h\u1ed7 tr\u1ee3 nhau. V\xed d\u1ee5 t\xf4i s\u1ebd h\u1ed7 tr\u1ee3 c\xf4ng vi\u1ec7c ki\u1ec3m tra, c\xf2n \u0111\u1ed3ng nghi\u1ec7p t\u1ed5ng h\u1ee3p ghi ch\xe9p s\u1ea3n xu\u1ea5t. Ngo\xe0i ra thay v\xec m\u1ed9t ng\u01b0\u1eddi \u0111\u1ea3m nh\u1eadn t\u1ea5t c\u1ea3, n\u1ebfu chia c\xf4ng vi\u1ec7c theo \u0111i\u1ec3m m\u1ea1nh c\u1ee7a t\u1eebng ng\u01b0\u1eddi th\xec c\xf3 th\u1ec3 n\xe2ng hi\u1ec7u qu\u1ea3. Khi x\u1ea3y ra v\u1ea5n \u0111\u1ec1, thay v\xec \u0111\u1ea9y tr\xe1ch nhi\u1ec7m, vi\u1ec7c chia s\u1ebb th\xf4ng tin ngay v\xe0 c\xf9ng t\xecm c\xe1ch gi\u1ea3i quy\u1ebft r\u1ea5t quan tr\u1ecdng.")
A.hbc=s([A.cUH,A.cUi,A.cU7],t.l5)
A.jr6=s(["\ud611\uc5c5","\ud611\ub825\ud558\ub2e4","\ud611\uc870\ud558\ub2e4","\ud300\uc6cc\ud06c","\uc5ed\ud560","\uc5ed\ud560 \ubd84\ub2f4","\uc5c5\ubb34 \ubd84\ub2f4","\ub2f4\ub2f9\ud558\ub2e4","\ub2f4\ub2f9\uc790","\ub2f4\ub2f9 \uc5c5\ubb34","\ucc45\uc784 \ubc94\uc704","\uc5c5\ubb34 \ubc94\uc704","\uc5c5\ubb34\ub7c9","\ubd84\ubc30\ud558\ub2e4","\ubc30\uc815\ud558\ub2e4","\uc778\uc6d0\uc744 \ubc30\uc815\ud558\ub2e4","\uc6b0\uc120\uc21c\uc704","\uc6b0\uc120\uc21c\uc704\ub97c \uc815\ud558\ub2e4","\uc9c4\ud589 \uc0c1\ud669","\uc9c4\ucc99\ub3c4","\uc77c\uc815","\uc77c\uc815\uc744 \uc870\uc815\ud558\ub2e4","\ub9c8\uac10","\ub9c8\uac10\uc77c","\uae30\ud55c","\uc9c0\uc6d0\ud558\ub2e4","\uc9c0\uc6d0 \uc694\uccad","\ub3c4\uc640\uc8fc\ub2e4","\uc778\uc218\uc778\uacc4","\uc778\uc218\uc778\uacc4\ud558\ub2e4","\uc778\uacc4\ud558\ub2e4","\uacf5\uc720\ud558\ub2e4","\uc815\ubcf4 \uacf5\uc720","\uc804\ub2ec\ud558\ub2e4","\ub204\ub77d\ub418\ub2e4","\uc911\ubcf5\ub418\ub2e4","\uc870\uc728\ud558\ub2e4","\ud611\uc758\ud558\ub2e4","\ucc28\uc9c8","\ucc28\uc9c8\uc774 \uc0dd\uae30\ub2e4","\ubcd1\ubaa9","\ubcd1\ubaa9 \ud604\uc0c1"],t.s)
A.jGi=s(["V-\ub294 \ub370\ub2e4\uac00","V-\ub3c4\ub85d","V-(\uc73c)\u3139 \ud14c\ub2c8(\uae4c)","V-\ub294 \ub300\uc2e0(\uc5d0)","V-(\uc73c)\u3134/\ub294 \ubc18\uba74\uc5d0","V-\ub294 \ub9cc\ud07c","V-\ub2e4\uac00\ub294","V-(\uc73c)\u3139 \uacbd\uc6b0","V-\uac8c \ub418\ub2e4","V-\uae30 \uc704\ud574\uc11c","V-\ub294 \uacfc\uc815\uc5d0\uc11c","V-\uc9c0 \uc54a\ub3c4\ub85d","V-(\uc73c)\u3139 \uac83 \uac19\ub2e4","V-\uae30\ub85c \ud558\ub2e4"],t.s)
A.ic2=s(["\ud611\uc5c5 = h\u1ee3p t\xe1c c\xf4ng vi\u1ec7c","\ud611\ub825\ud558\ub2e4 = h\u1ee3p t\xe1c/ph\u1ed1i h\u1ee3p","\uc5ed\ud560 = vai tr\xf2","\uc5ed\ud560 \ubd84\ub2f4 = ph\xe2n chia vai tr\xf2","\uc5c5\ubb34 \ubd84\ub2f4 = ph\xe2n chia c\xf4ng vi\u1ec7c","\ub2f4\ub2f9\ud558\ub2e4 = ph\u1ee5 tr\xe1ch","\ub2f4\ub2f9\uc790 = ng\u01b0\u1eddi ph\u1ee5 tr\xe1ch","\ub2f4\ub2f9 \uc5c5\ubb34 = c\xf4ng vi\u1ec7c ph\u1ee5 tr\xe1ch","\ucc45\uc784 \ubc94\uc704 = ph\u1ea1m vi tr\xe1ch nhi\u1ec7m","\uc5c5\ubb34\ub7c9 = kh\u1ed1i l\u01b0\u1ee3ng c\xf4ng vi\u1ec7c","\ubd84\ubc30\ud558\ub2e4 = ph\xe2n b\u1ed5","\ubc30\uc815\ud558\ub2e4 = ph\xe2n c\xf4ng","\uc6b0\uc120\uc21c\uc704 = th\u1ee9 t\u1ef1 \u01b0u ti\xean","\uc9c4\ud589 \uc0c1\ud669 = t\xecnh h\xecnh ti\u1ebfn \u0111\u1ed9","\uc9c4\ucc99\ub3c4 = m\u1ee9c \u0111\u1ed9 ti\u1ebfn tri\u1ec3n","\uc77c\uc815 = l\u1ecbch tr\xecnh","\ub9c8\uac10 = h\u1ea1n ho\xe0n th\xe0nh","\uae30\ud55c = th\u1eddi h\u1ea1n","\uc9c0\uc6d0\ud558\ub2e4 = h\u1ed7 tr\u1ee3","\uc9c0\uc6d0 \uc694\uccad = y\xeau c\u1ea7u h\u1ed7 tr\u1ee3","\uc778\uc218\uc778\uacc4 = b\xe0n giao c\xf4ng vi\u1ec7c","\uc778\uacc4\ud558\ub2e4 = b\xe0n giao","\uacf5\uc720\ud558\ub2e4 = chia s\u1ebb","\uc804\ub2ec\ud558\ub2e4 = truy\u1ec1n \u0111\u1ea1t","\ub204\ub77d\ub418\ub2e4 = b\u1ecb b\u1ecf s\xf3t","\uc911\ubcf5\ub418\ub2e4 = b\u1ecb tr\xf9ng","\uc870\uc728\ud558\ub2e4 = \u0111i\u1ec1u ph\u1ed1i","\ud611\uc758\ud558\ub2e4 = trao \u0111\u1ed5i \u0111\u1ec3 th\u1ed1ng nh\u1ea5t","\ucc28\uc9c8 = tr\u1edf ng\u1ea1i \u1ea3nh h\u01b0\u1edfng k\u1ebf ho\u1ea1ch","\ubcd1\ubaa9 = \u0111i\u1ec3m ngh\u1ebdn","V-\ub294 \ub370\ub2e4\uac00 = kh\xf4ng nh\u1eefng... m\xe0 c\xf2n...","V-\ub3c4\ub85d = \u0111\u1ec3/sao cho...","V-(\uc73c)\u3139 \ud14c\ub2c8\uae4c = t\xf4i s\u1ebd... n\xean...","V-\ub294 \ub300\uc2e0\uc5d0 = thay v\xec/\u0111\u1ed5i l\u1ea1i...","V-(\uc73c)\u3134/\ub294 \ubc18\uba74\uc5d0 = trong khi/tr\xe1i l\u1ea1i...","V-\ub294 \ub9cc\ud07c = v\xec... n\xean t\u01b0\u01a1ng \u1ee9ng...","V-\ub2e4\uac00\ub294 = n\u1ebfu c\u1ee9... th\xec s\u1ebd...","\uc81c\uac00 \uc0dd\uc0b0 \uae30\ub85d\uc744 \uc815\ub9ac\ud560 \ud14c\ub2c8\uae4c \uac80\uc0ac \uacb0\uacfc\ub97c \ud655\uc778\ud574 \uc8fc\uc138\uc694.","\uc5c5\ubb34\uac00 \uc911\ubcf5\ub418\uc9c0 \uc54a\ub3c4\ub85d \ub2f4\ub2f9\uc790\ub97c \uc815\ud569\uc2dc\ub2e4.","\ud604\uc7ac \uc18d\ub3c4\ub85c \uacc4\uc18d \uc9c4\ud589\ud558\ub2e4\uac00\ub294 \ub9c8\uac10\uc774 \ub2a6\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc5ec\ub7ec \uc0ac\ub78c\uc774 \ud568\uaed8 \ud558\ub294 \ub9cc\ud07c \uc9c4\ud589 \uc0c1\ud669\uc744 \uacf5\uc720\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc88b\uc740 \ud611\uc5c5\uc740 \ub2e8\uc21c\ud788 \uc11c\ub85c \ub3c4\uc640\uc8fc\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ub2f4\ub2f9 \uc5c5\ubb34, \ucc45\uc784 \ubc94\uc704, \uc9c4\ud589 \uc0c1\ud669\uacfc \ubb38\uc81c\ub97c \uba85\ud655\ud558\uac8c \uacf5\uc720\ud558\ub294 \uac83\uc5d0\uc11c \uc2dc\uc791\ub429\ub2c8\ub2e4."],t.s)
