A.cGR=new B.cu("\ub3d9\ub8cc\uc758 \ub9d0\ud22c \ub54c\ubb38\uc5d0 \ubd88\ud3b8\ud588\ub358 \uc0c1\ud669\uc744 \ucc28\ubd84\ud558\uac8c \ub9d0\ud574 \ubcf4\uc138\uc694.","\ubbfc\uc218 \uc528, \uc544\uae4c \ud68c\uc758\uc5d0\uc11c \ud55c \uac00\uc9c0 \ud655\uc778\ud558\uace0 \uc2f6\uc740 \ubd80\ubd84\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc81c\uac00 \uc790\ub8cc \uc124\uba85\uc744 \ud558\uace0 \uc788\uc744 \ub54c \u201c\uadf8\uac83\ub3c4 \uc81c\ub300\ub85c \ubabb \ud588\uc5b4\uc694?\u201d\ub77c\uace0 \ub9d0\uc500\ud558\uc168\ub294\ub370 \uc800\ud55c\ud14c\ub294 \uadf8 \ud45c\ud604\uc774 \uc870\uae08 \uac15\ud558\uac8c \ub4e4\ub838\uc2b5\ub2c8\ub2e4. \uc800\ub97c \ube44\ub09c\ud558\ub824\ub294 \uc758\ub3c4\uc600\ub2e4\uace0 \ub2e8\uc815\ud558\ub824\ub294 \uac74 \uc544\ub2d9\ub2c8\ub2e4. \ub2e4\ub9cc \uc81c\uac00 \uc5b4\ub5a4 \ubd80\ubd84\uc744 \uc218\uc815\ud574\uc57c \ud558\ub294\uc9c0 \uad6c\uccb4\uc801\uc73c\ub85c \ub9d0\uc500\ud574 \uc8fc\uc168\uc73c\uba74 \uc88b\uaca0\uc2b5\ub2c8\ub2e4. \uc800\ub3c4 \ubd80\uc871\ud55c \ubd80\ubd84\uc774 \uc788\uc73c\uba74 \ubc14\ub85c \ud655\uc778\ud558\uace0 \uace0\uce58\uaca0\uc2b5\ub2c8\ub2e4.")
A.l7T=s(["\ud604\uc7ac \uc5c5\ubb34","\uc5c5\ubb34\ub7c9","\uc601\ud5a5","\ubd88\ub9cc","\uc870\uc815 \uc694\uccad"],t.s)
A.cGg=new B.cu("\uc5c5\ubb34\uac00 \ub108\ubb34 \ub9ce\uc774 \uc9d1\uc911\ub410\uc744 \ub54c \ud300\uc7a5\uc5d0\uac8c \uc870\uc815\uc744 \uc694\uccad\ud574 \ubcf4\uc138\uc694.","\ud300\uc7a5\ub2d8, \ud604\uc7ac \uc5c5\ubb34 \ubd84\ub2f4\uc5d0 \ub300\ud574 \uc7a0\uae50 \ub9d0\uc500\ub4dc\ub9ac\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \ucd5c\uadfc\uc5d0 \uc81c\uac00 \uc0dd\uc0b0 \uae30\ub85d, \ucd5c\uc885 \uac80\uc0ac\uc640 \uc7ac\uac80\uc0ac \uc5c5\ubb34\ub97c \ud568\uaed8 \ub9e1\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ub204\uad6c\ubcf4\ub2e4 \uc77c\uc774 \ub9ce\ub2e4\uace0 \ubd88\ub9cc\uc744 \ub9d0\ud558\ub824\ub294 \uac74 \uc544\ub2d9\ub2c8\ub2e4. \ub2e4\ub9cc \uac80\uc0ac \ubb3c\ub7c9\uc774 \ub9ce\uc544\uc9c0\ub294 \ub0a0\uc5d0\ub294 \uae30\ub85d \uc5c5\ubb34\uae4c\uc9c0 \ub3d9\uc2dc\uc5d0 \ucc98\ub9ac\ud558\uae30 \uc5b4\ub824\uc6cc\uc11c \ud655\uc778 \uc2dc\uac04\uc774 \ubd80\uc871\ud574\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud488\uc9c8\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uc9c0 \uc54a\ub3c4\ub85d \uc77c\ubd80 \uae30\ub85d \uc5c5\ubb34\uc758 \uc2dc\uac04\uc774\ub098 \ub2f4\ub2f9\uc790\ub97c \uc870\uc815\ud560 \uc218 \uc788\uc744\uc9c0 \uac80\ud1a0\ud574 \uc8fc\uc168\uc73c\uba74 \ud569\ub2c8\ub2e4.")
A.l5f=s(["\uc0ac\uc2e4","\uc778\uc815","\uc601\ud5a5","\uc0ac\uacfc","\uc7ac\ubc1c \ubc29\uc9c0"],t.s)
A.cGJ=new B.cu("\uc790\uc2e0\uc758 \uc2e4\uc218\ub97c \uc778\uc815\ud558\uace0 \ub3d9\ub8cc\uc5d0\uac8c \uc0ac\uacfc\ud574 \ubcf4\uc138\uc694.","\uc5b4\uc81c \uc5c5\ubb34 \ubcc0\uacbd \ub0b4\uc6a9\uc744 \uc81c\uac00 \uc804\ub2ec\ud574\uc57c \ud588\ub294\ub370 \ud655\uc778\ub9cc \ud558\uace0 \uacf5\uc720\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4. \uadf8 \ub54c\ubb38\uc5d0 \ubbfc\uc218 \uc528\uac00 \uc774\uc804 \uae30\uc900\uc73c\ub85c \uc791\uc5c5\uc744 \uacc4\uc18d\ud558\uac8c \ub41c \ubd80\ubd84\uc740 \uc81c \ucc45\uc784\uc774 \ub9de\uc2b5\ub2c8\ub2e4. \uc5c5\ubb34\uc5d0 \ud63c\uc120\uc744 \ub4dc\ub824\uc11c \uc8c4\uc1a1\ud569\ub2c8\ub2e4. \ub2e4\uc74c\ubd80\ud130\ub294 \ubcc0\uacbd \ub0b4\uc6a9\uc744 \ud655\uc778\ud558\ub294 \uc989\uc2dc \uad00\ub828\uc790\uc5d0\uac8c \uacf5\uc720\ud558\uace0 \uc804\ub2ec \uc5ec\ubd80\uae4c\uc9c0 \ub2e4\uc2dc \ud655\uc778\ud558\uaca0\uc2b5\ub2c8\ub2e4. \uac19\uc740 \ubb38\uc81c\uac00 \ubc18\ubcf5\ub418\uc9c0 \uc54a\ub3c4\ub85d \uccb4\ud06c \ud56d\ubaa9\uc5d0\ub3c4 \ucd94\uac00\ud558\uaca0\uc2b5\ub2c8\ub2e4.")
A.l6a=s(["\uc591\ucabd \uc785\uc7a5","\ubb38\uc81c","\uc0ac\uc2e4 \ud655\uc778","\uacf5\ud1b5 \ubaa9\ud45c","\ub300\uc548","\ud569\uc758"],t.s)
A.cGB=new B.cu("\ub450 \ubd80\uc11c\uc758 \uac08\ub4f1\uc744 \uc911\uac04\uc5d0\uc11c \uc870\uc815\ud574 \ubcf4\uc138\uc694.","\ub450 \ud300\uc758 \ub9d0\uc500\uc744 \ub4e4\uc5b4 \ubcf4\ub2c8 \uc0dd\uc0b0\ud300\uc740 \uc77c\uc815 \uc9c0\uc5f0\uc774 \uac00\uc7a5 \ud070 \ubb38\uc81c\uc774\uace0 \ud488\uc9c8\ud300\uc740 \uac80\uc0ac \uc694\uccad\uc774 \ud55c\uaebc\ubc88\uc5d0 \ubab0\ub9ac\ub294 \uac83\uc774 \ubb38\uc81c\uc778 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \uc11c\ub85c \ucc45\uc784\uc744 \ubbf8\ub8e8\uae30\ubcf4\ub2e4\ub294 \uac80\uc0ac \uc694\uccad \uacfc\uc815\ubd80\ud130 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uaca0\uc2b5\ub2c8\ub2e4. \uae34\uae09 \uac74\uacfc \uc77c\ubc18 \uac74\uc744 \uad6c\ubd84\ud558\uace0 \uc0dd\uc0b0\ud300\uc774 \uc694\uccad \uc2dc \uc6b0\uc120\uc21c\uc704\ub97c \ud45c\uc2dc\ud558\uba74 \ud488\uc9c8\ud300\uc5d0\uc11c\ub3c4 \uc77c\uc815\uc744 \uc870\uc815\ud558\uae30 \uc26c\uc6b8 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \uc77c\uc8fc\uc77c \ub3d9\uc548 \uc774 \ubc29\ubc95\uc744 \uc801\uc6a9\ud55c \ud6c4 \uc2e4\uc81c \ub300\uae30 \uc2dc\uac04\uc774 \uc904\uc5c8\ub294\uc9c0 \uac19\uc774 \ud655\uc778\ud574 \ubcf4\uba74 \uc5b4\ub5a8\uae4c\uc694?")
A.j6H=s([A.cGR,A.cGg,A.cGJ,A.cGB],t.uf)
A.l6x=s(["\uac08\ub4f1 \uc6d0\uc778\uc744 \ub450 \uac00\uc9c0 \uc774\uc0c1 \uc4f0\uc138\uc694.","\uc624\ud574\uc640 \uc5c5\ubb34 \ubd84\ub2f4\uc744 \ud3ec\ud568\ud574 \ubcf4\uc138\uc694.","\uac10\uc815\uc801\uc778 \ub300\uc751\uc758 \ubb38\uc81c\uc810\uc744 \uc4f0\uc138\uc694.","\ub300\ud654\uc640 \uc0ac\uc2e4 \ud655\uc778\uc758 \uc911\uc694\uc131\uc744 \uc4f0\uc138\uc694.","\ud574\uacb0\ucc45\uc744 \uc81c\uc548\ud558\uc138\uc694.","V-\uae30\ubcf4\ub2e4\ub294\uacfc V-\ub2e4 \ubcf4\ub2c8\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cTR=new B.dc("\uc9c1\uc7a5\uc5d0\uc11c \uac08\ub4f1\uc774 \uc0dd\uae30\ub294 \uc6d0\uc778\uacfc \ud574\uacb0 \ubc29\ubc95\uc5d0 \ub300\ud574 \uc368 \ubcf4\uc138\uc694.","\uc9c1\uc7a5\uc5d0\uc11c\ub294 \uc5c5\ubb34 \ubc29\uc2dd, \uc5ed\ud560 \ubd84\ub2f4, \uc758\uc0ac\uc18c\ud1b5 \ubb38\uc81c \ub54c\ubb38\uc5d0 \uac08\ub4f1\uc774 \uc0dd\uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 \ub2f4\ub2f9\uc790\uac00 \uba85\ud655\ud558\uc9c0 \uc54a\uac70\ub098 \ubcc0\uacbd \ub0b4\uc6a9\uc744 \uc81c\ub300\ub85c \uacf5\uc720\ud558\uc9c0 \uc54a\uc73c\uba74 \uc11c\ub85c \ub2e4\ub978 \ub0b4\uc6a9\uc744 \uc54c\uace0 \uc77c\ud558\uac8c \ub418\uc5b4 \uc624\ud574\uac00 \uc0dd\uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubc14\uc058\ub2e4\ub294 \uc774\uc720\ub85c \ub300\ud654\ub97c \uacc4\uc18d \ubbf8\ub8e8\ub2e4 \ubcf4\ub2c8 \uc791\uc740 \uc624\ud574\uac00 \ub354 \ud070 \ubd88\ub9cc\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uacbd\uc6b0\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uac08\ub4f1\uc774 \uc0dd\uacbc\uc744 \ub54c \uc0c1\ub300\ubc29\uc744 \ud0d3\ud558\uae30\ubcf4\ub2e4\ub294 \uba3c\uc800 \uc5b4\ub5a4 \uc0c1\ud669\uc774 \uc788\uc5c8\ub294\uc9c0 \uc0ac\uc2e4\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \ub610\ud55c \uc790\uc2e0\uc758 \uc785\uc7a5\ub9cc \uc124\uba85\ud558\uc9c0 \ub9d0\uace0 \uc0c1\ub300\ubc29\uc758 \uc124\uba85\ub3c4 \ub05d\uae4c\uc9c0 \ub4e4\uc5b4\uc57c \ud569\ub2c8\ub2e4. \uc5c5\ubb34 \ubb38\uc81c\ub77c\uba74 \ub2f4\ub2f9 \ubc94\uc704, \uc77c\uc815\uacfc \uc804\ub2ec \ubc29\ubc95\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \ub2e4\uc2dc \uc815\ud574\uc11c \uac19\uc740 \ubb38\uc81c\uac00 \ubc18\ubcf5\ub418\uc9c0 \uc54a\ub3c4\ub85d \ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\u1ede n\u01a1i l\xe0m vi\u1ec7c, m\xe2u thu\u1eabn c\xf3 th\u1ec3 ph\xe1t sinh do c\xe1ch l\xe0m vi\u1ec7c, ph\xe2n chia vai tr\xf2 ho\u1eb7c v\u1ea5n \u0111\u1ec1 giao ti\u1ebfp. \u0110\u1eb7c bi\u1ec7t n\u1ebfu ng\u01b0\u1eddi ph\u1ee5 tr\xe1ch kh\xf4ng r\xf5 ho\u1eb7c n\u1ed9i dung thay \u0111\u1ed5i kh\xf4ng \u0111\u01b0\u1ee3c chia s\u1ebb \u0111\xfang th\xec m\u1ecdi ng\u01b0\u1eddi c\xf3 th\u1ec3 l\xe0m vi\u1ec7c v\u1edbi th\xf4ng tin kh\xe1c nhau v\xe0 d\u1eabn \u0111\u1ebfn hi\u1ec3u l\u1ea7m. C\u0169ng c\xf3 tr\u01b0\u1eddng h\u1ee3p v\xec b\u1eadn n\xean li\xean t\u1ee5c tr\xec ho\xe3n \u0111\u1ed1i tho\u1ea1i, khi\u1ebfn hi\u1ec3u l\u1ea7m nh\u1ecf d\u1eabn \u0111\u1ebfn b\u1ea5t m\xe3n l\u1edbn h\u01a1n. Khi x\u1ea3y ra m\xe2u thu\u1eabn, thay v\xec \u0111\u1ed5 l\u1ed7i cho \u0111\u1ed1i ph\u01b0\u01a1ng, n\xean x\xe1c nh\u1eadn tr\u01b0\u1edbc s\u1ef1 th\u1eadt v\u1ec1 t\xecnh hu\u1ed1ng \u0111\xe3 x\u1ea3y ra. Ngo\xe0i vi\u1ec7c gi\u1ea3i th\xedch l\u1eadp tr\u01b0\u1eddng c\u1ee7a m\xecnh, c\u0169ng c\u1ea7n nghe h\u1ebft l\u1eddi gi\u1ea3i th\xedch c\u1ee7a \u0111\u1ed1i ph\u01b0\u01a1ng. N\u1ebfu l\xe0 v\u1ea5n \u0111\u1ec1 c\xf4ng vi\u1ec7c, \u0111i\u1ec1u quan tr\u1ecdng l\xe0 x\xe1c \u0111\u1ecbnh l\u1ea1i c\u1ee5 th\u1ec3 ph\u1ea1m vi ph\u1ee5 tr\xe1ch, l\u1ecbch v\xe0 c\xe1ch truy\u1ec1n \u0111\u1ea1t \u0111\u1ec3 c\xf9ng v\u1ea5n \u0111\u1ec1 kh\xf4ng l\u1eb7p l\u1ea1i.")
A.l4U=s(["\uc798\ubabb\ud55c \ud589\ub3d9\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \uc4f0\uc138\uc694.","\uc0c1\ub300\ubc29\uc5d0\uac8c \ubbf8\uce5c \uc601\ud5a5\uc744 \uc4f0\uc138\uc694.","\uc0ac\uacfc\ub97c \uc4f0\uc138\uc694.","\ubcc0\uba85\uacfc \uc124\uba85\uc758 \ucc28\uc774\ub97c \uc4f0\uc138\uc694.","\uc55e\uc73c\ub85c\uc758 \ud589\ub3d9\uc744 \uc4f0\uc138\uc694.","V/A-\ub354\ub77c\ub3c4\ub97c \uc0ac\uc6a9\ud558\uc138\uc694."],t.s)
A.cTP=new B.dc("\ub3d9\ub8cc\uc5d0\uac8c \uc0ac\uacfc\ud558\uace0 \uad00\uacc4\ub97c \ud68c\ubcf5\ud558\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574 \uc368 \ubcf4\uc138\uc694.","\ub3d9\ub8cc\uc5d0\uac8c \uc0ac\uacfc\ud560 \ub54c\ub294 \ub2e8\uc21c\ud788 \u201c\ubbf8\uc548\ud569\ub2c8\ub2e4\u201d\ub77c\uace0 \ub9d0\ud558\ub294 \uac83\ubcf4\ub2e4 \uc790\uc2e0\uc774 \uc5b4\ub5a4 \ud589\ub3d9\uc744 \ud588\ub294\uc9c0 \uad6c\uccb4\uc801\uc73c\ub85c \uc778\uc815\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \ubcc0\uacbd\ub41c \uc5c5\ubb34 \ub0b4\uc6a9\uc744 \uc804\ub2ec\ud558\uc9c0 \uc54a\uc544 \uc0c1\ub300\ubc29\uc774 \ub2e4\uc2dc \uc791\uc5c5\ud558\uac8c \ub410\ub2e4\uba74 \uadf8 \uc0ac\uc2e4\uacfc \uc601\ud5a5\uc744 \uba3c\uc800 \uc778\uc815\ud574\uc57c \ud569\ub2c8\ub2e4. \uc790\uc2e0\uc5d0\uac8c \uc774\uc720\uac00 \uc788\ub354\ub77c\ub3c4 \uc0c1\ub300\ubc29\uc774 \ubd88\ud3b8\ud558\uac70\ub098 \uc190\ud574\ub97c \ubcf8 \ubd80\ubd84\uae4c\uc9c0 \uc5c6\uc5c8\ub358 \uc77c\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4. \uc124\uba85\uc774 \ud544\uc694\ud558\ub354\ub77c\ub3c4 \ucc45\uc784\uc744 \ud53c\ud558\uae30 \uc704\ud55c \ubcc0\uba85\ucc98\ub7fc \ub9d0\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \uc0ac\uacfc\ud55c \ud6c4\uc5d0\ub294 \uc55e\uc73c\ub85c \uc5b4\ub5bb\uac8c \ud589\ub3d9\uc744 \ubc14\uafc0 \uac83\uc778\uc9c0 \uad6c\uccb4\uc801\uc73c\ub85c \uc57d\uc18d\ud558\uace0 \uc2e4\uc81c\ub85c \uc9c0\ucf1c\uc57c \uc2e0\ub8b0\ub97c \ub2e4\uc2dc \uc313\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","Khi xin l\u1ed7i \u0111\u1ed3ng nghi\u1ec7p, thay v\xec ch\u1ec9 n\xf3i \u201cxin l\u1ed7i\u201d, \u0111i\u1ec1u quan tr\u1ecdng l\xe0 th\u1eeba nh\u1eadn c\u1ee5 th\u1ec3 m\xecnh \u0111\xe3 l\xe0m h\xe0nh \u0111\u1ed9ng g\xec. V\xed d\u1ee5 n\u1ebfu kh\xf4ng truy\u1ec1n \u0111\u1ea1t n\u1ed9i dung c\xf4ng vi\u1ec7c \u0111\xe3 thay \u0111\u1ed5i khi\u1ebfn \u0111\u1ed1i ph\u01b0\u01a1ng ph\u1ea3i l\xe0m l\u1ea1i, c\u1ea7n th\u1eeba nh\u1eadn tr\u01b0\u1edbc s\u1ef1 th\u1eadt \u0111\xf3 v\xe0 \u1ea3nh h\u01b0\u1edfng \u0111\xe3 g\xe2y ra. D\xf9 b\u1ea3n th\xe2n c\xf3 l\xfd do, \u0111i\u1ec1u \u0111\xf3 c\u0169ng kh\xf4ng l\xe0m cho ph\u1ea7n b\u1ea5t ti\u1ec7n ho\u1eb7c thi\u1ec7t h\u1ea1i c\u1ee7a \u0111\u1ed1i ph\u01b0\u01a1ng bi\u1ebfn m\u1ea5t. D\xf9 c\u1ea7n gi\u1ea3i th\xedch, c\u0169ng kh\xf4ng n\xean n\xf3i nh\u01b0 m\u1ed9t l\u1eddi bi\u1ec7n minh \u0111\u1ec3 tr\xe1nh tr\xe1ch nhi\u1ec7m. Sau khi xin l\u1ed7i, c\u1ea7n cam k\u1ebft c\u1ee5 th\u1ec3 m\xecnh s\u1ebd thay \u0111\u1ed5i c\xe1ch h\xe0nh \u0111\u1ed9ng th\u1ebf n\xe0o v\xe0 th\u1ef1c s\u1ef1 th\u1ef1c hi\u1ec7n th\xec m\u1edbi c\xf3 th\u1ec3 x\xe2y d\u1ef1ng l\u1ea1i l\xf2ng tin.")
A.l7o=s(["\ud604\uc7ac \uc5c5\ubb34\ub7c9\uc744 \ud655\uc778\ud558\uc138\uc694.","\ub2f4\ub2f9 \ubc94\uc704\ub97c \uc4f0\uc138\uc694.","\uc911\ubcf5\uacfc \ub204\ub77d\uc744 \ud655\uc778\ud558\uc138\uc694.","\uc591\ucabd \uc785\uc7a5\uc744 \uc124\uba85\ud558\uc138\uc694.","\uc870\uc815 \ubc29\uc548\uc744 \uc81c\uc548\ud558\uc138\uc694.","\ud569\uc758 \ud6c4 \ud655\uc778 \ubc29\ubc95\uc744 \uc4f0\uc138\uc694."],t.s)
A.cTY=new B.dc("\uc5c5\ubb34 \ubd84\ub2f4 \uac08\ub4f1\uc744 \ud574\uacb0\ud558\ub294 \ubc29\ubc95\uc744 \uc368 \ubcf4\uc138\uc694.","\uc5c5\ubb34 \ubd84\ub2f4 \ubb38\uc81c\ub85c \uac08\ub4f1\uc774 \uc0dd\uacbc\uc744 \ub54c\ub294 \uba3c\uc800 \ub204\uac00 \uc77c\uc744 \ub354 \ub9ce\uc774 \ud55c\ub2e4\uace0 \uc8fc\uc7a5\ud558\uae30\ubcf4\ub2e4 \uc2e4\uc81c \uc5c5\ubb34\ub97c \ubaa9\ub85d\uc73c\ub85c \uc815\ub9ac\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \uac01 \uc9c1\uc6d0\uc774 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 \uc5c5\ubb34, \ud544\uc694\ud55c \uc2dc\uac04\uacfc \ub9c8\uac10 \uae30\ud55c\uc744 \ud655\uc778\ud558\uba74 \uc5c5\ubb34\uac00 \ud55c \uc0ac\ub78c\uc5d0\uac8c \uc9c0\ub098\uce58\uac8c \uc9d1\uc911\ub3fc \uc788\ub294\uc9c0 \ud310\ub2e8\ud558\uae30 \uc26c\uc6cc\uc9d1\ub2c8\ub2e4. \ub610\ud55c \ub450 \uc0ac\ub78c\uc774 \uac19\uc740 \uc77c\uc744 \ud558\uace0 \uc788\uac70\ub098 \ubc18\ub300\ub85c \ub2f4\ub2f9\uc790\uac00 \uc5c6\ub294 \uc5c5\ubb34\uac00 \uc788\ub294\uc9c0\ub3c4 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \uc591\ucabd\uc758 \uc0c1\ud669\uc744 \ub4e4\uc740 \ud6c4\uc5d0\ub294 \uc5c5\ubb34\ub7c9\uacfc \uc219\ub828\ub3c4\ub97c \uace0\ub824\ud574\uc11c \ub2f4\ub2f9 \ubc94\uc704\ub97c \ub2e4\uc2dc \uc870\uc815\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc870\uc815 \ud6c4\uc5d0\ub294 \uc77c\uc8fc\uc77c\uc774\ub098 \uc77c\uc815 \uae30\uac04 \ub3d9\uc548 \uc2e4\uc81c\ub85c \ubb38\uc81c\uac00 \uc904\uc5c8\ub294\uc9c0 \ud655\uc778\ud558\uace0 \ud544\uc694\ud558\uba74 \ub2e4\uc2dc \uc218\uc815\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.","Khi x\u1ea3y ra m\xe2u thu\u1eabn v\u1ec1 ph\xe2n chia c\xf4ng vi\u1ec7c, thay v\xec tranh lu\u1eadn ai l\xe0m nhi\u1ec1u h\u01a1n, tr\u01b0\u1edbc ti\xean n\xean l\u1eadp danh s\xe1ch c\xf4ng vi\u1ec7c th\u1ef1c t\u1ebf. N\u1ebfu x\xe1c nh\u1eadn c\xf4ng vi\u1ec7c m\u1ed7i nh\xe2n vi\xean ph\u1ee5 tr\xe1ch, th\u1eddi gian c\u1ea7n thi\u1ebft v\xe0 h\u1ea1n ho\xe0n th\xe0nh th\xec s\u1ebd d\u1ec5 \u0111\xe1nh gi\xe1 xem c\xf4ng vi\u1ec7c c\xf3 t\u1eadp trung qu\xe1 m\u1ee9c v\xe0o m\u1ed9t ng\u01b0\u1eddi hay kh\xf4ng. Ngo\xe0i ra c\u0169ng c\u1ea7n ki\u1ec3m tra c\xf3 vi\u1ec7c n\xe0o hai ng\u01b0\u1eddi \u0111ang c\xf9ng l\xe0m ho\u1eb7c ng\u01b0\u1ee3c l\u1ea1i kh\xf4ng c\xf3 ai ph\u1ee5 tr\xe1ch hay kh\xf4ng. Sau khi nghe t\xecnh h\xecnh hai ph\xeda, c\xf3 th\u1ec3 \u0111i\u1ec1u ch\u1ec9nh l\u1ea1i ph\u1ea1m vi ph\u1ee5 tr\xe1ch d\u1ef1a tr\xean kh\u1ed1i l\u01b0\u1ee3ng v\xe0 m\u1ee9c \u0111\u1ed9 th\xe0nh th\u1ea1o. Sau khi \u0111i\u1ec1u ch\u1ec9nh, n\xean theo d\xf5i m\u1ed9t tu\u1ea7n ho\u1eb7c m\u1ed9t kho\u1ea3ng th\u1eddi gian xem v\u1ea5n \u0111\u1ec1 th\u1ef1c t\u1ebf c\xf3 gi\u1ea3m kh\xf4ng v\xe0 s\u1eeda l\u1ea1i n\u1ebfu c\u1ea7n.")
A.iGG=s([A.cTR,A.cTP,A.cTY],t.l5)
