A.j_a=s(["Hai t\u1eeb ho\xe0n to\xe0n gi\u1ed1ng nhau","\ud3c9\ub4f1 nh\u1ea5n m\u1ea1nh b\xecnh \u0111\u1eb3ng, \ud615\ud3c9\uc131 xem x\xe9t c\u1ea3 ho\xe0n c\u1ea3nh v\xe0 nhu c\u1ea7u","\ud615\ud3c9\uc131 ch\u1ec9 c\xf3 ngh\u0129a l\xe0 thu\u1ebf","\ud3c9\ub4f1 ch\u1ec9 d\xf9ng trong tr\u01b0\u1eddng h\u1ecdc"],t.s)
A.dBh=new B.a5("\ud3c9\ub4f1\uacfc \ud615\ud3c9\uc131\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",A.j_a,1,"\ud3c9\ub4f1 v\xe0 \ud615\ud3c9\uc131 c\xf3 li\xean quan nh\u01b0ng kh\xf4ng ho\xe0n to\xe0n \u0111\u1ed3ng nh\u1ea5t.","\uc0ac\ud68c \uc774\ud574","\uace0\uae09")
