A.jk5=s(["Ch\u1ec9 t\u0103ng l\u01b0\u1ee3ng c\xf4ng vi\u1ec7c","\u0110\xe3i ng\u1ed9 + m\xf4i tr\u01b0\u1eddng + c\u01a1 h\u1ed9i ph\xe1t tri\u1ec3n","Kh\xf4ng c\u1ea7n \u0111\xe0o t\u1ea1o","Ch\u1ec9 tuy\u1ec3n ng\u01b0\u1eddi m\u1edbi"],t.s)
A.dCV=new B.a5("C\xf4ng ty mu\u1ed1n gi\u1eef nh\xe2n vi\xean gi\u1ecfi th\xec \u0111i\u1ec1u n\xe0o ph\xf9 h\u1ee3p nh\u1ea5t?",A.jk5,1,"\u0110\xe3i ng\u1ed9, m\xf4i tr\u01b0\u1eddng l\xe0m vi\u1ec7c v\xe0 c\u01a1 h\u1ed9i ph\xe1t tri\u1ec3n \u0111\u1ec1u \u1ea3nh h\u01b0\u1edfng \u0111\u1ebfn kh\u1ea3 n\u0103ng gi\u1eef nh\xe2n t\xe0i.","\uc2e4\uc804","\uace0\uae09")
A.i4g=s(["\ub178\ub3d9\ub825 \ubd80\uc871","\ub178\ub3d9\ub825 \uae09\uc99d","\uc778\ub825 \uacfc\uc789","\uc815\ub144 \uac10\uc18c\ub9cc"],t.s)
A.dC3=new B.a5("\uc800\ucd9c\uc0b0\uacfc \uace0\ub839\ud654\uac00 \uc9c0\uc18d\ub418\uba74 \uc5b4\ub5a4 \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud560 \uac00\ub2a5\uc131\uc774 \ud07d\ub2c8\uae4c?",A.i4g,0,"\uc800\ucd9c\uc0b0\uacfc \uace0\ub839\ud654\ub294 \uc7a5\uae30\uc801\uc73c\ub85c \ub178\ub3d9\ub825 \ubd80\uc871\uc744 \uc2ec\ud654\uc2dc\ud0ac \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc0ac\ud68c","\uace0\uae09")
A.htm=s([A.dDG,A.dCl,A.dFp,A.dDF,A.dFq,A.dFE,A.dF2,A.dDY,A.dEB,A.dDk,A.dCK,A.dFs,A.dDS,A.dBm,A.dBs,A.dAK,A.dCV,A.dC3],t.yc)
A.hUG=s(["\uc800\ucd9c\uc0b0","\uace0\ub839\ud654","\uadfc\ubb34 \ud658\uacbd","\uc219\ub828\uacf5","\uc9c0\ubc29","\uc678\uad6d\uc778 \uadfc\ub85c\uc790"],t.s)
A.dHc=new B.dj("\ud55c\uad6d\uc758 \uc81c\uc870\uc5c5\uc5d0\uc11c \uc778\ub825 \ubd80\uc871\uc774 \ubc1c\uc0dd\ud558\ub294 \uc774\uc720\ub294 \ubb34\uc5c7\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\uae4c?",A.hUG,"\uc81c\uc870\uc5c5\uc758 \uc778\ub825 \ubd80\uc871\uc5d0\ub294 \uc5ec\ub7ec \uc6d0\uc778\uc774 \uc788\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uc800\ucd9c\uc0b0\uacfc \uace0\ub839\ud654\ub85c \uc0dd\uc0b0\uac00\ub2a5\uc778\uad6c\uac00 \uac10\uc18c\ud558\uace0 \uc788\uace0 \uc80a\uc740 \uce35\uc774 \ud798\ub4e0 \ud604\uc7a5 \uc5c5\ubb34\ub97c \uc120\ud638\ud558\uc9c0 \uc54a\ub294 \uacbd\uc6b0\ub3c4 \ub9ce\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 \uc9c0\ubc29 \uc911\uc18c\uae30\uc5c5\uc740 \uc219\ub828 \uc778\ub825\uc744 \ud655\ubcf4\ud558\uae30\uac00 \ub354 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uadfc\ubb34 \ud658\uacbd\uc744 \uac1c\uc120\ud558\ub294 \ub3d9\uc2dc\uc5d0 \uc678\uad6d\uc778 \uadfc\ub85c\uc790 \ud65c\uc6a9\uacfc \uc790\ub3d9\ud654, \uc9c1\uc5c5 \uad50\uc721\uc744 \ud568\uaed8 \ud655\ub300\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.")
A.jEt=s(["\uc784\uae08","\ubcf5\ub9ac\ud6c4\uc0dd","\uace0\uc6a9 \uc548\uc815","\uacbd\ub825 \uac1c\ubc1c","\uadfc\ubb34 \ud658\uacbd","\uc6cc\ub77c\ubc38"],t.s)
A.dHj=new B.dj("\uc9c1\uc7a5\uc744 \uc120\ud0dd\ud560 \ub54c \uac00\uc7a5 \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud558\ub294 \uc870\uac74\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.jEt,"\uc800\ub294 \uc784\uae08\ub3c4 \uc911\uc694\ud558\uc9c0\ub9cc \uc7a5\uae30\uc801\uc73c\ub85c \uacbd\ub825\uc744 \ubc1c\uc804\uc2dc\ud0ac \uc218 \uc788\ub294\uc9c0\uac00 \ub354 \uc911\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uc0c8\ub85c\uc6b4 \uae30\uc220\uc744 \ubc30\uc6b8 \uc218 \uc788\uace0 \uc5c5\ubb34 \uacbd\ud5d8\uc744 \ub113\ud790 \uc218 \uc788\ub294 \ud68c\uc0ac\ub77c\uba74 \ucc98\uc74c \uc5f0\ubd09\uc774 \uc870\uae08 \ub0ae\ub354\ub77c\ub3c4 \uc7a5\uae30\uc801\uc73c\ub85c \ub354 \uc88b\uc740 \uc120\ud0dd\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.")
A.hRQ=s(["\uc7ac\uad50\uc721","\uc9c1\ubb34 \uc804\ud658","\ub514\uc9c0\ud138 \uae30\uc220","\ubb38\uc81c \ud574\uacb0","\uc804\ubb38\uc131"],t.s)
A.dHH=new B.dj("\uc790\ub3d9\ud654\uac00 \ud655\ub300\ub418\uba74 \uadfc\ub85c\uc790\ub294 \ubb34\uc5c7\uc744 \uc900\ube44\ud574\uc57c \ud569\ub2c8\uae4c?",A.hRQ,"\uc790\ub3d9\ud654\ub85c \ubc18\ubcf5\uc801\uc778 \uc5c5\ubb34\uac00 \uc904\uc5b4\ub4e4 \uac00\ub2a5\uc131\uc774 \uc788\uae30 \ub54c\ubb38\uc5d0 \uadfc\ub85c\uc790\ub3c4 \uc0c8\ub85c\uc6b4 \uae30\uc220\uc744 \uacc4\uc18d \ubc30\uc6cc\uc57c \ud569\ub2c8\ub2e4. \ud2b9\ud788 \uc124\ube44 \uc6b4\uc601\uc774\ub098 \ub370\uc774\ud130 \ud65c\uc6a9\uacfc \uac19\uc740 \ub514\uc9c0\ud138 \uae30\uc220\uc744 \uc775\ud788\uace0 \uc0ac\ub78c\uc774 \ub354 \uc798\ud560 \uc218 \uc788\ub294 \ubb38\uc81c \ud574\uacb0\uacfc \uc758\uc0ac\uc18c\ud1b5 \ub2a5\ub825\uc744 \uac15\ud654\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.")
A.hMk=s([A.dHc,A.dHj,A.dHH],t.Gu)
A.j6A=s(["\ud604\uc7ac \ubb38\uc81c\ub97c \uc124\uba85\ud558\uc138\uc694.","\uc778\ub825 \ubd80\uc871\uc758 \uc6d0\uc778\uc744 \uc4f0\uc138\uc694.","\uae30\uc5c5\uc774 \ud560 \uc218 \uc788\ub294 \uc77c\uc744 \uc81c\uc548\ud558\uc138\uc694.","\uc815\ubd80\uc758 \uc5ed\ud560\uc744 \uc124\uba85\ud558\uc138\uc694.","\ubcf8\uc778\uc758 \uc758\uacac\uc744 \uc815\ub9ac\ud558\uc138\uc694."],t.s)
A.e30=new B.ek("\uc81c\uc870\uc5c5\uc758 \uc778\ub825 \ubd80\uc871 \ubb38\uc81c\uc640 \ud574\uacb0 \ubc29\uc548",A.j6A,"\ucd5c\uadfc \uc81c\uc870\uc5c5\uc5d0\uc11c\ub294 \uc219\ub828 \uc778\ub825 \ubd80\uc871 \ubb38\uc81c\uac00 \uc810\uc810 \uc2ec\uac01\ud574\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc800\ucd9c\uc0b0\uacfc \uace0\ub839\ud654\ub85c \uc0dd\uc0b0\uac00\ub2a5\uc778\uad6c\uac00 \uac10\uc18c\ud558\uace0 \uc788\uc73c\uba70 \uc80a\uc740 \uce35\uc774 \uc81c\uc870 \ud604\uc7a5\ubcf4\ub2e4 \ub2e4\ub978 \uc9c1\uc885\uc744 \uc120\ud638\ud558\ub294 \uac83\ub3c4 \ud55c \uc6d0\uc778\uc785\ub2c8\ub2e4. \uae30\uc5c5\uc740 \ub2e8\uc21c\ud788 \uc2e0\uaddc \ucc44\uc6a9\uc744 \ud655\ub300\ud558\ub294 \ub370 \uadf8\uce58\uc9c0 \uc54a\uace0 \uadfc\ubb34 \ud658\uacbd\uacfc \ucc98\uc6b0\ub97c \uac1c\uc120\ud558\uace0 \uae30\uc874 \uc9c1\uc6d0\uc758 \uc9c1\ubb34 \uad50\uc721\uc744 \uac15\ud654\ud574\uc57c \ud569\ub2c8\ub2e4. \ub610\ud55c \uc790\ub3d9\ud654\ub97c \ud1b5\ud574 \ubc18\ubcf5\uc801\uc778 \uc5c5\ubb34\ub97c \uc904\uc774\ub294 \uac83\ub3c4 \ud544\uc694\ud569\ub2c8\ub2e4. \uc815\ubd80\ub294 \uc9c1\uc5c5 \uad50\uc721\uc744 \ud655\ub300\ud558\uace0 \uc678\uad6d\uc778 \uc804\ubb38 \uc778\ub825\uc774 \uc548\uc815\uc801\uc73c\ub85c \uadfc\ubb34\ud560 \uc218 \uc788\ub294 \uc81c\ub3c4\ub97c \ub9c8\ub828\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.")
A.hpO=s(["\ub178\ub3d9\uc2dc\uc7a5\uc758 \ubcc0\ud654\ub97c \uc124\uba85\ud558\uc138\uc694.","\uac10\uc18c\ud560 \uac00\ub2a5\uc131\uc774 \uc788\ub294 \uc5c5\ubb34\ub97c \uc4f0\uc138\uc694.","\uc0c8\ub86d\uac8c \uc99d\uac00\ud560 \uc9c1\ubb34\ub97c \uc124\uba85\ud558\uc138\uc694.","\uadfc\ub85c\uc790\uc5d0\uac8c \ud544\uc694\ud55c \ub2a5\ub825\uc744 \uc81c\uc2dc\ud558\uc138\uc694.","\ubcf8\uc778\uc758 \uc900\ube44 \uacc4\ud68d\uc744 \uc4f0\uc138\uc694."],t.s)
A.e35=new B.ek("\ubbf8\ub798 \ub178\ub3d9\uc2dc\uc7a5\uc5d0 \ud544\uc694\ud55c \ub2a5\ub825",A.hpO,"\uc778\uacf5\uc9c0\ub2a5\uacfc \uc790\ub3d9\ud654 \uae30\uc220\uc774 \ubc1c\uc804\ud558\uba74\uc11c \ub178\ub3d9\uc2dc\uc7a5\ub3c4 \ube60\ub974\uac8c \ubcc0\ud654\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ubc18\ubcf5\uc801\uc774\uace0 \ub2e8\uc21c\ud55c \uc5c5\ubb34\ub294 \uac10\uc18c\ud560 \uac00\ub2a5\uc131\uc774 \uc788\ub294 \ubc18\uba74\uc5d0 AI, \ub370\uc774\ud130, \uc790\ub3d9\ud654 \uc124\ube44\uc640 \uad00\ub828\ub41c \uc9c1\ubb34\ub294 \uc99d\uac00\ud560 \uac83\uc73c\ub85c \uc608\uc0c1\ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc55e\uc73c\ub85c\ub294 \ud55c \uac00\uc9c0 \uae30\uc220\ub9cc \uac00\uc9c0\uace0 \uc624\ub7ab\ub3d9\uc548 \uc77c\ud558\uae30\ubcf4\ub2e4 \ubcc0\ud654\uc5d0 \ub9de\ucdb0 \uc0c8\ub85c\uc6b4 \uae30\uc220\uc744 \ubc30\uc6b0\ub294 \ub2a5\ub825\uc774 \uc911\uc694\ud574\uc9c8 \uac83\uc785\ub2c8\ub2e4. \ub610\ud55c \ubb38\uc81c\ub97c \ubd84\uc11d\ud558\uace0 \ub3d9\ub8cc\uc640 \ud611\ub825\ud558\ub294 \ub2a5\ub825\uc740 \uc790\ub3d9\ud654\ud558\uae30 \uc5b4\ub824\uc6b4 \uc601\uc5ed\uc774\uae30 \ub54c\ubb38\uc5d0 \ub354\uc6b1 \uc911\uc694\ud574\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc800\ub3c4 \ud604\uc7a5 \uacbd\ud5d8\uc744 \ubc14\ud0d5\uc73c\ub85c \ub514\uc9c0\ud138 \uae30\uc220\uacfc \ud55c\uad6d\uc5b4 \uc758\uc0ac\uc18c\ud1b5 \ub2a5\ub825\uc744 \uacc4\uc18d \ubc1c\uc804\uc2dc\ud0a4\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.")
A.i4D=s([A.e30,A.e35],t.Qd)
A.i3X=s(["\ub178\ub3d9\uc2dc\uc7a5","\ucc44\uc6a9","\uace0\uc6a9","\ucde8\uc5c5","\uc2e4\uc5c5","\uc784\uae08","\ubcf5\uc9c0","\uc9c1\ubb34","\uc774\uc9c1","\ud1f4\uc0ac","\uc778\ub825 \ubd80\uc871","\uc678\uad6d\uc778 \uadfc\ub85c\uc790","\uc9c1\uc5c5 \uad50\uc721","\uace0\uc6a9 \uc548\uc815"],t.s)
A.hkD=s(["-\ub294 \ucd94\uc138\uc774\ub2e4","-(\uc73c)\u3139 \uc804\ub9dd\uc774\ub2e4","-\uc5d0 \ub530\ub77c","-\uc5d0 \ube44\ud574","-\ub294 \ub370 \ube44\ud574","-\ub294 \ub9cc\ud07c","-\uc9c0 \uc54a\uc744 \uc218 \uc5c6\ub2e4","-\uae30 \ub9c8\ub828\uc774\ub2e4","-\ub294 \uac00\uc6b4\ub370","-(\uc73c)\u3139 \uc6b0\ub824\uac00 \uc788\ub2e4","-\uc744/\ub97c \uace0\ub824\ud558\uba74","-\ub294 \ub370 \uc788\uc5b4\uc11c","-\ub290\ub0d0\uc5d0 \ub530\ub77c","-\ub294 \ubc18\uba74\uc5d0","-\uace0\uc790 \ud558\ub2e4"],t.s)
A.hhf=s(["\ucc44\uc6a9\uc740 \ud68c\uc0ac\uac00 \uc0ac\ub78c\uc744 \ubf51\ub294 \uacfc\uc815\uc774\uace0 \ucde8\uc5c5\uc740 \uac1c\uc778\uc774 \uc9c1\uc7a5\uc744 \uad6c\ud574 \uc77c\ud558\uac8c \ub418\ub294 \uac83\uc744 \ub9d0\ud55c\ub2e4.","\uace0\uc6a9\uc740 \uae30\uc5c5\uc774 \uc0ac\ub78c\uc744 \uace0\uc6a9\ud558\uc5ec \uc77c\uc744 \ub9e1\uae30\ub294 \uad00\uacc4\ub97c \uc758\ubbf8\ud55c\ub2e4.","\uc2e4\uc5c5\ub960\uc740 \uacbd\uc81c\uc640 \ub178\ub3d9\uc2dc\uc7a5 \uc0c1\ud669\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc911\uc694\ud55c \uc9c0\ud45c\uc774\ub2e4.","\uc778\ub825 \ubd80\uc871\uc740 \ub2e8\uc21c\ud788 \uc0ac\ub78c\uc774 \uc801\ub2e4\ub294 \uc758\ubbf8\ubfd0 \uc544\ub2c8\ub77c \ud544\uc694\ud55c \uae30\uc220\uc744 \uac00\uc9c4 \uc0ac\ub78c\uc774 \ubd80\uc871\ud55c \uacbd\uc6b0\ub3c4 \ud3ec\ud568\ud55c\ub2e4.","\uc815\uaddc\uc9c1\uacfc \ube44\uc815\uaddc\uc9c1\uc740 \uacc4\uc57d \uae30\uac04\uacfc \uace0\uc6a9 \uc548\uc815\uc131 \ub4f1\uc5d0\uc11c \ucc28\uc774\uac00 \uc788\ub2e4.","\uc784\uae08\ubfd0\ub9cc \uc544\ub2c8\ub77c \ubcf5\uc9c0\uc640 \uadfc\ubb34 \ud658\uacbd\ub3c4 \uc9c1\uc7a5\uc744 \uc120\ud0dd\ud558\ub294 \uc911\uc694\ud55c \uae30\uc900\uc774\ub2e4.","\uc790\ub3d9\ud654\uac00 \ud655\ub300\ub418\uba74 \uc77c\ubd80 \uc9c1\ubb34\ub294 \uac10\uc18c\ud558\uace0 \uc0c8\ub85c\uc6b4 \uc9c1\ubb34\ub294 \uc99d\uac00\ud560 \uc218 \uc788\ub2e4.","\uc9c1\ubb34 \uc804\ud658\uc744 \uc704\ud574\uc11c\ub294 \uc7ac\uad50\uc721\uacfc \uc0c8\ub85c\uc6b4 \uae30\uc220 \uc2b5\ub4dd\uc774 \ud544\uc694\ud558\ub2e4.","\uc800\ucd9c\uc0b0\uacfc \uace0\ub839\ud654\ub294 \uc7a5\uae30\uc801\uc73c\ub85c \ub178\ub3d9\ub825 \ubd80\uc871 \ubb38\uc81c\ub97c \uc2ec\ud654\uc2dc\ud0ac \uc218 \uc788\ub2e4.","\uc548\uc815\uc801\uc778 \ub178\ub3d9\uc2dc\uc7a5\uc744 \uc704\ud574 \uae30\uc5c5, \uc815\ubd80, \uadfc\ub85c\uc790 \ubaa8\ub450\uc758 \ub178\ub825\uc774 \ud544\uc694\ud558\ub2e4."],t.s)
