A.dBu=new B.a5("\uac74\uac15\ud55c \ubbf8\ub514\uc5b4 \uc774\uc6a9 \ubc29\ubc95\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",A.i3F,1,"\uc5ec\ub7ec \ucd9c\ucc98\ub97c \ube44\uad50\ud558\uace0 \uacfc\ub3c4\ud55c \ubbf8\ub514\uc5b4 \uc774\uc6a9\uc744 \uc870\uc808\ud558\ub294 \uac83\uc774 \ubc14\ub78c\uc9c1\ud569\ub2c8\ub2e4.","\uc2e4\uc804","\uc911\uc0c1")
A.jbk=s([A.dCd,A.dEF,A.dB0,A.dEQ,A.dEl,A.dAS,A.dCw,A.dE4,A.dC8,A.dBK,A.dBw,A.dEa,A.dAJ,A.dCn,A.dDd,A.dES,A.dF1,A.dBu],t.yc)
A.ieP=s(["\ucd9c\ucc98","\uacf5\uc2dd \uc790\ub8cc","\ub0a0\uc9dc","\uc5ec\ub7ec \uc5b8\ub860\uc0ac","\uadfc\uac70","\uc0ac\uc2e4 \ud655\uc778"],t.s)
A.dHW=new B.dj("\uc778\ud130\ub137\uc5d0\uc11c \ubcf8 \uc815\ubcf4\uac00 \uc0ac\uc2e4\uc778\uc9c0 \uc5b4\ub5bb\uac8c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\uae4c?",A.ieP,"\uc778\ud130\ub137\uc5d0\uc11c \uc815\ubcf4\ub97c \ubd24\uc744 \ub54c\ub294 \uba3c\uc800 \ub204\uac00 \uc791\uc131\ud588\ub294\uc9c0\uc640 \ucd9c\ucc98\uac00 \uc5b4\ub514\uc778\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \ub610\ud55c \uc624\ub798\ub41c \uc815\ubcf4\uac00 \ub2e4\uc2dc \uacf5\uc720\ub418\ub294 \uacbd\uc6b0\ub3c4 \uc788\uae30 \ub54c\ubb38\uc5d0 \uc791\uc131 \ub0a0\uc9dc\ub3c4 \uc0b4\ud3b4\ubcfc \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc911\uc694\ud55c \ub0b4\uc6a9\uc774\ub77c\uba74 \ud55c \uac00\uc9c0 \uac8c\uc2dc\ubb3c\ub9cc \ubbff\uae30\ubcf4\ub2e4 \uacf5\uc2dd \uae30\uad00\uc758 \uc790\ub8cc\ub098 \uc5ec\ub7ec \uc5b8\ub860\uc0ac\uc758 \ubcf4\ub3c4\ub97c \ube44\uad50\ud55c \ub4a4 \ud310\ub2e8\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.")
A.hlw=s(["\uc815\ubcf4 \uacf5\uc720","\uc18d\ub3c4","\ud5c8\uc704 \uc815\ubcf4","\uc18c\ud1b5","\uc911\ub3c5","\uc5ec\ub860"],t.s)
A.dH6=new B.dj("SNS\uc758 \uc7a5\uc810\uacfc \ub2e8\uc810\uc740 \ubb34\uc5c7\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\uae4c?",A.hlw,"SNS\uc758 \uac00\uc7a5 \ud070 \uc7a5\uc810\uc740 \ub204\uad6c\ub098 \ube60\ub974\uac8c \uc815\ubcf4\ub97c \uacf5\uc720\ud558\uace0 \ub2e4\ub978 \uc0ac\ub78c\uacfc \uc18c\ud1b5\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uae34\uae09\ud55c \uc0c1\ud669\uc5d0\uc11c\ub294 \ud544\uc694\ud55c \uc815\ubcf4\uac00 \ub9e4\uc6b0 \ube60\ub974\uac8c \uc804\ub2ec\ub420 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ubc18\uba74\uc5d0 \uc0ac\uc2e4\uc774 \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc815\ubcf4\ub3c4 \uac19\uc740 \uc18d\ub3c4\ub85c \ud655\uc0b0\ub420 \uc218 \uc788\uace0 \uc0ac\uc6a9 \uc2dc\uac04\uc774 \uc9c0\ub098\uce58\uac8c \uae38\uc5b4\uc9c0\uba74 \uc77c\uc0c1\uc0dd\ud65c\uc774\ub098 \uc218\uba74\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.")
A.jyn=s(["\uc5b8\ub860\uc0ac","\ud50c\ub7ab\ud3fc","\uc774\uc6a9\uc790","\uc0ac\uc2e4 \ud655\uc778","\uad50\uc721","\ucc45\uc784"],t.s)
A.dI_=new B.dj("\uac00\uc9dc \ub274\uc2a4 \ubb38\uc81c\ub97c \uc904\uc774\uae30 \uc704\ud574 \ub204\uac00 \ub178\ub825\ud574\uc57c \ud569\ub2c8\uae4c?",A.jyn,"\uac00\uc9dc \ub274\uc2a4 \ubb38\uc81c\ub294 \ud55c\ucabd\uc758 \ub178\ub825\ub9cc\uc73c\ub85c \ud574\uacb0\ud558\uae30 \uc5b4\ub835\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uc5b8\ub860\uc0ac\ub294 \uc815\ud655\ud55c \uc0ac\uc2e4 \ud655\uc778\uacfc \uc815\uc815\ubcf4\ub3c4\uc5d0 \ucc45\uc784\uc744 \uac00\uc838\uc57c \ud558\uace0 \ud50c\ub7ab\ud3fc\ub3c4 \ud5c8\uc704 \uc815\ubcf4\uac00 \uacfc\ub3c4\ud558\uac8c \ud655\uc0b0\ub418\uc9c0 \uc54a\ub3c4\ub85d \uad00\ub9ac\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc774\uc6a9\uc790 \uc5ed\uc2dc \uc815\ubcf4\ub97c \ubc14\ub85c \uacf5\uc720\ud558\uae30\ubcf4\ub2e4 \ucd9c\ucc98\uc640 \uadfc\uac70\ub97c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \ud559\uad50\uc640 \uc0ac\ud68c\uc5d0\uc11c \ubbf8\ub514\uc5b4 \ub9ac\ud130\ub7ec\uc2dc \uad50\uc721\uc744 \uac15\ud654\ud558\ub294 \uac83\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.iZi=s([A.dHW,A.dH6,A.dI_],t.Gu)
A.iyF=s(["\uac00\uc9dc \ub274\uc2a4\uc758 \ud2b9\uc9d5\uc744 \uc124\uba85\ud558\uc138\uc694.","\ud655\uc0b0\ub418\ub294 \uc774\uc720\ub97c \uc4f0\uc138\uc694.","\uac1c\uc778\uacfc \uc0ac\ud68c\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc744 \uc124\uba85\ud558\uc138\uc694.","\uc774\uc6a9\uc790\uac00 \ud574\uc57c \ud560 \uc77c\uc744 \uc4f0\uc138\uc694.","\uc5b8\ub860\uacfc \ud50c\ub7ab\ud3fc\uc758 \uc5ed\ud560\uc744 \uc81c\uc548\ud558\uc138\uc694."],t.s)
A.e34=new B.ek("\uac00\uc9dc \ub274\uc2a4\uac00 \uc0ac\ud68c\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uacfc \ud574\uacb0 \ubc29\uc548",A.iyF,"\uc778\ud130\ub137\uacfc SNS\uac00 \ubc1c\ub2ec\ud558\uba74\uc11c \ub204\uad6c\ub098 \uc27d\uac8c \uc815\ubcf4\ub97c \uc0dd\uc0b0\ud558\uace0 \uacf5\uc720\ud560 \uc218 \uc788\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uc774\ub7ec\ud55c \ubcc0\ud654\ub294 \uc815\ubcf4 \uc811\uadfc\uc131\uc744 \ub192\uc600\uc9c0\ub9cc \ud655\uc778\ub418\uc9c0 \uc54a\uc740 \uc815\ubcf4\uac00 \ube60\ub974\uac8c \ud655\uc0b0\ub418\ub294 \ubb38\uc81c\ub3c4 \ub9cc\ub4e4\uc5c8\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 \uc790\uadf9\uc801\uc778 \uc81c\ubaa9\uc774\ub098 \uc0ac\ub78c\ub4e4\uc758 \ubd88\uc548\uc744 \uc774\uc6a9\ud55c \ud5c8\uc704 \uc815\ubcf4\ub294 \uc0ac\uc2e4\ubcf4\ub2e4 \ub354 \ube60\ub974\uac8c \ud37c\uc9c8 \uac00\ub2a5\uc131\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uac00\uc9dc \ub274\uc2a4\uac00 \ubc18\ubcf5\uc801\uc73c\ub85c \ud655\uc0b0\ub418\uba74 \uac1c\uc778\uc774 \uc798\ubabb\ub41c \ud310\ub2e8\uc744 \ud560 \uc218 \uc788\uc744 \ubfd0\ub9cc \uc544\ub2c8\ub77c \uc0ac\ud68c\uc801 \uac08\ub4f1\uacfc \ubd88\uc2e0\ub3c4 \ucee4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc774\uc6a9\uc790\ub294 \uc815\ubcf4\ub97c \uacf5\uc720\ud558\uae30 \uc804\uc5d0 \ucd9c\ucc98\uc640 \uadfc\uac70\ub97c \ud655\uc778\ud574\uc57c \ud558\uba70 \uc5b8\ub860\uacfc \ud50c\ub7ab\ud3fc\ub3c4 \uc0ac\uc2e4 \ud655\uc778\uacfc \uc798\ubabb\ub41c \uc815\ubcf4\uc758 \uc815\uc815\uc5d0 \ucc45\uc784\uc744 \uac00\uc838\uc57c \ud569\ub2c8\ub2e4.")
A.jaQ=s(["\ub514\uc9c0\ud138 \uc815\ubcf4 \ud658\uacbd\uc758 \ud2b9\uc9d5\uc744 \uc124\uba85\ud558\uc138\uc694.","\ubbf8\ub514\uc5b4 \ub9ac\ud130\ub7ec\uc2dc\uc758 \uc758\ubbf8\ub97c \uc4f0\uc138\uc694.","\ucd94\ucc9c \uc54c\uace0\ub9ac\uc998\uc758 \uc601\ud5a5\uc744 \uc124\uba85\ud558\uc138\uc694.","\uac1c\uc778\uc774 \uac00\uc838\uc57c \ud560 \ud0dc\ub3c4\ub97c \uc4f0\uc138\uc694.","\uad50\uc721\uc758 \ud544\uc694\uc131\uc744 \uc81c\uc548\ud558\uc138\uc694."],t.s)
A.e2K=new B.ek("\ub514\uc9c0\ud138 \uc2dc\ub300\uc5d0 \ud544\uc694\ud55c \ubbf8\ub514\uc5b4 \ub9ac\ud130\ub7ec\uc2dc",A.jaQ,"\ub514\uc9c0\ud138 \uc2dc\ub300\uc5d0\ub294 \ub9e4\uc77c \ub9e4\uc6b0 \ub9ce\uc740 \uc815\ubcf4\uac00 \ub2e4\uc591\ud55c \ud50c\ub7ab\ud3fc\uc744 \ud1b5\ud574 \uc81c\uacf5\ub429\ub2c8\ub2e4. \ubb38\uc81c\ub294 \uc815\ubcf4\uc758 \uc591\uc774 \ub9ce\uc544\uc84c\ub2e4\uace0 \ud574\uc11c \ubaa8\ub4e0 \uc815\ubcf4\uc758 \uc9c8\uacfc \uc2e0\ub8b0\uc131\uc774 \ub192\uc544\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc810\uc785\ub2c8\ub2e4. \ud2b9\ud788 \ucd94\ucc9c \uc54c\uace0\ub9ac\uc998\uc740 \uc774\uc6a9\uc790\uc758 \uad00\uc2ec\uc0ac\uc5d0 \ub9de\ub294 \uc815\ubcf4\ub97c \ud3b8\ub9ac\ud558\uac8c \ubcf4\uc5ec \uc8fc\ub294 \ubc18\uba74\uc5d0 \ube44\uc2b7\ud55c \uc758\uacac\ub9cc \ubc18\ubcf5\uc801\uc73c\ub85c \uc811\ud558\uac8c \ub9cc\ub4e4 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \ud604\ub300 \uc0ac\ud68c\uc5d0\uc11c\ub294 \uc815\ubcf4\ub97c \ub2e8\uc21c\ud788 \uc18c\ube44\ud558\ub294 \ub2a5\ub825\ubcf4\ub2e4 \ucd9c\ucc98\uc640 \uadfc\uac70\ub97c \ud655\uc778\ud558\uace0 \ub2e4\ub978 \uad00\uc810\uacfc \ube44\uad50\ud558\ub294 \ubbf8\ub514\uc5b4 \ub9ac\ud130\ub7ec\uc2dc\uac00 \uc911\uc694\ud569\ub2c8\ub2e4. \uc774\ub7ec\ud55c \ub2a5\ub825\uc740 \uac1c\uc778\uc5d0\uac8c\ub9cc \ub9e1\uae30\uae30\ubcf4\ub2e4 \ud559\uad50\uc640 \uc0ac\ud68c \uad50\uc721\uc744 \ud1b5\ud574 \uc9c0\uc18d\uc801\uc73c\ub85c \uae38\ub7ec\uc57c \ud569\ub2c8\ub2e4.")
A.idW=s([A.e34,A.e2K],t.Qd)
A.iI7=s(["\uc5b8\ub860","\ubbf8\ub514\uc5b4","\ubcf4\ub3c4","\uae30\uc0ac","\ucd9c\ucc98","\uc0ac\uc2e4 \ud655\uc778","\ud5c8\uc704 \uc815\ubcf4","\uac00\uc9dc \ub274\uc2a4","\uc54c\uace0\ub9ac\uc998","\ucd94\ucc9c \uc2dc\uc2a4\ud15c","\uc5ec\ub860","\uc815\ubcf4 \uacfc\ubd80\ud558","\ubbf8\ub514\uc5b4 \ub9ac\ud130\ub7ec\uc2dc","\ube44\ud310\uc801 \uc0ac\uace0"],t.s)
A.iQb=s(["-\uc5d0 \ub530\ub974\uba74","-\ub294 \uac83\uc73c\ub85c \ub098\ud0c0\ub098\ub2e4","-\ub2e4\uace0 \ubcfc \uc218 \uc788\ub2e4","-\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4","-\uc5d0 \ube44\ud574","-\ub294 \ubc18\uba74\uc5d0","-\ub2e4\uace0 \ud574\uc11c","-\uc744/\ub97c \ud1b5\ud574","-\ub294 \uacfc\uc815\uc5d0\uc11c","-(\uc73c)\u3139 \uac00\ub2a5\uc131\uc774 \uc788\ub2e4","-\ub294 \ub370 \uadf8\uce58\uc9c0 \uc54a\uace0","-\uc744/\ub97c \ub458\ub7ec\uc2f8\uace0","-(\uc73c)\u3141\uc5d0\ub3c4 \ubd88\uad6c\ud558\uace0","-\uae30 \uc704\ud574\uc11c\ub294","-\ub294 \uac83\uc774 \ubc14\ub78c\uc9c1\ud558\ub2e4"],t.s)
A.hI6=s(["\uc5b8\ub860\uc740 \uc0ac\ud68c\uc758 \uc911\uc694\ud55c \uc0ac\uac74\uacfc \uc815\ubcf4\ub97c \ub300\uc911\uc5d0\uac8c \uc804\ub2ec\ud558\ub294 \uc5ed\ud560\uc744 \ud55c\ub2e4.","\ubbf8\ub514\uc5b4\ub294 \uc815\ubcf4\ub97c \uc804\ub2ec\ud558\ub294 \ub2e4\uc591\ud55c \uc218\ub2e8\uacfc \ud50c\ub7ab\ud3fc\uc744 \ud3ec\uad04\ud558\ub294 \uac1c\ub150\uc774\ub2e4.","\uc778\ud130\ub137\uc5d0\uc11c\ub294 \ub204\uad6c\ub098 \uc815\ubcf4\ub97c \uc0dd\uc0b0\ud560 \uc218 \uc788\uae30 \ub54c\ubb38\uc5d0 \ucd9c\ucc98\ub97c \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc774 \uc911\uc694\ud558\ub2e4.","\uac00\uc9dc \ub274\uc2a4\ub294 \uc0ac\uc2e4\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc \uc0ac\uc2e4\uacfc \ub2e4\ub978 \ub0b4\uc6a9\uc744 \ud3ec\ud568\ud558\ub294 \uc815\ubcf4\uc77c \uc218 \uc788\ub2e4.","\uae30\uc0ac \uc81c\ubaa9\ub9cc \ubcf4\uace0 \ub0b4\uc6a9\uc744 \ud310\ub2e8\ud558\uba74 \uc2e4\uc81c \ub0b4\uc6a9\uacfc \ub2e4\ub978 \uacb0\ub860\uc744 \ub0b4\ub9b4 \uac00\ub2a5\uc131\uc774 \uc788\ub2e4.","\uc54c\uace0\ub9ac\uc998 \uae30\ubc18 \ucd94\ucc9c\uc740 \ud3b8\ub9ac\ud558\uc9c0\ub9cc \ube44\uc2b7\ud55c \uc815\ubcf4\ub9cc \ubc18\ubcf5\uc801\uc73c\ub85c \uc811\ud558\uac8c \ub9cc\ub4e4 \uc218\ub3c4 \uc788\ub2e4.","SNS\uc5d0\uc11c \uc815\ubcf4\uac00 \ube60\ub974\uac8c \ud655\uc0b0\ub418\uba74 \uc798\ubabb\ub41c \uc815\ubcf4\ub3c4 \ud568\uaed8 \ud37c\uc9c8 \uc218 \uc788\ub2e4.","\ubbf8\ub514\uc5b4 \ub9ac\ud130\ub7ec\uc2dc\ub294 \uc815\ubcf4\ub97c \uc774\ud574\ud558\uace0 \ubd84\uc11d\ud558\uba70 \uc2e0\ub8b0\uc131\uc744 \ud310\ub2e8\ud558\ub294 \ub2a5\ub825\uc744 \uc758\ubbf8\ud55c\ub2e4.","\uac1c\uc778\uc740 \uc815\ubcf4\ub97c \uacf5\uc720\ud558\uae30 \uc804\uc5d0 \ucd9c\ucc98\uc640 \uc0ac\uc2e4 \uc5ec\ubd80\ub97c \ud655\uc778\ud560 \ucc45\uc784\uc774 \uc788\ub2e4.","\uac74\uac15\ud55c \uc815\ubcf4 \uc0ac\ud68c\ub97c \uc704\ud574 \uc5b8\ub860, \ud50c\ub7ab\ud3fc, \uc774\uc6a9\uc790\uc758 \ucc45\uc784\uc774 \ubaa8\ub450 \uc911\uc694\ud558\ub2e4."],t.s)
