A.jee=s(["-\uc5d0 \ub2ec\ub824 \uc788\ub2e4","-\uc744/\ub97c \uac10\uc548\ud558\uba74","-\ub294 \ub370 \ube44\ud574","-\ub294 \ubc18\uba74\uc5d0","-(\uc73c)\u3139\uc218\ub85d","-\uc5d0 \ub530\ub77c","-\uc744/\ub97c \uc911\uc2ec\uc73c\ub85c","-\ub294 \ud0d3\uc5d0","-(\uc73c)\u3139 \uc218\ubc16\uc5d0 \uc5c6\ub2e4","-\uae30\uc5d0\ub294","-\ub294 \uc148\uc774\ub2e4","-\uc744/\ub97c \uace0\ub824\ud560 \ub54c","-(\uc73c)\u3139 \uc6b0\ub824\uac00 \uc788\ub2e4","-\uc9c0 \uc54a\ub294 \ud55c","-\uae30 \ub9c8\ub828\uc774\ub2e4"],t.s)
A.iwe=s(["\uc804\uc138\ub294 \ud070 \ubcf4\uc99d\uae08\uc744 \ub9e1\uae30\uace0 \ub9e4\ub2ec \uc6d4\uc138\ub97c \ub0b4\uc9c0 \uc54a\ub294 \ubc29\uc2dd\uc774\uba70 \uc6d4\uc138\ub294 \ubcf4\uc99d\uae08\uacfc \ud568\uaed8 \ub9e4\ub2ec \uc784\ub300\ub8cc\ub97c \ub0b4\ub294 \ubc29\uc2dd\uc774\ub2e4.","\ubcf4\uc99d\uae08\uacfc \uc6d4\uc138 \uc678\uc5d0\ub3c4 \uad00\ub9ac\ube44\uc5d0 \uc5b4\ub5a4 \ud56d\ubaa9\uc774 \ud3ec\ud568\ub418\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud55c\ub2e4.","\uc784\ub300\ucc28 \uacc4\uc57d\uc744 \ud560 \ub54c\ub294 \uacc4\uc57d \uae30\uac04\uacfc \ubcf4\uc99d\uae08 \ubc18\ud658 \uc870\uac74\uc744 \ud655\uc778\ud574\uc57c \ud55c\ub2e4.","\uc8fc\ud0dd \uac00\uaca9\uc740 \uae08\ub9ac, \uacf5\uae09, \uc218\uc694, \uc9c0\uc5ed, \uad50\ud1b5 \ub4f1 \uc5ec\ub7ec \uc694\uc778\uc758 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4.","\uae08\ub9ac\uac00 \uc0c1\uc2b9\ud558\uba74 \uc8fc\ud0dd\ub2f4\ubcf4\ub300\ucd9c \uc774\uc790 \ubd80\ub2f4\uc774 \ucee4\uc9c8 \uc218 \uc788\ub2e4.","\uc8fc\uac70\ube44 \ubd80\ub2f4\uc774 \ucee4\uc9c0\uba74 \uccad\ub144\uce35\uc758 \uc18c\ube44\uc640 \uacb0\ud63c, \ucd9c\uc0b0\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub2e4.","\uc8fc\ud0dd \uacf5\uae09\uc774 \ubd80\uc871\ud55c \uc9c0\uc5ed\uc5d0\uc11c\ub294 \uac00\uaca9\uacfc \uc784\ub300\ub8cc\uac00 \uc0c1\uc2b9\ud560 \uac00\ub2a5\uc131\uc774 \uc788\ub2e4.","\uacf5\uacf5\uc8fc\ud0dd\uc740 \uc8fc\uac70 \ucde8\uc57d \uacc4\uce35\uc758 \uc8fc\uac70 \uc548\uc815\uc744 \uc9c0\uc6d0\ud558\ub294 \uc5ed\ud560\uc744 \ud55c\ub2e4.","\ubd80\ub3d9\uc0b0\uc740 \uac00\uaca9 \uc0c1\uc2b9 \uac00\ub2a5\uc131\ub9cc \ubcf4\uace0 \uacb0\uc815\ud558\uae30\ubcf4\ub2e4 \ub300\ucd9c \ubd80\ub2f4\uacfc \uc0dd\ud65c \uc5ec\uac74\ub3c4 \ud568\uaed8 \uac80\ud1a0\ud574\uc57c \ud55c\ub2e4.","\uacc4\uc57d \uc804\uc5d0 \ub4f1\uae30\uc640 \uc2e4\uc81c \uc8fc\ud0dd \uc0c1\ud0dc\ub97c \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc774 \uc911\uc694\ud558\ub2e4."],t.s)
