A.dHi=new B.dj("\uae30\uc5c5\uc774 \ud0c4\uc18c \ubc30\ucd9c\uc744 \uc904\uc774\uae30 \uc704\ud574 \ubb34\uc5c7\uc744 \ud560 \uc218 \uc788\uc2b5\ub2c8\uae4c?",A.hJt,"\uae30\uc5c5\uc740 \uba3c\uc800 \uc0dd\uc0b0 \uacfc\uc815\uc5d0\uc11c \uc0ac\uc6a9\ub418\ub294 \uc5d0\ub108\uc9c0\uc758 \uc591\uc744 \uc815\ud655\ud788 \ubd84\uc11d\ud574\uc57c \ud569\ub2c8\ub2e4. \uc5d0\ub108\uc9c0 \ud6a8\uc728\uc774 \ub0ae\uc740 \uc124\ube44\ub97c \uad50\uccb4\ud558\uace0 \ud0dc\uc591\uad11\uacfc \uac19\uc740 \uc7ac\uc0dd \uc5d0\ub108\uc9c0\uc758 \uc0ac\uc6a9\uc744 \ud655\ub300\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub610\ud55c \ubd88\ud544\uc694\ud55c \uc804\ub825 \uc18c\ube44\ub97c \uc904\uc774\uace0 \uacf5\uc815\uc744 \ucd5c\uc801\ud654\ud568\uc73c\ub85c\uc368 \ud0c4\uc18c \ubc30\ucd9c\ub7c9\uc744 \uc9c0\uc18d\uc801\uc73c\ub85c \uac10\ucd95\ud574\uc57c \ud569\ub2c8\ub2e4.")
A.jyJ=s(["\ub179\uc0c9 \uc131\uc7a5","\uae30\uc220 \ud601\uc2e0","\uce5c\ud658\uacbd","\ube44\uc6a9","\uc9c0\uc18d \uac00\ub2a5\uc131"],t.s)
A.dHf=new B.dj("\uacbd\uc81c \ubc1c\uc804\uacfc \ud658\uacbd \ubcf4\ud638\ub97c \ub3d9\uc2dc\uc5d0 \ud560 \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\uae4c?",A.jyJ,"\uacbd\uc81c \ubc1c\uc804\uacfc \ud658\uacbd \ubcf4\ud638\uac00 \ubc18\ub4dc\uc2dc \ubc18\ub300\ub418\ub294 \uac1c\ub150\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ucd08\uae30\uc5d0\ub294 \uce5c\ud658\uacbd \uae30\uc220\uc5d0 \ub9ce\uc740 \ube44\uc6a9\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc9c0\ub9cc \uc7a5\uae30\uc801\uc73c\ub85c\ub294 \uc5d0\ub108\uc9c0 \ube44\uc6a9\uc744 \uc904\uc774\uace0 \uc0c8\ub85c\uc6b4 \uc0b0\uc5c5\uacfc \uc77c\uc790\ub9ac\ub97c \ub9cc\ub4e4 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uae30\uc220 \ud601\uc2e0\uc744 \ubc14\ud0d5\uc73c\ub85c \ub179\uc0c9 \uc131\uc7a5\uc744 \ucd94\uc9c4\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.igM=s(["\ubd84\ub9ac\ubc30\ucd9c","\uc7ac\uc0ac\uc6a9","\uc77c\ud68c\uc6a9\ud488","\uc5d0\ub108\uc9c0 \uc808\uc57d","\ub300\uc911\uad50\ud1b5"],t.s)
A.dHk=new B.dj("\uac1c\uc778\uc774 \ud658\uacbd\uc744 \ubcf4\ud638\ud558\uae30 \uc704\ud574 \uc2e4\ucc9c\ud560 \uc218 \uc788\ub294 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.igM,"\uac1c\uc778\uc740 \uc77c\ud68c\uc6a9\ud488 \uc0ac\uc6a9\uc744 \uc904\uc774\uace0 \uc7ac\uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \uc81c\ud488\uc744 \uc120\ud0dd\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub610\ud55c \uc4f0\ub808\uae30\ub97c \uc815\ud655\ud558\uac8c \ubd84\ub9ac\ubc30\ucd9c\ud558\uace0 \ubd88\ud544\uc694\ud55c \uc804\uae30 \uc0ac\uc6a9\uc744 \uc904\uc774\ub294 \uac83\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4. \uac00\ub2a5\ud558\uba74 \uc790\ub3d9\ucc28 \ub300\uc2e0 \ub300\uc911\uad50\ud1b5\uc744 \uc774\uc6a9\ud558\ub294 \uac83\ub3c4 \ud0c4\uc18c \ubc30\ucd9c\uc744 \uc904\uc774\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.")
A.hkS=s([A.dHi,A.dHf,A.dHk],t.Gu)
A.jsO=s(["\ud604\uc7ac \ubb38\uc81c\ub97c \uc124\uba85\ud558\uc138\uc694.","\uc8fc\uc694 \ud0c4\uc18c \ubc30\ucd9c \uc6d0\uc778\uc744 \uc4f0\uc138\uc694.","\uad6c\uccb4\uc801\uc778 \uac10\ucd95 \ubc29\uc548\uc744 \uc81c\uc548\ud558\uc138\uc694.","\uacbd\uc81c\uc801 \ud6a8\uacfc\uc640 \ud658\uacbd\uc801 \ud6a8\uacfc\ub97c \uc124\uba85\ud558\uc138\uc694.","\uc7a5\uae30\uc801\uc778 \ubaa9\ud45c\ub97c \uc4f0\uc138\uc694."],t.s)
A.e3_=new B.ek("\uae30\uc5c5\uc758 \ud0c4\uc18c \ubc30\ucd9c \uac10\ucd95 \ubc29\uc548",A.jsO,"\uc6b0\ub9ac \ud68c\uc0ac\ub294 \uc0dd\uc0b0 \uc124\ube44\uc758 \uc804\ub825 \uc0ac\uc6a9\ub7c9\uc774 \ub9ce\uc544 \ud0c4\uc18c \ubc30\ucd9c\ub7c9\ub3c4 \ub192\uc740 \ud3b8\uc785\ub2c8\ub2e4. \ud2b9\ud788 \uc624\ub798\ub41c \uc124\ube44\ub294 \uc5d0\ub108\uc9c0 \ud6a8\uc728\uc774 \ub0ae\uc544 \ubd88\ud544\uc694\ud55c \uc804\ub825 \uc18c\ube44\uac00 \ubc1c\uc0dd\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub97c \uac1c\uc120\ud558\uae30 \uc704\ud574 \uace0\ud6a8\uc728 \uc124\ube44\ub85c \ub2e8\uacc4\uc801\uc73c\ub85c \uad50\uccb4\ud558\uace0 \uacf5\uc7a5 \uc9c0\ubd95\uc5d0 \ud0dc\uc591\uad11 \ubc1c\uc804 \uc2dc\uc124\uc744 \ud655\ub300\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ucd08\uae30 \ud22c\uc790 \ube44\uc6a9\uc740 \uc99d\uac00\ud560 \uc218 \uc788\uc9c0\ub9cc \uc7a5\uae30\uc801\uc73c\ub85c \uc804\ub825 \ube44\uc6a9\uc744 \uc904\uc774\uace0 \ud0c4\uc18c \ubc30\ucd9c\ub7c9\uc744 \uac10\ucd95\ud558\ub294 \ud6a8\uacfc\ub97c \uae30\ub300\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc55e\uc73c\ub85c\ub294 \uc0dd\uc0b0\ub7c9\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc81c\ud488\ub2f9 \ud0c4\uc18c \ubc30\ucd9c\ub7c9\ub3c4 \uc8fc\uc694 \uad00\ub9ac \uc9c0\ud45c\ub85c \ud65c\uc6a9\ud574\uc57c \ud569\ub2c8\ub2e4.")
A.iK_=s(["\ud604\uc7ac \ud658\uacbd \ubb38\uc81c\ub97c \uc124\uba85\ud558\uc138\uc694.","\uc815\ubd80\uc758 \uc5ed\ud560\uc744 \uc4f0\uc138\uc694.","\uae30\uc5c5\uc758 \uc5ed\ud560\uc744 \uc4f0\uc138\uc694.","\uac1c\uc778\uc758 \uc5ed\ud560\uc744 \uc4f0\uc138\uc694.","\ubcf8\uc778\uc758 \uc758\uacac\uc744 \uc815\ub9ac\ud558\uc138\uc694."],t.s)
A.e2P=new B.ek("\uc9c0\uc18d \uac00\ub2a5\ud55c \uc0ac\ud68c\ub97c \uc704\ud55c \uc6b0\ub9ac\uc758 \uc5ed\ud560",A.iK_,"\uae30\ud6c4 \ubcc0\ud654\uc640 \uc790\uc6d0 \uace0\uac08 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud574\uc11c\ub294 \uc815\ubd80\uc640 \uae30\uc5c5, \uac1c\uc778\uc774 \ubaa8\ub450 \ub178\ub825\ud574\uc57c \ud569\ub2c8\ub2e4. \uc815\ubd80\ub294 \uba85\ud655\ud55c \ud658\uacbd \uae30\uc900\uc744 \ub9c8\ub828\ud558\uace0 \uce5c\ud658\uacbd \uae30\uc220 \uac1c\ubc1c\uc744 \uc9c0\uc6d0\ud574\uc57c \ud569\ub2c8\ub2e4. \uae30\uc5c5\uc740 \uc0dd\uc0b0 \uacfc\uc815\uc5d0\uc11c \ubc1c\uc0dd\ud558\ub294 \uc624\uc5fc \ubb3c\uc9c8\uacfc \ud0c4\uc18c \ubc30\ucd9c\uc744 \uc904\uc774\ub294 \ud55c\ud3b8 \uc790\uc6d0\uc744 \ud6a8\uc728\uc801\uc73c\ub85c \uc0ac\uc6a9\ud574\uc57c \ud569\ub2c8\ub2e4. \uac1c\uc778\ub3c4 \ubd84\ub9ac\ubc30\ucd9c, \uc5d0\ub108\uc9c0 \uc808\uc57d, \uc77c\ud68c\uc6a9\ud488 \uc0ac\uc6a9 \uac10\uc18c\uc640 \uac19\uc740 \uc791\uc740 \ud589\ub3d9\uc744 \uafb8\uc900\ud788 \uc2e4\ucc9c\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc9c0\uc18d \uac00\ub2a5\ud55c \uc0ac\ud68c\ub294 \ud2b9\uc815 \uc9d1\ub2e8\uc758 \ub178\ub825\ub9cc\uc73c\ub85c \ub9cc\ub4e4 \uc218 \uc5c6\uc73c\uba70 \uc0ac\ud68c \uc804\uccb4\uc758 \uc7a5\uae30\uc801\uc778 \ud611\ub825\uc774 \ud544\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.")
A.i_M=s([A.e3_,A.e2P],t.Qd)
