A.iTT=s(["-\ub294 \ud0d3\uc5d0","-\ub294 \ub370 \ubc18\ud574","-(\uc73c)\u3139\uc218\ub85d","-\uc9c0 \uc54a\uc744 \uc218 \uc5c6\ub2e4","-\uace0\ub3c4 \ub0a8\ub2e4","-\ub294 \uc148\uc774\ub2e4","-\uc744/\ub97c \ub458\ub7ec\uc2f8\uace0","-\uae30\uc5d0 \uc55e\uc11c","-\ub294 \ud55c\ud3b8","-\uc5d0 \uc774\ub974\uae30\uae4c\uc9c0","-\uc744/\ub97c \uacc4\uae30\ub85c","-\uace0\uc790 \ud558\ub2e4","-(\uc73c)\u3141\uc73c\ub85c\uc368","-\uae30\uc5d0","-\uc9c0 \uc54a\uc73c\uba74 \uc548 \ub418\ub2e4"],t.s)
A.jhp=s(["\uae30\ud6c4 \ubcc0\ud654\ub294 \ub2e8\uc21c\ud55c \ud658\uacbd \ubb38\uc81c\uac00 \uc544\ub2c8\ub77c \uacbd\uc81c\uc640 \uc0ac\ud68c \uc804\uccb4\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce5c\ub2e4.","\uc628\uc2e4\uac00\uc2a4 \ubc30\ucd9c \uc99d\uac00\ub294 \uc9c0\uad6c \uc628\ub09c\ud654\uc758 \uc8fc\uc694 \uc6d0\uc778 \uc911 \ud558\ub098\uc774\ub2e4.","\ud0c4\uc18c \uc911\ub9bd\uc740 \ubc30\ucd9c\ud55c \ud0c4\uc18c\uc640 \ud761\uc218\ud558\uac70\ub098 \uc81c\uac70\ud55c \ud0c4\uc18c\uc758 \uc591\uc744 \uade0\ud615 \uc788\uac8c \ub9cc\ub4dc\ub294 \uac83\uc744 \uc758\ubbf8\ud55c\ub2e4.","\uc7ac\uc0dd \uc5d0\ub108\uc9c0\ub294 \uc9c0\uc18d \uac00\ub2a5\ud55c \uc5d0\ub108\uc9c0 \uccb4\uacc4\ub97c \ub9cc\ub4dc\ub294 \ub370 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud55c\ub2e4.","\uc790\uc6d0 \uace0\uac08\uc744 \uc904\uc774\uae30 \uc704\ud574 \uc7ac\uc0ac\uc6a9\uacfc \uc7ac\ud65c\uc6a9\uc744 \ud655\ub300\ud560 \ud544\uc694\uac00 \uc788\ub2e4.","\ud3d0\uae30\ubb3c\uc740 \ubc1c\uc0dd\ud55c \ud6c4 \ucc98\ub9ac\ud558\ub294 \uac83\ubcf4\ub2e4 \ubc1c\uc0dd \uc790\uccb4\ub97c \uc904\uc774\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4.","\uae30\uc5c5\uc740 \uc218\uc775\ubfd0\ub9cc \uc544\ub2c8\ub77c \ud658\uacbd\uacfc \uc0ac\ud68c\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\ub3c4 \uace0\ub824\ud574\uc57c \ud55c\ub2e4.","ESG \uacbd\uc601\uc740 \ud658\uacbd, \uc0ac\ud68c, \uc9c0\ubc30 \uad6c\uc870\ub97c \ud568\uaed8 \uace0\ub824\ud558\ub294 \uacbd\uc601 \ubc29\uc2dd\uc774\ub2e4.","\ud658\uacbd \uaddc\uc81c\uac00 \uac15\ud654\ub418\uba74 \uae30\uc5c5\uc758 \ucd08\uae30 \ube44\uc6a9\uc740 \ub298 \uc218 \uc788\uc9c0\ub9cc \uc7a5\uae30\uc801\uc778 \uacbd\uc7c1\ub825\uc5d0\ub294 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\ub2e4.","\uc9c0\uc18d \uac00\ub2a5\ud55c \ubc1c\uc804\uc744 \uc704\ud574 \uc815\ubd80, \uae30\uc5c5, \uc18c\ube44\uc790\uac00 \ud568\uaed8 \ub178\ub825\ud574\uc57c \ud55c\ub2e4."],t.s)
A.z4=new B.hC(5,"\ud658\uacbd \ubb38\uc81c\uc640 \uc9c0\uc18d \uac00\ub2a5\ud55c \ubc1c\uc804",A.jd9,A.hgC,A.jby,A.i9e,A.jKp,A.i3Q,A.i_l,A.hkS,A.i_M,A.il9,A.iTT,A.jhp)
A.i1Q=s(["\uacfc\ud559, \uae30\uc220, \uc5f0\uad6c \uac1c\ubc1c\uc5d0 \uad00\ud55c \uace0\uae09 \uc5b4\ud718\ub97c \uc775\ud78c\ub2e4.","\uae30\ucd08 \uc5f0\uad6c, \uc751\uc6a9 \uc5f0\uad6c, \uc2e4\uc99d, \uc0c1\uc6a9\ud654\uc758 \ub2e8\uacc4\ub97c \uad6c\ubcc4\ud55c\ub2e4.","\uc5f0\uad6c \uc131\uacfc\uc640 \uc5f0\uad6c \uac1c\ubc1c \ud22c\uc790\ub97c \uc124\uba85\ud55c\ub2e4.","\ud2b9\ud5c8\uc640 \uc9c0\uc2dd \uc7ac\uc0b0\uad8c\uc5d0 \uad00\ud55c \uc5b4\ud718\ub97c \uc775\ud78c\ub2e4.","\uc6d0\ucc9c \uae30\uc220\uacfc \ud575\uc2ec \uae30\uc220\uc758 \uc5ed\ud560\uc744 \uc81c\uc2dc\ud55c\ub2e4.","\ubc18\ub3c4\uccb4 \uc0b0\uc5c5\uc5d0 \uad00\ud55c \uace0\uae09 \uc5b4\ud718\ub97c \uc775\ud78c\ub2e4.","\uc18c\uc7ac, \ubd80\ud488, \uc7a5\ube44, \uacf5\uae09\ub9dd\uc758 \uad00\uacc4\ub97c \uc124\uba85\ud55c\ub2e4.","\uc0dd\uba85 \uacf5\ud559\uacfc \uc2e0\uc57d \uac1c\ubc1c\uc5d0 \uad00\ud55c \uc5b4\ud718\ub97c \uc775\ud78c\ub2e4.","\uc784\uc0c1 \uc5f0\uad6c\uc640 \uc758\ub8cc \uae30\uae30\uc758 \uac1c\ubc1c \uacfc\uc815\uc744 \uc124\uba85\ud55c\ub2e4.","\ub85c\ubd07, \uc790\uc728\uc8fc\ud589\ucc28, \uc13c\uc11c\uc5d0 \uad00\ud55c \uc5b4\ud718\ub97c \uc775\ud78c\ub2e4.","\uc591\uc790 \uae30\uc220\uacfc \uc591\uc790 \ucef4\ud4e8\ud305\uc758 \uac1c\ub150\uc744 \uc124\uba85\ud55c\ub2e4.","\uc704\uc131, \ubc1c\uc0ac\uccb4, \uc6b0\uc8fc \uc0b0\uc5c5\uc5d0 \uad00\ud55c \uc5b4\ud718\ub97c \uc775\ud78c\ub2e4.","\uad6d\uac00 \uac04 \uae30\uc220 \uacbd\uc7c1\uc758 \uc6d0\uc778\uacfc \uc601\ud5a5\uc744 \ubd84\uc11d\ud55c\ub2e4.","\uae30\uc220 \ud45c\uc900\uacfc \uad6d\uc81c \ud45c\uc900\uc758 \uc911\uc694\uc131\uc744 \uc124\uba85\ud55c\ub2e4.","\uc5f0\uad6c \uc724\ub9ac, \ud45c\uc808, \ub370\uc774\ud130 \uc870\uc791 \ubb38\uc81c\ub97c \uc81c\uc2dc\ud55c\ub2e4.","\uae30\uc220 \ud601\uc2e0\uacfc \ubbf8\ub798 \uc0ac\ud68c\ub97c \uc8fc\uc81c\ub85c \uace0\uae09 TOPIK \ub9d0\ud558\uae30\uc640 \uc4f0\uae30\ub97c \uc5f0\uc2b5\ud55c\ub2e4."],t.s)
A.dir=new B.e("\uacfc\ud559\uae30\uc220\uc758 \ubc1c\uc804\uc740 \uc0b0\uc5c5 \uad6c\uc870\uc640 \uc0dd\ud65c \ubc29\uc2dd\uc744 \ubcc0\ud654\uc2dc\ud0a4\uace0 \uc788\uc2b5\ub2c8\ub2e4.","S\u1ef1 ph\xe1t tri\u1ec3n khoa h\u1ecdc c\xf4ng ngh\u1ec7 \u0111ang thay \u0111\u1ed5i c\u01a1 c\u1ea5u ng\xe0nh v\xe0 c\xe1ch s\u1ed1ng.")
A.ir5=s([A.dir],t.T)
