A.dHn=new B.dj("\ub300\ucd9c\uc744 \ubc1b\uae30 \uc804\uc5d0 \ubb34\uc5c7\uc744 \ud655\uc778\ud574\uc57c \ud55c\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\uae4c?",A.ja7,"\ub300\ucd9c\uc744 \ubc1b\uae30 \uc804\uc5d0\ub294 \uba3c\uc800 \uae08\ub9ac\uc640 \uc0c1\ud658 \uae30\uac04\uc744 \ud655\uc778\ud574\uc57c \ud55c\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uae08\ub9ac\uac00 \ub0ae\uc544 \ubcf4\uc5ec\ub3c4 \uc0c1\ud658 \uae30\uac04\uc774 \uae38\uba74 \uc804\uccb4 \uc774\uc790 \ubd80\ub2f4\uc774 \ucee4\uc9c8 \uc218 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \ub610\ud55c \ub9e4\ub2ec \uac1a\uc544\uc57c \ud558\ub294 \uae08\uc561\uc774 \uc790\uc2e0\uc758 \uc18c\ub4dd\uc5d0 \ube44\ud574 \uc9c0\ub098\uce58\uac8c \ub192\uc9c0 \uc54a\uc740\uc9c0\ub3c4 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \ub300\ucd9c\uc740 \ud544\uc694\ud55c \uacbd\uc6b0 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\uc9c0\ub9cc \uc0c1\ud658 \ub2a5\ub825\uc744 \uace0\ub824\ud558\uc9c0 \uc54a\uace0 \ubc1b\uc73c\uba74 \uc7a5\uae30\uc801\uc778 \ubd80\ub2f4\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.")
A.iOt=s(["\uac1c\uc778\uc815\ubcf4","\uc1a1\uae08","\uacf5\uc2dd \uae30\uad00","\ud655\uc778","\ubcf4\uc774\uc2a4\ud53c\uc2f1","\uc758\uc2ec"],t.s)
A.dHA=new B.dj("\uae08\uc735 \uc0ac\uae30\ub97c \uc608\ubc29\ud558\ub824\uba74 \uc5b4\ub5bb\uac8c \ud574\uc57c \ud569\ub2c8\uae4c?",A.iOt,"\uae08\uc735 \uc0ac\uae30\ub97c \uc608\ubc29\ud558\ub824\uba74 \ubaa8\ub974\ub294 \uc0ac\ub78c\uc774 \uc804\ud654\ub098 \uba54\uc2dc\uc9c0\ub85c \ub3c8\uc744 \uc694\uad6c\ud560 \ub54c \ubc14\ub85c \uc1a1\uae08\ud574\uc11c\ub294 \uc548 \ub429\ub2c8\ub2e4. \ud2b9\ud788 \uc740\ud589\uc774\ub098 \uacf5\uacf5\uae30\uad00 \uc9c1\uc6d0\uc744 \uc0ac\uce6d\ud558\uba74\uc11c \uacc4\uc88c\ubc88\ud638\ub098 \ube44\ubc00\ubc88\ud638\ub97c \uc694\uad6c\ud558\uba74 \uc758\uc2ec\ud574\uc57c \ud569\ub2c8\ub2e4. \uc0c1\ub300\ubc29\uc774 \uc54c\ub824 \uc900 \uc804\ud654\ubc88\ud638\ub97c \uc774\uc6a9\ud558\uae30\ubcf4\ub2e4 \ud574\ub2f9 \uae30\uad00\uc758 \uacf5\uc2dd \uc5f0\ub77d\ucc98\ub97c \uc9c1\uc811 \ucc3e\uc544 \uc0ac\uc2e4\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc548\uc804\ud569\ub2c8\ub2e4. \uac1c\uc778\uc815\ubcf4\uc640 \uae08\uc735 \uc815\ubcf4\ub3c4 \ud568\ubd80\ub85c \uc81c\uacf5\ud558\uc9c0 \uc54a\uc544\uc57c \ud569\ub2c8\ub2e4.")
