A.hss=s(["-\uc744/\ub97c \ubc14\ud0d5\uc73c\ub85c","-\uc744/\ub97c \uc804\uc81c\ub85c","-\uc744/\ub97c \uac10\uc218\ud558\uace0","-\ub294 \uacfc\uc815\uc5d0\uc11c","-\ub294 \ub3d9\uc2dc\uc5d0","-\ub2e4\ub294 \uc810\uc5d0\uc11c","-\uc744/\ub97c \ud544\uc694\ub85c \ud558\ub2e4","-\uc5d0 \ub300\ud55c \uc6b0\ub824\uac00 \uc81c\uae30\ub418\ub2e4","-\uc744/\ub97c \uc885\ud569\ud574 \ubcf4\uba74","-\uc744/\ub97c \uace0\ub824\ud560 \ud544\uc694\uac00 \uc788\ub2e4","-\uc5d0 \ub300\uc751\ud574","-\uc744/\ub97c \ud1b5\ud574","-\uc5d0 \uadf8\uce58\uc9c0 \uc54a\uace0","-\ub294 \ub370 \uc911\uc810\uc744 \ub450\ub2e4","-\uc744/\ub97c \ub458\ub7ec\uc2fc"],t.s)
A.j32=s(["\ubcf5\uc7a1\ud55c \ubb38\uc81c\ub97c \ud574\uacb0\ud560 \ub54c\ub294 \ud55c \uac00\uc9c0 \uc694\uc778\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \uc5ec\ub7ec \ubcc0\uc218\ub97c \ud568\uaed8 \ubd84\uc11d\ud574\uc57c \ud55c\ub2e4.","\uae30\uc5c5\uc758 \uc131\uacfc\ub294 \ub9e4\ucd9c\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc218\uc775\uc131, \uc0dd\uc0b0\uc131, \uc548\uc815\uc131 \ub4f1 \uc5ec\ub7ec \uc9c0\ud45c\ub85c \ud3c9\uac00\ud574\uc57c \ud55c\ub2e4.","\uc0c8\ub85c\uc6b4 \uae30\uc220\uc744 \ub3c4\uc785\ud560 \ub54c\ub294 \ud6a8\uacfc\ubfd0\ub9cc \uc544\ub2c8\ub77c \ube44\uc6a9\uacfc \uc704\ud5d8 \uc694\uc18c\ub3c4 \uac80\ud1a0\ud574\uc57c \ud55c\ub2e4.","\ud658\uacbd\uacfc \uc0ac\ud68c \ubb38\uc81c\ub294 \uae30\uc5c5 \uacbd\uc601\uacfc \ubcc4\uac1c\uc758 \ubb38\uc81c\uac00 \uc544\ub2c8\ub77c \uc7a5\uae30\uc801\uc778 \uacbd\uc7c1\ub825\uacfc \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4.","\uc778\uad6c \uac10\uc18c\uc640 \uace0\ub839\ud654\ub294 \ub178\ub3d9\uc2dc\uc7a5\uacfc \uc18c\ube44 \uad6c\uc870\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub2e4.","\uc8fc\ud0dd \uac00\uaca9\uacfc \uae08\ub9ac\ub294 \uac00\uacc4\uc758 \uc18c\ube44\uc640 \uc7ac\uc815 \uc0c1\ud0dc\uc5d0 \uc9c1\uc811\uc801\uc778 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\ub2e4.","\uac1c\uc778\uc758 \uae08\uc735 \uacc4\ud68d\uc5d0\uc11c\ub294 \uc218\uc775\ubcf4\ub2e4 \uba3c\uc800 \uc704\ud5d8\uacfc \uc0c1\ud658 \ub2a5\ub825\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4.","\ud68c\uc758\uc5d0\uc11c\ub294 \ubb38\uc81c\ub97c \uc9c0\uc801\ud558\ub294 \ub370 \uadf8\uce58\uc9c0 \uc54a\uace0 \uc2e4\ud589 \uac00\ub2a5\ud55c \ub300\uc548\uc744 \uc81c\uc2dc\ud574\uc57c \ud55c\ub2e4.","\uc815\ucc45\uc774\ub098 \uc804\ub7b5\uc740 \ub2e8\uae30 \ud6a8\uacfc\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc7a5\uae30\uc801\uc778 \uc9c0\uc18d \uac00\ub2a5\uc131\ub3c4 \uace0\ub824\ud574\uc57c \ud55c\ub2e4.","\uc88b\uc740 \ud310\ub2e8\uc744 \uc704\ud574\uc11c\ub294 \ub370\uc774\ud130, \ud604\uc7a5 \uacbd\ud5d8, \ube44\uc6a9, \uc704\ud5d8, \uc774\ud574\uad00\uacc4\uc790\uc758 \uc758\uacac\uc744 \uc885\ud569\uc801\uc73c\ub85c \uac80\ud1a0\ud574\uc57c \ud55c\ub2e4."],t.s)
