A.dHM=new B.dj("\uc9c1\uc7a5\uc5d0\uc11c \uc790\uc2e0\uc758 \uad8c\ub9ac\ub97c \uc9c0\ud0a4\uae30 \uc704\ud574 \ubb34\uc5c7\uc774 \ud544\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\uae4c?",A.jbz,"\uc9c1\uc7a5\uc5d0\uc11c \uc790\uc2e0\uc758 \uad8c\ub9ac\ub97c \uc9c0\ud0a4\uae30 \uc704\ud574\uc11c\ub294 \uba3c\uc800 \uadfc\ub85c\uacc4\uc57d\uc11c\uc640 \ud68c\uc0ac \uaddc\uc815\uc744 \uc815\ud655\ud788 \ud655\uc778\ud574\uc57c \ud55c\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uae09\uc5ec\uc640 \uadfc\ub85c\uc2dc\uac04 \uac19\uc740 \uc911\uc694\ud55c \ub0b4\uc6a9\uc740 \uac00\ub2a5\ud55c \ud55c \ubb38\uc11c\ub85c \ub0a8\uaca8 \ub450\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4. \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud588\uc744 \ub54c\ub294 \uac10\uc815\uc801\uc73c\ub85c \ub300\uc751\ud558\uae30\ubcf4\ub2e4 \uad00\ub828 \uae30\ub85d\uc744 \uc815\ub9ac\ud558\uace0 \ud544\uc694\ud55c \uacbd\uc6b0 \uc0c1\ub2f4 \uae30\uad00\uc744 \ud1b5\ud574 \ud574\uacb0 \ubc29\ubc95\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.hUR=s(["\uc0ac\uc0dd\ud65c","\uae08\uc735 \uc0ac\uae30","\ub3d9\uc758","\uc628\ub77c\uc778","\uc815\ubcf4 \uc720\ucd9c","\ud53c\ud574"],t.s)
A.dHz=new B.dj("\uac1c\uc778\uc815\ubcf4 \ubcf4\ud638\uac00 \uc911\uc694\ud55c \uc774\uc720\ub294 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.hUR,"\uac1c\uc778\uc815\ubcf4\uc5d0\ub294 \uc774\ub984\uacfc \uc5f0\ub77d\ucc98\ubfd0\ub9cc \uc544\ub2c8\ub77c \uae08\uc735 \uc815\ubcf4\ub098 \uc704\uce58 \uc815\ubcf4\ucc98\ub7fc \ubbfc\uac10\ud55c \uc815\ubcf4\ub3c4 \ud3ec\ud568\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc815\ubcf4\uac00 \ubcf8\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \uc720\ucd9c\ub418\uba74 \uae08\uc735 \uc0ac\uae30\ub098 \uc0ac\uc0dd\ud65c \uce68\ud574\uc640 \uac19\uc740 \ud53c\ud574\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc628\ub77c\uc778 \uc11c\ube44\uc2a4\ub97c \uc774\uc6a9\ud560 \ub54c \uc5b4\ub5a4 \uc815\ubcf4\ub97c \uc81c\uacf5\ud558\ub294\uc9c0 \ud655\uc778\ud558\uace0 \ube44\ubc00\ubc88\ud638\ub098 \uc778\uc99d \uc815\ubcf4\ub3c4 \uc548\uc804\ud558\uac8c \uad00\ub9ac\ud574\uc57c \ud569\ub2c8\ub2e4.")
