A.dHE=new B.dj("\uc6d4\uae09\uc744 \ubc1b\uc73c\uba74 \uc5b4\ub5bb\uac8c \uad00\ub9ac\ud558\ub294 \uac83\uc774 \uc88b\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\uae4c?",A.jlK,"\uc6d4\uae09\uc744 \ubc1b\uc73c\uba74 \uba3c\uc800 \uc6d4\uc138\ub098 \ubcf4\ud5d8\ub8cc \uac19\uc740 \uace0\uc815 \uc9c0\ucd9c\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uadf8\ub2e4\uc74c \uc0dd\ud65c\ube44 \uc608\uc0b0\uc744 \uc815\ud558\uace0 \uc77c\uc815 \uae08\uc561\uc740 \uc800\ucd95\uacfc \ube44\uc0c1\uae08\uc73c\ub85c \ub530\ub85c \uad00\ub9ac\ud558\ub294 \uac83\uc774 \ud544\uc694\ud569\ub2c8\ub2e4. \ub0a8\uc740 \ub3c8\uc744 \ubaa8\ub450 \uc18c\ube44\ud558\uae30\ubcf4\ub2e4\ub294 \uc7a5\uae30\uc801\uc778 \ubaa9\ud45c\ub97c \uc704\ud574 \uacc4\ud68d\uc801\uc73c\ub85c \uc0ac\uc6a9\ud558\ub294 \uc2b5\uad00\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.iTn=s(["\uae08\ub9ac","\uc0c1\ud658 \uae30\uac04","\uc6d0\uae08","\uc774\uc790","\uc18c\ub4dd","\uc0c1\ud658 \ub2a5\ub825"],t.s)
A.dHt=new B.dj("\ub300\ucd9c\uc744 \ubc1b\uc744 \ub54c \ubb34\uc5c7\uc744 \uac00\uc7a5 \uc911\uc694\ud558\uac8c \ud655\uc778\ud574\uc57c \ud569\ub2c8\uae4c?",A.iTn,"\ub300\ucd9c\uc744 \ubc1b\uc744 \ub54c\ub294 \ub2e8\uc21c\ud788 \ub300\ucd9c \ud55c\ub3c4\ub9cc \ubcf4\uba74 \uc548 \ub41c\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ud604\uc7ac \uc18c\ub4dd\uc73c\ub85c \ub9e4\ub2ec \uc6d0\uae08\uacfc \uc774\uc790\ub97c \uc548\uc815\uc801\uc73c\ub85c \uac1a\uc744 \uc218 \uc788\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \ub610\ud55c \uae08\ub9ac\uac00 \uc624\ub97c \uacbd\uc6b0 \uc0c1\ud658 \ubd80\ub2f4\uc774 \uc5bc\ub9c8\ub098 \ucee4\uc9c8 \uc218 \uc788\ub294\uc9c0\ub3c4 \ubbf8\ub9ac \uacc4\uc0b0\ud574 \ubcf4\ub294 \uac83\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.")
A.j9m=s(["\uc548\uc815\uc131","\uc218\uc775\ub960","\uc704\ud5d8","\ube44\uc0c1\uae08","\uc7a5\uae30 \ubaa9\ud45c"],t.s)
A.dHI=new B.dj("\uc800\ucd95\uacfc \ud22c\uc790 \uc911 \uc5b4\ub290 \uac83\uc774 \ub354 \uc911\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\uae4c?",A.j9m,"\uc800\ucd95\uacfc \ud22c\uc790\ub294 \ubaa9\uc801\uc774 \ub2e4\ub974\uae30 \ub54c\ubb38\uc5d0 \uc5b4\ub290 \ud558\ub098\ub9cc \uc911\uc694\ud558\ub2e4\uace0 \ubcf4\uae30\ub294 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \uac11\uc791\uc2a4\ub7ec\uc6b4 \uc9c0\ucd9c\uc5d0 \ub300\ube44\ud560 \ube44\uc0c1\uae08\uc740 \ube44\uad50\uc801 \uc548\uc804\ud55c \ubc29\uc2dd\uc73c\ub85c \ubcf4\uad00\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ubc18\uba74\uc5d0 \uc7a5\uae30\uc801\uc778 \uc790\uc0b0 \ud615\uc131\uc744 \uc704\ud574\uc11c\ub294 \uc790\uc2e0\uc758 \uc704\ud5d8 \uac10\uc218 \uc218\uc900\uc5d0 \ub9de\ub294 \ud22c\uc790\ub3c4 \uace0\ub824\ud560 \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.")
A.htU=s([A.dHE,A.dHt,A.dHI],t.Gu)
A.jig=s(["\uc18c\ub4dd\uacfc \uc9c0\ucd9c \uad00\ub9ac \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","\uc800\ucd95\uc758 \ud544\uc694\uc131\uc744 \uc124\uba85\ud558\uc138\uc694.","\ubd80\ucc44 \uad00\ub9ac \ubc29\ubc95\uc744 \uc4f0\uc138\uc694.","\ube44\uc0c1\uae08\uc758 \uc911\uc694\uc131\uc744 \uc124\uba85\ud558\uc138\uc694.","\ubcf8\uc778\uc758 \uc758\uacac\uc744 \uc815\ub9ac\ud558\uc138\uc694."],t.s)
A.e2H=new B.ek("\ud569\ub9ac\uc801\uc778 \uac00\uacc4 \uc7ac\uc815 \uad00\ub9ac \ubc29\ubc95",A.jig,"\uc548\uc815\uc801\uc778 \uac00\uacc4 \uc7ac\uc815\uc744 \uc720\uc9c0\ud558\ub824\uba74 \uba3c\uc800 \ub9e4\ub2ec \ubc1c\uc0dd\ud558\ub294 \uc18c\ub4dd\uacfc \uc9c0\ucd9c\uc744 \uc815\ud655\ud788 \ud30c\uc545\ud574\uc57c \ud569\ub2c8\ub2e4. \uc6d4\uc138\uc640 \ubcf4\ud5d8\ub8cc \uac19\uc740 \uace0\uc815 \uc9c0\ucd9c\uc744 \ud655\uc778\ud55c \ud6c4 \uc0dd\ud65c\ube44 \uc608\uc0b0\uc744 \uc815\ud558\uace0 \ubd88\ud544\uc694\ud55c \uc18c\ube44\ub97c \uc904\uc77c \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ub610\ud55c \uac11\uc791\uc2a4\ub7ec\uc6b4 \uc9c8\ubcd1\uc774\ub098 \uc2e4\uc9c1\uc5d0 \ub300\ube44\ud560 \uc218 \uc788\ub3c4\ub85d \uc77c\uc815\ud55c \ube44\uc0c1\uae08\uc744 \ub9c8\ub828\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4. \ub300\ucd9c\uc774 \uc788\ub2e4\uba74 \ub192\uc740 \uc218\uc775\uc744 \uae30\ub300\ud558\uba70 \ubb34\ub9ac\ud558\uac8c \ud22c\uc790\ud558\uae30\ubcf4\ub2e4 \uc548\uc815\uc801\uc73c\ub85c \ubd80\ucc44\ub97c \uc0c1\ud658\ud560 \uc218 \uc788\ub294 \uacc4\ud68d\uc744 \uc6b0\uc120 \uc138\uc6cc\uc57c \ud569\ub2c8\ub2e4.")
A.hZE=s(["\uac00\uacc4 \ubd80\ucc44 \uc99d\uac00 \ud604\uc0c1\uc744 \uc124\uba85\ud558\uc138\uc694.","\uc8fc\ud0dd \uac00\uaca9\uacfc \ub300\ucd9c\uc758 \uc601\ud5a5\uc744 \uc4f0\uc138\uc694.","\uae08\ub9ac \uc0c1\uc2b9 \uc2dc \ubb38\uc81c\ub97c \uc124\uba85\ud558\uc138\uc694.","\uac00\uacc4\uc640 \uacbd\uc81c\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc744 \uc4f0\uc138\uc694.","\ub300\ucc45\uc744 \uc81c\uc548\ud558\uc138\uc694."],t.s)
A.e2W=new B.ek("\uac00\uacc4 \ubd80\ucc44 \uc99d\uac00\uc758 \uc6d0\uc778\uacfc \uc601\ud5a5",A.hZE,"\uac00\uacc4 \ubd80\ucc44\ub294 \uc8fc\ud0dd \uad6c\uc785\uacfc \uc0dd\ud65c\ube44, \uac01\uc885 \uc18c\ube44\ub97c \uc704\ud574 \ub300\ucd9c\uc774 \ub298\uc5b4\ub098\uba74\uc11c \uc99d\uac00\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 \uc8fc\ud0dd \uac00\uaca9\uc774 \uc18c\ub4dd\ubcf4\ub2e4 \ube60\ub974\uac8c \uc0c1\uc2b9\ud558\uba74 \ub9ce\uc740 \uac00\uad6c\uac00 \ud070 \uaddc\ubaa8\uc758 \ub300\ucd9c\uc744 \uc774\uc6a9\ud558\uac8c \ub429\ub2c8\ub2e4. \uae08\ub9ac\uac00 \ub0ae\uc744 \ub54c\ub294 \uc0c1\ud658 \ubd80\ub2f4\uc774 \ube44\uad50\uc801 \uc791\uc744 \uc218 \uc788\uc9c0\ub9cc \uae08\ub9ac\uac00 \uc0c1\uc2b9\ud558\uba74 \ub9e4\ub2ec \ub0b4\uc57c \ud558\ub294 \uc774\uc790\uac00 \ud06c\uac8c \ub298\uc5b4\ub0a0 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uac00\uacc4\uac00 \uc18c\ub4dd\uc758 \ub9ce\uc740 \ubd80\ubd84\uc744 \ub300\ucd9c \uc0c1\ud658\uc5d0 \uc0ac\uc6a9\ud558\uba74 \uc18c\ube44 \uc5ec\ub825\uc774 \uc904\uc5b4 \uacbd\uc81c \uc804\uccb4\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uac1c\uc778\uc740 \uc790\uc2e0\uc758 \uc0c1\ud658 \ub2a5\ub825\uc744 \uace0\ub824\ud574 \ub300\ucd9c \uaddc\ubaa8\ub97c \uacb0\uc815\ud558\uace0 \uc7a5\uae30\uc801\uc778 \uc7ac\uc815 \uacc4\ud68d\uc744 \uc138\uc6b8 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.")
A.heV=s([A.e2H,A.e2W],t.Qd)
A.jbj=s(["\uc18c\ub4dd","\uc9c0\ucd9c","\uc800\ucd95","\uc608\uae08","\uc801\uae08","\uae08\ub9ac","\uc2e0\uc6a9","\ub300\ucd9c","\ubd80\ucc44","\uc790\uc0b0","\ud22c\uc790","\ubcf4\ud5d8","\uc5f0\uae08","\uac00\uacc4 \ubd80\ucc44"],t.s)
A.hr_=s(["-\ub294 \ub370 \ube44\ud574","-(\uc73c)\u3139\uc218\ub85d","-\uc5d0 \ub530\ub77c","-\uc744/\ub97c \uac10\uc548\ud558\uba74","-\uc9c0 \uc54a\ub294 \ud55c","-(\uc73c)\u3139 \uc6b0\ub824\uac00 \uc788\ub2e4","-\ub294 \uc148\uc774\ub2e4","-\uae30\ub294 \ud558\uc9c0\ub9cc","-\ub294 \ubc18\uba74\uc5d0","-\uae30 \ub9c8\ub828\uc774\ub2e4","-\uc5d0 \ube44\ucd94\uc5b4 \ubcfc \ub54c","-\uc744/\ub97c \ud1a0\ub300\ub85c","-\ub294 \uac00\uc6b4\ub370","-(\uc73c)\u3141\uc73c\ub85c\uc368","-\uace0\uc790 \ud558\ub2e4"],t.s)
A.jpd=s(["\uc18c\ub4dd\uc740 \uc77c\uc815 \uae30\uac04 \ubc8c\uc5b4\ub4e4\uc778 \uacbd\uc81c\uc801 \uc218\uc785\uc744 \uc758\ubbf8\ud55c\ub2e4.","\uc9c0\ucd9c\uc740 \uc0ac\uc6a9\ud55c \ub3c8 \uc804\uccb4\ub97c \ub9d0\ud558\uba70 \uc18c\ube44\ub294 \uc0c1\ud488\uc774\ub098 \uc11c\ube44\uc2a4\ub97c \uad6c\ub9e4\ud558\uc5ec \uc0ac\uc6a9\ud558\ub294 \ud589\uc704\ub97c \uac15\uc870\ud55c\ub2e4.","\uc608\uae08\uc740 \ubaa9\ub3c8\uc744 \ub9e1\uae30\ub294 \ubc29\uc2dd\uc774 \ub9ce\uace0 \uc801\uae08\uc740 \uc77c\uc815 \uae08\uc561\uc744 \uc815\uae30\uc801\uc73c\ub85c \ub123\ub294 \ubc29\uc2dd\uc774 \uc77c\ubc18\uc801\uc774\ub2e4.","\ub300\ucd9c\uc744 \ubc1b\uc744 \ub54c\ub294 \uae08\ub9ac\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc0c1\ud658 \uae30\uac04\uacfc \ucd1d\uc774\uc790\ub3c4 \ud655\uc778\ud574\uc57c \ud55c\ub2e4.","\uc2e0\uc6a9\uc810\uc218\ub294 \uae08\uc735 \uac70\ub798 \uc774\ub825\uacfc \uc0c1\ud658 \uc0c1\ud0dc \ub4f1\uc758 \uc601\ud5a5\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4.","\uc790\uc0b0\uc5d0\uc11c \ubd80\ucc44\ub97c \ube7c\uba74 \uc21c\uc790\uc0b0\uc744 \uacc4\uc0b0\ud560 \uc218 \uc788\ub2e4.","\uc218\uc775\ub960\uc774 \ub192\uc744\uc218\ub85d \uc77c\ubc18\uc801\uc73c\ub85c \ub354 \ud070 \uc704\ud5d8\uc744 \ub3d9\ubc18\ud560 \uac00\ub2a5\uc131\ub3c4 \uace0\ub824\ud574\uc57c \ud55c\ub2e4.","\ubb3c\uac00\uac00 \uc624\ub974\uba74 \uac19\uc740 \ub3c8\uc73c\ub85c \uc0b4 \uc218 \uc788\ub294 \uc0c1\ud488\uc758 \uc591\uc774 \uc904\uc5b4 \uad6c\ub9e4\ub825\uc774 \ub5a8\uc5b4\uc9c8 \uc218 \uc788\ub2e4.","\ube44\uc0c1\uae08\uc740 \uc608\uc0c1\ud558\uc9c0 \ubabb\ud55c \uc9c0\ucd9c\uc5d0 \ub300\ube44\ud558\uae30 \uc704\ud55c \uc790\uae08\uc774\ub2e4.","\uae08\uc735 \uc0ac\uae30\ub97c \uc608\ubc29\ud558\uae30 \uc704\ud574 \ube44\ubc00\ubc88\ud638\uc640 \uc778\uc99d \ubc88\ud638\ub97c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc54c\ub824 \uc8fc\uc9c0 \uc54a\uc544\uc57c \ud55c\ub2e4."],t.s)
A.zd=new B.hC(9,"\uae08\uc735 \uc0dd\ud65c\uacfc \uac00\uacc4 \uacbd\uc81c",A.h8H,A.jCj,A.hiC,A.ilo,A.hl2,A.iih,A.iWs,A.htU,A.heV,A.jbj,A.hr_,A.jpd)
A.jrf=s(["HANNEST 5 \uc218\uc900\uc5d0\uc11c \uc0ac\ud68c \ubb38\uc81c\ub97c \ud1a0\ub860\ud558\ub294 \ubc29\ubc95\uc744 \uc885\ud569\uc801\uc73c\ub85c \ubcf5\uc2b5\ud55c\ub2e4.","\uc6d0\uc778, \uc601\ud5a5, \ud574\uacb0\ucc45\uc744 \ubd84\uc11d\ud558\ub294 \ub370 \ud544\uc694\ud55c \uace0\uae09 \uc5b4\ud718\ub97c \uc775\ud78c\ub2e4.","\ud604\uc0c1, \uc6d0\uc778, \uacb0\uacfc, \ud574\uacb0\ucc45\uc758 \ub17c\ub9ac\uc801 \uad6c\uc870\ub85c \ubb38\uc81c\ub97c \uc124\uba85\ud55c\ub2e4.","\uac1c\uc778\uc758 \uad00\uc810\uacfc \uc0ac\ud68c\uc801 \uad00\uc810\uc744 \ube44\uad50\ud558\uc5ec \uc81c\uc2dc\ud55c\ub2e4.","\uac10\uc815\uc801\uc778 \uc8fc\uc7a5\ubcf4\ub2e4 \uadfc\uac70\uc5d0 \uae30\ubc18\ud55c \ub17c\ub9ac\ub97c \uc804\uac1c\ud55c\ub2e4.","\uc815\ucc45\uc758 \ud6a8\uacfc, \ud55c\uacc4, \uc9c0\uc18d \uac00\ub2a5\uc131\uc744 \uc124\uba85\ud55c\ub2e4.","\uc778\uad6c, \ub178\ub3d9, \ubcf5\uc9c0, \uae30\uc220, \ud658\uacbd, \uc18c\ube44 \uc8fc\uc81c\ub97c \uc11c\ub85c \uc5f0\uacb0\ud55c\ub2e4.","\uc815\ucc45\uc758 \uc7a5\uc810\uacfc \ub2e8\uc810\uc744 \uade0\ud615 \uc788\uac8c \uc81c\uc2dc\ud55c\ub2e4.","\ud1a0\ub860\uc5d0\uc11c \uc0c1\ub300\ub97c \uc874\uc911\ud558\uba74\uc11c \ubc18\ub860\uc744 \uc81c\uae30\ud55c\ub2e4.","\uad6c\uccb4\uc801\uc778 \ud604\uc2e4 \uc0ac\ub840\ub97c \ud65c\uc6a9\ud558\uc5ec \uc8fc\uc7a5\uc758 \uc124\ub4dd\ub825\uc744 \ub192\uc778\ub2e4.","\uc0ac\ud68c\uc801 \ud569\uc758\uc640 \uc774\ud574\uad00\uacc4 \ucda9\ub3cc\uc5d0 \uad00\ud55c \uc5b4\ud718\ub97c \uc775\ud78c\ub2e4.","\uac1c\uc778, \uae30\uc5c5, \uc815\ubd80\uc758 \ucc45\uc784\uc744 \uad6c\ubd84\ud558\uc5ec \uc124\uba85\ud55c\ub2e4.","\ub2e8\uae30 \ud574\uacb0\ucc45\uacfc \uc7a5\uae30 \ud574\uacb0\ucc45\uc744 \ub098\ub204\uc5b4 \uc81c\uc2dc\ud55c\ub2e4.","\uc11c\ub860, \ubcf8\ub860, \uacb0\ub860\uc744 \uac16\ucd98 \uace0\uae09 TOPIK \ubb38\ub2e8\uc744 \uc791\uc131\ud55c\ub2e4.","\uc0ac\ud68c \ubb38\uc81c\uc5d0 \uad00\ud55c \uba74\uc811 \ub2f5\ubcc0, \ud1a0\ub860, \ub17c\uc220\uc744 \uc885\ud569\uc801\uc73c\ub85c \uc5f0\uc2b5\ud55c\ub2e4.","5\ub2e8\uacc4 \uc804\uccb4\ub97c \ubcf5\uc2b5\ud560 \uc218 \uc788\ub294 \uc885\ud569 \ud559\uc2b5\uc73c\ub85c HANNEST 5\ub97c \ub9c8\ubb34\ub9ac\ud55c\ub2e4."],t.s)
A.dlw=new B.e("\ubcf5\uc7a1\ud55c \uc0ac\ud68c \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub824\uba74 \uc885\ud569\uc801 \uc0ac\uace0\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.","Mu\u1ed1n gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1 x\xe3 h\u1ed9i ph\u1ee9c t\u1ea1p th\xec c\u1ea7n t\u01b0 duy t\u1ed5ng h\u1ee3p.")
A.jkm=s([A.dlw],t.T)
A.dOm=new B.f("\uc885\ud569\uc801 \uc0ac\uace0","T\u01b0 duy t\u1ed5ng h\u1ee3p","\uba85\uc0ac",A.jkm,A.a,A.a)
A.djA=new B.e("\uc815\ubcf4\ub97c \uadf8\ub300\ub85c \ubc1b\uc544\ub4e4\uc774\uae30\ubcf4\ub2e4 \ube44\ud310\uc801 \uc0ac\uace0\ub97c \ud1b5\ud574 \ud310\ub2e8\ud574\uc57c \ud569\ub2c8\ub2e4.","Thay v\xec ti\u1ebfp nh\u1eadn nguy\xean th\xf4ng tin, c\u1ea7n ph\xe1n \u0111o\xe1n th\xf4ng qua t\u01b0 duy ph\u1ea3n bi\u1ec7n.")
A.ih7=s([A.djA],t.T)
A.dMf=new B.f("\ube44\ud310\uc801 \uc0ac\uace0","T\u01b0 duy ph\u1ea3n bi\u1ec7n","\uba85\uc0ac",A.ih7,A.a,A.a)
A.d73=new B.e("\ubb38\uc81c \uc778\uc2dd\uc774 \ubd80\uc871\ud558\uba74 \uc801\uc808\ud55c \ud574\uacb0 \ubc29\uc548\uc744 \ucc3e\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.","N\u1ebfu thi\u1ebfu nh\u1eadn th\u1ee9c v\u1ea5n \u0111\u1ec1 th\xec kh\xf3 t\xecm \u0111\u01b0\u1ee3c ph\u01b0\u01a1ng \xe1n gi\u1ea3i quy\u1ebft ph\xf9 h\u1ee3p.")
A.izC=s([A.d73],t.T)
A.dR8=new B.f("\ubb38\uc81c \uc778\uc2dd","Nh\u1eadn th\u1ee9c v\u1ea5n \u0111\u1ec1","\uba85\uc0ac",A.izC,A.a,A.a)
