A.ewv=new B.X("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\uc2e0\uccad\ud558\ub824\uba74 \uc2e0\uccad\uc11c\uc640 \uc2e0\ubd84\uc99d\uc774 \ud544\uc694\ud569\ub2c8\ub2e4. \uc2e0\uccad\uc11c\uc5d0 \uc774\ub984, \uc8fc\uc18c, \uc5f0\ub77d\ucc98\ub97c \uc4f0\uace0 \uc544\ub798\uc5d0 \uc11c\uba85\ud574 \uc8fc\uc138\uc694.",A.iOx,0,"\u0110o\u1ea1n v\u0103n n\xf3i c\u1ea7n \u0111\u01a1n \u0111\u0103ng k\xfd v\xe0 gi\u1ea5y t\u1edd t\xf9y th\xe2n.")
A.jdK=s(["\uc11c\ub958\uac00 \ubaa8\ub450 \uc644\ubcbd\ud588\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \ubd80\uc871\ud55c \uc11c\ub958\ub97c \ucd94\uac00\ub85c \uc900\ube44\ud574\uc57c \ud569\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \uc2e0\uccad\uc744 \uc774\ubbf8 \ucde8\uc18c\ud588\uc2b5\ub2c8\ub2e4.","\uc9c1\uc6d0\uc740 \uc11c\ub958\uac00 \ud544\uc694 \uc5c6\ub2e4\uace0 \ud588\uc2b5\ub2c8\ub2e4."],t.s)
A.erj=new B.X("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\ubbfc \uc528\uac00 \uc81c\ucd9c\ud55c \uc11c\ub958\uc5d0\ub294 \ud55c \uac00\uc9c0\uac00 \ube60\uc838 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc9c1\uc6d0\uc740 \ubd80\uc871\ud55c \uc11c\ub958\ub97c \uc900\ube44\ud574\uc11c \ub2e4\uc2dc \uc81c\ucd9c\ud574 \ub2ec\ub77c\uace0 \ud588\uc2b5\ub2c8\ub2e4.",A.jdK,1,"Min c\u1ea7n chu\u1ea9n b\u1ecb th\xeam gi\u1ea5y t\u1edd c\xf2n thi\u1ebfu.")
A.hJG=s(["\ubbfc \uc528\ub294 \uc774\uc0ac \ud6c4 \ud544\uc694\ud55c \uc808\ucc28\ub97c \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \ud574\uc678\uc5ec\ud589\uc744 \uc608\uc57d\ud588\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \ubcd1\uc6d0\uc5d0\uc11c \uce58\ub8cc\ubc1b\uc558\uc2b5\ub2c8\ub2e4.","\ubbfc \uc528\ub294 \ud68c\uc0ac\uc5d0 \uc785\uc0ac\ud588\uc2b5\ub2c8\ub2e4."],t.s)
A.es9=new B.X("\ub2e4\uc74c\uc744 \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\ubbfc \uc528\ub294 \uc774\uc0ac\ud55c \ud6c4 \uc8fc\uc18c\uc640 \uad00\ub828\ub41c \ud589\uc815 \uc5c5\ubb34\ub97c \ud655\uc778\ud558\ub824\uace0 \uae30\uad00\uc5d0 \ubb38\uc758\ud588\uc2b5\ub2c8\ub2e4. \ud544\uc694\ud55c \uc808\ucc28\uc640 \uc11c\ub958\ub97c \uba3c\uc800 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.",A.hJG,0,"\u0110o\u1ea1n v\u0103n n\xf3i v\u1ec1 vi\u1ec7c h\u1ecfi th\u1ee7 t\u1ee5c li\xean quan \u0111\u1ebfn \u0111\u1ecba ch\u1ec9 sau khi chuy\u1ec3n nh\xe0.")
