A.fqV=new B.I("\uac00\uacc4","kinh t\u1ebf gia \u0111\xecnh, h\u1ed9 gia \u0111\xecnh","\uac00\uacc4 \uc9c0\ucd9c\uc744 \uc904\uc774\uae30 \uc704\ud574 \ubd88\ud544\uc694\ud55c \uc18c\ube44\ub97c \uc904\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.","\u0110\u1ec3 gi\u1ea3m chi ti\xeau gia \u0111\xecnh, t\xf4i \u0111ang c\u1eaft gi\u1ea3m nh\u1eefng kho\u1ea3n ti\xeau d\xf9ng kh\xf4ng c\u1ea7n thi\u1ebft.")
A.fuh=new B.I("\uac00\uacc4\ubd80","s\u1ed5 thu chi gia \u0111\xecnh","\ub9e4\uc77c \uac00\uacc4\ubd80\ub97c \uc4f0\uba74 \uc9c0\ucd9c \ub0b4\uc6a9\uc744 \uc27d\uac8c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","N\u1ebfu ghi s\u1ed5 thu chi m\u1ed7i ng\xe0y th\xec c\xf3 th\u1ec3 d\u1ec5 d\xe0ng ki\u1ec3m tra c\xe1c kho\u1ea3n chi.")
A.fs4=new B.I("\uc0dd\ud65c\ube44","chi ph\xed sinh ho\u1ea1t","\uc6d4\uae09\uc5d0\uc11c \uc0dd\ud65c\ube44\ub97c \uba3c\uc800 \uacc4\uc0b0\ud574 \ubd24\uc2b5\ub2c8\ub2e4.","T\xf4i \u0111\xe3 t\xednh chi ph\xed sinh ho\u1ea1t tr\u01b0\u1edbc t\u1eeb ti\u1ec1n l\u01b0\u01a1ng.")
A.fsx=new B.I("\uc8fc\uac70\ube44","chi ph\xed nh\xe0 \u1edf","\ub3c4\uc2dc\uc5d0\uc11c\ub294 \uc8fc\uac70\ube44\uac00 \ud070 \ubd80\ub2f4\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\u1ede th\xe0nh ph\u1ed1, chi ph\xed nh\xe0 \u1edf c\xf3 th\u1ec3 tr\u1edf th\xe0nh g\xe1nh n\u1eb7ng l\u1edbn.")
A.fsH=new B.I("\uad50\ud1b5\ube44","chi ph\xed giao th\xf4ng","\ub300\uc911\uad50\ud1b5\uc744 \uc774\uc6a9\ud558\uba74\uc11c \uad50\ud1b5\ube44\ub97c \uc904\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.","T\xf4i \u0111ang gi\u1ea3m chi ph\xed giao th\xf4ng b\u1eb1ng c\xe1ch s\u1eed d\u1ee5ng ph\u01b0\u01a1ng ti\u1ec7n c\xf4ng c\u1ed9ng.")
A.fvN=new B.I("\ud1b5\uc2e0\ube44","chi ph\xed vi\u1ec5n th\xf4ng","\ud734\ub300\uc804\ud654 \uc694\uae08\uc81c\ub97c \ubc14\uafd4\uc11c \ud1b5\uc2e0\ube44\ub97c \uc904\uc600\uc2b5\ub2c8\ub2e4.","T\xf4i \u0111\xe3 \u0111\u1ed5i g\xf3i c\u01b0\u1edbc \u0111i\u1ec7n tho\u1ea1i \u0111\u1ec3 gi\u1ea3m chi ph\xed vi\u1ec5n th\xf4ng.")
A.fur=new B.I("\uad50\uc721\ube44","chi ph\xed gi\xe1o d\u1ee5c","\uc790\ub140\uac00 \ub9ce\uc73c\uba74 \uad50\uc721\ube44 \ubd80\ub2f4\uc774 \ucee4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","N\u1ebfu c\xf3 nhi\u1ec1u con th\xec g\xe1nh n\u1eb7ng chi ph\xed gi\xe1o d\u1ee5c c\xf3 th\u1ec3 t\u0103ng.")
