A.fn0=new B.ac("\ubbfc","\ub9de\uc544\uc694. \ud560\uc778\uc774\ub77c\uace0 \ud558\uba74 \ud544\uc694\ud558\uc9c0 \uc54a\uc740 \ubb3c\uac74\ub3c4 \uc0ac\uace0 \uc2f6\uc5b4\uc838\uc694.","\u0110\xfang v\u1eady. Khi nghe n\xf3i gi\u1ea3m gi\xe1 th\xec ngay c\u1ea3 \u0111\u1ed3 kh\xf4ng c\u1ea7n t\xf4i c\u0169ng mu\u1ed1n mua.")
A.fqH=new B.ac("\uc9c0\uc218","\uc0ac\uae30 \uc804\uc5d0 \uc815\ub9d0 \ud544\uc694\ud55c \ubb3c\uac74\uc778\uc9c0 \ud55c \ubc88 \uc0dd\uac01\ud574 \ubcf4\ub294 \uac8c \uc88b\uc544\uc694.","Tr\u01b0\u1edbc khi mua n\xean suy ngh\u0129 m\u1ed9t l\u1ea7n xem \u0111\xf3 c\xf3 th\u1ef1c s\u1ef1 l\xe0 \u0111\u1ed3 c\u1ea7n thi\u1ebft hay kh\xf4ng.")
A.fnB=new B.ac("\ubbfc","\uc55e\uc73c\ub85c\ub294 \uc608\uc0b0\uc744 \uc815\ud558\uace0 \uc6b0\uc120\uc21c\uc704\uc5d0 \ub530\ub77c \ub3c8\uc744 \uc4f0\ub3c4\ub85d \ud560\uac8c\uc694.","T\u1eeb gi\u1edd t\xf4i s\u1ebd x\xe1c \u0111\u1ecbnh ng\xe2n s\xe1ch v\xe0 ti\xeau ti\u1ec1n theo th\u1ee9 t\u1ef1 \u01b0u ti\xean.")
A.fnw=new B.ac("\uc9c0\uc218","\uadf8\ub807\uac8c \ud558\uba74 \uc9c0\ucd9c\uc744 \uad00\ub9ac\ud558\uace0 \uc800\ucd95\ud558\ub294 \ub370 \ud6e8\uc52c \ub3c4\uc6c0\uc774 \ub420 \uac70\uc608\uc694.","N\u1ebfu l\xe0m nh\u01b0 v\u1eady s\u1ebd gi\xfap r\u1ea5t nhi\u1ec1u cho vi\u1ec7c qu\u1ea3n l\xfd chi ti\xeau v\xe0 ti\u1ebft ki\u1ec7m.")
