A.jMM=s(["\uad6d\uc81c\ud654 \uc2dc\ub300\uc758 \uc758\ubbf8\uc640 \ud2b9\uc9d5\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\uad50\ud1b5\uacfc \ud1b5\uc2e0\uc758 \ubc1c\ub2ec\ub85c \uad6d\uac00 \uac04 \uad50\ub958\uac00 \ud65c\ubc1c\ud574\uc9c4 \uc774\uc720\ub97c \uc54c\uc544\ubd05\ub2c8\ub2e4.","\uad6d\uc81c\ud654\ub85c \uc778\ud574 \uc0ac\ub78c, \uc0c1\ud488, \uc815\ubcf4, \ubb38\ud654\uac00 \ube60\ub974\uac8c \uc774\ub3d9\ud558\uace0 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\uc678\uad6d\uc778\uacfc \ud568\uaed8 \uc0dd\ud65c\ud558\uace0 \uc77c\ud558\ub294 \uacbd\uc6b0\uac00 \ub298\uc5b4\ub098\uba74\uc11c \ubb38\ud654\uc801 \ub2e4\uc591\uc131\uc774 \uc911\uc694\ud574\uc9c0\uace0 \uc788\uc74c\uc744 \ubc30\uc6c1\ub2c8\ub2e4.","\ub2e4\ub978 \ubb38\ud654\uc640 \uac00\uce58\uad00\uc744 \uc774\ud574\ud558\uace0 \uc874\uc911\ud558\ub294 \ud0dc\ub3c4\uc758 \uc911\uc694\uc131\uc744 \uc54c\uc544\ubd05\ub2c8\ub2e4.","\uad6d\uc81c\ud654\uac00 \uacbd\uc81c, \uad50\uc721, \uc9c1\uc7a5, \uc77c\uc0c1\uc0dd\ud65c\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc744 \uc0dd\uac01\ud574 \ubd05\ub2c8\ub2e4.","\uc678\uad6d\uc5b4 \ub2a5\ub825\uacfc \uc758\uc0ac\uc18c\ud1b5 \ub2a5\ub825\uc774 \uad6d\uc81c\ud654 \uc2dc\ub300\uc5d0 \uc911\uc694\ud55c \uacbd\uc7c1\ub825\uc774 \ub420 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\uad6d\uc81c\ud654\uc758 \uc7a5\uc810\ubfd0\ub9cc \uc544\ub2c8\ub77c \ubb38\ud654 \uac08\ub4f1, \ubd88\ud3c9\ub4f1 \ub4f1 \ubc1c\uc0dd\ud560 \uc218 \uc788\ub294 \ubb38\uc81c\ub3c4 \ud568\uaed8 \uc0dd\uac01\ud574 \ubd05\ub2c8\ub2e4."],t.s)
A.fv3=new B.I("\uad6d\uc81c\ud654","qu\u1ed1c t\u1ebf h\xf3a","\uad6d\uc81c\ud654\uac00 \uc9c4\ud589\ub418\uba74\uc11c \uad6d\uac00 \uac04 \uad50\ub958\uac00 \ub354\uc6b1 \ud65c\ubc1c\ud574\uc84c\uc2b5\ub2c8\ub2e4.","Khi qu\xe1 tr\xecnh qu\u1ed1c t\u1ebf h\xf3a di\u1ec5n ra, giao l\u01b0u gi\u1eefa c\xe1c qu\u1ed1c gia tr\u1edf n\xean s\xf4i \u0111\u1ed9ng h\u01a1n.")
A.fyq=new B.I("\uc138\uacc4\ud654","to\xe0n c\u1ea7u h\xf3a","\uc138\uacc4\ud654\ub85c \uc778\ud574 \uc0ac\ub78c\uacfc \uc0c1\ud488\uc774 \uad6d\uacbd\uc744 \ub118\uc5b4 \ub354 \uc790\uc720\ub86d\uac8c \uc774\ub3d9\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.","Do to\xe0n c\u1ea7u h\xf3a, con ng\u01b0\u1eddi v\xe0 h\xe0ng h\xf3a \u0111ang di chuy\u1ec3n qua bi\xean gi\u1edbi t\u1ef1 do h\u01a1n.")
A.fyy=new B.I("\uad6d\uc81c \uc0ac\ud68c","c\u1ed9ng \u0111\u1ed3ng qu\u1ed1c t\u1ebf","\ud658\uacbd \ubb38\uc81c\ub294 \uad6d\uc81c \uc0ac\ud68c\uac00 \ud568\uaed8 \ud574\uacb0\ud574\uc57c \ud560 \ubb38\uc81c\uc785\ub2c8\ub2e4.","V\u1ea5n \u0111\u1ec1 m\xf4i tr\u01b0\u1eddng l\xe0 v\u1ea5n \u0111\u1ec1 m\xe0 c\u1ed9ng \u0111\u1ed3ng qu\u1ed1c t\u1ebf c\u1ea7n c\xf9ng nhau gi\u1ea3i quy\u1ebft.")
A.ftP=new B.I("\uad50\ub958","giao l\u01b0u, trao \u0111\u1ed5i","\ud55c\uad6d\uacfc \ubca0\ud2b8\ub0a8 \uc0ac\uc774\uc758 \ubb38\ud654 \uad50\ub958\uac00 \ud65c\ubc1c\ud569\ub2c8\ub2e4.","Giao l\u01b0u v\u0103n h\xf3a gi\u1eefa H\xe0n Qu\u1ed1c v\xe0 Vi\u1ec7t Nam r\u1ea5t s\xf4i \u0111\u1ed9ng.")
