A.foN=new B.ac("\uc9c0\uc218","\ubb38\ud654 \ucc28\uc774 \ub54c\ubb38\uc5d0 \uc624\ud574\uac00 \uc0dd\uae34 \uc801\ub3c4 \uc788\uc5b4\uc694?","B\u1ea1n c\xf3 t\u1eebng x\u1ea3y ra hi\u1ec3u l\u1ea7m do kh\xe1c bi\u1ec7t v\u0103n h\xf3a kh\xf4ng?")
A.fmK=new B.ac("\ubbfc","\ub124. \uc5b4\ub5a4 \ud589\ub3d9\uc774 \uc81c \ub098\ub77c\uc5d0\uc11c\ub294 \uad1c\ucc2e\uc9c0\ub9cc \ub2e4\ub978 \ub098\ub77c\uc5d0\uc11c\ub294 \uc608\uc758\uac00 \uc544\ub2d0 \uc218\ub3c4 \uc788\ub354\ub77c\uace0\uc694.","C\xf3. C\xf3 h\xe0nh \u0111\u1ed9ng \u1edf n\u01b0\u1edbc t\xf4i th\xec b\xecnh th\u01b0\u1eddng nh\u01b0ng \u1edf n\u01b0\u1edbc kh\xe1c c\xf3 th\u1ec3 b\u1ecb xem l\xe0 kh\xf4ng l\u1ecbch s\u1ef1.")
A.fpN=new B.ac("\uc9c0\uc218","\uadf8\ub798\uc11c \ub2e4\ub978 \ubb38\ud654\ub97c \uc874\uc911\ud558\ub294 \ud0dc\ub3c4\uac00 \uc911\uc694\ud558\uaca0\ub124\uc694.","V\xec v\u1eady th\xe1i \u0111\u1ed9 t\xf4n tr\u1ecdng v\u0103n h\xf3a kh\xe1c r\u1ea5t quan tr\u1ecdng nh\u1ec9.")
A.fmf=new B.ac("\ubbfc","\ub9de\uc544\uc694. \ud568\uaed8 \uc9c0\ub0bc\uc218\ub85d \uc11c\ub85c\uc758 \ubb38\ud654\ub97c \ub354 \ub9ce\uc774 \uc774\ud574\ud558\uac8c \ub3fc\uc694.","\u0110\xfang v\u1eady. C\xe0ng s\u1ed1ng v\xe0 l\xe0m vi\u1ec7c c\xf9ng nhau th\xec c\xe0ng hi\u1ec3u v\u0103n h\xf3a c\u1ee7a nhau h\u01a1n.")
A.foF=new B.ac("\uc9c0\uc218","\uc678\uad6d\uc5b4\ub97c \uc798\ud558\uba74 \ud68c\uc0ac\uc5d0\uc11c\ub3c4 \ub3c4\uc6c0\uc774 \ub9ce\uc774 \ub418\uc9c0\uc694?","N\u1ebfu gi\u1ecfi ngo\u1ea1i ng\u1eef th\xec trong c\xf4ng ty c\u0169ng r\u1ea5t h\u1eefu \xedch \u0111\xfang kh\xf4ng?")
A.fq8=new B.ac("\ubbfc","\ub124. \ud1b5\uc5ed\uc774 \ud544\uc694\ud560 \uc815\ub3c4\ub85c \uc911\uc694\ud55c \ud68c\uc758\uc5d0\uc11c\ub294 \uc678\uad6d\uc5b4 \ub2a5\ub825\uc774 \uc815\ub9d0 \ub3c4\uc6c0\uc774 \ub3fc\uc694.","V\xe2ng. Trong nh\u1eefng cu\u1ed9c h\u1ecdp quan tr\u1ecdng \u0111\u1ebfn m\u1ee9c c\u1ea7n phi\xean d\u1ecbch th\xec n\u0103ng l\u1ef1c ngo\u1ea1i ng\u1eef th\u1ef1c s\u1ef1 r\u1ea5t h\u1eefu \xedch.")
A.fmk=new B.ac("\uc9c0\uc218","\uc55e\uc73c\ub85c \uad6d\uc81c\uc801\uc778 \uc5c5\ubb34\ub3c4 \ud574 \ubcf4\uace0 \uc2f6\uc5b4\uc694?","Sau n\xe0y b\u1ea1n c\xf3 mu\u1ed1n th\u1eed l\xe0m c\xf4ng vi\u1ec7c mang t\xednh qu\u1ed1c t\u1ebf kh\xf4ng?")
A.fnk=new B.ac("\ubbfc","\ub124. \uadf8\ub798\uc11c \ud55c\uad6d\uc5b4\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc601\uc5b4\ub3c4 \uacc4\uc18d \uacf5\ubd80\ud558\ub824\uace0 \ud574\uc694.","C\xf3. V\xec v\u1eady t\xf4i \u0111\u1ecbnh ti\u1ebfp t\u1ee5c h\u1ecdc kh\xf4ng ch\u1ec9 ti\u1ebfng H\xe0n m\xe0 c\u1ea3 ti\u1ebfng Anh.")
A.fnt=new B.ac("\uc9c0\uc218","\uad6d\uc81c\ud654 \uc2dc\ub300\uc5d0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uacfc \ud611\ub825\ud558\ub294 \ub2a5\ub825\uc774 \uc815\ub9d0 \uc911\uc694\ud558\ub124\uc694.","Trong th\u1eddi \u0111\u1ea1i qu\u1ed1c t\u1ebf h\xf3a, n\u0103ng l\u1ef1c h\u1ee3p t\xe1c v\u1edbi nh\u1eefng ng\u01b0\u1eddi kh\xe1c nhau th\u1ef1c s\u1ef1 r\u1ea5t quan tr\u1ecdng.")
