A.fox=new B.ac("\uc9c0\uc218","\ub9de\uc544\uc694. \uc9c8\ubcd1\uc740 \uce58\ub8cc\ud558\ub294 \uac83\ub3c4 \uc911\uc694\ud558\uc9c0\ub9cc \uc608\ubc29\ud558\ub294 \uac83\uc774 \ub354 \uc911\uc694\ud560 \ub54c\ub3c4 \uc788\uc5b4\uc694.","\u0110\xfang v\u1eady. \u0110i\u1ec1u tr\u1ecb b\u1ec7nh quan tr\u1ecdng nh\u01b0ng \u0111\xf4i khi ph\xf2ng b\u1ec7nh c\xf2n quan tr\u1ecdng h\u01a1n.")
A.foP=new B.ac("\ubbfc","\uc55e\uc73c\ub85c \ubab8\uc5d0 \ubb34\ub9ac\uac00 \uac00\uc9c0 \uc54a\ub3c4\ub85d \uc0dd\ud65c \uc2b5\uad00\uc744 \ubc14\uafd4 \ubcfc\uac8c\uc694.","T\u1eeb gi\u1edd t\xf4i s\u1ebd th\u1eed thay \u0111\u1ed5i th\xf3i quen sinh ho\u1ea1t \u0111\u1ec3 c\u01a1 th\u1ec3 kh\xf4ng b\u1ecb qu\xe1 s\u1ee9c.")
