A.fid=new B.ar("\ud559\uc0dd\uc758 \uc9c4\ub85c\ub97c \uc120\ud0dd\ud560 \ub54c \uace0\ub824\ud560 \ub0b4\uc6a9\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.hme,0,"\uc9c4\ub85c\ub97c \uc120\ud0dd\ud560 \ub54c\ub294 \ud559\uc0dd\uc758 \uad00\uc2ec\uacfc \uc801\uc131, \ub2a5\ub825, \ubbf8\ub798 \uacc4\ud68d \ub4f1\uc744 \uc885\ud569\uc801\uc73c\ub85c \uace0\ub824\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.ilO=s(["\u2460 \uc7ac\ud65c\uc6a9\ud488\uc744 \ubd84\ub9ac\ubc30\ucd9c\ud55c\ub2e4","\u2461 \uc77c\ud68c\uc6a9\ud488 \uc0ac\uc6a9\uc744 \uc904\uc778\ub2e4","\u2462 \ud544\uc694\ud558\uc9c0 \uc54a\uc740 \uc804\uae30\ub97c \uacc4\uc18d \ucf1c \ub454\ub2e4","\u2463 \ub300\uc911\uad50\ud1b5\uc744 \uc774\uc6a9\ud55c\ub2e4"],t.s)
A.fio=new B.ar("\ud658\uacbd \ubcf4\ud638\ub97c \uc704\ud55c \ud589\ub3d9\uc73c\ub85c \uc801\uc808\ud558\uc9c0 \uc54a\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.ilO,2,"\ubd88\ud544\uc694\ud55c \uc804\uae30 \uc0ac\uc6a9\uc740 \uc5d0\ub108\uc9c0 \ub0ad\ube44\uc774\ubbc0\ub85c \ud658\uacbd \ubcf4\ud638\uc5d0 \ub3c4\uc6c0\uc774 \ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.")
A.ha_=s(["\u2460 \ud544\uc694\ud55c \uc9c0\ucd9c\uacfc \uc800\ucd95 \uacc4\ud68d\uc744 \uba3c\uc800 \uc138\uc6b4\ub2e4","\u2461 \ud560\uc778\ud558\uba74 \ud544\uc694\ud558\uc9c0 \uc54a\uc740 \ubb3c\uac74\ub3c4 \ubaa8\ub450 \uc0b0\ub2e4","\u2462 \uc218\uc785\uc744 \ud655\uc778\ud558\uc9c0 \uc54a\uace0 \uacc4\uc18d \uc18c\ube44\ud55c\ub2e4","\u2463 \ub300\ucd9c \uc870\uac74\uc744 \ud655\uc778\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
A.fkC=new B.ar("\uc6d4\uae09\uc744 \ubc1b\uc740 \ud6c4 \ud569\ub9ac\uc801\uc73c\ub85c \ub3c8\uc744 \uad00\ub9ac\ud558\ub294 \ubc29\ubc95\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.ha_,0,"\ud569\ub9ac\uc801\uc778 \uacbd\uc81c\uc0dd\ud65c\uc744 \uc704\ud574\uc11c\ub294 \uc18c\ub4dd\uacfc \uc9c0\ucd9c\uc744 \ud30c\uc545\ud558\uace0 \uc608\uc0b0\uacfc \uc800\ucd95 \uacc4\ud68d\uc744 \uc138\uc6b0\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.")
A.iVV=s(["\u2460 \uc784\uae08, \uadfc\ub85c\uc2dc\uac04 \ub4f1 \uadfc\ub85c\uc870\uac74","\u2461 \ub3d9\ub8cc\uc758 \uac1c\uc778 \ube44\ubc00\ubc88\ud638","\u2462 \ud68c\uc0ac \uadfc\ucc98 \uc2dd\ub2f9\uc758 \uba54\ub274","\u2463 \uce5c\uad6c\uc758 \uc5ec\ud589 \uc77c\uc815"],t.s)
A.fls=new B.ar("\uadfc\ub85c\uacc4\uc57d\uc11c\ub97c \ud655\uc778\ud560 \ub54c \uc911\uc694\ud55c \ub0b4\uc6a9\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.iVV,0,"\uadfc\ub85c\uacc4\uc57d\uc11c\uc5d0\uc11c\ub294 \uc784\uae08\uacfc \uadfc\ub85c\uc2dc\uac04 \ub4f1 \uc911\uc694\ud55c \uadfc\ub85c\uc870\uac74\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.")
A.jEf=s(["\u2460 \uad00\ub828 \uae30\uad00\uc774\ub098 \uc804\ubb38\uac00\uc5d0\uac8c \uc0c1\ub2f4\ud55c\ub2e4","\u2461 \uc544\ubb34\uac83\ub3c4 \ud558\uc9c0 \uc54a\ub294\ub2e4","\u2462 \ubaa8\ub4e0 \uc11c\ub958\ub97c \ubc84\ub9b0\ub2e4","\u2463 \uc0c1\ub300\ubc29\uc758 \ub9d0\uc744 \ubb34\uc870\uac74 \ub530\ub978\ub2e4"],t.s)
A.fhC=new B.ar("\uc790\uc2e0\uc758 \uad8c\ub9ac\uac00 \uce68\ud574\ub418\uc5c8\ub2e4\uace0 \uc0dd\uac01\ub418\ub294\ub370 \ud63c\uc790 \ud574\uacb0\ud558\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \uac00\uc7a5 \uc801\uc808\ud55c \ud589\ub3d9\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.jEf,0,"\ud63c\uc790 \ud574\uacb0\ud558\uae30 \uc5b4\ub824\uc6b4 \ubc95\ub960\uc774\ub098 \uad8c\ub9ac \ubb38\uc81c\ub294 \uad00\ub828 \uae30\uad00\uc774\ub098 \uc804\ubb38\uac00\uc758 \ub3c4\uc6c0\uc744 \ubc1b\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.")
A.i0m=s(["\u2460 \uacf5\uc2dd \uc548\ub0b4\uc640 \ub2f4\ub2f9 \uae30\uad00\uc758 \ucd5c\uc2e0 \uc815\ubcf4\ub97c \ud655\uc778\ud55c\ub2e4","\u2461 \uba87 \ub144 \uc804 \uc778\ud130\ub137 \uae00\ub9cc \ubbff\ub294\ub2e4","\u2462 \ub0a0\uc9dc\uac00 \uc5c6\ub294 \uac1c\uc778 \ub313\uae00\ub9cc \ubbff\ub294\ub2e4","\u2463 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc0c1\ud669\uc744 \uadf8\ub300\ub85c \uc801\uc6a9\ud55c\ub2e4"],t.s)
A.fkt=new B.ar("\uc911\uc694\ud55c \uccb4\ub958\xb7\ud589\uc815 \uc815\ubcf4\ub97c \ud655\uc778\ud558\ub294 \ubc29\ubc95\uc73c\ub85c \uac00\uc7a5 \ubc14\ub78c\uc9c1\ud55c \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.i0m,0,"\uccb4\ub958\uc640 \ud589\uc815 \uc815\ubcf4\ub294 \uc0c1\ud669\uc774\ub098 \uc2dc\uae30\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc73c\ubbc0\ub85c \uacf5\uc2dd\uc801\uc778 \ucd5c\uc2e0 \uc815\ubcf4\ub97c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.i8K=s(["\u2460 \uc11c\ub85c \ub2e4\ub978 \ubb38\ud654\uc640 \uac00\uce58\uad00\uc744 \uc774\ud574\ud558\uace0 \uc874\uc911\ud55c\ub2e4","\u2461 \ub2e4\ub978 \ubb38\ud654\ub97c \ubb34\uc870\uac74 \ud2c0\ub838\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4","\u2462 \uad6d\uc801\uc774 \ub2e4\ub974\uba74 \ucc28\ubcc4\ud55c\ub2e4","\u2463 \uc790\uc2e0\uc758 \ubb38\ud654\ub9cc \uc778\uc815\ud55c\ub2e4"],t.s)
A.flG=new B.ar("\ub2e4\ubb38\ud654 \uc0ac\ud68c\uc5d0\uc11c \ud544\uc694\ud55c \ud0dc\ub3c4\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.i8K,0,"\ub2e4\ubb38\ud654 \uc0ac\ud68c\uc5d0\uc11c\ub294 \uc11c\ub85c\uc758 \ucc28\uc774\ub97c \uc778\uc815\ud558\uace0 \ud3b8\uacac\uacfc \ucc28\ubcc4\uc744 \uc904\uc774\ub294 \ud0dc\ub3c4\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.h5p=s(["\u2460 \uc5ed\uc0ac\uc640 \ubb38\ud654\uc801 \uac00\uce58\ub97c \ub2e4\uc74c \uc138\ub300\uc5d0 \uc804\ud558\uae30 \uc704\ud574\uc11c","\u2461 \uc624\ub798\ub41c \uac83\uc740 \ubaa8\ub450 \uc5c6\uc560\uae30 \uc704\ud574\uc11c","\u2462 \ud604\uc7ac \uc0ac\ub78c\ub9cc \uc774\uc6a9\ud558\uae30 \uc704\ud574\uc11c","\u2463 \uad00\uad11\uac1d\uc744 \ub9c9\uae30 \uc704\ud574\uc11c"],t.s)
A.fkU=new B.ar("\ubb38\ud654\uc720\uc0b0\uc744 \ubcf4\uc874\ud574\uc57c \ud558\ub294 \uc774\uc720\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.h5p,0,"\ubb38\ud654\uc720\uc0b0\uc740 \uc5ed\uc0ac\uc640 \ubb38\ud654\uc801 \uac00\uce58\uac00 \uc788\uc73c\ubbc0\ub85c \uc798 \ubcf4\uc874\ud558\uc5ec \ub2e4\uc74c \uc138\ub300\uc5d0 \uc804\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.")
A.NW=s(["\u2460 \ubed4\ud588\ub294\ub370","\u2461 \ub9c8\ub828\uc778\ub370","\u2462 \uce58\uace0","\u2463 \uc870\ucc28"],t.s)
A.fks=new B.ar("\ub2e4\uc74c \ub300\ud654\uc5d0 \ub4e4\uc5b4\uac08 \ud45c\ud604\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?\n\n\uac00: \uc5b4\uc81c \uacf5\uc7a5\uc5d0\uc11c \uc0ac\uace0\uac00 \ub0ac\uc5b4\uc694?\n\ub098: \uc544\ub2c8\uc694. \uae30\uacc4\uac00 \uac11\uc790\uae30 \uc6c0\uc9c1\uc5ec\uc11c \ub2e4\uce60______ \ub2e4\ud589\ud788 \uba48\ucdc4\uc5b4\uc694.",A.NW,0,'\uc2e4\uc81c\ub85c \ub2e4\uce58\uc9c0\ub294 \uc54a\uc558\uc9c0\ub9cc \uac70\uc758 \ub2e4\uce60 \uc0c1\ud669\uc774\uc5c8\uc73c\ubbc0\ub85c "-(\uc73c)\u3139 \ubed4\ud558\ub2e4"\uac00 \uac00\uc7a5 \uc54c\ub9de\uc2b5\ub2c8\ub2e4.')
A.flm=new B.ar("\ub2e4\uc74c \ub300\ud654\uc5d0 \ub4e4\uc5b4\uac08 \ud45c\ud604\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?\n\n\uac00: \uc774 \uc11c\ub958\ub9cc \uc900\ube44\ud558\uba74 \ub418\uaca0\uc9c0\uc694?\n\ub098: \ub2e4\ub978 \uc11c\ub958\uac00 \ub354 \ud544\uc694______ \ubaa8\ub974\ub2c8\uae4c \uacf5\uc2dd \uc548\ub0b4\ub97c \ud655\uc778\ud574 \ubcf4\uc138\uc694.",A.NH,0,'\ucd94\uac00 \uc11c\ub958\uac00 \ud544\uc694\ud560 \uac00\ub2a5\uc131\uc774 \uc788\uc9c0\ub9cc \ud655\uc2e4\ud558\uc9c0 \uc54a\uc73c\ubbc0\ub85c "-(\uc73c)\u3139\uc9c0\ub3c4 \ubaa8\ub974\ub2e4"\uac00 \uac00\uc7a5 \uc54c\ub9de\uc2b5\ub2c8\ub2e4.')
A.hXx=s(["\u2460 \uc8c4\uc1a1\ud558\uc9c0\ub9cc \uc81c\uac00 \uc774\ud574\ud55c \ub0b4\uc6a9\uc774 \ub9de\ub294\uc9c0 \ub2e4\uc2dc \ud655\uc778\ud574\ub3c4 \ub420\uae4c\uc694?","\u2461 \uadf8\ub0e5 \uc81c\uac00 \uc6d0\ud558\ub294 \ub300\ub85c \ud558\uaca0\uc2b5\ub2c8\ub2e4.","\u2462 \ubaa8\ub974\uc9c0\ub9cc \uc544\ub294 \ucc99\ud558\uaca0\uc2b5\ub2c8\ub2e4.","\u2463 \ubb3c\uc5b4\ubcf4\uba74 \uc548 \ub418\ub2c8\uae4c \uadf8\ub0e5 \ud558\uaca0\uc2b5\ub2c8\ub2e4."],t.s)
A.fkv=new B.ar("\ub2e4\uc74c \uc0c1\ud669\uc5d0\uc11c \uac00\uc7a5 \uc801\uc808\ud55c \ub9d0\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\ud68c\uc0ac\uc5d0\uc11c \uc0c1\uc0ac\uc758 \uc791\uc5c5 \uc9c0\uc2dc\ub97c \uc815\ud655\ud788 \ub4e3\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.",A.hXx,0,"\uc5c5\ubb34\ub97c \uc815\ud655\ud558\uac8c \uc774\ud574\ud558\uc9c0 \ubabb\ud588\uc744 \ub54c\ub294 \uc815\uc911\ud558\uac8c \ub2e4\uc2dc \ud655\uc778\ud558\ub294 \uac83\uc774 \uac00\uc7a5 \uc548\uc804\ud558\uace0 \uc801\uc808\ud569\ub2c8\ub2e4.")
A.iHH=s(["\u2460 \uc790\uc2e0\uc758 \uc548\uc804\uc744 \ud655\uc778\ud55c \ub4a4 \ud544\uc694\ud55c \uae34\uae09 \uc2e0\uace0\ub97c \ud558\uace0 \uc0c1\ud669\uc744 \uc815\ud655\ud558\uac8c \uc124\uba85\ud55c\ub2e4","\u2461 \uc704\ud5d8\ud55c \ub3c4\ub85c \ud55c\uac00\uc6b4\ub370\ub85c \ubc14\ub85c \ub6f0\uc5b4\ub4e0\ub2e4","\u2462 \uc544\ubb34\uc5d0\uac8c\ub3c4 \uc54c\ub9ac\uc9c0 \uc54a\uace0 \ub5a0\ub09c\ub2e4","\u2463 \ud53c\ud574\uc790\uc758 \uac1c\uc778\uc815\ubcf4\ub97c SNS\uc5d0 \uc62c\ub9b0\ub2e4"],t.s)
A.fly=new B.ar("\ub2e4\uc74c \uc0c1\ud669\uc5d0\uc11c \uac00\uc7a5 \uc801\uc808\ud55c \ud589\ub3d9\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\uae38\uc5d0\uc11c \uc0ac\uace0\ub97c \ubaa9\uaca9\ud588\uace0 \uc0ac\ub78c\uc774 \ub2e4\uce5c \uac83 \uac19\uc2b5\ub2c8\ub2e4.",A.iHH,0,"\uae34\uae09 \uc0c1\ud669\uc5d0\uc11c\ub294 \uc790\uc2e0\uc758 \uc548\uc804\uc744 \uba3c\uc800 \ud655\uc778\ud558\uace0 \ud544\uc694\ud55c \uacbd\uc6b0 119 \ub610\ub294 112 \ub4f1 \uad00\ub828 \uae30\uad00\uc5d0 \uc2e0\uace0\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.icZ=s(["\u2460 \ubaa8\ub974\ub294 \uc815\ubcf4\ub294 \uc815\ud655\ud55c \ucd9c\ucc98\uc5d0\uc11c \ud655\uc778\ud558\uace0 \ud544\uc694\ud55c \uacbd\uc6b0 \ub3c4\uc6c0\uc744 \uc694\uccad\ud55c\ub2e4","\u2461 \ubaa8\ub974\ub294 \ub0b4\uc6a9\ub3c4 \ubaa8\ub450 \uc544\ub294 \ucc99\ud55c\ub2e4","\u2462 \uaddc\uce59\uc740 \uc790\uc2e0\uc5d0\uac8c \ud544\uc694\ud560 \ub54c\ub9cc \uc9c0\ud0a8\ub2e4","\u2463 \uc778\ud130\ub137\uc5d0 \uc788\ub294 \uc815\ubcf4\ub294 \ubaa8\ub450 \uc0ac\uc2e4\uc774\ub77c\uace0 \uc0dd\uac01\ud55c\ub2e4"],t.s)
A.flb=new B.ar("\ub2e4\uc74c \uc911 \ud55c\uad6d \uc0dd\ud65c\uc5d0\uc11c \uac00\uc7a5 \ubc14\ub78c\uc9c1\ud55c \ud0dc\ub3c4\ub97c \uace0\ub974\uc2ed\uc2dc\uc624.",A.icZ,0,"\ud55c\uad6d \uc0dd\ud65c\uc5d0\uc11c\ub294 \uc815\ud655\ud55c \uc815\ubcf4 \ud655\uc778, \uaddc\uce59 \uc900\uc218, \uc6d0\ud65c\ud55c \uc758\uc0ac\uc18c\ud1b5, \ud544\uc694\ud560 \ub54c \ub3c4\uc6c0\uc744 \uc694\uccad\ud558\ub294 \ud0dc\ub3c4\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.")
