A.fhN=new B.ar('"\ubbf8\ub798 \uc138\ub300"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?',A.iiR,0,'"\ubbf8\ub798 \uc138\ub300"\ub294 \uc55e\uc73c\ub85c \ud0dc\uc5b4\ub098\uac70\ub098 \uc0b4\uc544\uac08 \ub2e4\uc74c \uc138\ub300\uc758 \uc0ac\ub78c\ub4e4\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4.')
A.j2m=s(["\u2460 \uac1c\uc778, \uae30\uc5c5, \uc815\ubd80 \ub4f1\uc774 \ud568\uaed8 \ub178\ub825\ud55c\ub2e4","\u2461 \ud658\uacbd \ubb38\uc81c\ub294 \uc544\ubb34\ub3c4 \uc2e0\uacbd \uc4f0\uc9c0 \uc54a\ub294\ub2e4","\u2462 \ubaa8\ub4e0 \ucc45\uc784\uc744 \ud55c \uc0ac\ub78c\uc5d0\uac8c\ub9cc \ub9e1\uae34\ub2e4","\u2463 \uc4f0\ub808\uae30 \ubb38\uc81c\ub97c \ubb34\uc2dc\ud55c\ub2e4"],t.s)
A.fiU=new B.ar("\ud658\uacbd \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud55c \ud0dc\ub3c4\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?",A.j2m,0,"\ud658\uacbd \ubb38\uc81c\ub294 \uac1c\uc778\uc758 \uc0dd\ud65c \uc2b5\uad00\ubfd0\ub9cc \uc544\ub2c8\ub77c \uae30\uc5c5 \ud65c\ub3d9\uacfc \uc81c\ub3c4\uc5d0\ub3c4 \uad00\ub828\ub418\ubbc0\ub85c \uc0ac\ud68c \uc804\uccb4\uc758 \ud611\ub825\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.")
A.iew=s(["\u2460 \ud55c","\u2461 \ucc99","\u2462 \uacb8","\u2463 \uc815\ub3c4\ub85c"],t.s)
A.fjD=new B.ar("\ub2e4\uc74c \ub300\ud654\uc5d0 \ub4e4\uc5b4\uac08 \ud45c\ud604\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?\n\n\uac00: \uc4f0\ub808\uae30 \ubb38\uc81c\uac00 \uacc4\uc18d \uc2ec\ud574\uc9c0\ub294 \uac83 \uac19\uc544\uc694.\n\ub098: \ub124. \uc0ac\ub78c\ub4e4\uc774 \uc0dd\ud65c \uc2b5\uad00\uc744 \ubc14\uafb8\uc9c0 \uc54a\ub294______ \ud574\uacb0\ud558\uae30 \uc5b4\ub824\uc6b8 \uac70\uc608\uc694.",A.iew,0,'\ud2b9\uc815 \uc870\uac74\uc774 \ubc14\ub00c\uc9c0 \uc54a\uc73c\uba74 \ub4a4\uc758 \uacb0\uacfc\ub3c4 \ub2ec\ub77c\uc9c0\uae30 \uc5b4\ub835\ub2e4\ub294 \uc758\ubbf8\uc774\ubbc0\ub85c "-\uc9c0 \uc54a\ub294 \ud55c"\uc774 \uac00\uc7a5 \uc54c\ub9de\uc2b5\ub2c8\ub2e4.')
