A.fEG=new B.O("\uadc0\ud654\ub97c \uc2e0\uccad\ud558\uae30 \uc804\uc5d0 \ud574\uc57c \ud560 \uc77c\ub85c \uc54c\ub9de\uc740 \uac83\uc740?","Tr\u01b0\u1edbc khi xin nh\u1eadp qu\u1ed1c t\u1ecbch n\xean l\xe0m g\xec?",A.hRk,0,"C\u1ea7n ki\u1ec3m tra \u0111i\u1ec1u ki\u1ec7n v\xe0 th\u1ee7 t\u1ee5c \xe1p d\u1ee5ng cho tr\u01b0\u1eddng h\u1ee3p c\u1ee7a m\xecnh.")
A.jjB=s(["\uac1c\uc778\uc758 \uc0c1\ud669\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4.","\ubaa8\ub4e0 \uc0ac\ub78c\uc5d0\uac8c \uc5b8\uc81c\ub098 \uc644\uc804\ud788 \uac19\ub2e4.","\uc544\ubb34 \uc870\uac74\ub3c4 \uc5c6\ub2e4.","\ud68c\uc0ac\uc5d0\uc11c \uc790\uc720\ub86d\uac8c \uacb0\uc815\ud55c\ub2e4."],t.s)
A.fCZ=new B.O("\uadc0\ud654 \uc694\uac74\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Ph\xe1t bi\u1ec3u n\xe0o \u0111\xfang v\u1ec1 \u0111i\u1ec1u ki\u1ec7n nh\u1eadp qu\u1ed1c t\u1ecbch?",A.jjB,0,"\u0110i\u1ec1u ki\u1ec7n c\xf3 th\u1ec3 kh\xe1c nhau t\xf9y ho\xe0n c\u1ea3nh v\xe0 lo\u1ea1i h\u1ed3 s\u01a1.")
A.hRX=s(["\ud55c\uad6d\uc5b4\uc640 \ud55c\uad6d \uc0ac\ud68c\uc5d0 \ub300\ud574 \uacf5\ubd80\ud55c\ub2e4.","\ud55c\uad6d\uc758 \ubc95\uc744 \uc804\ud600 \ubc30\uc6b0\uc9c0 \uc54a\ub294\ub2e4.","\uc0dd\ud65c\uc815\ubcf4\ub97c \ubaa8\ub450 \ubb34\uc2dc\ud55c\ub2e4.","\uc0ac\ud68c\uc640 \uc18c\ud1b5\ud558\uc9c0 \uc54a\ub294\ub2e4."],t.s)
A.fID=new B.O("\uadc0\ud654\ub97c \uc900\ube44\ud560 \ub54c \ub3c4\uc6c0\uc774 \ub418\ub294 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110i\u1ec1u g\xec c\xf3 \xedch khi chu\u1ea9n b\u1ecb nh\u1eadp qu\u1ed1c t\u1ecbch?",A.hRX,0,"Ti\u1ebfng H\xe0n v\xe0 hi\u1ec3u bi\u1ebft v\u1ec1 x\xe3 h\u1ed9i H\xe0n Qu\u1ed1c gi\xfap \xedch cho vi\u1ec7c h\xf2a nh\u1eadp v\xe0 chu\u1ea9n b\u1ecb.")
A.iWC=s(["\ud544\uc694\ud55c \uc2ec\uc0ac\uc640 \uc808\ucc28\uac00 \uc9c4\ud589\ub420 \uc218 \uc788\ub2e4.","\uc2e0\uccad\ud558\ub294 \uc21c\uac04 \uc790\ub3d9\uc73c\ub85c \uad6d\uc801\uc744 \uc5bb\ub294\ub2e4.","\uc544\ubb34 \uc808\ucc28\ub3c4 \ud544\uc694\ud558\uc9c0 \uc54a\ub2e4.","\uc740\ud589\uc774 \uad6d\uc801\uc744 \uacb0\uc815\ud55c\ub2e4."],t.s)
A.fC0=new B.O("\uadc0\ud654\ub97c \uc2e0\uccad\ud55c \ud6c4\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Ph\xe1t bi\u1ec3u n\xe0o \u0111\xfang sau khi n\u1ed9p \u0111\u01a1n xin nh\u1eadp qu\u1ed1c t\u1ecbch?",A.iWC,0,"Sau khi \u0111\u0103ng k\xfd c\xf2n c\xf3 th\u1ec3 c\xf3 c\xe1c b\u01b0\u1edbc x\xe9t duy\u1ec7t v\xe0 th\u1ee7 t\u1ee5c.")
A.hlN=s(["\uad8c\ub9ac\uc640 \uc758\ubb34\ub97c \ud568\uaed8 \uc774\ud574\ud55c\ub2e4.","\uc790\uc2e0\uc758 \uad8c\ub9ac\ub9cc \uc911\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4.","\ubc95\uc744 \uc9c0\ud0ac \ud544\uc694\uac00 \uc5c6\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4.","\ub2e4\ub978 \uc0ac\ub78c\uc758 \uad8c\ub9ac\ub97c \ubb34\uc2dc\ud55c\ub2e4."],t.s)
A.fIv=new B.O("\ub300\ud55c\ubbfc\uad6d \uad6d\ubbfc\uc774 \ub418\uc5c8\uc744 \ub54c \uc911\uc694\ud55c \ud0dc\ub3c4\ub294 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Th\xe1i \u0111\u1ed9 n\xe0o quan tr\u1ecdng khi tr\u1edf th\xe0nh c\xf4ng d\xe2n H\xe0n Qu\u1ed1c?",A.hlN,0,"C\xf4ng d\xe2n c\u1ea7n hi\u1ec3u c\u1ea3 quy\u1ec1n v\xe0 ngh\u0129a v\u1ee5.")
A.iZZ=s(["\uc874\uc911\ud574\uc57c \ud55c\ub2e4.","\ubb34\uc870\uac74 \ubb34\uc2dc\ud574\uc57c \ud55c\ub2e4.","\uc790\uc2e0\uc758 \uad8c\ub9ac\ubcf4\ub2e4 \ud56d\uc0c1 \uc5c6\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4.","\uce68\ud574\ud574\ub3c4 \uad1c\ucc2e\ub2e4."],t.s)
A.fFV=new B.O("\ub2e4\ub978 \uc0ac\ub78c\uc758 \uad8c\ub9ac\uc5d0 \ub300\ud574 \uc5b4\ub5a4 \ud0dc\ub3c4\ub97c \uac00\uc838\uc57c \ud569\ub2c8\uae4c?","C\u1ea7n c\xf3 th\xe1i \u0111\u1ed9 nh\u01b0 th\u1ebf n\xe0o \u0111\u1ed1i v\u1edbi quy\u1ec1n c\u1ee7a ng\u01b0\u1eddi kh\xe1c?",A.iZZ,0,"Trong x\xe3 h\u1ed9i d\xe2n ch\u1ee7 c\u1ea7n t\xf4n tr\u1ecdng quy\u1ec1n c\u1ee7a ng\u01b0\u1eddi kh\xe1c.")
A.jnv=s(["\uad00\ub828 \uacf5\uc2dd \uae30\uad00\uc758 \uc548\ub0b4\ub97c \ud655\uc778\ud55c\ub2e4.","\uc778\ud130\ub137\uc758 \ubaa8\ub4e0 \uae00\uc744 \uadf8\ub300\ub85c \ubbff\ub294\ub2e4.","\uce5c\uad6c \ud55c \uc0ac\ub78c\uc758 \uacbd\ud5d8\ub9cc \ub530\ub978\ub2e4.","\ud655\uc778\ud558\uc9c0 \uc54a\uace0 \uc2e0\uccad\ud55c\ub2e4."],t.s)
A.fEM=new B.O("\uad6d\uc801\uc5d0 \uad00\ud55c \uc815\ud655\ud55c \uc815\ubcf4\ub97c \ud655\uc778\ud558\ub294 \ubc29\ubc95\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740?","C\xe1ch ph\xf9 h\u1ee3p nh\u1ea5t \u0111\u1ec3 ki\u1ec3m tra th\xf4ng tin ch\xednh x\xe1c v\u1ec1 qu\u1ed1c t\u1ecbch l\xe0 g\xec?",A.jnv,0,"Th\xf4ng tin ph\xe1p l\xfd quan tr\u1ecdng n\xean \u0111\u01b0\u1ee3c ki\u1ec3m tra t\u1eeb c\u01a1 quan ch\xednh th\u1ee9c.")
A.h3S=s(["\uad6d\ubbfc\uc774 \ub41c\ub2e4\ub294 \uac83\uc740 \uad8c\ub9ac\uc640 \ucc45\uc784\uc744 \ud568\uaed8 \uc774\ud574\ud558\ub294 \uac83\uacfc \uad00\ub828\uc774 \uc788\ub2e4.","\uadc0\ud654 \uc2e0\uccad\uc790\ub294 \ubaa8\ub450 \uac19\uc740 \uc870\uac74\ub9cc \uc801\uc6a9\ubc1b\ub294\ub2e4.","\uad6d\uc801\uacfc \uccb4\ub958\uc790\uaca9\uc740 \uc644\uc804\ud788 \uac19\uc740 \uc758\ubbf8\uc774\ub2e4.","\ud55c\uad6d \uc0ac\ud68c\uc5d0 \ub300\ud55c \uc774\ud574\ub294 \uc804\ud600 \ud544\uc694\ud558\uc9c0 \uc54a\ub2e4."],t.s)
A.fCl=new B.O("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.h3S,0,"Tr\u1edf th\xe0nh c\xf4ng d\xe2n li\xean quan \u0111\u1ebfn c\u1ea3 quy\u1ec1n, tr\xe1ch nhi\u1ec7m v\xe0 vi\u1ec7c s\u1ed1ng c\xf9ng c\u1ed9ng \u0111\u1ed3ng.")
A.hIU=s([A.fIB,A.fEq,A.fEG,A.fCZ,A.fID,A.fC0,A.fIv,A.fFV,A.fEM,A.fCl],t.h)
A.hJR=s(["\uad6d\uc801 = qu\u1ed1c t\u1ecbch.","\uad6d\ubbfc = c\xf4ng d\xe2n/ng\u01b0\u1eddi d\xe2n c\u1ee7a qu\u1ed1c gia.","\uadc0\ud654 = nh\u1eadp qu\u1ed1c t\u1ecbch.","\uad6d\uc801 \ucde8\ub4dd = c\xf3 \u0111\u01b0\u1ee3c qu\u1ed1c t\u1ecbch.","\uc694\uac74 = \u0111i\u1ec1u ki\u1ec7n.","\uc808\ucc28 = th\u1ee7 t\u1ee5c.","\uc2ec\uc0ac = x\xe9t duy\u1ec7t.","\uad8c\ub9ac = quy\u1ec1n.","\uc758\ubb34 = ngh\u0129a v\u1ee5.","\uadc0\ud654\ub294 \ub300\ud55c\ubbfc\uad6d \uad6d\uc801\uc744 \ucde8\ub4dd\ud558\ub294 \ubc29\ubc95 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4.","\uadc0\ud654 \uc694\uac74\uacfc \uc808\ucc28\ub294 \uac1c\uc778\uc758 \uc0c1\ud669\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ud55c\uad6d\uc5b4\uc640 \ud55c\uad6d \uc0ac\ud68c\uc5d0 \ub300\ud55c \uc774\ud574\ub294 \uc548\uc815\uc801\uc778 \uc0ac\ud68c\uc0dd\ud65c\uc5d0 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.","\ub300\ud55c\ubbfc\uad6d \uad6d\ubbfc\uc740 \uc790\uc2e0\uc758 \uad8c\ub9ac\uc640 \ud568\uaed8 \ucc45\uc784\uacfc \uc758\ubb34\ub3c4 \uc774\ud574\ud574\uc57c \ud569\ub2c8\ub2e4.","\uad6d\uc801\uc5d0 \uad00\ud55c \uc911\uc694\ud55c \ub0b4\uc6a9\uc740 \uacf5\uc2dd \uae30\uad00\uc758 \ucd5c\uc2e0 \uc548\ub0b4\ub97c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4."],t.s)
A.fA4=new B.dJ(32,"\ubc95","\ub300\ud55c\ubbfc\uad6d \uad6d\ubbfc \ub418\uae30","Tr\u1edf th\xe0nh c\xf4ng d\xe2n H\xe0n Qu\u1ed1c",A.ix9,A.h9S,A.jEn,A.ith,"\ub300\ud55c\ubbfc\uad6d \uad6d\ubbfc\uc774 \ub418\ub294 \uacfc\uc815 \uc774\ud574\ud558\uae30","\uad6d\uc801\uc740 \ud55c \uc0ac\ub78c\uc774 \uc5b4\ub290 \uad6d\uac00\uc758 \uad6d\ubbfc\uc778\uc9c0\ub97c \ub098\ud0c0\ub0b4\ub294 \uc911\uc694\ud55c \ubc95\uc801 \uad00\uacc4\uc785\ub2c8\ub2e4.\n\n\uc678\uad6d\uc778\uc774 \ub300\ud55c\ubbfc\uad6d \uad6d\uc801\uc744 \ucde8\ub4dd\ud558\uc5ec \ub300\ud55c\ubbfc\uad6d \uad6d\ubbfc\uc774 \ub418\ub294 \ubc29\ubc95 \uc911 \ud558\ub098\uac00 \uadc0\ud654\uc785\ub2c8\ub2e4.\n\n\uadc0\ud654\ub97c \uc2e0\uccad\ud558\ub824\uba74 \uad00\ub828 \ubc95\uc5d0\uc11c \uc815\ud55c \uc694\uac74\uc744 \uac16\ucd94\uace0 \ud544\uc694\ud55c \uc808\ucc28\ub97c \ub530\ub77c\uc57c \ud569\ub2c8\ub2e4. \uc2e0\uccad\uc790\uc758 \uac00\uc871\uad00\uacc4, \uac70\uc8fc \uc0c1\ud669 \ub4f1 \uac1c\uc778\uc758 \uc0c1\ud669\uc5d0 \ub530\ub77c \uc801\uc6a9\ub418\ub294 \uc870\uac74\uc774\ub098 \uc808\ucc28\uac00 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ub530\ub77c\uc11c \ub2e4\ub978 \uc0ac\ub78c\uc758 \uacbd\ud5d8\ub9cc\uc744 \ubcf4\uace0 \uc790\uc2e0\uc758 \uacbd\uc6b0\ub3c4 \uac19\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c\ub294 \uc548 \ub429\ub2c8\ub2e4. \uc790\uc2e0\uc758 \uc0c1\ud669\uc5d0 \ub9de\ub294 \uc815\ud655\ud55c \uc815\ubcf4\ub97c \uacf5\uc2dd \uae30\uad00\uc5d0\uc11c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.\n\n\uadc0\ud654 \uacfc\uc815\uc5d0\uc11c\ub294 \ud55c\uad6d\uc5d0\uc11c \uc0dd\ud65c\ud558\ub294 \ub370 \ud544\uc694\ud55c \uae30\ubcf8\uc801\uc778 \ud55c\uad6d\uc5b4 \ub2a5\ub825\uacfc \ud55c\uad6d \uc0ac\ud68c\uc5d0 \ub300\ud55c \uc774\ud574\ub3c4 \uc911\uc694\ud558\uac8c \uc5ec\uaca8\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ud55c\uad6d \uc0ac\ud68c\uc758 \uc5ed\uc0ac, \ubb38\ud654, \ubc95\uacfc \uc81c\ub3c4 \ub4f1\uc744 \ubc30\uc6b0\ub294 \uac83\uc740 \uc2dc\ud5d8\uc744 \uc900\ube44\ud558\uae30 \uc704\ud574\uc11c\ub9cc \ud544\uc694\ud55c \uac83\uc774 \uc544\ub2d9\ub2c8\ub2e4. \uc2e4\uc81c\ub85c \uc9c0\uc5ed\uc0ac\ud68c\uc5d0\uc11c \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uacfc \ud568\uaed8 \uc0b4\uc544\uac00\ub294 \ub370\uc5d0\ub3c4 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.\n\n\ub300\ud55c\ubbfc\uad6d \uad6d\ubbfc\uc774 \ub418\uba74 \ubc95\uc5d0 \ub530\ub77c \uc5ec\ub7ec \uad8c\ub9ac\ub97c \uac00\uc9c0\uac8c \ub429\ub2c8\ub2e4. \ub3d9\uc2dc\uc5d0 \ubc95\uc744 \uc9c0\ud0a4\uace0 \uacf5\ub3d9\uccb4\uc758 \uad6c\uc131\uc6d0\uc73c\ub85c\uc11c \ucc45\uc784\uc744 \ub2e4\ud558\ub294 \uc790\uc138\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4.\n\n\uad6d\ubbfc\uc774 \ub41c\ub2e4\ub294 \uac83\uc740 \ub2e8\uc21c\ud788 \uad6d\uc801\uc744 \ucde8\ub4dd\ud558\ub294 \uac83\ub9cc\uc744 \uc758\ubbf8\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc790\uc2e0\uc758 \uad8c\ub9ac\ub97c \uc774\ud574\ud558\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uad8c\ub9ac\ub3c4 \uc874\uc911\ud558\uba74\uc11c \uc0ac\ud68c\uc758 \uad6c\uc131\uc6d0\uc73c\ub85c \ud568\uaed8 \uc0b4\uc544\uac00\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.\n","Qu\u1ed1c t\u1ecbch l\xe0 m\u1ed1i quan h\u1ec7 ph\xe1p l\xfd quan tr\u1ecdng cho bi\u1ebft m\u1ed9t ng\u01b0\u1eddi l\xe0 c\xf4ng d\xe2n c\u1ee7a qu\u1ed1c gia n\xe0o.\n\nM\u1ed9t trong nh\u1eefng c\xe1ch ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i c\xf3 th\u1ec3 c\xf3 qu\u1ed1c t\u1ecbch H\xe0n Qu\u1ed1c v\xe0 tr\u1edf th\xe0nh c\xf4ng d\xe2n H\xe0n Qu\u1ed1c l\xe0 nh\u1eadp qu\u1ed1c t\u1ecbch.\n\nMu\u1ed1n xin nh\u1eadp qu\u1ed1c t\u1ecbch, ng\u01b0\u1eddi \u0111\u0103ng k\xfd ph\u1ea3i \u0111\xe1p \u1ee9ng c\xe1c \u0111i\u1ec1u ki\u1ec7n do ph\xe1p lu\u1eadt li\xean quan quy \u0111\u1ecbnh v\xe0 th\u1ef1c hi\u1ec7n c\xe1c th\u1ee7 t\u1ee5c c\u1ea7n thi\u1ebft. T\xf9y t\xecnh tr\u1ea1ng c\u01b0 tr\xfa, quan h\u1ec7 gia \u0111\xecnh v\xe0 ho\xe0n c\u1ea3nh c\xe1 nh\xe2n c\u1ee7a ng\u01b0\u1eddi \u0111\u0103ng k\xfd m\xe0 \u0111i\u1ec1u ki\u1ec7n ho\u1eb7c th\u1ee7 t\u1ee5c \xe1p d\u1ee5ng c\xf3 th\u1ec3 kh\xe1c nhau.\n\nV\xec v\u1eady kh\xf4ng n\xean ch\u1ec9 nh\xecn v\xe0o tr\u01b0\u1eddng h\u1ee3p c\u1ee7a ng\u01b0\u1eddi kh\xe1c r\u1ed3i ngh\u0129 r\u1eb1ng tr\u01b0\u1eddng h\u1ee3p c\u1ee7a m\xecnh c\u0169ng gi\u1ed1ng nh\u01b0 v\u1eady. \u0110i\u1ec1u quan tr\u1ecdng l\xe0 ph\u1ea3i ki\u1ec3m tra th\xf4ng tin ch\xednh x\xe1c ph\xf9 h\u1ee3p v\u1edbi ho\xe0n c\u1ea3nh c\u1ee7a b\u1ea3n th\xe2n t\u1eeb c\u01a1 quan ch\xednh th\u1ee9c.\n\nTrong qu\xe1 tr\xecnh chu\u1ea9n b\u1ecb nh\u1eadp qu\u1ed1c t\u1ecbch, kh\u1ea3 n\u0103ng ti\u1ebfng H\xe0n c\u01a1 b\u1ea3n c\u1ea7n thi\u1ebft cho cu\u1ed9c s\u1ed1ng t\u1ea1i H\xe0n Qu\u1ed1c v\xe0 s\u1ef1 hi\u1ec3u bi\u1ebft v\u1ec1 x\xe3 h\u1ed9i H\xe0n Qu\u1ed1c c\u0169ng c\xf3 \xfd ngh\u0129a quan tr\u1ecdng.\n\nVi\u1ec7c h\u1ecdc l\u1ecbch s\u1eed, v\u0103n h\xf3a, ph\xe1p lu\u1eadt v\xe0 c\xe1c h\u1ec7 th\u1ed1ng c\u1ee7a H\xe0n Qu\u1ed1c kh\xf4ng ch\u1ec9 c\u1ea7n thi\u1ebft \u0111\u1ec3 chu\u1ea9n b\u1ecb cho k\u1ef3 \u0111\xe1nh gi\xe1. Nh\u1eefng ki\u1ebfn th\u1ee9c \u0111\xf3 c\xf2n gi\xfap \xedch khi th\u1ef1c t\u1ebf sinh s\u1ed1ng c\xf9ng nh\u1eefng ng\u01b0\u1eddi kh\xe1c trong c\u1ed9ng \u0111\u1ed3ng.\n\nKhi tr\u1edf th\xe0nh c\xf4ng d\xe2n H\xe0n Qu\u1ed1c, m\u1ed9t ng\u01b0\u1eddi c\xf3 nhi\u1ec1u quy\u1ec1n theo ph\xe1p lu\u1eadt. \u0110\u1ed3ng th\u1eddi, vi\u1ec7c tu\xe2n th\u1ee7 ph\xe1p lu\u1eadt v\xe0 c\xf3 tr\xe1ch nhi\u1ec7m v\u1edbi t\u01b0 c\xe1ch th\xe0nh vi\xean c\u1ee7a c\u1ed9ng \u0111\u1ed3ng c\u0169ng r\u1ea5t quan tr\u1ecdng.\n\nTr\u1edf th\xe0nh c\xf4ng d\xe2n kh\xf4ng ch\u1ec9 \u0111\u01a1n gi\u1ea3n l\xe0 c\xf3 qu\u1ed1c t\u1ecbch. \u0110i\u1ec1u quan tr\u1ecdng l\xe0 hi\u1ec3u c\xe1c quy\u1ec1n c\u1ee7a m\xecnh, t\xf4n tr\u1ecdng quy\u1ec1n c\u1ee7a ng\u01b0\u1eddi kh\xe1c v\xe0 c\xf9ng sinh s\u1ed1ng v\u1edbi t\u01b0 c\xe1ch m\u1ed9t th\xe0nh vi\xean c\u1ee7a x\xe3 h\u1ed9i.\n","\uadc0\ud654 \uc808\ucc28 \ubb38\uc758\ud558\uae30","\uc548: \uc548\ub155\ud558\uc138\uc694. \uadc0\ud654\uc5d0 \ub300\ud574 \uc54c\uc544\ubcf4\uace0 \uc2f6\uc740\ub370\uc694.\n\n\uc0c1\ub2f4\uc6d0: \ub124. \uc5b4\ub5a4 \ub0b4\uc6a9\uc774 \uad81\uae08\ud558\uc138\uc694?\n\n\uc548: \ud55c\uad6d\uc5d0\uc11c \uc624\ub798 \uc0b4\uc558\ub294\ub370 \uadc0\ud654\ub97c \uc2e0\uccad\ud560 \uc218 \uc788\ub294\uc9c0 \uc54c\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.\n\n\uc0c1\ub2f4\uc6d0: \uadc0\ud654\ub294 \uac1c\uc778\uc758 \uc0c1\ud669\uc5d0 \ub530\ub77c \ud544\uc694\ud55c \uc694\uac74\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc548: \uadf8\ub7ec\uba74 \uba3c\uc800 \ubb34\uc5c7\uc744 \ud655\uc778\ud574\uc57c \ud574\uc694?\n\n\uc0c1\ub2f4\uc6d0: \ubcf8\uc778\uc758 \uccb4\ub958 \uc0c1\ud669\uacfc \uac00\uc871\uad00\uacc4 \ub4f1 \uae30\ubcf8\uc801\uc778 \uc815\ubcf4\ub97c \ud655\uc778\ud55c \ud6c4 \uc5b4\ub5a4 \uc808\ucc28\uac00 \uc801\uc6a9\ub418\ub294\uc9c0 \uc54c\uc544\ubcf4\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.\n\n\uc548: \ud55c\uad6d\uc5b4 \uacf5\ubd80\ub3c4 \uacc4\uc18d\ud574\uc57c\uaca0\ub124\uc694.\n\n\uc0c1\ub2f4\uc6d0: \ub124. \ud55c\uad6d\uc5d0\uc11c \uc0dd\ud65c\ud558\ub824\uba74 \ud55c\uad6d\uc5b4 \ub2a5\ub825\uacfc \ud55c\uad6d \uc0ac\ud68c\uc5d0 \ub300\ud55c \uc774\ud574\uac00 \ub9ce\uc740 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.\n\n\uc548: \uc2e0\uccad\ud558\uba74 \ubc14\ub85c \uad6d\uc801\uc744 \ubc1b\uc744 \uc218 \uc788\ub098\uc694?\n\n\uc0c1\ub2f4\uc6d0: \uc2e0\uccad \ud6c4\uc5d0\ub294 \ud544\uc694\ud55c \uc2ec\uc0ac\uc640 \uc808\ucc28\uac00 \uc9c4\ud589\ub420 \uc218 \uc788\uae30 \ub54c\ubb38\uc5d0 \ubc14\ub85c \uacb0\uc815\ub41c\ub2e4\uace0 \uc0dd\uac01\ud558\uba74 \uc548 \ub429\ub2c8\ub2e4.\n\n\uc548: \uc778\ud130\ub137\uc5d0 \uc815\ubcf4\uac00 \uc544\uc8fc \ub9ce\uc740\ub370 \uc5b4\ub5a4 \uac83\uc744 \ubd10\uc57c \ud560\uae4c\uc694?\n\n\uc0c1\ub2f4\uc6d0: \uad6d\uc801\uacfc \uad00\ub828\ub41c \uc911\uc694\ud55c \ub0b4\uc6a9\uc740 \uacf5\uc2dd \uae30\uad00\uc758 \ucd5c\uc2e0 \uc548\ub0b4\ub97c \ud655\uc778\ud558\ub294 \uac83\uc774 \uac00\uc7a5 \uc88b\uc2b5\ub2c8\ub2e4.\n\n\uc548: \ub124. \ub2e4\ub978 \uc0ac\ub78c\uc758 \uacbd\uc6b0\ub9cc \ubcf4\uace0 \ud310\ub2e8\ud558\uc9c0 \ub9d0\uc544\uc57c\uaca0\ub124\uc694.\n\n\uc0c1\ub2f4\uc6d0: \ub9de\uc2b5\ub2c8\ub2e4. \uc0ac\ub78c\ub9c8\ub2e4 \uc0c1\ud669\uc774 \ub2e4\ub97c \uc218 \uc788\uc73c\ub2c8\uae4c \uc790\uc2e0\uc758 \uc870\uac74\uc744 \uc815\ud655\ud788 \ud655\uc778\ud558\uc138\uc694.\n","An: Xin ch\xe0o. T\xf4i mu\u1ed1n t\xecm hi\u1ec3u v\u1ec1 vi\u1ec7c nh\u1eadp qu\u1ed1c t\u1ecbch.\n\nNh\xe2n vi\xean t\u01b0 v\u1ea5n: V\xe2ng. Anh mu\u1ed1n bi\u1ebft n\u1ed9i dung g\xec?\n\nAn: T\xf4i \u0111\xe3 s\u1ed1ng \u1edf H\xe0n Qu\u1ed1c kh\xe1 l\xe2u v\xe0 mu\u1ed1n bi\u1ebft m\xecnh c\xf3 th\u1ec3 xin nh\u1eadp qu\u1ed1c t\u1ecbch kh\xf4ng.\n\nNh\xe2n vi\xean: C\xe1c \u0111i\u1ec1u ki\u1ec7n c\u1ea7n thi\u1ebft c\xf3 th\u1ec3 kh\xe1c nhau t\xf9y ho\xe0n c\u1ea3nh c\u1ee7a t\u1eebng ng\u01b0\u1eddi.\n\nAn: V\u1eady tr\u01b0\u1edbc ti\xean t\xf4i c\u1ea7n ki\u1ec3m tra \u0111i\u1ec1u g\xec?\n\nNh\xe2n vi\xean: N\xean ki\u1ec3m tra t\xecnh tr\u1ea1ng c\u01b0 tr\xfa, quan h\u1ec7 gia \u0111\xecnh v\xe0 nh\u1eefng th\xf4ng tin c\u01a1 b\u1ea3n c\u1ee7a b\u1ea3n th\xe2n, sau \u0111\xf3 t\xecm hi\u1ec3u th\u1ee7 t\u1ee5c n\xe0o \xe1p d\u1ee5ng cho tr\u01b0\u1eddng h\u1ee3p c\u1ee7a m\xecnh.\n\nAn: V\u1eady t\xf4i c\u0169ng n\xean ti\u1ebfp t\u1ee5c h\u1ecdc ti\u1ebfng H\xe0n nh\u1ec9.\n\nNh\xe2n vi\xean: V\xe2ng. Kh\u1ea3 n\u0103ng ti\u1ebfng H\xe0n v\xe0 hi\u1ec3u bi\u1ebft v\u1ec1 x\xe3 h\u1ed9i H\xe0n Qu\u1ed1c gi\xfap \xedch r\u1ea5t nhi\u1ec1u khi sinh s\u1ed1ng t\u1ea1i H\xe0n Qu\u1ed1c.\n\nAn: N\u1ebfu n\u1ed9p h\u1ed3 s\u01a1 th\xec c\xf3 th\u1ec3 nh\u1eadn qu\u1ed1c t\u1ecbch ngay kh\xf4ng?\n\nNh\xe2n vi\xean: Sau khi n\u1ed9p h\u1ed3 s\u01a1 c\xf3 th\u1ec3 ph\u1ea3i tr\u1ea3i qua c\xe1c b\u01b0\u1edbc x\xe9t duy\u1ec7t v\xe0 th\u1ee7 t\u1ee5c c\u1ea7n thi\u1ebft, v\xec v\u1eady kh\xf4ng n\xean ngh\u0129 r\u1eb1ng s\u1ebd \u0111\u01b0\u1ee3c quy\u1ebft \u0111\u1ecbnh ngay.\n\nAn: Tr\xean Internet c\xf3 r\u1ea5t nhi\u1ec1u th\xf4ng tin, t\xf4i n\xean xem th\xf4ng tin n\xe0o?\n\nNh\xe2n vi\xean: \u0110\u1ed1i v\u1edbi n\u1ed9i dung quan tr\u1ecdng v\u1ec1 qu\u1ed1c t\u1ecbch, t\u1ed1t nh\u1ea5t n\xean ki\u1ec3m tra h\u01b0\u1edbng d\u1eabn m\u1edbi nh\u1ea5t t\u1eeb c\u01a1 quan ch\xednh th\u1ee9c.\n\nAn: V\xe2ng. T\xf4i kh\xf4ng n\xean ch\u1ec9 nh\xecn tr\u01b0\u1eddng h\u1ee3p c\u1ee7a ng\u01b0\u1eddi kh\xe1c r\u1ed3i t\u1ef1 k\u1ebft lu\u1eadn.\n\nNh\xe2n vi\xean: \u0110\xfang v\u1eady. Ho\xe0n c\u1ea3nh m\u1ed7i ng\u01b0\u1eddi c\xf3 th\u1ec3 kh\xe1c nhau n\xean h\xe3y ki\u1ec3m tra ch\xednh x\xe1c \u0111i\u1ec1u ki\u1ec7n c\u1ee7a b\u1ea3n th\xe2n.\n",A.jGR,A.ikN,A.hIU,A.hJR)
A.jxi=s(["Hi\u1ec3u kh\xe1i ni\u1ec7m \uc900\ubc95 v\xe0 \uc900\ubc95\uc758\uc2dd.","Hi\u1ec3u v\xec sao m\u1ecdi th\xe0nh vi\xean trong x\xe3 h\u1ed9i c\u1ea7n tu\xe2n th\u1ee7 ph\xe1p lu\u1eadt.","Bi\u1ebft m\u1ed1i quan h\u1ec7 gi\u1eefa ph\xe1p lu\u1eadt, tr\u1eadt t\u1ef1 v\xe0 quy\u1ec1n l\u1ee3i c\u1ee7a con ng\u01b0\u1eddi.","Hi\u1ec3u r\u1eb1ng tu\xe2n th\u1ee7 quy t\u1eafc nh\u1ecf trong \u0111\u1eddi s\u1ed1ng c\u0169ng l\xe0 m\u1ed9t ph\u1ea7n c\u1ee7a \xfd th\u1ee9c ph\xe1p lu\u1eadt.","Bi\u1ebft h\u1eadu qu\u1ea3 c\xf3 th\u1ec3 x\u1ea3y ra khi vi ph\u1ea1m ph\xe1p lu\u1eadt.","Hi\u1ec3u tr\xe1ch nhi\u1ec7m c\u1ee7a m\u1ed7i c\xe1 nh\xe2n trong c\u1ed9ng \u0111\u1ed3ng.","Luy\u1ec7n \u0111\u1ecdc hi\u1ec3u v\xe0 c\xe2u h\u1ecfi ki\u1ebfn th\u1ee9c x\xe3 h\u1ed9i li\xean quan \u0111\u1ebfn tu\xe2n th\u1ee7 ph\xe1p lu\u1eadt."],t.s)
A.jhl=s(["\uc900\ubc95\uc740 \ubc95\uacfc \uaddc\uce59\uc744 \uc9c0\ud0a4\ub294 \uac83\uc744 \ub9d0\ud569\ub2c8\ub2e4.","\uc900\ubc95\uc758\uc2dd\uc740 \ubc95\uc744 \uc874\uc911\ud558\uace0 \uc2a4\uc2a4\ub85c \uc9c0\ud0a4\ub824\ub294 \ud0dc\ub3c4\ub97c \uc758\ubbf8\ud569\ub2c8\ub2e4.","\uc0ac\ud68c \uad6c\uc131\uc6d0\uc774 \ubc95\uc744 \uc9c0\ud0a4\uba74 \uc0ac\ud68c\uc758 \uc9c8\uc11c\uc640 \uc548\uc804\uc744 \uc720\uc9c0\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.","\ubc95\uc740 \uac1c\uc778\uc758 \uc790\uc720\uc640 \uad8c\ub9ac\ub97c \ubcf4\ud638\ud558\uba74\uc11c \ub2e4\ub978 \uc0ac\ub78c\uc758 \uad8c\ub9ac\ub3c4 \ud568\uaed8 \ubcf4\ud638\ud558\ub294 \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4.","\uad50\ud1b5\ubc95\uaddc, \uadfc\ub85c \uad00\ub828 \uaddc\uce59, \uc0dd\ud65c \uc18d \uc548\uc804\uaddc\uce59 \ub4f1\uc744 \uc9c0\ud0a4\ub294 \uac83\ub3c4 \uc900\ubc95\uc0dd\ud65c\uc758 \uc77c\ubd80\uc785\ub2c8\ub2e4.","\ubc95\uc744 \uc704\ubc18\ud558\uba74 \uc0c1\ud669\uc5d0 \ub530\ub77c \ubc8c\uae08\uc774\ub098 \ucc98\ubc8c \ub4f1\uc758 \ubc95\uc801 \ucc45\uc784\uc774 \uc0dd\uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ubc95\uc744 \uc9c0\ud0a4\ub294 \uac83\uc740 \ucc98\ubc8c\uc744 \ud53c\ud558\uae30 \uc704\ud574\uc11c\ub9cc\uc774 \uc544\ub2c8\ub77c \uc11c\ub85c \uc2e0\ub8b0\ud558\uba70 \uc0b4\uc544\uac00\uae30 \uc704\ud574 \uc911\uc694\ud569\ub2c8\ub2e4.","\ubbfc\uc8fc\uc0ac\ud68c\uc5d0\uc11c\ub294 \uc790\uc2e0\uc758 \uad8c\ub9ac\ub97c \uc8fc\uc7a5\ud558\ub294 \uac83\uacfc \ud568\uaed8 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uad8c\ub9ac\uc640 \uacf5\ub3d9\uccb4\uc758 \uc9c8\uc11c\ub3c4 \uc874\uc911\ud574\uc57c \ud569\ub2c8\ub2e4."],t.s)
