A.jML=s(["\uc900\ubc95 = h\xe0nh \u0111\u1ed9ng tu\xe2n th\u1ee7 ph\xe1p lu\u1eadt; \uc900\ubc95\uc758\uc2dd = \xfd th\u1ee9c v\xe0 th\xe1i \u0111\u1ed9 t\u1ef1 gi\xe1c tu\xe2n th\u1ee7 ph\xe1p lu\u1eadt.","\ubc95\uacfc \uaddc\uce59\uc740 \uac19\uc740 \ub9d0\uc774 \uc544\ub2c8\uc9c0\ub9cc \uc0ac\ud68c \uc9c8\uc11c\ub97c \uc720\uc9c0\ud558\uae30 \uc704\ud55c \uae30\uc900\uc774\ub77c\ub294 \uacf5\ud1b5\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4.","\uad8c\ub9ac\uac00 \uc788\ub2e4\uace0 \ud574\uc11c \ub2e4\ub978 \uc0ac\ub78c\uc758 \uad8c\ub9ac\ub97c \uce68\ud574\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.","\ubc95 \uc704\ubc18\uc740 \uc0c1\ud669\uacfc \ubc95\ub960\uc5d0 \ub530\ub77c \uc11c\ub85c \ub2e4\ub978 \ucc45\uc784\uc774\ub098 \ucc98\ubc8c\uc774 \ubc1c\uc0dd\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ubc8c\uae08 = ti\u1ec1n ph\u1ea1t; \ucc98\ubc8c = kh\xe1i ni\u1ec7m r\u1ed9ng h\u01a1n v\u1ec1 x\u1eed ph\u1ea1t.","\uad50\ud1b5\ubc95\uaddc\ub97c \uc9c0\ud0a4\ub294 \uac83\ub3c4 \uc900\ubc95\uc0dd\ud65c\uc758 \ud55c \uc608\uc785\ub2c8\ub2e4.","\uc900\ubc95\uc740 \ucc98\ubc8c\uc744 \ud53c\ud558\uae30 \uc704\ud55c \ud589\ub3d9\ub9cc\uc744 \uc758\ubbf8\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\uacf5\ub3d9\uccb4 \uc0dd\ud65c\uc5d0\uc11c\ub294 \uac1c\uc778\uc758 \uc790\uc720\uc640 \ud568\uaed8 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc548\uc804\uacfc \uad8c\ub9ac\ub3c4 \uc0dd\uac01\ud574\uc57c \ud569\ub2c8\ub2e4."],t.s)
A.jgg=s(["\uc900\ubc95 \u2192 tu\xe2n th\u1ee7 ph\xe1p lu\u1eadt.","\uc900\ubc95\uc758\uc2dd \u2192 \xfd th\u1ee9c t\u1ef1 gi\xe1c t\xf4n tr\u1ecdng v\xe0 tu\xe2n th\u1ee7 ph\xe1p lu\u1eadt.","\ubc95\uc740 \uc0ac\ud68c \uc9c8\uc11c\ub97c \uc720\uc9c0\ud558\ub294 \ub370 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud55c\ub2e4.","\ubc95\uc740 \uac1c\uc778\uc758 \uad8c\ub9ac\ub97c \ubcf4\ud638\ud558\ub294 \uc5ed\ud560\uc744 \ud55c\ub2e4.","\ubc95\uc744 \uc704\ubc18\ud558\uba74 \ubc95\uc801\uc778 \ucc45\uc784\uc774 \uc0dd\uae38 \uc218 \uc788\ub2e4.","\uad50\ud1b5\ubc95\uaddc\uc640 \uc548\uc804\uaddc\uce59\uc744 \uc9c0\ud0a4\ub294 \uac83\uc740 \uc0ac\uace0 \uc608\ubc29\uc5d0 \ub3c4\uc6c0\uc774 \ub41c\ub2e4.","\uc790\uc2e0\uc758 \uad8c\ub9ac\ubfd0 \uc544\ub2c8\ub77c \ub2e4\ub978 \uc0ac\ub78c\uc758 \uad8c\ub9ac\ub3c4 \uc874\uc911\ud574\uc57c \ud55c\ub2e4.","\uc900\ubc95\uc0dd\ud65c\uc740 \uc0ac\ud68c\uc801 \uc2e0\ub8b0\ub97c \ub192\uc774\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\ub2e4.","\uc77c\uc0c1\uc0dd\ud65c\uc758 \uc791\uc740 \uaddc\uce59\uc744 \uc9c0\ud0a4\ub294 \uac83\ub3c4 \uc911\uc694\ud558\ub2e4."],t.s)
A.jD4=s(["\ubc95\uacfc \uaddc\uce59\uc744 \uc9c0\ud0a4\ub294 \uac83","\ubc95\uc744 \ub9c8\uc74c\ub300\ub85c \ubc14\uafb8\ub294 \uac83","\uaddc\uce59\uc744 \ubaa8\ub450 \ubb34\uc2dc\ud558\ub294 \uac83","\ubc95\uc6d0\uc5d0\uc11c\ub9cc \uc77c\ud558\ub294 \uac83"],t.s)
A.fFb=new B.O("\u201c\uc900\ubc95\u201d\uc758 \ub73b\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\xdd ngh\u0129a ph\xf9 h\u1ee3p nh\u1ea5t c\u1ee7a \uc900\ubc95 l\xe0 g\xec?",A.jD4,0,"\uc900\ubc95 = tu\xe2n th\u1ee7 ph\xe1p lu\u1eadt v\xe0 c\xe1c quy \u0111\u1ecbnh.")
A.hYZ=s(["\ubc95\uc744 \uc874\uc911\ud558\uace0 \uc2a4\uc2a4\ub85c \uc9c0\ud0a4\ub824\ub294 \ud0dc\ub3c4","\ubc95\uc744 \uc704\ubc18\ud558\ub824\ub294 \ud0dc\ub3c4","\ub2e4\ub978 \uc0ac\ub78c\uc758 \uad8c\ub9ac\ub97c \ubb34\uc2dc\ud558\ub294 \ud0dc\ub3c4","\uaddc\uce59\uc774 \ud544\uc694 \uc5c6\ub2e4\uace0 \uc0dd\uac01\ud558\ub294 \ud0dc\ub3c4"],t.s)
A.fC_=new B.O("\u201c\uc900\ubc95\uc758\uc2dd\u201d\uc758 \uc124\uba85\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Gi\u1ea3i th\xedch n\xe0o ph\xf9 h\u1ee3p v\u1edbi \uc900\ubc95\uc758\uc2dd?",A.hYZ,0,"\uc900\ubc95\uc758\uc2dd l\xe0 th\xe1i \u0111\u1ed9 t\xf4n tr\u1ecdng v\xe0 t\u1ef1 gi\xe1c tu\xe2n th\u1ee7 ph\xe1p lu\u1eadt.")
A.hp8=s(["\uc0ac\ud68c \uc9c8\uc11c\uc640 \uc0ac\ub78c\ub4e4\uc758 \uad8c\ub9ac\ub97c \ubcf4\ud638\ud558\uae30 \uc704\ud574\uc11c","\ub2e4\ub978 \uc0ac\ub78c\uc744 \ubd88\ud3b8\ud558\uac8c \ud558\uae30 \uc704\ud574\uc11c","\ubaa8\ub4e0 \uc790\uc720\ub97c \uc5c6\uc560\uae30 \uc704\ud574\uc11c","\uc0ac\ub78c\ub4e4\uc744 \uc11c\ub85c \ubbff\uc9c0 \ubabb\ud558\uac8c \ud558\uae30 \uc704\ud574\uc11c"],t.s)
A.fHr=new B.O("\ubc95\uc744 \uc9c0\ud0a4\ub294 \uc774\uc720\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","L\xfd do ph\xf9 h\u1ee3p \u0111\u1ec3 tu\xe2n th\u1ee7 ph\xe1p lu\u1eadt l\xe0 g\xec?",A.hp8,0,"Ph\xe1p lu\u1eadt g\xf3p ph\u1ea7n duy tr\xec tr\u1eadt t\u1ef1 v\xe0 b\u1ea3o v\u1ec7 quy\u1ec1n c\u1ee7a con ng\u01b0\u1eddi.")
A.hwL=s(["\uc0ac\uace0 \uc608\ubc29\uacfc \uc548\uc804\uc5d0 \ub3c4\uc6c0\uc774 \ub41c\ub2e4.","\uad50\ud1b5\uc0ac\uace0\uac00 \ub354 \ub9ce\uc544\uc9c4\ub2e4.","\ub2e4\ub978 \uc0ac\ub78c\uc758 \uc548\uc804\uc774 \ub354 \uc704\ud5d8\ud574\uc9c4\ub2e4.","\uad50\ud1b5\uc9c8\uc11c\uac00 \uc5c6\uc5b4\uc9c0\uac8c \ub41c\ub2e4."],t.s)
A.fBO=new B.O("\uad50\ud1b5\ubc95\uaddc\ub97c \uc9c0\ucf30\uc744 \ub54c \uae30\ub300\ud560 \uc218 \uc788\ub294 \ud6a8\uacfc\ub294 \ubb34\uc5c7\uc785\ub2c8\uae4c?","C\xf3 th\u1ec3 k\u1ef3 v\u1ecdng l\u1ee3i \xedch n\xe0o khi tu\xe2n th\u1ee7 lu\u1eadt giao th\xf4ng?",A.hwL,0,"Tu\xe2n th\u1ee7 lu\u1eadt giao th\xf4ng gi\xfap t\u0103ng an to\xe0n v\xe0 ph\xf2ng ng\u1eeba tai n\u1ea1n.")
