A.fX_=new B.r("\uad50\ud1b5 \ud63c\uc7a1","\xf9n t\u1eafc giao th\xf4ng","\ucd9c\ud1f4\uadfc \uc2dc\uac04\uc5d0\ub294 \uad50\ud1b5 \ud63c\uc7a1\uc774 \uc2ec\ud569\ub2c8\ub2e4.","V\xe0o gi\u1edd \u0111i l\xe0m v\xe0 tan l\xe0m, t\xecnh tr\u1ea1ng \xf9n t\u1eafc giao th\xf4ng nghi\xeam tr\u1ecdng.")
A.fSr=new B.r("\uc8fc\ucc28 \ubb38\uc81c","v\u1ea5n \u0111\u1ec1 \u0111\u1ed7 xe","\uc8fc\ud0dd\uac00\uc5d0\uc11c\ub294 \uc8fc\ucc28 \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud558\uae30\ub3c4 \ud569\ub2c8\ub2e4.","T\u1ea1i c\xe1c khu d\xe2n c\u01b0 \u0111\xf4i khi ph\xe1t sinh v\u1ea5n \u0111\u1ec1 \u0111\u1ed7 xe.")
A.fVQ=new B.r("\uc18c\uc74c","ti\u1ebfng \u1ed3n","\uc8fc\ubbfc\ub4e4\uc774 \uacf5\uc0ac\uc7a5\uc758 \uc18c\uc74c \ubb38\uc81c\ub97c \uc2e0\uace0\ud588\uc2b5\ub2c8\ub2e4.","Ng\u01b0\u1eddi d\xe2n \u0111\xe3 b\xe1o v\u1ea5n \u0111\u1ec1 ti\u1ebfng \u1ed3n t\u1ea1i c\xf4ng tr\u01b0\u1eddng.")
