A.i8A=s(["\uac74\uad6d\uc2e0\ud654\ub85c\uc11c \uc5ed\uc0ac\uc801 \uc758\ubbf8\uc640 \uc2e0\ud654\uc801 \ub0b4\uc6a9\uc744 \ud568\uaed8 \uc774\ud574\ud55c\ub2e4.","\ubaa8\ub4e0 \ub0b4\uc6a9\uc744 \ud604\ub300\uc758 \uc815\ud655\ud55c \uae30\ub85d\uc774\ub77c\uace0 \uc0dd\uac01\ud55c\ub2e4.","\ud55c\uad6d \uc5ed\uc0ac\uc640 \uc544\ubb34 \uad00\uacc4\uac00 \uc5c6\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4.","\ud604\ub300 \ubc95\ub960 \ubb38\uc11c\ub77c\uace0 \uc0dd\uac01\ud55c\ub2e4."],t.s)
A.fEN=new B.O("\ub2e8\uad70\uc2e0\ud654\ub97c \uc774\ud574\ud558\ub294 \ud0dc\ub3c4\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","C\xe1ch hi\u1ec3u ph\xf9 h\u1ee3p nh\u1ea5t \u0111\u1ed1i v\u1edbi th\u1ea7n tho\u1ea1i Dangun l\xe0 g\xec?",A.i8A,0,"\u0110\xe2y l\xe0 th\u1ea7n tho\u1ea1i l\u1eadp qu\u1ed1c, c\u1ea7n hi\u1ec3u c\u1ea3 \xfd ngh\u0129a l\u1ecbch s\u1eed v\xe0 \u0111\u1eb7c \u0111i\u1ec3m th\u1ea7n tho\u1ea1i.")
A.ii8=s(["\uace0\uc870\uc120\uc5d0\ub294 \uc0ac\ud68c\uc9c8\uc11c\ub97c \uc720\uc9c0\ud558\uae30 \uc704\ud55c \ubc95\uc774 \uc788\uc5c8\ub2e4.","\ud638\ub791\uc774\uc640 \uacf0\uc774 \ubaa8\ub450 \uc0ac\ub78c\uc774 \ub418\uc5c8\ub2e4.","\uace0\uc870\uc120\uc5d0\ub294 \ubc95\uc774 \uc804\ud600 \uc5c6\uc5c8\ub2e4.","\ud64d\uc775\uc778\uac04\uc740 \ub2e4\ub978 \uc0ac\ub78c\uc744 \ud574\uce5c\ub2e4\ub294 \ub73b\uc774\ub2e4."],t.s)
A.fGc=new B.O("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.ii8,0,"\uace0\uc870\uc120\uc5d0\ub294 8\uc870\ubc95\uc774 \uc788\uc5c8\ub2e4\uace0 \uc54c\ub824\uc838 \uc788\uc2b5\ub2c8\ub2e4.")
A.iqx=s([A.fBp,A.fBq,A.fC7,A.fDL,A.fEA,A.fDP,A.fCh,A.fGU,A.fEN,A.fGc],t.h)
A.jKF=s(["\uace0\uc870\uc120 = \ud55c\uad6d \uace0\ub300\uc0ac\uc758 \uc911\uc694\ud55c \ucd08\uae30 \uad6d\uac00.","\uac74\uad6d = l\u1eadp qu\u1ed1c.","\ub2e8\uad70\uc655\uac80 = nh\xe2n v\u1eadt trung t\xe2m c\u1ee7a th\u1ea7n tho\u1ea1i l\u1eadp qu\u1ed1c Gojoseon.","\ud658\uc6c5 = Hwanung.","\uc6c5\ub140 = Ungnyeo.","\ub2e8\uad70\uc2e0\ud654 = th\u1ea7n tho\u1ea1i Dangun.","\ud64d\uc775\uc778\uac04 = \ub110\ub9ac \uc778\uac04\uc744 \uc774\ub86d\uac8c \ud55c\ub2e4.","\uc81c\uc815\uc77c\uce58 = ch\xednh tr\u1ecb v\xe0 t\u1ebf t\u1ef1 c\xf3 quan h\u1ec7 m\u1eadt thi\u1ebft.","8\uc870\ubc95 = lu\u1eadt c\u1ee7a Gojoseon.","8\uc870\ubc95\uc744 \ud1b5\ud574 \ub2f9\uc2dc \uc0ac\ud68c\uc758 \uc9c8\uc11c\uc640 \uc7ac\uc0b0\uc5d0 \ub300\ud55c \uc0dd\uac01\uc744 \uc774\ud574\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ub2e8\uad70\uc2e0\ud654\ub294 \uace0\uc870\uc120\uc758 \uac74\uad6d\uacfc \uad00\ub828\ub41c \uc911\uc694\ud55c \uc804\ud1b5 \uc774\uc57c\uae30\uc785\ub2c8\ub2e4.","\uc5ed\uc0ac\ub97c \uacf5\ubd80\ud560 \ub54c\uc5d0\ub294 \uc2e0\ud654\uc801 \ub0b4\uc6a9\uacfc \uc5ed\uc0ac\uc801 \uc0ac\uc2e4\uc744 \uad6c\ubd84\ud558\uc5ec \uc774\ud574\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4."],t.s)
A.fA8=new B.dJ(37,"\uc5ed\uc0ac","\uace0\uc870\uc120\uc758 \uac74\uad6d","S\u1ef1 th\xe0nh l\u1eadp Gojoseon",A.ii_,A.hh8,A.iFj,A.hUb,"\uace0\uc870\uc120\uacfc \ub2e8\uad70\uc2e0\ud654","\uace0\uc870\uc120\uc740 \ud55c\uad6d \uace0\ub300\uc0ac\uc5d0\uc11c \uc911\uc694\ud55c \uad6d\uac00\uc785\ub2c8\ub2e4.\n\n\uc804\ud1b5\uc801\uc778 \uac74\uad6d \uc774\uc57c\uae30\uc5d0\uc11c\ub294 \ub2e8\uad70\uc655\uac80\uc774 \uace0\uc870\uc120\uc744 \uc138\uc6e0\ub2e4\uace0 \uc804\ud574\uc9d1\ub2c8\ub2e4. \ub2e8\uad70\uc758 \uac74\uad6d \uc774\uc57c\uae30\ub97c \ub2e8\uad70\uc2e0\ud654\ub77c\uace0 \ubd80\ub985\ub2c8\ub2e4.\n\n\ub2e8\uad70\uc2e0\ud654\uc5d0 \ub530\ub974\uba74 \ud558\ub298\uc758 \uc2e0\uc778 \ud658\uc778\uc758 \uc544\ub4e4 \ud658\uc6c5\uc740 \uc778\uac04 \uc138\uc0c1\uc5d0\uc11c \uc0b4\uae30\ub97c \uc6d0\ud588\uc2b5\ub2c8\ub2e4. \ud658\uc6c5\uc740 \ud558\ub298\uc5d0\uc11c \ub0b4\ub824\uc640 \uc0ac\ub78c\ub4e4\uc744 \ub2e4\uc2a4\ub838\ub2e4\uace0 \uc804\ud574\uc9d1\ub2c8\ub2e4.\n\n\uadf8\ub54c \uacf0\uacfc \ud638\ub791\uc774\uac00 \uc0ac\ub78c\uc774 \ub418\uace0 \uc2f6\uc5b4 \ud588\uc2b5\ub2c8\ub2e4. \ud658\uc6c5\uc740 \uacf0\uacfc \ud638\ub791\uc774\uc5d0\uac8c \uc465\uacfc \ub9c8\ub298\uc744 \uc8fc\uace0 \uc77c\uc815 \uae30\uac04 \ud587\ube5b\uc744 \ubcf4\uc9c0 \ub9d0\ub77c\uace0 \ud588\uc2b5\ub2c8\ub2e4.\n\n\ud638\ub791\uc774\ub294 \uc774\ub97c \uacac\ub514\uc9c0 \ubabb\ud588\uc9c0\ub9cc \uacf0\uc740 \uacac\ub514\uc5b4 \uc5ec\uc790\uac00 \ub418\uc5c8\uace0, \uc774 \uc5ec\uc790\ub97c \uc6c5\ub140\ub77c\uace0 \ud569\ub2c8\ub2e4.\n\n\uc774\ud6c4 \uc6c5\ub140\uc640 \ud658\uc6c5 \uc0ac\uc774\uc5d0\uc11c \ub2e8\uad70\uc655\uac80\uc774 \ud0dc\uc5b4\ub0ac\uace0 \ub2e8\uad70\uc655\uac80\uc774 \uace0\uc870\uc120\uc744 \uc138\uc6e0\ub2e4\uace0 \uc804\ud574\uc9d1\ub2c8\ub2e4.\n\n\ub2e8\uad70\uc2e0\ud654\uc5d0\ub294 \ud64d\uc775\uc778\uac04\uc774\ub77c\ub294 \uc0dd\uac01\ub3c4 \ub098\ud0c0\ub0a9\ub2c8\ub2e4. \ud64d\uc775\uc778\uac04\uc740 '\ub110\ub9ac \uc778\uac04\uc744 \uc774\ub86d\uac8c \ud55c\ub2e4'\ub294 \uc758\ubbf8\ub85c \uc124\uba85\ub429\ub2c8\ub2e4.\n\n\uace0\uc870\uc120\uc5d0\ub294 \uc0ac\ud68c\uc758 \uc9c8\uc11c\ub97c \uc720\uc9c0\ud558\uae30 \uc704\ud55c \ubc95\ub3c4 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc774\ub97c 8\uc870\ubc95\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4. \ubaa8\ub4e0 \ub0b4\uc6a9\uc774 \uc624\ub298\ub0a0\uae4c\uc9c0 \uc804\ud574\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc \ub0a8\uc544 \uc788\ub294 \ub0b4\uc6a9\uc744 \ud1b5\ud574 \ub2f9\uc2dc \uc0ac\ud68c\uc758 \ubaa8\uc2b5\uc744 \uc5b4\ub290 \uc815\ub3c4 \uc774\ud574\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc608\ub97c \ub4e4\uc5b4 \uc0ac\ub78c\uc758 \uc0dd\uba85\uacfc \uc7ac\uc0b0\uc744 \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud588\uc73c\uba70 \uc0ac\uc720\uc7ac\uc0b0\uacfc \uc0ac\ud68c\uc801 \uacc4\uce35\uc774 \uc874\uc7ac\ud588\uc74c\uc744 \ucd94\uce21\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ub2e8\uad70\uc2e0\ud654\ub294 \uc5ed\uc0ac\uc801 \uc0ac\uc2e4\uc744 \uadf8\ub300\ub85c \uae30\ub85d\ud55c \uc790\ub8cc\ub77c\uae30\ubcf4\ub2e4 \uace0\ub300 \uc0ac\ub78c\ub4e4\uc774 \uc790\uc2e0\ub4e4\uc758 \uad6d\uac00\uc640 \uc0ac\ud68c\ub97c \uc5b4\ub5bb\uac8c \uc774\ud574\ud588\ub294\uc9c0\ub97c \ubcf4\uc5ec \uc8fc\ub294 \uc911\uc694\ud55c \uac74\uad6d \uc774\uc57c\uae30\ub85c \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n","Gojoseon l\xe0 m\u1ed9t qu\u1ed1c gia quan tr\u1ecdng trong l\u1ecbch s\u1eed c\u1ed5 \u0111\u1ea1i H\xe0n Qu\u1ed1c.\n\nTrong c\xe2u chuy\u1ec7n l\u1eadp qu\u1ed1c truy\u1ec1n th\u1ed1ng, Dangun Wanggeom \u0111\u01b0\u1ee3c k\u1ec3 l\xe0 ng\u01b0\u1eddi \u0111\xe3 th\xe0nh l\u1eadp Gojoseon. C\xe2u chuy\u1ec7n l\u1eadp qu\u1ed1c c\u1ee7a Dangun \u0111\u01b0\u1ee3c g\u1ecdi l\xe0 th\u1ea7n tho\u1ea1i Dangun.\n\nTheo th\u1ea7n tho\u1ea1i Dangun, Hwanung, con trai c\u1ee7a th\u1ea7n tr\u1eddi Hwanin, mu\u1ed1n s\u1ed1ng trong th\u1ebf gi\u1edbi lo\xe0i ng\u01b0\u1eddi. Hwanung \u0111\u01b0\u1ee3c k\u1ec3 l\xe0 \u0111\xe3 t\u1eeb tr\u1eddi xu\u1ed1ng v\xe0 cai qu\u1ea3n con ng\u01b0\u1eddi.\n\nKhi \u0111\xf3 c\xf3 m\u1ed9t con g\u1ea5u v\xe0 m\u1ed9t con h\u1ed5 mu\u1ed1n tr\u1edf th\xe0nh ng\u01b0\u1eddi. Hwanung \u0111\u01b0a cho ch\xfang ng\u1ea3i c\u1ee9u v\xe0 t\u1ecfi, \u0111\u1ed3ng th\u1eddi y\xeau c\u1ea7u kh\xf4ng nh\xecn \xe1nh s\xe1ng m\u1eb7t tr\u1eddi trong m\u1ed9t th\u1eddi gian nh\u1ea5t \u0111\u1ecbnh.\n\nCon h\u1ed5 kh\xf4ng ch\u1ecbu \u0111\u1ef1ng \u0111\u01b0\u1ee3c, nh\u01b0ng con g\u1ea5u \u0111\xe3 ki\xean tr\xec v\xe0 tr\u1edf th\xe0nh m\u1ed9t ng\u01b0\u1eddi ph\u1ee5 n\u1eef g\u1ecdi l\xe0 Ungnyeo.\n\nSau \u0111\xf3 Dangun Wanggeom \u0111\u01b0\u1ee3c sinh ra t\u1eeb Hwanung v\xe0 Ungnyeo, v\xe0 theo truy\u1ec1n thuy\u1ebft, Dangun \u0111\xe3 th\xe0nh l\u1eadp Gojoseon.\n\nTrong th\u1ea7n tho\u1ea1i Dangun c\u0169ng xu\u1ea5t hi\u1ec7n t\u01b0 t\u01b0\u1edfng Hongik Ingan. Hongik Ingan \u0111\u01b0\u1ee3c gi\u1ea3i th\xedch l\xe0 \u201cl\xe0m l\u1ee3i r\u1ed9ng r\xe3i cho con ng\u01b0\u1eddi\u201d.\n\nGojoseon c\u0169ng c\xf3 ph\xe1p lu\u1eadt \u0111\u1ec3 duy tr\xec tr\u1eadt t\u1ef1 x\xe3 h\u1ed9i. Lu\u1eadt n\xe0y \u0111\u01b0\u1ee3c g\u1ecdi l\xe0 Lu\u1eadt 8 \u0111i\u1ec1u. Kh\xf4ng ph\u1ea3i to\xe0n b\u1ed9 c\xe1c \u0111i\u1ec1u lu\u1eadt \u0111\u1ec1u c\xf2n \u0111\u01b0\u1ee3c truy\u1ec1n l\u1ea1i \u0111\u1ebfn ng\xe0y nay, nh\u01b0ng qua nh\u1eefng n\u1ed9i dung c\xf2n l\u1ea1i c\xf3 th\u1ec3 ph\u1ea7n n\xe0o hi\u1ec3u \u0111\u01b0\u1ee3c x\xe3 h\u1ed9i th\u1eddi \u0111\xf3.\n\nV\xed d\u1ee5, c\xf3 th\u1ec3 suy \u0111o\xe1n r\u1eb1ng con ng\u01b0\u1eddi coi tr\u1ecdng t\xednh m\u1ea1ng v\xe0 t\xe0i s\u1ea3n, \u0111\u1ed3ng th\u1eddi \u0111\xe3 t\u1ed3n t\u1ea1i t\xe0i s\u1ea3n t\u01b0 h\u1eefu v\xe0 c\xe1c t\u1ea7ng l\u1edbp x\xe3 h\u1ed9i.\n\nTh\u1ea7n tho\u1ea1i Dangun kh\xf4ng n\xean \u0111\u01b0\u1ee3c hi\u1ec3u \u0111\u01a1n gi\u1ea3n nh\u01b0 m\u1ed9t b\u1ea3n ghi ch\xe9p nguy\xean v\u1eb9n c\xe1c s\u1ef1 ki\u1ec7n l\u1ecbch s\u1eed. N\xf3 c\u0169ng l\xe0 c\xe2u chuy\u1ec7n l\u1eadp qu\u1ed1c quan tr\u1ecdng cho th\u1ea5y ng\u01b0\u1eddi th\u1eddi c\u1ed5 \u0111\u1ea1i hi\u1ec3u v\u1ec1 qu\u1ed1c gia v\xe0 x\xe3 h\u1ed9i c\u1ee7a m\xecnh nh\u01b0 th\u1ebf n\xe0o.\n","\ub2e8\uad70\uc2e0\ud654 \uacf5\ubd80\ud558\uae30","\uc548: \ubbfc\uc218 \uc528, \ud55c\uad6d \uc5ed\uc0ac\ucc45\uc5d0\uc11c \ub2e8\uad70\uc655\uac80\uc774\ub77c\ub294 \uc774\ub984\uc744 \ubd24\uc5b4\uc694.\n\n\ubbfc\uc218: \ub124. \uace0\uc870\uc120\uc758 \uac74\uad6d \uc774\uc57c\uae30\uc5d0\uc11c \ub4f1\uc7a5\ud558\ub294 \uc778\ubb3c\uc774\uc5d0\uc694.\n\n\uc548: \ub2e8\uad70\uc2e0\ud654\uc5d0\ub294 \uacf0\ub3c4 \ub098\uc624\uc9c0\uc694?\n\n\ubbfc\uc218: \ub9de\uc544\uc694. \uacf0\uc774 \uc0ac\ub78c\uc774 \ub418\uc5b4 \uc6c5\ub140\uac00 \ub418\uc5c8\ub2e4\uace0 \uc804\ud574\uc838\uc694.\n\n\uc548: \ud638\ub791\uc774\ub3c4 \uac19\uc774 \uc0ac\ub78c\uc774 \ub418\uc5c8\uc5b4\uc694?\n\n\ubbfc\uc218: \uc544\ub2c8\uc694. \uc774\uc57c\uae30\uc5d0\uc11c\ub294 \ud638\ub791\uc774\ub294 \ub05d\uae4c\uc9c0 \uacac\ub514\uc9c0 \ubabb\ud558\uace0 \uacf0\ub9cc \uc0ac\ub78c\uc774 \ub429\ub2c8\ub2e4.\n\n\uc548: \ud658\uc6c5\uc740 \ub204\uad6c\uc608\uc694?\n\n\ubbfc\uc218: \ud558\ub298\uc5d0\uc11c \uc778\uac04 \uc138\uc0c1\uc73c\ub85c \ub0b4\ub824\uc654\ub2e4\uace0 \uc804\ud574\uc9c0\ub294 \uc778\ubb3c\uc774\uc5d0\uc694.\n\n\uc548: \ud64d\uc775\uc778\uac04\uc774\ub77c\ub294 \ub9d0\ub3c4 \uc5ec\uae30\uc11c \ub098\uc624\ub294 \uac70\uc608\uc694?\n\n\ubbfc\uc218: \ub124. \ub110\ub9ac \uc778\uac04\uc744 \uc774\ub86d\uac8c \ud55c\ub2e4\ub294 \ub73b\uc73c\ub85c \uc124\uba85\ud574\uc694.\n\n\uc548: \uace0\uc870\uc120\uc5d0\ub3c4 \ubc95\uc774 \uc788\uc5c8\uc5b4\uc694?\n\n\ubbfc\uc218: \ub124. 8\uc870\ubc95\uc774 \uc788\uc5c8\ub2e4\uace0 \uc54c\ub824\uc838 \uc788\uc5b4\uc694.\n\n\uc548: \uc65c 8\uc870\ubc95\uc774 \uc911\uc694\ud55c\uac00\uc694?\n\n\ubbfc\uc218: \ub0a8\uc544 \uc788\ub294 \ub0b4\uc6a9\uc744 \ud1b5\ud574 \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc774 \uc0dd\uba85\uacfc \uc7ac\uc0b0\uc744 \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud588\ub2e4\ub294 \uc810\uacfc \uc0ac\ud68c \ubaa8\uc2b5\uc744 \uc5b4\ub290 \uc815\ub3c4 \uc54c \uc218 \uc788\uae30 \ub54c\ubb38\uc774\uc5d0\uc694.\n\n\uc548: \ub2e8\uad70\uc2e0\ud654\ub97c \ubaa8\ub450 \uc5ed\uc0ac\uc801 \uc0ac\uc2e4\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ub418\ub098\uc694?\n\n\ubbfc\uc218: \uac74\uad6d\uc2e0\ud654\uc774\uae30 \ub54c\ubb38\uc5d0 \uc5ed\uc0ac\uc801 \uc0ac\uc2e4\uacfc \uc2e0\ud654\uc801 \ub0b4\uc6a9\uc744 \uad6c\ubd84\ud574\uc11c \uc774\ud574\ud558\ub294 \uac83\uc774 \uc88b\uc544\uc694.\n","An: Minsu, t\xf4i th\u1ea5y t\xean Dangun Wanggeom trong s\xe1ch l\u1ecbch s\u1eed H\xe0n Qu\u1ed1c.\n\nMinsu: V\xe2ng. \u0110\xf3 l\xe0 nh\xe2n v\u1eadt xu\u1ea5t hi\u1ec7n trong c\xe2u chuy\u1ec7n th\xe0nh l\u1eadp Gojoseon.\n\nAn: Trong th\u1ea7n tho\u1ea1i Dangun c\u0169ng c\xf3 con g\u1ea5u \u0111\xfang kh\xf4ng?\n\nMinsu: \u0110\xfang. Theo c\xe2u chuy\u1ec7n, con g\u1ea5u tr\u1edf th\xe0nh ng\u01b0\u1eddi ph\u1ee5 n\u1eef t\xean Ungnyeo.\n\nAn: Con h\u1ed5 c\u0169ng tr\u1edf th\xe0nh ng\u01b0\u1eddi \xe0?\n\nMinsu: Kh\xf4ng. Trong c\xe2u chuy\u1ec7n con h\u1ed5 kh\xf4ng ch\u1ecbu \u0111\u1ef1ng \u0111\u01b0\u1ee3c \u0111\u1ebfn cu\u1ed1i, ch\u1ec9 c\xf3 con g\u1ea5u tr\u1edf th\xe0nh ng\u01b0\u1eddi.\n\nAn: Hwanung l\xe0 ai?\n\nMinsu: L\xe0 nh\xe2n v\u1eadt \u0111\u01b0\u1ee3c k\u1ec3 l\xe0 \u0111\xe3 t\u1eeb tr\u1eddi xu\u1ed1ng th\u1ebf gi\u1edbi lo\xe0i ng\u01b0\u1eddi.\n\nAn: C\u1ee5m Hongik Ingan c\u0169ng xu\u1ea5t ph\xe1t t\u1eeb c\xe2u chuy\u1ec7n n\xe0y \xe0?\n\nMinsu: V\xe2ng. N\xf3 \u0111\u01b0\u1ee3c gi\u1ea3i th\xedch l\xe0 \u201cl\xe0m l\u1ee3i r\u1ed9ng r\xe3i cho con ng\u01b0\u1eddi\u201d.\n\nAn: Gojoseon c\u0169ng c\xf3 lu\u1eadt \xe0?\n\nMinsu: V\xe2ng. Ng\u01b0\u1eddi ta bi\u1ebft r\u1eb1ng c\xf3 Lu\u1eadt 8 \u0111i\u1ec1u.\n\nAn: T\u1ea1i sao Lu\u1eadt 8 \u0111i\u1ec1u quan tr\u1ecdng?\n\nMinsu: V\xec th\xf4ng qua nh\u1eefng n\u1ed9i dung c\xf2n l\u1ea1i, c\xf3 th\u1ec3 ph\u1ea7n n\xe0o hi\u1ec3u x\xe3 h\u1ed9i th\u1eddi \u0111\xf3 v\xe0 bi\u1ebft r\u1eb1ng con ng\u01b0\u1eddi coi tr\u1ecdng t\xednh m\u1ea1ng c\u0169ng nh\u01b0 t\xe0i s\u1ea3n.\n\nAn: V\u1eady c\xf3 n\xean hi\u1ec3u to\xe0n b\u1ed9 th\u1ea7n tho\u1ea1i Dangun l\xe0 s\u1ef1 ki\u1ec7n l\u1ecbch s\u1eed kh\xf4ng?\n\nMinsu: V\xec \u0111\xe2y l\xe0 th\u1ea7n tho\u1ea1i l\u1eadp qu\u1ed1c n\xean t\u1ed1t nh\u1ea5t c\u1ea7n ph\xe2n bi\u1ec7t n\u1ed9i dung th\u1ea7n tho\u1ea1i v\u1edbi c\xe1c s\u1ef1 ki\u1ec7n l\u1ecbch s\u1eed.\n",A.iYv,A.ikJ,A.iqx,A.jKF)
A.js2=s(["Bi\u1ebft v\u1ecb tr\xed \u0111\u1ecba l\xfd c\u01a1 b\u1ea3n c\u1ee7a H\xe0n Qu\u1ed1c.","Hi\u1ec3u \u0111\u1eb7c \u0111i\u1ec3m b\xe1n \u0111\u1ea3o Tri\u1ec1u Ti\xean v\xe0 ba m\u1eb7t gi\xe1p bi\u1ec3n.","Bi\u1ebft c\xe1c v\xf9ng bi\u1ec3n \ub3d9\ud574, \uc11c\ud574, \ub0a8\ud574.","Hi\u1ec3u \u0111\u1eb7c \u0111i\u1ec3m b\u1ed1n m\xf9a c\u1ee7a kh\xed h\u1eadu H\xe0n Qu\u1ed1c.","Bi\u1ebft \u0111\u1eb7c \u0111i\u1ec3m m\xf9a h\xe8 n\xf3ng \u1ea9m v\xe0 m\xf9a \u0111\xf4ng l\u1ea1nh, kh\xf4.","Hi\u1ec3u kh\xe1i ni\u1ec7m \uc7a5\ub9c8 v\xe0 \u1ea3nh h\u01b0\u1edfng c\u1ee7a m\u01b0a m\xf9a h\xe8.","Bi\u1ebft \u0111\u1eb7c \u0111i\u1ec3m \u0111\u1ecba h\xecnh \ub3d9\uace0\uc11c\uc800.","Nh\u1eadn bi\u1ebft m\u1ed9t s\u1ed1 n\xfai, s\xf4ng v\xe0 \u0111\u1ea3o ti\xeau bi\u1ec3u c\u1ee7a H\xe0n Qu\u1ed1c."],t.s)
A.hpu=s(["\ud55c\uad6d\uc740 \uc544\uc2dc\uc544 \ub300\ub959\uc758 \ub3d9\ucabd\uc5d0 \uc788\ub294 \ud55c\ubc18\ub3c4\uc5d0 \uc704\uce58\ud569\ub2c8\ub2e4.","\ud55c\ubc18\ub3c4\ub294 \uc0bc\uba74\uc774 \ubc14\ub2e4\ub85c \ub458\ub7ec\uc2f8\uc5ec \uc788\uc2b5\ub2c8\ub2e4.","\ub3d9\ucabd\uc5d0\ub294 \ub3d9\ud574, \uc11c\ucabd\uc5d0\ub294 \uc11c\ud574, \ub0a8\ucabd\uc5d0\ub294 \ub0a8\ud574\uac00 \uc788\uc2b5\ub2c8\ub2e4.","\ud55c\uad6d\uc740 \ubd04, \uc5ec\ub984, \uac00\uc744, \uaca8\uc6b8\uc758 \uc0ac\uacc4\uc808\uc774 \ube44\uad50\uc801 \ub69c\ub837\ud569\ub2c8\ub2e4.","\uc5ec\ub984\uc740 \ub365\uace0 \uc2b5\ud558\uba70 \ube44\uac00 \ub9ce\uc774 \ub0b4\ub9ac\ub294 \uc2dc\uae30\uac00 \uc788\uc2b5\ub2c8\ub2e4.","\uaca8\uc6b8\uc740 \ub300\uccb4\ub85c \ucda5\uace0 \uac74\uc870\ud55c \ud3b8\uc785\ub2c8\ub2e4.","\uc5ec\ub984\ucca0\uc5d0\ub294 \uc7a5\ub9c8\uc640 \ud0dc\ud48d\uc758 \uc601\ud5a5\uc744 \ubc1b\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ud55c\uad6d\uc740 \uc0b0\uc9c0\uac00 \ub9ce\uc740 \ub098\ub77c\uc785\ub2c8\ub2e4.","\ub3d9\ucabd\uc740 \ub192\uace0 \uc11c\ucabd\uc740 \ube44\uad50\uc801 \ub0ae\uc740 \ub3d9\uace0\uc11c\uc800\uc758 \uc9c0\ud615\uc801 \ud2b9\uc9d5\uc774 \ub098\ud0c0\ub0a9\ub2c8\ub2e4.","\uc11c\ucabd\uacfc \ub0a8\ucabd\uc5d0\ub294 \ube44\uad50\uc801 \ub113\uc740 \ud3c9\uc57c\uac00 \ubc1c\ub2ec\ud588\uc2b5\ub2c8\ub2e4.","\ud55c\uac15\uacfc \ub099\ub3d9\uac15\uc740 \ud55c\uad6d\uc758 \ub300\ud45c\uc801\uc778 \uac15\uc785\ub2c8\ub2e4.","\uc81c\uc8fc\ub3c4\uc758 \ud55c\ub77c\uc0b0\uc740 \ub300\ud55c\ubbfc\uad6d\uc5d0\uc11c \uac00\uc7a5 \ub192\uc740 \uc0b0\uc785\ub2c8\ub2e4."],t.s)
