A.fFs=new B.O("\ub2e4\uc74c \uc5f0\uacb0\uc774 \ub9de\uc9c0 \uc54a\ub294 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","C\u1eb7p n\xe0o sau \u0111\xe2y KH\xd4NG \u0111\xfang?",A.iDz,3,"\uc0b0\uc7ac\ubcf4\ud5d8 li\xean quan \u0111\u1ebfn tai n\u1ea1n lao \u0111\u1ed9ng, kh\xf4ng li\xean quan \u0111\u1ebfn chuy\u1ec3n tuy\u1ebfn t\xe0u \u0111i\u1ec7n.")
A.hdh=s(["\ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uac19\uc740 \ubcf5\uc9c0\uc11c\ube44\uc2a4\ub97c \uc774\uc6a9\ud55c\ub2e4.","\ubcf5\uc9c0\uc81c\ub3c4\ub294 \uc0dd\ud65c \uc548\uc815\uc744 \ub3d5\uae30 \uc704\ud55c \uc5ed\ud560\uc744 \ud55c\ub2e4.","\uac74\uac15\ubcf4\ud5d8\uc740 \uad50\ud1b5\uc694\uae08\uc744 \uc9c0\uc6d0\ud558\ub294 \uc81c\ub3c4\uc774\ub2e4.","\ubcf5\uc9c0\uc11c\ube44\uc2a4\uc5d0 \ub300\ud574 \ubb38\uc758\ud560 \uacf3\uc774 \uc5c6\ub2e4."],t.s)
