A.fG8=new B.O("\ud55c\uad6d\uc758 \uc5ed\uc0ac\uc640 \ubb38\ud654\uc5d0 \uc624\ub7ab\ub3d9\uc548 \uc601\ud5a5\uc744 \uc900 \uc885\uad50\ub294 \ubb34\uc5c7\uc785\ub2c8\uae4c?","T\xf4n gi\xe1o n\xe0o \u0111\xe3 \u1ea3nh h\u01b0\u1edfng l\xe2u d\xe0i \u0111\u1ebfn l\u1ecbch s\u1eed v\xe0 v\u0103n h\xf3a H\xe0n Qu\u1ed1c?",A.hn6,0,"\ubd88\uad50 \u0111\xe3 c\xf3 \u1ea3nh h\u01b0\u1edfng l\xe2u d\xe0i \u0111\u1ebfn l\u1ecbch s\u1eed v\xe0 v\u0103n h\xf3a H\xe0n Qu\u1ed1c.")
A.jrS=s(["\uc804\ud1b5\uc801\uc778 \uc608\uc808\uacfc \uac00\uce58\uad00","\uc9c0\ud558\ucca0 \ud658\uc2b9","\ubcd1\uc6d0 \ucc98\ubc29\uc804","\uad50\ud1b5\uce74\ub4dc"],t.s)
A.fIM=new B.O("\uc720\uad50\uc640 \uad00\ub828\uc774 \uae4a\uc740 \uac83\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110i\u1ec1u n\xe0o c\xf3 li\xean quan nhi\u1ec1u \u0111\u1ebfn \u1ea3nh h\u01b0\u1edfng c\u1ee7a Nho gi\xe1o?",A.jrS,0,"\uc720\uad50 \u0111\xe3 \u1ea3nh h\u01b0\u1edfng nhi\u1ec1u \u0111\u1ebfn l\u1ec5 nghi v\xe0 gi\xe1 tr\u1ecb truy\u1ec1n th\u1ed1ng.")
A.hft=s(["\uc11c\ub85c\uc758 \uc2e0\ub150\uc744 \uc874\uc911\ud55c\ub2e4.","\ubb34\uc870\uac74 \uc790\uc2e0\uc758 \uc885\uad50\ub97c \uac15\uc694\ud55c\ub2e4.","\ub2e4\ub978 \uc0ac\ub78c\uc758 \uc885\uad50\ub97c \ube44\ub09c\ud55c\ub2e4.","\uc885\uad50\uac00 \ub2e4\ub974\uba74 \ub300\ud654\ud558\uc9c0 \uc54a\ub294\ub2e4."],t.s)
A.fHl=new B.O("\uc885\uad50\uac00 \ub2e4\ub978 \uc0ac\ub78c\uc744 \ub300\ud558\ub294 \ud0dc\ub3c4\ub85c \uc54c\ub9de\uc740 \uac83\uc740?","Th\xe1i \u0111\u1ed9 ph\xf9 h\u1ee3p \u0111\u1ed1i v\u1edbi ng\u01b0\u1eddi c\xf3 t\xf4n gi\xe1o kh\xe1c l\xe0 g\xec?",A.hft,0,"T\xf4n tr\u1ecdng ni\u1ec1m tin c\u1ee7a ng\u01b0\u1eddi kh\xe1c l\xe0 th\xe1i \u0111\u1ed9 ph\xf9 h\u1ee3p.")
A.jkq=s(["\ud55c\uad6d\uc5d0\ub294 \uc885\uad50\uac00 \uc5c6\ub294 \uc0ac\ub78c\ub3c4 \uc788\ub2e4.","\ud55c\uad6d\uc778\uc740 \ubaa8\ub450 \uac19\uc740 \uc885\uad50\ub97c \ubbff\ub294\ub2e4.","\ud55c\uad6d\uc5d0\uc11c\ub294 \uc885\uad50\ub97c \uc120\ud0dd\ud560 \uc218 \uc5c6\ub2e4.","\ubd88\uad50 \uc0ac\ucc30\uc744 \uc131\ub2f9\uc774\ub77c\uace0 \ud55c\ub2e4."],t.s)
A.fHW=new B.O("\ub2e4\uc74c \uc911 \ub9de\ub294 \uc124\uba85\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Ph\xe1t bi\u1ec3u n\xe0o sau \u0111\xe2y \u0111\xfang?",A.jkq,0,"\u1ede H\xe0n Qu\u1ed1c c\u0169ng c\xf3 nh\u1eefng ng\u01b0\u1eddi kh\xf4ng theo t\xf4n gi\xe1o.")
A.heR=s(["\ud55c\uad6d\uc5d0\ub294 \uc5ec\ub7ec \uc885\uad50\ub97c \uac00\uc9c4 \uc0ac\ub78c\ub4e4\uc774 \ud568\uaed8 \uc0b4\uace0 \uc788\ub2e4.","\ubaa8\ub4e0 \ud55c\uad6d \uc0ac\ub78c\uc740 \ubd88\uad50\ub97c \ubbff\ub294\ub2e4.","\uc885\uad50\uac00 \uc5c6\ub294 \uc0ac\ub78c\uc740 \uc5c6\ub2e4.","\ub2e4\ub978 \uc0ac\ub78c\uc758 \uc885\uad50\ub294 \uc874\uc911\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4."],t.s)
A.fIk=new B.O("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.heR,0,"B\xe0i \u0111\u1ecdc n\xf3i r\u1eb1ng nh\u1eefng ng\u01b0\u1eddi c\xf3 nhi\u1ec1u t\xf4n gi\xe1o v\xe0 quan ni\u1ec7m kh\xe1c nhau c\xf9ng sinh s\u1ed1ng \u1edf H\xe0n Qu\u1ed1c.")
