A.iTm=s(["\uc544\ud30c\ud2b8 = chung c\u01b0; \uc6d0\ub8f8 = c\u0103n/ph\xf2ng studio m\u1ed9t ph\xf2ng.","\uc804\uc138 v\xe0 \uc6d4\uc138 l\xe0 hai h\xecnh th\u1ee9c thu\xea nh\xe0 kh\xe1c nhau.","\ubcf4\uc99d\uae08 = ti\u1ec1n \u0111\u1eb7t c\u1ecdc; \uc6d4\uc138 = ti\u1ec1n thu\xea h\xe0ng th\xe1ng.","\uad00\ub9ac\ube44 kh\xf4ng gi\u1ed1ng \uc6d4\uc138 v\xe0 c\xf3 th\u1ec3 \u0111\u01b0\u1ee3c t\xednh ri\xeang.","\uc628\ub3cc = v\u0103n h\xf3a/ph\u01b0\u01a1ng th\u1ee9c s\u01b0\u1edfi s\xe0n truy\u1ec1n th\u1ed1ng.","\ud604\uad00 = khu v\u1ef1c c\u1eeda v\xe0o, n\u01a1i th\u01b0\u1eddng c\u1edfi v\xe0 \u0111\u1ec3 gi\xe0y.","\uce35\uac04\uc18c\uc74c = ti\u1ebfng \u1ed3n truy\u1ec1n gi\u1eefa c\xe1c t\u1ea7ng trong nh\xe0 \u1edf t\u1eadp th\u1ec3.","\ubd84\ub9ac\ubc30\ucd9c = ph\xe2n lo\u1ea1i r\xe1c tr\u01b0\u1edbc khi b\u1ecf, kh\xf4ng \u0111\u01a1n gi\u1ea3n l\xe0 v\u1ee9t t\u1ea5t c\u1ea3 r\xe1c c\xf9ng nhau."],t.s)
A.hAe=s(["\uc544\ud30c\ud2b8 \u2192 c\u0103n h\u1ed9/chung c\u01b0.","\ub2e8\ub3c5\uc8fc\ud0dd \u2192 nh\xe0 ri\xeang.","\uc6d0\ub8f8 \u2192 ph\xf2ng studio.","\uc804\uc138 \u2192 h\xecnh th\u1ee9c thu\xea v\u1edbi ti\u1ec1n \u0111\u1eb7t c\u1ecdc l\u1edbn.","\uc6d4\uc138 \u2192 h\xecnh th\u1ee9c thu\xea tr\u1ea3 ti\u1ec1n h\xe0ng th\xe1ng.","\ubcf4\uc99d\uae08 \u2192 ti\u1ec1n \u0111\u1eb7t c\u1ecdc.","\uad00\ub9ac\ube44 \u2192 ph\xed qu\u1ea3n l\xfd.","\uc628\ub3cc \u2192 ph\u01b0\u01a1ng th\u1ee9c s\u01b0\u1edfi s\xe0n truy\u1ec1n th\u1ed1ng.","\uc9d1 \uc548\uc5d0 \ub4e4\uc5b4\uac08 \ub54c \uc2e0\ubc1c\uc744 \ubc97\ub294 \ubb38\ud654\uac00 \uc77c\ubc18\uc801\uc774\ub2e4.","\uacf5\ub3d9\uc8fc\ud0dd\uc5d0\uc11c\ub294 \uce35\uac04\uc18c\uc74c \ub4f1 \uc774\uc6c3\uc5d0 \ub300\ud55c \ubc30\ub824\uac00 \uc911\uc694\ud558\ub2e4.","\uc4f0\ub808\uae30\ub294 \uc9c0\uc5ed \uaddc\uce59\uc5d0 \ub530\ub77c \ubd84\ub9ac\ubc30\ucd9c\ud574\uc57c \ud55c\ub2e4."],t.s)
