A.fFK=new B.O("\uc9d1\uc744 \uad6c\ud560 \ub54c \ud655\uc778\ud560 \ub0b4\uc6a9\uc73c\ub85c \uc54c\ub9de\uc9c0 \uc54a\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110\xe2u KH\xd4NG ph\u1ea3i n\u1ed9i dung c\u1ea7n ki\u1ec3m tra khi t\xecm nh\xe0?",A.iN0,3,"\u0110i\u1ec3m thi \u1edf tr\u01b0\u1eddng kh\xf4ng ph\u1ea3i \u0111i\u1ec1u ki\u1ec7n c\u1ee7a h\u1ee3p \u0111\u1ed3ng nh\xe0.")
A.ig8=s(["\uacf5\ub3d9\uc8fc\ud0dd\uc5d0\uc11c\ub294 \uc774\uc6c3\uc5d0 \ub300\ud55c \ubc30\ub824\uac00 \uc911\uc694\ud558\ub2e4.","\ud55c\uad6d\uc5d0\uc11c\ub294 \uc9d1 \uc548\uc5d0\uc11c\ub3c4 \ud56d\uc0c1 \uc2e0\ubc1c\uc744 \uc2e0\ub294\ub2e4.","\uc4f0\ub808\uae30\ub294 \ubaa8\ub450 \ud568\uaed8 \ubc84\ub9ac\uba74 \ub41c\ub2e4.","\uad00\ub9ac\ube44\uc640 \uc6d4\uc138\ub294 \ud56d\uc0c1 \uac19\uc740 \ub73b\uc774\ub2e4."],t.s)
