A.jBl=s(["\ubcf4\uc721 = ch\u0103m s\xf3c v\xe0 nu\xf4i d\u01b0\u1ee1ng tr\u1ebb nh\u1ecf.","\uc591\uc721 = kh\xe1i ni\u1ec7m r\u1ed9ng v\u1ec1 vi\u1ec7c cha m\u1eb9 ho\u1eb7c ng\u01b0\u1eddi ch\u0103m s\xf3c nu\xf4i d\u01b0\u1ee1ng con.","\uc5b4\ub9b0\uc774\uc9d1 v\xe0 \uc720\uce58\uc6d0 kh\xf4ng ho\xe0n to\xe0n gi\u1ed1ng nhau v\u1ec1 vai tr\xf2 v\xe0 h\u1ec7 th\u1ed1ng qu\u1ea3n l\xfd.","\uc601\uc720\uc544 th\u01b0\u1eddng ch\u1ec9 tr\u1ebb s\u01a1 sinh v\xe0 tr\u1ebb nh\u1ecf.","\ubcf4\ud638\uc790 = cha m\u1eb9 ho\u1eb7c ng\u01b0\u1eddi c\xf3 tr\xe1ch nhi\u1ec7m ch\u0103m s\xf3c, gi\xe1m h\u1ed9 tr\u1ebb.","\uc6b4\uc601\uc2dc\uac04 = gi\u1edd ho\u1ea1t \u0111\u1ed9ng; \uc774\uc6a9\uc2dc\uac04 = th\u1eddi gian th\u1ef1c t\u1ebf s\u1eed d\u1ee5ng d\u1ecbch v\u1ee5.","\uc0c1\ub2f4 = t\u01b0 v\u1ea5n ho\u1eb7c trao \u0111\u1ed5i, kh\xf4ng gi\u1ed1ng \uc2e0\uccad = \u0111\u0103ng k\xfd."],t.s)
A.jBK=s(["\ubcf4\uc721 \u2192 ch\u0103m s\xf3c v\xe0 nu\xf4i d\u01b0\u1ee1ng tr\u1ebb.","\uc5b4\ub9b0\uc774\uc9d1 \u2192 c\u01a1 s\u1edf ch\u0103m s\xf3c tr\u1ebb nh\u1ecf.","\uc720\uce58\uc6d0 \u2192 c\u01a1 s\u1edf gi\xe1o d\u1ee5c tr\u1ebb m\u1eabu gi\xe1o.","\uc601\uc720\uc544 \u2192 tr\u1ebb s\u01a1 sinh v\xe0 tr\u1ebb nh\u1ecf.","\uc591\uc721 \u2192 nu\xf4i d\u01b0\u1ee1ng con c\xe1i.","\ub9de\ubc8c\uc774 \uac00\uc815 \u2192 c\u1ea3 v\u1ee3 v\xe0 ch\u1ed3ng c\xf9ng \u0111i l\xe0m.","\ubcf4\ud638\uc790 \u2192 ng\u01b0\u1eddi gi\xe1m h\u1ed9 ho\u1eb7c ch\u0103m s\xf3c tr\u1ebb.","\uc6b4\uc601\uc2dc\uac04 \u2192 gi\u1edd ho\u1ea1t \u0111\u1ed9ng.","\uac00\uc815\uacfc \ubcf4\uc721\uae30\uad00\uc758 \ud611\ub825\uc774 \uc911\uc694\ud558\ub2e4.","\uc544\uc774\uc758 \uac74\uac15\uc774\ub098 \uc0dd\ud65c\uc5d0 \ubcc0\ud654\uac00 \uc788\uc73c\uba74 \ubcf4\uc721\uae30\uad00\uc5d0 \uc54c\ub824 \uc8fc\ub294 \uac83\uc774 \uc88b\ub2e4."],t.s)
A.hgA=s(["\uc544\uc774\ub97c \uc548\uc804\ud558\uac8c \ub3cc\ubcf4\uace0 \uc131\uc7a5\ud558\ub3c4\ub85d \ub3d5\ub294 \uac83","\uc790\ub3d9\ucc28\ub97c \uc6b4\uc804\ud558\ub294 \uac83","\ud68c\uc0ac\uc5d0\uc11c \uc77c\ud558\ub294 \uac83","\uc740\ud589 \uc5c5\ubb34\ub97c \ubcf4\ub294 \uac83"],t.s)
