A.fIE=new B.O("\u201c\uc6b4\uc601\uc2dc\uac04\u201d\uc758 \ub73b\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\uc6b4\uc601\uc2dc\uac04 c\xf3 ngh\u0129a l\xe0 g\xec?",A.jN6,0,"\uc6b4\uc601\uc2dc\uac04 l\xe0 kho\u1ea3ng th\u1eddi gian m\u1ed9t c\u01a1 s\u1edf ho\u1ea1t \u0111\u1ed9ng.")
A.hjJ=s(["\ubcf4\uc721\uc740 \uc544\uc774\uc758 \uc131\uc7a5\uacfc \uad00\uacc4\uac00 \uc5c6\ub2e4.","\uac00\uc815\uacfc \ubcf4\uc721\uae30\uad00\uc774 \ud611\ub825\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4.","\uc5b4\ub9b0\uc774\uc9d1\uc5d0\uc11c\ub294 \uc544\uc774\ub97c \ub3cc\ubcf4\uc9c0 \uc54a\ub294\ub2e4.","\ubcf4\ud638\uc790\ub294 \uc544\uc774\uc758 \uac74\uac15 \uc815\ubcf4\ub97c \uc54c\ub824 \uc904 \ud544\uc694\uac00 \uc5c6\ub2e4."],t.s)
A.fBF=new B.O("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.hjJ,1,"B\xe0i \u0111\u1ecdc nh\u1ea5n m\u1ea1nh r\u1eb1ng s\u1ef1 h\u1ee3p t\xe1c gi\u1eefa gia \u0111\xecnh v\xe0 c\u01a1 s\u1edf ch\u0103m s\xf3c tr\u1ebb r\u1ea5t quan tr\u1ecdng.")
