A.fG0=new B.O("\ud55c\uad6d\uc774 \ud574\uc678\uc5d0\uc11c \uc218\uc785\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc740 \uac83\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740?","\u0110\xe2u l\xe0 th\u1ee9 H\xe0n Qu\u1ed1c th\u01b0\u1eddng c\u1ea7n nh\u1eadp kh\u1ea9u t\u1eeb n\u01b0\u1edbc ngo\xe0i?",A.hue,0,"Nguy\xean v\u1eadt li\u1ec7u v\xe0 n\u0103ng l\u01b0\u1ee3ng l\xe0 nh\u1eefng m\u1eb7t h\xe0ng c\xf3 th\u1ec3 c\u1ea7n nh\u1eadp kh\u1ea9u.")
A.hnP=s(["\uc218\ucd9c\uc774 \uc601\ud5a5\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4.","\ud55c\uad6d \uacbd\uc81c\uc5d0\ub294 \uc808\ub300 \uc601\ud5a5\uc774 \uc5c6\ub2e4.","\ubaa8\ub4e0 \uc218\uc785 \uac00\uaca9\uc774 \ud56d\uc0c1 \uac19\uc544\uc9c4\ub2e4.","\ubaa8\ub4e0 \uae30\uc5c5\uc758 \ub9e4\ucd9c\uc774 \uc790\ub3d9\uc73c\ub85c \uc99d\uac00\ud55c\ub2e4."],t.s)
A.fGj=new B.O("\uc138\uacc4\uacbd\uc81c\uac00 \uc5b4\ub824\uc6cc\uc9c0\uba74 \ud55c\uad6d\uc5d0 \uc5b4\ub5a4 \uc601\ud5a5\uc774 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\uae4c?","N\u1ebfu kinh t\u1ebf th\u1ebf gi\u1edbi g\u1eb7p kh\xf3 kh\u0103n th\xec H\xe0n Qu\u1ed1c c\xf3 th\u1ec3 ch\u1ecbu \u1ea3nh h\u01b0\u1edfng n\xe0o?",A.hnP,0,"Khi nhu c\u1ea7u qu\u1ed1c t\u1ebf gi\u1ea3m, xu\u1ea5t kh\u1ea9u c\u1ee7a H\xe0n Qu\u1ed1c c\xf3 th\u1ec3 b\u1ecb \u1ea3nh h\u01b0\u1edfng.")
A.iQn=s(["\ud55c\uad6d\uc740 \uc218\ucd9c\uacfc \uc218\uc785\uc744 \ud1b5\ud574 \uc138\uacc4\uacbd\uc81c\uc640 \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4.","FTA\ub294 \ubb34\uc5ed\uc744 \uc644\uc804\ud788 \uc911\ub2e8\ud558\uae30 \uc704\ud55c \ud611\uc815\uc774\ub2e4.","\ud658\uc728\uc740 \uc218\ucd9c\uc785\uacfc \uc544\ubb34 \uad00\uacc4\uac00 \uc5c6\ub2e4.","\uc138\uacc4\uc2dc\uc7a5\uc5d0\uc11c\ub294 \uae30\uc5c5 \uac04 \uacbd\uc7c1\uc774 \uc5c6\ub2e4."],t.s)
A.fEF=new B.O("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.iQn,0,"Xu\u1ea5t nh\u1eadp kh\u1ea9u l\xe0 m\u1ed9t trong nh\u1eefng y\u1ebfu t\u1ed1 k\u1ebft n\u1ed1i kinh t\u1ebf H\xe0n Qu\u1ed1c v\u1edbi kinh t\u1ebf th\u1ebf gi\u1edbi.")
