A.fD3=new B.O("\uc77c\ubd80 \ub18d\ucd0c \uc9c0\uc5ed\uc5d0\uc11c \ub098\ud0c0\ub098\ub294 \ubb38\uc81c\ub294 \ubb34\uc5c7\uc785\ub2c8\uae4c?","V\u1ea5n \u0111\u1ec1 n\xe0o xu\u1ea5t hi\u1ec7n t\u1ea1i m\u1ed9t s\u1ed1 v\xf9ng n\xf4ng th\xf4n?",A.iZh,0,"M\u1ed9t s\u1ed1 khu v\u1ef1c n\xf4ng th\xf4n \u0111ang g\u1eb7p suy gi\u1ea3m d\xe2n s\u1ed1 v\xe0 gi\xe0 h\xf3a.")
A.inm=s(["\uc9d1\uc5d0\uc11c \uc0dd\ud65c\ud558\ub294 \ub370 \ub4dc\ub294 \ube44\uc6a9","\ubc84\uc2a4\ub97c \uac08\uc544\ud0c0\ub294 \ubc29\ubc95","\ubcd1\uc6d0 \uc9c4\ub8cc \ubc29\ubc95","\uc2e0\ubb38 \uae30\uc0ac"],t.s)
A.fEY=new B.O("\u201c\uc8fc\uac70\ube44\u201d\uc640 \uac00\uc7a5 \uad00\ub828\uc774 \uc788\ub294 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\uc8fc\uac70\ube44 li\xean quan nh\u1ea5t \u0111\u1ebfn \u0111i\u1ec1u g\xec?",A.inm,0,"\uc8fc\uac70\ube44 l\xe0 c\xe1c chi ph\xed li\xean quan \u0111\u1ebfn nh\xe0 \u1edf.")
A.j3v=s(["\uc790\uc5f0\ud658\uacbd\uc744 \uac00\uae4c\uc774\uc5d0\uc11c \uc811\ud560 \uc218 \uc788\ub2e4.","\ud56d\uc0c1 \ub300\ub3c4\uc2dc\ubcf4\ub2e4 \uc778\uad6c\uac00 \ub9ce\ub2e4.","\ubaa8\ub4e0 \uc0ac\ub78c\uc774 \ud68c\uc0ac\uc6d0\uc774\ub2e4.","\ub18d\uc5c5\uacfc \uad00\uacc4\uac00 \uc5c6\ub2e4."],t.s)
A.fII=new B.O("\ub18d\ucd0c\uc758 \ud2b9\uc9d5\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110\xe2u l\xe0 \u0111\u1eb7c \u0111i\u1ec3m ph\xf9 h\u1ee3p c\u1ee7a v\xf9ng n\xf4ng th\xf4n?",A.j3v,0,"N\xf4ng th\xf4n th\u01b0\u1eddng g\u1ea7n g\u0169i h\u01a1n v\u1edbi m\xf4i tr\u01b0\u1eddng t\u1ef1 nhi\xean.")
A.jmA=s(["\uc0ac\ud68c\uc5d0\uc11c \ub178\uc778 \uc778\uad6c\uc758 \ube44\uc911\uc774 \ub192\uc544\uc9c0\ub294 \ud604\uc0c1","\ub3c4\uc2dc\uc758 \uac74\ubb3c\uc774 \ub192\uc544\uc9c0\ub294 \ud604\uc0c1","\uad50\ud1b5\uc694\uae08\uc774 \ub0b4\ub824\uac00\ub294 \ud604\uc0c1","\ud559\uad50 \uc218\uac00 \uc99d\uac00\ud558\ub294 \ud604\uc0c1"],t.s)
A.fFX=new B.O("\u201c\uace0\ub839\ud654\u201d\uc758 \ub73b\uc73c\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\xdd ngh\u0129a ph\xf9 h\u1ee3p nh\u1ea5t c\u1ee7a \uace0\ub839\ud654 l\xe0 g\xec?",A.jmA,0,"\uace0\ub839\ud654 l\xe0 hi\u1ec7n t\u01b0\u1ee3ng t\u1ef7 l\u1ec7 ng\u01b0\u1eddi cao tu\u1ed5i trong x\xe3 h\u1ed9i t\u0103ng l\xean.")
A.hlX=s(["\uc9c0\uc5ed\uc758 \ud2b9\uc131\uc5d0 \ub9de\uac8c \ubc1c\uc804\ud55c\ub2e4.","\ubaa8\ub4e0 \uc2dc\uc124\uc744 \ud55c \ub3c4\uc2dc\uc5d0\ub9cc \ub9cc\ub4e0\ub2e4.","\ub18d\ucd0c\uc758 \uc2dc\uc124\uc744 \ubaa8\ub450 \uc5c6\uc564\ub2e4.","\ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uac19\uc740 \uc9c0\uc5ed\uc5d0 \uc0b0\ub2e4."],t.s)
A.fFG=new B.O("\ub3c4\uc2dc\uc640 \ub18d\ucd0c\uc758 \uade0\ud615 \uc788\ub294 \ubc1c\uc804\uc744 \uc704\ud574 \uc911\uc694\ud55c \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110i\u1ec1u g\xec quan tr\u1ecdng \u0111\u1ec3 th\xe0nh th\u1ecb v\xe0 n\xf4ng th\xf4n ph\xe1t tri\u1ec3n c\xe2n b\u1eb1ng?",A.hlX,0,"C\u1ea7n ph\xe1t tri\u1ec3n ph\xf9 h\u1ee3p v\u1edbi \u0111\u1eb7c \u0111i\u1ec3m v\xe0 nhu c\u1ea7u c\u1ee7a t\u1eebng khu v\u1ef1c.")
A.jwu=s(["\ud55c\uad6d\uc5d0\uc11c\ub294 \ub3c4\uc2dc\ud654\uac00 \uc804\ud600 \uc9c4\ud589\ub418\uc9c0 \uc54a\uc558\ub2e4.","\ub3c4\uc2dc\ub294 \uc7a5\uc810\ub9cc \uc788\uace0 \ubb38\uc81c\ub294 \uc5c6\ub2e4.","\uc77c\ubd80 \ub18d\ucd0c\uc5d0\uc11c\ub294 \uc778\uad6c \uac10\uc18c \ubb38\uc81c\uac00 \ub098\ud0c0\ub098\uace0 \uc788\ub2e4.","\ub18d\ucd0c\uc740 \uc790\uc5f0\ud658\uacbd\uacfc \uad00\uacc4\uac00 \uc5c6\ub2e4."],t.s)
A.fB_=new B.O("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.jwu,2,"B\xe0i \u0111\u1ecdc n\xf3i r\u1eb1ng m\u1ed9t s\u1ed1 v\xf9ng n\xf4ng th\xf4n \u0111ang g\u1eb7p v\u1ea5n \u0111\u1ec1 suy gi\u1ea3m d\xe2n s\u1ed1.")
A.jff=s([A.fIn,A.fDM,A.fDB,A.fFZ,A.fD3,A.fEY,A.fII,A.fFX,A.fFG,A.fB_],t.h)
A.jh5=s(["\ub3c4\uc2dc = th\xe0nh th\u1ecb.","\ub18d\ucd0c = n\xf4ng th\xf4n.","\ub300\ub3c4\uc2dc = th\xe0nh ph\u1ed1 l\u1edbn.","\ub3c4\uc2dc\ud654 = \u0111\xf4 th\u1ecb h\xf3a.","\uc0b0\uc5c5\ud654 = c\xf4ng nghi\u1ec7p h\xf3a.","\uc8fc\uac70\ube44 = chi ph\xed nh\xe0 \u1edf.","\uad50\ud1b5 \ud63c\uc7a1 = \xf9n t\u1eafc giao th\xf4ng.","\uc778\uad6c \uac10\uc18c = suy gi\u1ea3m d\xe2n s\u1ed1.","\uace0\ub839\ud654 = gi\xe0 h\xf3a d\xe2n s\u1ed1.","\ub18d\uc5c5 = n\xf4ng nghi\u1ec7p.","Th\xe0nh ph\u1ed1 th\u01b0\u1eddng c\xf3 nhi\u1ec1u vi\u1ec7c l\xe0m v\xe0 ti\u1ec7n \xedch nh\u01b0ng c\u0169ng c\xf3 th\u1ec3 c\xf3 chi ph\xed nh\xe0 \u1edf cao v\xe0 \xf9n t\u1eafc.","M\u1ed9t s\u1ed1 v\xf9ng n\xf4ng th\xf4n g\u1eb7p v\u1ea5n \u0111\u1ec1 suy gi\u1ea3m d\xe2n s\u1ed1 v\xe0 gi\xe0 h\xf3a.","\ub3c4\uc2dc\uc640 \ub18d\ucd0c\uc758 \uade0\ud615 \ubc1c\uc804\uc774 \uc911\uc694\ud569\ub2c8\ub2e4."],t.s)
A.fAn=new B.dJ(7,"\uc0ac\ud68c 1","\ud55c\uad6d\uc758 \ub3c4\uc2dc\uc640 \ub18d\ucd0c","Th\xe0nh th\u1ecb v\xe0 n\xf4ng th\xf4n H\xe0n Qu\u1ed1c",A.i9c,A.hy5,A.i9Y,A.jC7,"\ub3c4\uc2dc\uc640 \ub18d\ucd0c\uc758 \ubcc0\ud654","\ud55c\uad6d\uc740 \uc0b0\uc5c5\ud654\uc640 \uacbd\uc81c \ubc1c\uc804 \uacfc\uc815\uc5d0\uc11c \ub3c4\uc2dc\ud654\uac00 \ube60\ub974\uac8c \uc9c4\ud589\ub418\uc5c8\uc2b5\ub2c8\ub2e4.\n\n\ub9ce\uc740 \uc0ac\ub78c\uc774 \uc77c\uc790\ub9ac\uc640 \uad50\uc721 \uae30\ud68c\ub97c \ucc3e\uae30 \uc704\ud574 \ub3c4\uc2dc\ub85c \uc774\ub3d9\ud558\uba74\uc11c \uc11c\uc6b8\uacfc \uac19\uc740 \ub300\ub3c4\uc2dc\uc758 \uc778\uad6c\uac00 \ud06c\uac8c \uc99d\uac00\ud588\uc2b5\ub2c8\ub2e4.\n\n\ub3c4\uc2dc\uc5d0\ub294 \ud68c\uc0ac, \ud559\uad50, \ubcd1\uc6d0, \ubb38\ud654\uc2dc\uc124, \ub300\uc911\uad50\ud1b5 \ub4f1 \ub2e4\uc591\ud55c \uc2dc\uc124\uc774 \ubaa8\uc5ec \uc788\uc5b4 \uc0dd\ud65c\uc774 \ud3b8\ub9ac\ud55c \ud3b8\uc785\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \uc0ac\ub78c\uc774 \ub9ce\uc774 \ubaa8\uc774\uba74\uc11c \uad50\ud1b5 \ud63c\uc7a1, \ub192\uc740 \uc8fc\uac70\ube44, \ud658\uacbd \ubb38\uc81c \ub4f1\uc774 \ub098\ud0c0\ub098\uae30\ub3c4 \ud569\ub2c8\ub2e4.\n\n\ub18d\ucd0c\uc740 \ub3c4\uc2dc\ubcf4\ub2e4 \uc778\uad6c\uac00 \uc801\uace0 \uc790\uc5f0\ud658\uacbd\uc744 \uac00\uae4c\uc774\uc5d0\uc11c \uc811\ud560 \uc218 \uc788\ub2e4\ub294 \ud2b9\uc9d5\uc774 \uc788\uc2b5\ub2c8\ub2e4. \ub18d\uc5c5\uc740 \ub18d\ucd0c\uc758 \uc911\uc694\ud55c \uc0b0\uc5c5 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4.\n\n\ud558\uc9c0\ub9cc \uc77c\ubd80 \ub18d\ucd0c\uc5d0\uc11c\ub294 \uc80a\uc740 \uc0ac\ub78c\ub4e4\uc774 \ub3c4\uc2dc\ub85c \uc774\ub3d9\ud558\uba74\uc11c \uc778\uad6c \uac10\uc18c\uc640 \uace0\ub839\ud654 \ubb38\uc81c\uac00 \ub098\ud0c0\ub098\uace0 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ub530\ub77c\uc11c \ub3c4\uc2dc\uc640 \ub18d\ucd0c\uc774 \ud568\uaed8 \ubc1c\uc804\ud560 \uc218 \uc788\ub3c4\ub85d \uc9c0\uc5ed\uc758 \ud2b9\uc131\uc744 \uc0b4\ub9ac\uace0 \uade0\ud615 \uc788\ub294 \ubc1c\uc804\uc744 \uc774\ub8e8\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.\n","Trong qu\xe1 tr\xecnh c\xf4ng nghi\u1ec7p h\xf3a v\xe0 ph\xe1t tri\u1ec3n kinh t\u1ebf, H\xe0n Qu\u1ed1c \u0111\xe3 tr\u1ea3i qua qu\xe1 tr\xecnh \u0111\xf4 th\u1ecb h\xf3a nhanh ch\xf3ng.\n\nNhi\u1ec1u ng\u01b0\u1eddi chuy\u1ec3n \u0111\u1ebfn th\xe0nh ph\u1ed1 \u0111\u1ec3 t\xecm vi\u1ec7c l\xe0m v\xe0 c\u01a1 h\u1ed9i gi\xe1o d\u1ee5c, khi\u1ebfn d\xe2n s\u1ed1 c\xe1c th\xe0nh ph\u1ed1 l\u1edbn nh\u01b0 Seoul t\u0103ng m\u1ea1nh.\n\nTh\xe0nh ph\u1ed1 t\u1eadp trung nhi\u1ec1u c\u01a1 s\u1edf nh\u01b0 c\xf4ng ty, tr\u01b0\u1eddng h\u1ecdc, b\u1ec7nh vi\u1ec7n, c\u01a1 s\u1edf v\u0103n h\xf3a v\xe0 giao th\xf4ng c\xf4ng c\u1ed9ng n\xean cu\u1ed9c s\u1ed1ng kh\xe1 thu\u1eadn ti\u1ec7n. Tuy nhi\xean, do t\u1eadp trung \u0111\xf4ng ng\u01b0\u1eddi n\xean c\u0169ng xu\u1ea5t hi\u1ec7n c\xe1c v\u1ea5n \u0111\u1ec1 nh\u01b0 \xf9n t\u1eafc giao th\xf4ng, chi ph\xed nh\xe0 \u1edf cao v\xe0 v\u1ea5n \u0111\u1ec1 m\xf4i tr\u01b0\u1eddng.\n\nN\xf4ng th\xf4n c\xf3 d\xe2n s\u1ed1 \xedt h\u01a1n th\xe0nh ph\u1ed1 v\xe0 c\xf3 \u0111\u1eb7c \u0111i\u1ec3m l\xe0 c\xf3 th\u1ec3 s\u1ed1ng g\u1ea7n m\xf4i tr\u01b0\u1eddng t\u1ef1 nhi\xean. N\xf4ng nghi\u1ec7p l\xe0 m\u1ed9t trong nh\u1eefng ng\xe0nh quan tr\u1ecdng c\u1ee7a khu v\u1ef1c n\xf4ng th\xf4n.\n\nTuy nhi\xean, t\u1ea1i m\u1ed9t s\u1ed1 v\xf9ng n\xf4ng th\xf4n, khi ng\u01b0\u1eddi tr\u1ebb chuy\u1ec3n \u0111\u1ebfn th\xe0nh ph\u1ed1, v\u1ea5n \u0111\u1ec1 suy gi\u1ea3m d\xe2n s\u1ed1 v\xe0 gi\xe0 h\xf3a d\xe2n s\u1ed1 \u0111ang xu\u1ea5t hi\u1ec7n.\n\nV\xec v\u1eady, \u0111\u1ec3 th\xe0nh th\u1ecb v\xe0 n\xf4ng th\xf4n c\xf3 th\u1ec3 c\xf9ng ph\xe1t tri\u1ec3n, \u0111i\u1ec1u quan tr\u1ecdng l\xe0 ph\xe1t huy \u0111\u1eb7c \u0111i\u1ec3m c\u1ee7a t\u1eebng khu v\u1ef1c v\xe0 \u0111\u1ea1t \u0111\u01b0\u1ee3c s\u1ef1 ph\xe1t tri\u1ec3n c\xe2n b\u1eb1ng.\n","\ub3c4\uc2dc\uc640 \ub18d\ucd0c \uc0dd\ud65c \ube44\uad50\ud558\uae30","\uc548: \ubbfc\uc218 \uc528\ub294 \ub3c4\uc2dc\uc5d0\uc11c \uc0ac\ub294 \uac8c \uc88b\uc544\uc694?\n\n\ubbfc\uc218: \ub124. \uc800\ub294 \uad50\ud1b5\uc774 \ud3b8\ub9ac\ud574\uc11c \ub3c4\uc2dc \uc0dd\ud65c\uc744 \uc88b\uc544\ud574\uc694.\n\n\uc548: \uc800\ub3c4 \ucd9c\ud1f4\uadfc\ud558\uae30\uc5d0\ub294 \ub3c4\uc2dc\uac00 \ud3b8\ud55c \uac83 \uac19\uc544\uc694.\n\n\ubbfc\uc218: \uadf8\ub7f0\ub370 \uc8fc\uac70\ube44\uac00 \ube44\uc2f8\uace0 \uad50\ud1b5\uc774 \ubcf5\uc7a1\ud55c \uac83\uc740 \ubd88\ud3b8\ud574\uc694.\n\n\uc548: \ub9de\uc544\uc694. \uc800\ub294 \uac00\ub054 \uc870\uc6a9\ud55c \ub18d\ucd0c\uc5d0\uc11c \uc0b4\uace0 \uc2f6\ub2e4\ub294 \uc0dd\uac01\ub3c4 \ud574\uc694.\n\n\ubbfc\uc218: \ub18d\ucd0c\uc740 \uc790\uc5f0\ud658\uacbd\uc774 \uc88b\ub2e4\ub294 \uc7a5\uc810\uc774 \uc788\uc9c0\uc694.\n\n\uc548: \ud558\uc9c0\ub9cc \uc9c0\uc5ed\uc5d0 \ub530\ub77c \ubcd1\uc6d0\uc774\ub098 \ub300\uc911\uad50\ud1b5\uc744 \uc774\uc6a9\ud558\uae30 \ubd88\ud3b8\ud560 \uc218\ub3c4 \uc788\uaca0\ub124\uc694.\n\n\ubbfc\uc218: \ub124. \ub3c4\uc2dc\uc640 \ub18d\ucd0c\uc740 \uac01\uac01 \uc7a5\uc810\uacfc \ub2e8\uc810\uc774 \uc788\ub294 \uac83 \uac19\uc544\uc694.\n\n\uc548: \uadf8\ub798\uc11c \uc9c0\uc5ed\ub9c8\ub2e4 \ud544\uc694\ud55c \uc2dc\uc124\uc744 \uc798 \uac16\ucd94\ub294 \uac83\uc774 \uc911\uc694\ud558\uaca0\ub124\uc694.\n\n\ubbfc\uc218: \ub9de\uc544\uc694. \uc9c0\uc5ed\uc774 \uade0\ud615 \uc788\uac8c \ubc1c\uc804\ud558\uba74 \uc88b\uaca0\uc5b4\uc694.\n","An: Minsu th\xedch s\u1ed1ng \u1edf th\xe0nh ph\u1ed1 \xe0?\n\nMinsu: V\xe2ng. T\xf4i th\xedch cu\u1ed9c s\u1ed1ng th\xe0nh ph\u1ed1 v\xec giao th\xf4ng thu\u1eadn ti\u1ec7n.\n\nAn: T\xf4i c\u0169ng th\u1ea5y th\xe0nh ph\u1ed1 thu\u1eadn ti\u1ec7n cho vi\u1ec7c \u0111i l\xe0m.\n\nMinsu: Nh\u01b0ng chi ph\xed nh\xe0 \u1edf cao v\xe0 giao th\xf4ng ph\u1ee9c t\u1ea1p th\xec kh\xe1 b\u1ea5t ti\u1ec7n.\n\nAn: \u0110\xfang v\u1eady. \u0110\xf4i khi t\xf4i c\u0169ng ngh\u0129 mu\u1ed1n s\u1ed1ng \u1edf v\xf9ng n\xf4ng th\xf4n y\xean t\u0129nh.\n\nMinsu: N\xf4ng th\xf4n c\xf3 \u01b0u \u0111i\u1ec3m l\xe0 m\xf4i tr\u01b0\u1eddng t\u1ef1 nhi\xean t\u1ed1t.\n\nAn: Nh\u01b0ng t\xf9y khu v\u1ef1c, vi\u1ec7c s\u1eed d\u1ee5ng b\u1ec7nh vi\u1ec7n ho\u1eb7c giao th\xf4ng c\xf4ng c\u1ed9ng c\xf3 th\u1ec3 b\u1ea5t ti\u1ec7n.\n\nMinsu: V\xe2ng. T\xf4i ngh\u0129 th\xe0nh ph\u1ed1 v\xe0 n\xf4ng th\xf4n \u0111\u1ec1u c\xf3 \u01b0u \u0111i\u1ec3m v\xe0 nh\u01b0\u1ee3c \u0111i\u1ec3m ri\xeang.\n\nAn: V\xec v\u1eady vi\u1ec7c x\xe2y d\u1ef1ng \u0111\u1ea7y \u0111\u1ee7 nh\u1eefng c\u01a1 s\u1edf c\u1ea7n thi\u1ebft cho t\u1eebng khu v\u1ef1c l\xe0 quan tr\u1ecdng nh\u1ec9.\n\nMinsu: \u0110\xfang v\u1eady. S\u1ebd t\u1ed1t n\u1ebfu c\xe1c khu v\u1ef1c ph\xe1t tri\u1ec3n m\u1ed9t c\xe1ch c\xe2n b\u1eb1ng.\n",A.iTu,A.h7C,A.jff,A.jh5)
A.iDU=s(["Hi\u1ec3u h\u1ec7 th\u1ed1ng tr\u01b0\u1eddng h\u1ecdc c\u01a1 b\u1ea3n \u1edf H\xe0n Qu\u1ed1c.","Bi\u1ebft c\xe1c c\u1ea5p h\u1ecdc nh\u01b0 \ucd08\ub4f1\ud559\uad50, \uc911\ud559\uad50, \uace0\ub4f1\ud559\uad50 v\xe0 \ub300\ud559\uad50.","H\u1ecdc t\u1eeb v\u1ef1ng li\xean quan \u0111\u1ebfn tr\u01b0\u1eddng h\u1ecdc, l\u1edbp h\u1ecdc v\xe0 gi\xe1o vi\xean.","Hi\u1ec3u \xfd ngh\u0129a c\u1ee7a \uc758\ubb34\uad50\uc721.","Bi\u1ebft m\u1ed9t s\u1ed1 ho\u1ea1t \u0111\u1ed9ng v\xe0 quy t\u1eafc c\u01a1 b\u1ea3n trong tr\u01b0\u1eddng h\u1ecdc.","C\xf3 th\u1ec3 \u0111\u1ecdc hi\u1ec3u \u0111o\u1ea1n v\u0103n v\u1ec1 h\u1ec7 th\u1ed1ng gi\xe1o d\u1ee5c H\xe0n Qu\u1ed1c.","Luy\u1ec7n c\xe2u h\u1ecfi ki\u1ebfn th\u1ee9c x\xe3 h\u1ed9i li\xean quan \u0111\u1ebfn tr\u01b0\u1eddng h\u1ecdc."],t.s)
A.j9e=s(["\ud55c\uad6d\uc758 \ud559\uad50\uad50\uc721\uc740 \uc5ec\ub7ec \ub2e8\uacc4\ub85c \uc774\ub8e8\uc5b4\uc838 \uc788\uc2b5\ub2c8\ub2e4.","\ucd08\ub4f1\ud559\uad50, \uc911\ud559\uad50, \uace0\ub4f1\ud559\uad50\ub97c \uac70\uccd0 \ub300\ud559\uad50 \ub4f1\uc5d0 \uc9c4\ud559\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ucd08\ub4f1\ud559\uad50\uc640 \uc911\ud559\uad50 \uacfc\uc815\uc740 \uc758\ubb34\uad50\uc721\uc5d0 \ud3ec\ud568\ub429\ub2c8\ub2e4.","\ud559\uad50\uc5d0\uc11c\ub294 \uad50\uacfc \uacf5\ubd80\ubfd0\ub9cc \uc544\ub2c8\ub77c \ub2e4\uc591\ud55c \ud65c\ub3d9\ub3c4 \ud569\ub2c8\ub2e4.","\ud559\uc0dd\uc740 \ud559\uad50 \uaddc\uce59\uc744 \uc9c0\ud0a4\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc744 \uc874\uc911\ud574\uc57c \ud569\ub2c8\ub2e4.","\uad50\uc0ac\ub294 \ud559\uc0dd\uc758 \ud559\uc2b5\uacfc \uc0dd\ud65c\uc744 \uc9c0\ub3c4\ud569\ub2c8\ub2e4.","\ud559\ubd80\ubaa8\ub294 \ud559\uad50\uc640 \uc18c\ud1b5\ud558\uba70 \uc790\ub140\uc758 \uad50\uc721\uc5d0 \ucc38\uc5ec\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],t.s)
