A.fAZ=new B.O("\ubd84\uc7c1\uc774 \ubc1c\uc0dd\ud588\uc744 \ub54c \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\ub294 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Th\u1ee9 n\xe0o c\xf3 th\u1ec3 gi\xfap \xedch khi x\u1ea3y ra tranh ch\u1ea5p?",A.hZS,0,"H\u1ee3p \u0111\u1ed3ng v\xe0 h\xf3a \u0111\u01a1n c\xf3 th\u1ec3 gi\xfap x\xe1c \u0111\u1ecbnh n\u1ed9i dung giao d\u1ecbch.")
A.hai=s(["\ub0b4\uc6a9\uc744 \uc790\uc138\ud788 \ud655\uc778\ud55c\ub2e4.","\uacc4\uc57d\uc11c\ub97c \uc77d\uc9c0 \uc54a\ub294\ub2e4.","\uc870\uac74\uc744 \uc804\ud600 \ud655\uc778\ud558\uc9c0 \uc54a\ub294\ub2e4.","\ube48 \uacc4\uc57d\uc11c\uc5d0 \uba3c\uc800 \uc11c\uba85\ud55c\ub2e4."],t.s)
A.fHV=new B.O("\uacc4\uc57d\uc11c\uc5d0 \uc11c\uba85\ud558\uae30 \uc804\uc5d0 \ud574\uc57c \ud560 \uc77c\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Tr\u01b0\u1edbc khi k\xfd h\u1ee3p \u0111\u1ed3ng c\u1ea7n l\xe0m g\xec?",A.hai,0,"Tr\u01b0\u1edbc khi k\xfd ph\u1ea3i ki\u1ec3m tra k\u1ef9 n\u1ed9i dung h\u1ee3p \u0111\u1ed3ng.")
A.hMw=s(["\uad00\ub828 \uae30\uad00\uc774\ub098 \uc804\ubb38\uac00\uc5d0\uac8c \uc0c1\ub2f4\ud55c\ub2e4.","\ud655\uc778\ud558\uc9c0 \uc54a\uace0 \ub9c8\uc74c\ub300\ub85c \ucc98\ub9ac\ud55c\ub2e4.","\ubaa8\ub4e0 \uc790\ub8cc\ub97c \ubc84\ub9b0\ub2e4.","\uc0c1\ub300\ubc29\uc5d0\uac8c \ud3ed\ub825\uc744 \uc0ac\uc6a9\ud55c\ub2e4."],t.s)
A.fCJ=new B.O("\ubc95\ub960 \ubb38\uc81c\uac00 \ubcf5\uc7a1\ud560 \ub54c \ubc14\ub78c\uc9c1\ud55c \ud589\ub3d9\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Khi v\u1ea5n \u0111\u1ec1 ph\xe1p l\xfd ph\u1ee9c t\u1ea1p, h\xe0nh \u0111\u1ed9ng ph\xf9 h\u1ee3p l\xe0 g\xec?",A.hMw,0,"N\u1ebfu v\u1ea5n \u0111\u1ec1 ph\u1ee9c t\u1ea1p c\xf3 th\u1ec3 nh\u1eadn t\u01b0 v\u1ea5n t\u1eeb c\u01a1 quan ho\u1eb7c chuy\xean gia.")
A.jI5=s(["\uc0dd\ud65c \uc18d\uc5d0\uc11c\ub3c4 \uacc4\uc57d\uacfc \uac1c\uc778\uc815\ubcf4 \ubcf4\ud638 \ub4f1 \ubc95\ub960 \uc9c0\uc2dd\uc774 \ud544\uc694\ud558\ub2e4.","\ubc95\uc740 \ubc94\uc8c4 \uc0ac\uac74\uc5d0\ub9cc \ud544\uc694\ud558\ub2e4.","\uc911\uc694\ud55c \uacc4\uc57d\ub3c4 \ub9d0\ub85c\ub9cc \ud558\uba74 \uac00\uc7a5 \uc548\uc804\ud558\ub2e4.","\uc601\uc218\uc99d\uacfc \uacc4\uc57d\uc11c\ub294 \ubcf4\uad00\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4."],t.s)
A.fEC=new B.O("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.jI5,0,"Ph\xe1p lu\u1eadt li\xean quan \u0111\u1ebfn r\u1ea5t nhi\u1ec1u ho\u1ea1t \u0111\u1ed9ng h\u1eb1ng ng\xe0y nh\u01b0 thu\xea nh\xe0, mua h\xe0ng v\xe0 b\u1ea3o v\u1ec7 th\xf4ng tin c\xe1 nh\xe2n.")
