A.hh7=s(["\uacbd\uc81c\uc131\uc7a5 = t\u0103ng tr\u01b0\u1edfng kinh t\u1ebf; \uacbd\uc81c\ubc1c\uc804 = kh\xe1i ni\u1ec7m r\u1ed9ng h\u01a1n v\u1ec1 ph\xe1t tri\u1ec3n kinh t\u1ebf.","\ud55c\uac15\uc758 \uae30\uc801\uc740 \uc2e4\uc81c \uae30\uc801\uc774\ub77c\ub294 \uc758\ubbf8\ubcf4\ub2e4 \ud55c\uad6d\uc758 \ube60\ub978 \uacbd\uc81c\uc131\uc7a5\uc744 \ud45c\ud604\ud558\ub294 \ub9d0\uc785\ub2c8\ub2e4.","\uc0b0\uc5c5\ud654 = qu\xe1 tr\xecnh chuy\u1ec3n d\u1ecbch v\xe0 ph\xe1t tri\u1ec3n c\xe1c ng\xe0nh c\xf4ng nghi\u1ec7p.","\uc218\ucd9c = xu\u1ea5t kh\u1ea9u; \uc218\uc785 = nh\u1eadp kh\u1ea9u.","\uc81c\uc870\uc5c5 = ng\xe0nh s\u1ea3n xu\u1ea5t; \uc11c\ube44\uc2a4\uc5c5 = ng\xe0nh d\u1ecbch v\u1ee5.","\uacbd\uc81c\uc131\uc7a5\uc5d0\ub294 \uc815\ubd80 \uc815\ucc45\ubfd0 \uc544\ub2c8\ub77c \uae30\uc5c5, \uadfc\ub85c\uc790, \uad50\uc721, \uae30\uc220 \ub4f1 \uc5ec\ub7ec \uc694\uc18c\uac00 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ube60\ub978 \uacbd\uc81c\uc131\uc7a5\uc5d0\ub294 \uae0d\uc815\uc801\uc778 \uacb0\uacfc\ubfd0 \uc544\ub2c8\ub77c \ud658\uacbd\uc774\ub098 \uaca9\ucc28 \ubb38\uc81c\ub3c4 \ub098\ud0c0\ub0a0 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],t.s)
A.h2J=s(["\ud55c\uac15\uc758 \uae30\uc801 \u2192 \ud55c\uad6d\uc758 \ube60\ub978 \uacbd\uc81c\uc131\uc7a5\uc744 \ud45c\ud604\ud558\ub294 \ub9d0.","\uc0b0\uc5c5\ud654 \u2192 c\xf4ng nghi\u1ec7p h\xf3a.","\uc218\ucd9c \uc911\uc2ec\uc758 \uacbd\uc81c\uc131\uc7a5\uc740 \ud55c\uad6d \uacbd\uc81c\ubc1c\uc804\uc5d0 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud588\ub2e4.","\ub18d\uc5c5 \uc911\uc2ec\uc5d0\uc11c \uc81c\uc870\uc5c5\uacfc \uc11c\ube44\uc2a4\uc5c5 \uc911\uc2ec\uc73c\ub85c \uc0b0\uc5c5\uad6c\uc870\uac00 \ubcc0\ud654\ud588\ub2e4.","\uc790\ub3d9\ucc28, \ucca0\uac15, \uc870\uc120, \uc804\uc790 \ub4f1\uc774 \uc8fc\uc694 \uc0b0\uc5c5\uc73c\ub85c \uc131\uc7a5\ud588\ub2e4.","\uad50\uc721\uacfc \uc778\ub825, \uadfc\ub85c\uc790\uc758 \ub178\ub825\ub3c4 \uc131\uc7a5\uc5d0 \uae30\uc5ec\ud588\ub2e4.","\uacbd\uc81c\uc131\uc7a5\uc73c\ub85c \uc18c\ub4dd\uacfc \uc0dd\ud65c\uc218\uc900\uc774 \ud5a5\uc0c1\ub418\uc5c8\ub2e4.","\ube60\ub978 \uc0b0\uc5c5\ud654 \uacfc\uc815\uc5d0\uc11c \ud658\uacbd\uc624\uc5fc\uacfc \uc9c0\uc5ed \uaca9\ucc28 \ub4f1\uc758 \ubb38\uc81c\ub3c4 \ub098\ud0c0\ub0ac\ub2e4.","\ud604\uc7ac\ub294 \uc9c0\uc18d \uac00\ub2a5\ud55c \ubc1c\uc804\uacfc \uc0b6\uc758 \uc9c8\ub3c4 \uc911\uc694\ud558\ub2e4."],t.s)
