A.fE9=new B.O("\ubc31\uc81c\uc758 \uc5ed\uc0ac\uc640 \uad00\uacc4\uac00 \uae4a\uc740 \uc9c0\uc5ed\uc740 \uc5b4\ub514\uc785\ub2c8\uae4c?","Khu v\u1ef1c n\xe0o c\xf3 quan h\u1ec7 s\xe2u s\u1eafc v\u1edbi l\u1ecbch s\u1eed Baekje?",A.hdJ,0,"\uacf5\uc8fc\uc640 \ubd80\uc5ec\ub294 \ubc31\uc81c\uc758 \uc5ed\uc0ac\uc640 \ubb38\ud654\uc640 \uad00\ub828\uc774 \uae4a\uc2b5\ub2c8\ub2e4.")
A.imx=s(["\uad6d\ud1a0\uc758 \uac00\uc6b4\ub370\uc5d0 \uac00\uae4c\uc6cc \uc5ec\ub7ec \uc9c0\uc5ed\uc73c\ub85c \uc774\ub3d9\ud558\uae30 \ud3b8\ub9ac\ud558\ub2e4.","\ub300\ud55c\ubbfc\uad6d \ucd5c\ub0a8\ub2e8\uc758 \uc12c \uc9c0\uc5ed\uc774\ub2e4.","\ub3d9\ud574\uc5d0\ub9cc \uc788\ub294 \uc9c0\uc5ed\uc774\ub2e4.","\uc678\uad6d\uacfc \uc721\uc9c0\ub85c \uc9c1\uc811 \uc5f0\uacb0\ub418\uc5b4 \uc788\ub2e4."],t.s)
A.fDg=new B.O("\ucda9\uccad \uc9c0\uc5ed\uc758 \uc704\uce58\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740?","Ph\xe1t bi\u1ec3u n\xe0o \u0111\xfang v\u1ec1 v\u1ecb tr\xed c\u1ee7a v\xf9ng Chungcheong?",A.imx,0,"\ucda9\uccad \uc9c0\uc5ed\uc740 \uad6d\ud1a0 \uc911\ubd80\uc5d0 \uc788\uc5b4 \uc5ec\ub7ec \uc9c0\uc5ed\uc73c\ub85c \uc774\ub3d9\ud558\uae30 \ud3b8\ub9ac\ud55c \ud3b8\uc785\ub2c8\ub2e4.")
A.hLD=s(["\uac15\uc6d0\uc740 \uc790\uc5f0\uad00\uad11\uc774 \ubc1c\ub2ec\ud558\uace0 \ucda9\uccad\uc740 \uad50\ud1b5\uacfc \ud589\uc815 \uae30\ub2a5\ub3c4 \uc911\uc694\ud558\ub2e4.","\ucda9\uccad\ubd81\ub3c4\ub294 \ubc14\ub2e4\ub85c \ub458\ub7ec\uc2f8\uc778 \uc12c\uc774\ub2e4.","\uc138\uc885\uc740 \uaca8\uc6b8 \uc2a4\ud3ec\uce20\ub85c \uac00\uc7a5 \uc720\uba85\ud55c \ub3c4\uc2dc\uc774\ub2e4.","\uc124\uc545\uc0b0\uc740 \ucda9\uccad\ub0a8\ub3c4 \uc11c\ud574\uc548\uc5d0 \uc788\ub2e4."],t.s)
A.fCL=new B.O("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.hLD,0,"Gangwon n\u1ed5i b\u1eadt v\u1ec1 thi\xean nhi\xean, c\xf2n Chungcheong c\xf3 l\u1ee3i th\u1ebf v\u1ec1 giao th\xf4ng, h\xe0nh ch\xednh, nghi\xean c\u1ee9u v\xe0 l\u1ecbch s\u1eed.")
A.izf=s([A.fIF,A.fCd,A.fGW,A.fHI,A.fEB,A.fIt,A.fBS,A.fE9,A.fDg,A.fCL],t.h)
A.i_v=s(["\uac15\uc6d0 = khu v\u1ef1c ph\xeda \u0111\xf4ng, nhi\u1ec1u n\xfai.","\uac15\uc6d0 = \ub3d9\ud574\uc640 \uc811\ud568.","\uc124\uc545\uc0b0 = ng\u1ecdn n\xfai ti\xeau bi\u1ec3u c\u1ee7a Gangwon.","\uac15\ub989 \xb7 \uc18d\ucd08 = c\xe1c th\xe0nh ph\u1ed1 du l\u1ecbch b\u1edd bi\u1ec3n ph\xeda \u0111\xf4ng.","\uac15\uc6d0 = thi\xean nhi\xean + du l\u1ecbch + th\u1ec3 thao m\xf9a \u0111\xf4ng.","\ucda9\uccad = khu v\u1ef1c trung t\xe2m c\u1ee7a \u0111\u1ea5t n\u01b0\u1edbc.","\ucda9\uccad\ubd81\ub3c4 = khu v\u1ef1c n\u1ed9i \u0111\u1ecba, kh\xf4ng tr\u1ef1c ti\u1ebfp gi\xe1p bi\u1ec3n.","\ucda9\uccad\ub0a8\ub3c4 = ti\u1ebfp gi\xe1p bi\u1ec3n T\xe2y.","\ub300\uc804 = giao th\xf4ng + khoa h\u1ecdc v\xe0 nghi\xean c\u1ee9u.","\uc138\uc885 = h\xe0nh ch\xednh + nhi\u1ec1u c\u01a1 quan trung \u01b0\u01a1ng.","\uacf5\uc8fc \xb7 \ubd80\uc5ec = l\u1ecbch s\u1eed v\xe0 v\u0103n h\xf3a Baekje.","\uac15\uc6d0\uacfc \ucda9\uccad\uc740 \uc11c\ub85c \ub2e4\ub978 \uc790\uc5f0\ud658\uacbd\uacfc \uc9c0\uc5ed\uc801 \ud2b9\uc9d5\uc744 \uac00\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4."],t.s)
A.fAz=new B.dJ(46,"\uc9c0\ub9ac","\uac15\uc6d0\uacfc \ucda9\uccad","Khu v\u1ef1c Gangwon v\xe0 Chungcheong",A.jA0,A.jl5,A.jDc,A.jpv,"\uac15\uc6d0\uacfc \ucda9\uccad \uc9c0\uc5ed\uc758 \ud2b9\uc9d5","\uac15\uc6d0\uacfc \ucda9\uccad\uc740 \uc11c\ub85c \uac00\uae4c\uc6b4 \uc9c0\uc5ed\uc774\uc9c0\ub9cc \uc790\uc5f0\ud658\uacbd\uacfc \ub3c4\uc2dc\uc758 \uae30\ub2a5\uc5d0\uc11c \uc11c\ub85c \ub2e4\ub978 \ud2b9\uc9d5\uc744 \uac00\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uac15\uc6d0 \uc9c0\uc5ed\uc740 \ud55c\ubc18\ub3c4\uc758 \ub3d9\ucabd\uc5d0 \uc704\uce58\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc0b0\uc9c0\uac00 \ub9ce\uc73c\uba70 \ub3d9\ucabd\uc73c\ub85c\ub294 \ub3d9\ud574\uc640 \uc811\ud574 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ub300\ud45c\uc801\uc778 \uc0b0\uc73c\ub85c \uc124\uc545\uc0b0\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc124\uc545\uc0b0\uc740 \uc544\ub984\ub2e4\uc6b4 \uc790\uc5f0\uacbd\uad00\uc73c\ub85c \uc720\uba85\ud558\uc5ec \uc0ac\uacc4\uc808 \ub9ce\uc740 \uad00\uad11\uac1d\uc774 \ucc3e\uc2b5\ub2c8\ub2e4.\n\n\uac15\ub989\uacfc \uc18d\ucd08 \uac19\uc740 \ub3d9\ud574\uc548 \ub3c4\uc2dc\uc5d0\uc11c\ub294 \ubc14\ub2e4\uc640 \ud574\uc0b0\ubb3c, \ub2e4\uc591\ud55c \uad00\uad11\uc9c0\ub97c \uc990\uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uac15\uc6d0 \uc9c0\uc5ed\uc740 \uaca8\uc6b8\ucca0\uc5d0 \ub208\uc774 \ub9ce\uc774 \ub0b4\ub9ac\ub294 \uacf3\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc790\uc5f0\ud658\uacbd\uc744 \uc774\uc6a9\ud558\uc5ec \uc2a4\ud0a4\uc640 \uac19\uc740 \uaca8\uc6b8 \uc2a4\ud3ec\uce20\uc640 \uad00\uad11\uc0b0\uc5c5\uc774 \ubc1c\ub2ec\ud55c \uc9c0\uc5ed\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ucda9\uccad \uc9c0\uc5ed\uc740 \ud55c\ubc18\ub3c4 \uc911\ubd80\uc5d0 \uc704\uce58\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc9c0\ub9ac\uc801\uc73c\ub85c \uad6d\ud1a0\uc758 \uac00\uc6b4\ub370\uc5d0 \uac00\uae4c\uc6cc \uc218\ub3c4\uad8c\uacfc \uc601\ub0a8, \ud638\ub0a8 \ub4f1 \uc5ec\ub7ec \uc9c0\uc5ed\uc73c\ub85c \uc774\ub3d9\ud558\uae30 \ud3b8\ub9ac\ud569\ub2c8\ub2e4.\n\n\ucda9\uccad\ubd81\ub3c4\ub294 \ud55c\uad6d\uc5d0\uc11c \ubc14\ub2e4\uc640 \uc9c1\uc811 \uc811\ud558\uc9c0 \uc54a\ub294 \ub0b4\ub959 \uc9c0\uc5ed\uc785\ub2c8\ub2e4. \uccad\uc8fc\ub294 \ucda9\uccad\ubd81\ub3c4\uc758 \uc911\uc694\ud55c \ub3c4\uc2dc \uc911 \ud558\ub098\uc785\ub2c8\ub2e4.\n\n\ucda9\uccad\ub0a8\ub3c4\ub294 \uc11c\ud574\uc640 \uc811\ud574 \uc788\uc2b5\ub2c8\ub2e4. \ub18d\uc5c5\uc5d0 \uc720\ub9ac\ud55c \ud3c9\uc57c\uc640 \ud574\uc548 \uc9c0\uc5ed\uc774 \uc788\uc73c\uba70 \ucc9c\uc548, \uacf5\uc8fc, \ubcf4\ub839 \ub4f1 \uc5ec\ub7ec \ub3c4\uc2dc\uac00 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ub300\uc804\uad11\uc5ed\uc2dc\ub294 \ucda9\uccad\uad8c\uc758 \uc911\uc694\ud55c \ub3c4\uc2dc\uc785\ub2c8\ub2e4. \ucca0\ub3c4\uc640 \uace0\uc18d\ub3c4\ub85c \ub4f1 \uad50\ud1b5\uc774 \ubc1c\ub2ec\ud574 \uc788\uc73c\uba70 \uacfc\ud559\uacfc \uc5f0\uad6c \uae30\ub2a5\ub3c4 \ubc1c\ub2ec\ud588\uc2b5\ub2c8\ub2e4.\n\n\uc138\uc885\ud2b9\ubcc4\uc790\uce58\uc2dc\ub294 \ud589\uc815 \uae30\ub2a5\uc774 \uc911\uc694\ud55c \ub3c4\uc2dc\uc785\ub2c8\ub2e4. \uc5ec\ub7ec \uc911\uc559\ud589\uc815\uae30\uad00\uc774 \uc138\uc885\uc73c\ub85c \uc774\uc804\ud558\uc5ec \uad6d\uac00 \ud589\uc815\uc758 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uacf5\uc8fc\uc640 \ubd80\uc5ec\ub294 \ubc31\uc81c\uc758 \uc5ed\uc0ac\uc640 \uad00\ub828\uc774 \uae4a\uc2b5\ub2c8\ub2e4. \uc774 \uc9c0\uc5ed\uc5d0\ub294 \ubc31\uc81c \uc2dc\ub300\uc758 \ubb38\ud654\uc640 \uc5ed\uc0ac\ub97c \uc774\ud574\ud560 \uc218 \uc788\ub294 \uc5ec\ub7ec \uc720\uc801\uacfc \ubb38\ud654\uc720\uc0b0\uc774 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc774\ucc98\ub7fc \uac15\uc6d0\uc740 \uc0b0\uacfc \ubc14\ub2e4, \uc790\uc5f0\uad00\uad11\uc774 \uc911\uc694\ud55c \uc9c0\uc5ed\uc774\uace0 \ucda9\uccad\uc740 \uc911\uc559\uc5d0 \uc704\uce58\ud55c \uad50\ud1b5\uc758 \ud3b8\ub9ac\ud568\uacfc \ud589\uc815, \uc5f0\uad6c, \uc5ed\uc0ac\ubb38\ud654 \ub4f1\uc758 \ud2b9\uc9d5\uc744 \uac00\uc9c4 \uc9c0\uc5ed\uc785\ub2c8\ub2e4.\n","Gangwon v\xe0 Chungcheong l\xe0 hai v\xf9ng t\u01b0\u01a1ng \u0111\u1ed1i g\u1ea7n nhau nh\u01b0ng c\xf3 nh\u1eefng \u0111\u1eb7c \u0111i\u1ec3m kh\xe1c nhau v\u1ec1 m\xf4i tr\u01b0\u1eddng t\u1ef1 nhi\xean v\xe0 ch\u1ee9c n\u0103ng \u0111\xf4 th\u1ecb.\n\nGangwon n\u1eb1m \u1edf ph\xeda \u0111\xf4ng b\xe1n \u0111\u1ea3o Tri\u1ec1u Ti\xean. Khu v\u1ef1c n\xe0y c\xf3 nhi\u1ec1u n\xfai v\xe0 ph\xeda \u0111\xf4ng ti\u1ebfp gi\xe1p bi\u1ec3n \u0110\xf4ng.\n\nSeoraksan l\xe0 m\u1ed9t trong nh\u1eefng ng\u1ecdn n\xfai ti\xeau bi\u1ec3u. Nh\u1edd c\u1ea3nh quan thi\xean nhi\xean \u0111\u1eb9p, Seoraksan thu h\xfat nhi\u1ec1u du kh\xe1ch trong c\u1ea3 b\u1ed1n m\xf9a.\n\nT\u1ea1i c\xe1c th\xe0nh ph\u1ed1 ven bi\u1ec3n ph\xeda \u0111\xf4ng nh\u01b0 Gangneung v\xe0 Sokcho, ng\u01b0\u1eddi d\xe2n v\xe0 du kh\xe1ch c\xf3 th\u1ec3 t\u1eadn h\u01b0\u1edfng bi\u1ec3n, h\u1ea3i s\u1ea3n v\xe0 nhi\u1ec1u \u0111\u1ecba \u0111i\u1ec3m du l\u1ecbch.\n\nM\u1ed9t s\u1ed1 khu v\u1ef1c Gangwon c\xf3 l\u01b0\u1ee3ng tuy\u1ebft l\u1edbn v\xe0o m\xf9a \u0111\xf4ng. Nh\u1edd m\xf4i tr\u01b0\u1eddng t\u1ef1 nhi\xean n\xe0y, c\xe1c m\xf4n th\u1ec3 thao m\xf9a \u0111\xf4ng nh\u01b0 tr\u01b0\u1ee3t tuy\u1ebft v\xe0 ng\xe0nh du l\u1ecbch c\u0169ng ph\xe1t tri\u1ec3n t\u1ea1i m\u1ed9t s\u1ed1 n\u01a1i.\n\nV\xf9ng Chungcheong n\u1eb1m \u1edf khu v\u1ef1c trung t\xe2m b\xe1n \u0111\u1ea3o Tri\u1ec1u Ti\xean. Do v\u1ecb tr\xed g\u1ea7n trung t\xe2m l\xe3nh th\u1ed5, vi\u1ec7c di chuy\u1ec3n t\u1edbi v\xf9ng th\u1ee7 \u0111\xf4, Yeongnam hay Honam t\u01b0\u01a1ng \u0111\u1ed1i thu\u1eadn ti\u1ec7n.\n\nChungcheong B\u1eafc l\xe0 khu v\u1ef1c n\u1ed9i \u0111\u1ecba kh\xf4ng tr\u1ef1c ti\u1ebfp ti\u1ebfp gi\xe1p bi\u1ec3n. Cheongju l\xe0 m\u1ed9t trong nh\u1eefng th\xe0nh ph\u1ed1 quan tr\u1ecdng c\u1ee7a Chungcheong B\u1eafc.\n\nChungcheong Nam ti\u1ebfp gi\xe1p bi\u1ec3n T\xe2y. Khu v\u1ef1c n\xe0y c\xf3 nh\u1eefng \u0111\u1ed3ng b\u1eb1ng thu\u1eadn l\u1ee3i cho n\xf4ng nghi\u1ec7p, v\xf9ng ven bi\u1ec3n v\xe0 nhi\u1ec1u th\xe0nh ph\u1ed1 nh\u01b0 Cheonan, Gongju v\xe0 Boryeong.\n\nDaejeon l\xe0 m\u1ed9t th\xe0nh ph\u1ed1 quan tr\u1ecdng c\u1ee7a khu v\u1ef1c Chungcheong. H\u1ec7 th\u1ed1ng \u0111\u01b0\u1eddng s\u1eaft, \u0111\u01b0\u1eddng cao t\u1ed1c ph\xe1t tri\u1ec3n v\xe0 th\xe0nh ph\u1ed1 c\u0169ng c\xf3 ch\u1ee9c n\u0103ng m\u1ea1nh v\u1ec1 khoa h\u1ecdc v\xe0 nghi\xean c\u1ee9u.\n\nSejong l\xe0 th\xe0nh ph\u1ed1 c\xf3 ch\u1ee9c n\u0103ng h\xe0nh ch\xednh quan tr\u1ecdng. Nhi\u1ec1u c\u01a1 quan h\xe0nh ch\xednh trung \u01b0\u01a1ng \u0111\xe3 chuy\u1ec3n t\u1edbi Sejong v\xe0 th\xe0nh ph\u1ed1 gi\u1eef vai tr\xf2 quan tr\u1ecdng trong h\xe0nh ch\xednh qu\u1ed1c gia.\n\nGongju v\xe0 Buyeo c\xf3 quan h\u1ec7 s\xe2u s\u1eafc v\u1edbi l\u1ecbch s\u1eed Baekje. Hai khu v\u1ef1c n\xe0y c\xf3 nhi\u1ec1u di t\xedch v\xe0 di s\u1ea3n gi\xfap t\xecm hi\u1ec3u v\u0103n h\xf3a v\xe0 l\u1ecbch s\u1eed Baekje.\n\nNh\u01b0 v\u1eady, Gangwon n\u1ed5i b\u1eadt v\u1edbi n\xfai, bi\u1ec3n v\xe0 du l\u1ecbch thi\xean nhi\xean; c\xf2n Chungcheong n\u1ed5i b\u1eadt nh\u1edd v\u1ecb tr\xed trung t\xe2m, giao th\xf4ng thu\u1eadn l\u1ee3i, ch\u1ee9c n\u0103ng h\xe0nh ch\xednh, nghi\xean c\u1ee9u v\xe0 l\u1ecbch s\u1eed v\u0103n h\xf3a.\n","\uac15\uc6d0\uacfc \ucda9\uccad \uc5ec\ud589 \uacc4\ud68d\ud558\uae30","\uc548: \ubbfc\uc218 \uc528, \uc774\ubc88 \ud734\uac00\uc5d0 \uac15\uc6d0\ub3c4\uc5d0 \uac00 \ubcf4\uace0 \uc2f6\uc5b4\uc694.\n\n\ubbfc\uc218: \uc790\uc5f0\uc744 \uc88b\uc544\ud558\uba74 \uac15\uc6d0\ub3c4\uac00 \uc88b\uc544\uc694. \uc0b0\ub3c4 \ub9ce\uace0 \ubc14\ub2e4\ub3c4 \uc788\uc5b4\uc694.\n\n\uc548: \uc720\uba85\ud55c \uc0b0\uc740 \uc5b4\ub514\uc608\uc694?\n\n\ubbfc\uc218: \uc124\uc545\uc0b0\uc774 \uc544\uc8fc \uc720\uba85\ud574\uc694.\n\n\uc548: \ubc14\ub2e4\ub97c \ubcf4\uace0 \uc2f6\uc73c\uba74 \uc5b4\ub514\ub85c \uac00\ub294 \uac8c \uc88b\uc544\uc694?\n\n\ubbfc\uc218: \uac15\ub989\uc774\ub098 \uc18d\ucd08 \uac19\uc740 \ub3d9\ud574\uc548 \ub3c4\uc2dc\ub97c \uac00 \ubcf4\uc138\uc694.\n\n\uc548: \uaca8\uc6b8\uc5d0\ub294 \uc2a4\ud0a4\ub3c4 \ud0c8 \uc218 \uc788\uc9c0\uc694?\n\n\ubbfc\uc218: \ub124. \uac15\uc6d0 \uc9c0\uc5ed\uc5d0\ub294 \uaca8\uc6b8 \uc2a4\ud3ec\uce20\ub97c \uc990\uae38 \uc218 \uc788\ub294 \uacf3\ub3c4 \ub9ce\uc544\uc694.\n\n\uc548: \ucda9\uccad \uc9c0\uc5ed\uc740 \uc5b4\ub5a4 \ud2b9\uc9d5\uc774 \uc788\uc5b4\uc694?\n\n\ubbfc\uc218: \uad6d\ud1a0\uc758 \uac00\uc6b4\ub370 \ubd80\ubd84\uc774\ub77c \ub2e4\ub978 \uc9c0\uc5ed\uc73c\ub85c \uc774\ub3d9\ud558\uae30 \ud3b8\ub9ac\ud55c \ud3b8\uc774\uc5d0\uc694.\n\n\uc548: \ub300\uc804\ub3c4 \ucda9\uccad \uc9c0\uc5ed\uc5d0 \uc788\uc9c0\uc694?\n\n\ubbfc\uc218: \ub124. \ub300\uc804\uc740 \uad50\ud1b5\uacfc \uacfc\ud559 \uc5f0\uad6c\uac00 \ubc1c\ub2ec\ud55c \ub3c4\uc2dc\uc608\uc694.\n\n\uc548: \uc138\uc885\uc740\uc694?\n\n\ubbfc\uc218: \uc138\uc885\uc5d0\ub294 \uc5ec\ub7ec \uc911\uc559\ud589\uc815\uae30\uad00\uc774 \uc788\uc5b4\uc11c \ud589\uc815 \uae30\ub2a5\uc774 \uc911\uc694\ud574\uc694.\n\n\uc548: \uc5ed\uc0ac \uc720\uc801\uc744 \ubcf4\uace0 \uc2f6\uc73c\uba74 \uc5b4\ub514\ub85c \uac00\uba74 \uc88b\uc544\uc694?\n\n\ubbfc\uc218: \uacf5\uc8fc\ub098 \ubd80\uc5ec\uc5d0 \uac00 \ubcf4\uc138\uc694. \ubc31\uc81c\uc758 \uc5ed\uc0ac\uc640 \uad00\ub828\ub41c \uc720\uc801\uc744 \ub9ce\uc774 \ubcfc \uc218 \uc788\uc5b4\uc694.\n\n\uc548: \uac15\uc6d0\uacfc \ucda9\uccad\uc740 \ubd84\uc704\uae30\uac00 \uc815\ub9d0 \ub2e4\ub974\ub124\uc694.\n\n\ubbfc\uc218: \ub9de\uc544\uc694. \uadf8\ub798\uc11c \uc9c0\uc5ed\ubcc4 \ud2b9\uc9d5\uc744 \uc54c\uace0 \uc5ec\ud589\ud558\uba74 \ub354 \uc7ac\ubbf8\uc788\uc5b4\uc694.\n","An: Minsu, k\u1ef3 ngh\u1ec9 n\xe0y t\xf4i mu\u1ed1n th\u1eed \u0111i Gangwon.\n\nMinsu: N\u1ebfu th\xedch thi\xean nhi\xean th\xec Gangwon r\u1ea5t ph\xf9 h\u1ee3p. C\xf3 nhi\u1ec1u n\xfai v\xe0 c\u0169ng c\xf3 bi\u1ec3n.\n\nAn: N\xfai n\u1ed5i ti\u1ebfng l\xe0 n\xfai n\xe0o?\n\nMinsu: Seoraksan r\u1ea5t n\u1ed5i ti\u1ebfng.\n\nAn: N\u1ebfu mu\u1ed1n ng\u1eafm bi\u1ec3n th\xec n\xean \u0111i \u0111\xe2u?\n\nMinsu: H\xe3y th\u1eed t\u1edbi c\xe1c th\xe0nh ph\u1ed1 ven bi\u1ec3n ph\xeda \u0111\xf4ng nh\u01b0 Gangneung ho\u1eb7c Sokcho.\n\nAn: M\xf9a \u0111\xf4ng c\u0169ng c\xf3 th\u1ec3 tr\u01b0\u1ee3t tuy\u1ebft \u0111\xfang kh\xf4ng?\n\nMinsu: V\xe2ng. Gangwon c\xf3 nhi\u1ec1u n\u01a1i c\xf3 th\u1ec3 t\u1eadn h\u01b0\u1edfng c\xe1c m\xf4n th\u1ec3 thao m\xf9a \u0111\xf4ng.\n\nAn: V\xf9ng Chungcheong c\xf3 \u0111\u1eb7c \u0111i\u1ec3m g\xec?\n\nMinsu: V\xec n\u1eb1m \u1edf ph\u1ea7n gi\u1eefa c\u1ee7a \u0111\u1ea5t n\u01b0\u1edbc n\xean vi\u1ec7c \u0111i t\u1edbi c\xe1c khu v\u1ef1c kh\xe1c t\u01b0\u01a1ng \u0111\u1ed1i thu\u1eadn ti\u1ec7n.\n\nAn: Daejeon c\u0169ng thu\u1ed9c v\xf9ng Chungcheong \u0111\xfang kh\xf4ng?\n\nMinsu: V\xe2ng. Daejeon l\xe0 th\xe0nh ph\u1ed1 ph\xe1t tri\u1ec3n v\u1ec1 giao th\xf4ng v\xe0 nghi\xean c\u1ee9u khoa h\u1ecdc.\n\nAn: C\xf2n Sejong?\n\nMinsu: Sejong c\xf3 nhi\u1ec1u c\u01a1 quan h\xe0nh ch\xednh trung \u01b0\u01a1ng n\xean ch\u1ee9c n\u0103ng h\xe0nh ch\xednh r\u1ea5t quan tr\u1ecdng.\n\nAn: N\u1ebfu mu\u1ed1n xem di t\xedch l\u1ecbch s\u1eed th\xec n\xean \u0111i \u0111\xe2u?\n\nMinsu: H\xe3y th\u1eed t\u1edbi Gongju ho\u1eb7c Buyeo. C\xf3 th\u1ec3 th\u1ea5y nhi\u1ec1u di t\xedch li\xean quan \u0111\u1ebfn l\u1ecbch s\u1eed Baekje.\n\nAn: Gangwon v\xe0 Chungcheong c\xf3 kh\xf4ng kh\xed r\u1ea5t kh\xe1c nhau nh\u1ec9.\n\nMinsu: \u0110\xfang v\u1eady. Bi\u1ebft \u0111\u1eb7c \u0111i\u1ec3m t\u1eebng v\xf9ng tr\u01b0\u1edbc khi \u0111i s\u1ebd th\xfa v\u1ecb h\u01a1n.\n",A.jgG,A.jfB,A.izf,A.i_v)
A.hXg=s(["Hi\u1ec3u c\u1ea5u tr\xfac c\u01a1 b\u1ea3n c\u1ee7a h\u1ec7 th\u1ed1ng ch\xednh tr\u1ecb H\xe0n Qu\u1ed1c.","Hi\u1ec3u kh\xe1i ni\u1ec7m \uc0bc\uad8c\ubd84\ub9bd.","Bi\u1ebft vai tr\xf2 c\u01a1 b\u1ea3n c\u1ee7a \uc785\ubc95\ubd80, \ud589\uc815\ubd80 v\xe0 \uc0ac\ubc95\ubd80.","Bi\u1ebft vai tr\xf2 c\u1ee7a \uad6d\ud68c, \ub300\ud1b5\ub839 v\xe0 \ubc95\uc6d0.","Hi\u1ec3u l\xfd do quy\u1ec1n l\u1ef1c nh\xe0 n\u01b0\u1edbc \u0111\u01b0\u1ee3c ph\xe2n chia.","Bi\u1ebft vai tr\xf2 c\u01a1 b\u1ea3n c\u1ee7a \ud5cc\ubc95\uc7ac\ud310\uc18c.","Luy\u1ec7n \u0111\u1ecdc hi\u1ec3u v\xe0 c\xe2u h\u1ecfi ki\u1ebfn th\u1ee9c x\xe3 h\u1ed9i v\u1ec1 h\u1ec7 th\u1ed1ng ch\xednh tr\u1ecb."],t.s)
A.jdN=s(["\ub300\ud55c\ubbfc\uad6d\uc758 \uad6d\uac00 \uad8c\ub825\uc740 \uc785\ubc95, \ud589\uc815, \uc0ac\ubc95\uc73c\ub85c \ub098\ub204\uc5b4\uc838 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\ub7ec\ud55c \uc6d0\ub9ac\ub97c \uc0bc\uad8c\ubd84\ub9bd\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4.","\uc785\ubc95\ubd80\uc758 \ub300\ud45c\uc801\uc778 \uae30\uad00\uc740 \uad6d\ud68c\uc785\ub2c8\ub2e4.","\uad6d\ud68c\ub294 \ubc95\ub960\uc744 \ub9cc\ub4e4\uace0 \uad6d\uac00\uc758 \uc911\uc694\ud55c \uc77c\uc744 \uc2ec\uc758\ud569\ub2c8\ub2e4.","\ud589\uc815\ubd80\ub294 \ubc95\ub960\uacfc \uc815\ucc45\uc744 \uc2e4\uc81c\ub85c \uc9d1\ud589\ud558\ub294 \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4.","\ub300\ud1b5\ub839\uc740 \ud589\uc815\ubd80\ub97c \uc774\ub044\ub294 \uc911\uc694\ud55c \uad6d\uac00\uae30\uad00\uc785\ub2c8\ub2e4.","\uc0ac\ubc95\ubd80\uc758 \ub300\ud45c\uc801\uc778 \uae30\uad00\uc740 \ubc95\uc6d0\uc774\uba70 \uc7ac\ud310\uc744 \ud1b5\ud574 \ubc95\uc744 \uc801\uc6a9\ud569\ub2c8\ub2e4.","\ud5cc\ubc95\uc7ac\ud310\uc18c\ub294 \ud5cc\ubc95\uacfc \uad00\ub828\ub41c \uc911\uc694\ud55c \ubb38\uc81c\ub97c \ud310\ub2e8\ud569\ub2c8\ub2e4.","\uc0bc\uad8c\ubd84\ub9bd\uc740 \ud55c \uae30\uad00\uc5d0 \uad8c\ub825\uc774 \uc9c0\ub098\uce58\uac8c \uc9d1\uc911\ub418\ub294 \uac83\uc744 \ub9c9\uae30 \uc704\ud55c \uc911\uc694\ud55c \uc6d0\ub9ac\uc785\ub2c8\ub2e4."],t.s)
