A.fDW=new B.O("\u201c\uc800\uc791\uad8c\u201d\uacfc \uac00\uc7a5 \uad00\ub828\uc774 \uc788\ub294 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110i\u1ec1u n\xe0o li\xean quan nh\u1ea5t \u0111\u1ebfn \uc800\uc791\uad8c?",A.i5h,0,"\uc800\uc791\uad8c li\xean quan \u0111\u1ebfn vi\u1ec7c b\u1ea3o v\u1ec7 quy\u1ec1n \u0111\u1ed1i v\u1edbi t\xe1c ph\u1ea9m s\xe1ng t\u1ea1o.")
A.hNA=s(["\uc800\uc791\uad8c\uc744 \uc874\uc911\ud55c\ub2e4.","\ubaa8\ub4e0 \ucf58\ud150\uce20\ub97c \ud5c8\ub77d \uc5c6\uc774 \ubcf5\uc0ac\ud55c\ub2e4.","\uc720\ub8cc \ucf58\ud150\uce20\ub97c \ubd88\ubc95\uc73c\ub85c \uacf5\uc720\ud55c\ub2e4.","\ub2e4\ub978 \uc0ac\ub78c\uc758 \uc791\ud488\uc744 \uc790\uc2e0\uc758 \uac83\uc774\ub77c\uace0 \ud55c\ub2e4."],t.s)
A.fBK=new B.O("\uc778\ud130\ub137 \ucf58\ud150\uce20\ub97c \uc774\uc6a9\ud558\ub294 \ud0dc\ub3c4\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Th\xe1i \u0111\u1ed9 n\xe0o ph\xf9 h\u1ee3p khi s\u1eed d\u1ee5ng n\u1ed9i dung tr\xean Internet?",A.hNA,0,"C\u1ea7n t\xf4n tr\u1ecdng b\u1ea3n quy\u1ec1n khi s\u1eed d\u1ee5ng n\u1ed9i dung.")
A.h3x=s(["\ud55c\ub958\ub294 \ubb38\ud654 \uc678\uc758 \ub2e4\ub978 \ubd84\uc57c\uc5d0\ub294 \uc804\ud600 \uc601\ud5a5\uc744 \uc8fc\uc9c0 \uc54a\ub294\ub2e4.","\uc778\ud130\ub137\uacfc SNS\ub294 \ud55c\uad6d \ucf58\ud150\uce20\uac00 \ud574\uc678\uc5d0 \uc54c\ub824\uc9c0\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc8fc\uc5c8\ub2e4.","\uc778\ud130\ub137\uc5d0 \uc788\ub294 \ucf58\ud150\uce20\ub294 \ubaa8\ub450 \uc790\uc720\ub86d\uac8c \ubcf5\uc0ac\ud560 \uc218 \uc788\ub2e4.","\uc6f9\ud230\uc740 \uc758\ub8cc\uc81c\ub3c4\uc758 \ud55c \uc885\ub958\uc774\ub2e4."],t.s)
A.fF9=new B.O("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.h3x,1,"Internet v\xe0 SNS \u0111\xe3 gi\xfap n\u1ed9i dung v\u0103n h\xf3a H\xe0n Qu\u1ed1c ti\u1ebfp c\u1eadn ng\u01b0\u1eddi d\xf9ng \u1edf nhi\u1ec1u n\u01a1i.")
A.isp=s([A.fEi,A.fD1,A.fIh,A.fCN,A.fGb,A.fAS,A.fDm,A.fDW,A.fBK,A.fF9],t.h)
A.iWq=s(["\ub300\uc911\ubb38\ud654 = v\u0103n h\xf3a \u0111\u1ea1i ch\xfang.","\ud55c\ub958 = l\xe0n s\xf3ng v\u0103n h\xf3a H\xe0n Qu\u1ed1c.","\ucf58\ud150\uce20 = n\u1ed9i dung.","\ub300\uc911\uc74c\uc545 = nh\u1ea1c \u0111\u1ea1i ch\xfang.","\ub4dc\ub77c\ub9c8 = phim truy\u1ec1n h\xecnh.","\uc601\ud654 = phim \u0111i\u1ec7n \u1ea3nh.","\uc608\ub2a5 = ch\u01b0\u01a1ng tr\xecnh gi\u1ea3i tr\xed.","\uc6f9\ud230 = truy\u1ec7n tranh m\u1ea1ng.","\uc778\ud130\ub137\uacfc SNS\ub294 \ud55c\ub958 \ud655\uc0b0\uc5d0 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4.","\ud55c\ub958\ub294 \ud55c\uad6d\uc5b4 \ud559\uc2b5\uacfc \uad00\uad11 \ub4f1\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc800\uc791\uad8c = b\u1ea3n quy\u1ec1n.","\ubb38\ud654 \ucf58\ud150\uce20\ub97c \uc774\uc6a9\ud560 \ub54c\uc5d0\ub294 \uc800\uc791\uad8c\uc744 \uc874\uc911\ud574\uc57c \ud569\ub2c8\ub2e4."],t.s)
A.fAB=new B.dJ(18,"\ubb38\ud654","\ud55c\uad6d\uc758 \ub300\uc911\ubb38\ud654","V\u0103n h\xf3a \u0111\u1ea1i ch\xfang H\xe0n Qu\u1ed1c",A.hEm,A.jmj,A.jrK,A.if6,"\uc138\uacc4\ub85c \ud37c\uc9c0\ub294 \ud55c\uad6d\uc758 \ub300\uc911\ubb38\ud654","\ub300\uc911\ubb38\ud654\ub294 \uc74c\uc545, \uc601\ud654, \ub4dc\ub77c\ub9c8, \ubc29\uc1a1, \uc6f9\ud230 \ub4f1 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uc27d\uac8c \uc811\ud558\uace0 \uc990\uae30\ub294 \ubb38\ud654\ub97c \ub9d0\ud569\ub2c8\ub2e4.\n\n\ud55c\uad6d\uc758 \ub300\uc911\ubb38\ud654\ub3c4 \uc2dc\ub300\uc640 \uae30\uc220\uc758 \ubc1c\uc804\uc5d0 \ub530\ub77c \ub2e4\uc591\ud558\uac8c \ubcc0\ud654\ud574 \uc654\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 \uc778\ud130\ub137\uacfc \uc2a4\ub9c8\ud2b8\ud3f0, SNS\uac00 \ubc1c\ub2ec\ud558\uba74\uc11c \ud55c\uad6d\uc758 \ubb38\ud654 \ucf58\ud150\uce20\ub97c \ud574\uc678\uc5d0\uc11c\ub3c4 \uc27d\uac8c \uc811\ud560 \uc218 \uc788\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4.\n\n\ud55c\uad6d\uc758 \uc74c\uc545, \ub4dc\ub77c\ub9c8, \uc601\ud654 \ub4f1\uc774 \ud574\uc678\uc5d0\uc11c \uc778\uae30\ub97c \uc5bb\uc73c\uba74\uc11c \ud55c\uad6d \ubb38\ud654\uc5d0 \uad00\uc2ec\uc744 \uac16\ub294 \uc0ac\ub78c\ub3c4 \ub9ce\uc544\uc84c\uc2b5\ub2c8\ub2e4. \uc774\ub7ec\ud55c \ud604\uc0c1\uc744 \ud55c\ub958\ub77c\uace0 \ubd80\ub974\uae30\ub3c4 \ud569\ub2c8\ub2e4.\n\n\ud55c\ub958\ub294 \ubb38\ud654 \ucf58\ud150\uce20\ubfd0\ub9cc \uc544\ub2c8\ub77c \ub2e4\ub978 \ubd84\uc57c\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud55c\uad6d \ub4dc\ub77c\ub9c8\ub098 \uc601\ud654\ub97c \ubcf8 \ud6c4 \ud55c\uad6d\uc5b4\ub97c \ubc30\uc6b0\uae30 \uc2dc\uc791\ud558\uac70\ub098 \ud55c\uad6d \uc74c\uc2dd\uc5d0 \uad00\uc2ec\uc744 \uac16\ub294 \uc0ac\ub78c\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ub610\ud55c \uc791\ud488\uc758 \ucd2c\uc601\uc9c0\ub97c \uc9c1\uc811 \ubc29\ubb38\ud558\ub294 \uad00\uad11\uac1d\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ud55c\ud3b8 \uc778\ud130\ub137\uc5d0\uc11c\ub294 \uc601\uc0c1, \uc74c\uc545, \uc0ac\uc9c4 \ub4f1 \ub2e4\uc591\ud55c \ucf58\ud150\uce20\ub97c \uc27d\uac8c \uacf5\uc720\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ub2e4\ub978 \uc0ac\ub78c\uc774 \ub9cc\ub4e0 \ucf58\ud150\uce20\ub97c \ud5c8\ub77d \uc5c6\uc774 \uc0ac\uc6a9\ud558\uac70\ub098 \ubd88\ubc95\uc73c\ub85c \ubcf5\uc81c\ud574\uc11c\ub294 \uc548 \ub429\ub2c8\ub2e4.\n\n\ub300\uc911\ubb38\ud654\ub97c \uc990\uae30\uba74\uc11c \ub2e4\ub978 \ubb38\ud654\ub3c4 \uc874\uc911\ud558\uace0 \uc800\uc791\uad8c\uc744 \uc9c0\ud0a4\ub294 \ud0dc\ub3c4\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.\n","V\u0103n h\xf3a \u0111\u1ea1i ch\xfang l\xe0 c\xe1c lo\u1ea1i h\xecnh v\u0103n h\xf3a nh\u01b0 \xe2m nh\u1ea1c, \u0111i\u1ec7n \u1ea3nh, phim truy\u1ec1n h\xecnh, ch\u01b0\u01a1ng tr\xecnh ph\xe1t s\xf3ng v\xe0 webtoon m\xe0 nhi\u1ec1u ng\u01b0\u1eddi c\xf3 th\u1ec3 d\u1ec5 d\xe0ng ti\u1ebfp c\u1eadn v\xe0 th\u01b0\u1edfng th\u1ee9c.\n\nV\u0103n h\xf3a \u0111\u1ea1i ch\xfang H\xe0n Qu\u1ed1c c\u0169ng \u0111\xe3 thay \u0111\u1ed5i \u0111a d\u1ea1ng theo s\u1ef1 ph\xe1t tri\u1ec3n c\u1ee7a th\u1eddi \u0111\u1ea1i v\xe0 c\xf4ng ngh\u1ec7. \u0110\u1eb7c bi\u1ec7t, c\xf9ng v\u1edbi s\u1ef1 ph\xe1t tri\u1ec3n c\u1ee7a Internet, \u0111i\u1ec7n tho\u1ea1i th\xf4ng minh v\xe0 m\u1ea1ng x\xe3 h\u1ed9i, ng\u01b0\u1eddi \u1edf n\u01b0\u1edbc ngo\xe0i c\u0169ng c\xf3 th\u1ec3 d\u1ec5 d\xe0ng ti\u1ebfp c\u1eadn n\u1ed9i dung v\u0103n h\xf3a H\xe0n Qu\u1ed1c.\n\nKhi \xe2m nh\u1ea1c, phim truy\u1ec1n h\xecnh v\xe0 \u0111i\u1ec7n \u1ea3nh H\xe0n Qu\u1ed1c \u0111\u01b0\u1ee3c y\xeau th\xedch \u1edf n\u01b0\u1edbc ngo\xe0i, s\u1ed1 ng\u01b0\u1eddi quan t\xe2m \u0111\u1ebfn v\u0103n h\xf3a H\xe0n Qu\u1ed1c c\u0169ng t\u0103ng l\xean. Hi\u1ec7n t\u01b0\u1ee3ng n\xe0y c\u0169ng \u0111\u01b0\u1ee3c g\u1ecdi l\xe0 Hallyu.\n\nHallyu c\xf3 th\u1ec3 \u1ea3nh h\u01b0\u1edfng kh\xf4ng ch\u1ec9 \u0111\u1ebfn n\u1ed9i dung v\u0103n h\xf3a m\xe0 c\xf2n \u0111\u1ebfn c\xe1c l\u0129nh v\u1ef1c kh\xe1c. C\xf3 ng\u01b0\u1eddi b\u1eaft \u0111\u1ea7u h\u1ecdc ti\u1ebfng H\xe0n ho\u1eb7c quan t\xe2m \u0111\u1ebfn m\xf3n \u0103n H\xe0n Qu\u1ed1c sau khi xem phim H\xe0n. C\u0169ng c\xf3 kh\xe1ch du l\u1ecbch tr\u1ef1c ti\u1ebfp \u0111\u1ebfn th\u0103m c\xe1c \u0111\u1ecba \u0111i\u1ec3m quay phim.\n\nTr\xean Internet, video, \xe2m nh\u1ea1c, h\xecnh \u1ea3nh v\xe0 nhi\u1ec1u n\u1ed9i dung kh\xe1c c\xf3 th\u1ec3 \u0111\u01b0\u1ee3c chia s\u1ebb d\u1ec5 d\xe0ng. Tuy nhi\xean kh\xf4ng \u0111\u01b0\u1ee3c s\u1eed d\u1ee5ng tr\xe1i ph\xe9p ho\u1eb7c sao ch\xe9p b\u1ea5t h\u1ee3p ph\xe1p n\u1ed9i dung do ng\u01b0\u1eddi kh\xe1c t\u1ea1o ra.\n\nKhi th\u01b0\u1edfng th\u1ee9c v\u0103n h\xf3a \u0111\u1ea1i ch\xfang, th\xe1i \u0111\u1ed9 t\xf4n tr\u1ecdng c\xe1c n\u1ec1n v\u0103n h\xf3a kh\xe1c v\xe0 t\xf4n tr\u1ecdng b\u1ea3n quy\u1ec1n l\xe0 r\u1ea5t quan tr\u1ecdng.\n","\ud55c\ub958\uc5d0 \ub300\ud574 \uc774\uc57c\uae30\ud558\uae30","\ubbfc\uc218: \uc548 \uc528\ub294 \ud55c\uad6d\uc5b4\ub97c \uc65c \ubc30\uc6b0\uae30 \uc2dc\uc791\ud588\uc5b4\uc694?\n\n\uc548: \ucc98\uc74c\uc5d0\ub294 \ud55c\uad6d \ub4dc\ub77c\ub9c8\ub97c \uc88b\uc544\ud574\uc11c \ubc30\uc6b0\uae30 \uc2dc\uc791\ud588\uc5b4\uc694.\n\n\ubbfc\uc218: \ud55c\uad6d \ub4dc\ub77c\ub9c8\ub97c \ub9ce\uc774 \ubd24\uc5b4\uc694?\n\n\uc548: \ub124. \ub4dc\ub77c\ub9c8\ub97c \ubcf4\ub2e4\uac00 \ud55c\uad6d \uc74c\uc2dd\uacfc \ubb38\ud654\uc5d0\ub3c4 \uad00\uc2ec\uc774 \uc0dd\uacbc\uc5b4\uc694.\n\n\ubbfc\uc218: \uc694\uc998\uc740 \ud574\uc678\uc5d0\uc11c\ub3c4 \ud55c\uad6d \ucf58\ud150\uce20\ub97c \uc27d\uac8c \ubcfc \uc218 \uc788\uc9c0\uc694.\n\n\uc548: \ub9de\uc544\uc694. SNS\ub098 \ub3d9\uc601\uc0c1 \uc11c\ube44\uc2a4\ub97c \ud1b5\ud574 \ubc14\ub85c \ubcfc \uc218 \uc788\uc5b4\uc694.\n\n\ubbfc\uc218: \uc88b\uc544\ud558\ub294 \ud55c\uad6d \ubb38\ud654\uac00 \ub610 \uc788\uc5b4\uc694?\n\n\uc548: \uc74c\uc545\ub3c4 \uc88b\uc544\ud558\uace0 \uc6f9\ud230\ub3c4 \uac00\ub054 \ubd10\uc694.\n\n\ubbfc\uc218: \ud55c\ub958\uac00 \uc815\ub9d0 \uc5ec\ub7ec \ubd84\uc57c\uc5d0 \uc601\ud5a5\uc744 \uc8fc\ub294 \uac83 \uac19\ub124\uc694.\n\n\uc548: \ub124. \uadf8\ub7f0\ub370 \uc778\ud130\ub137\uc5d0\uc11c \ucf58\ud150\uce20\ub97c \uc0ac\uc6a9\ud560 \ub54c \uc800\uc791\uad8c\ub3c4 \uc870\uc2ec\ud574\uc57c\uaca0\uc5b4\uc694.\n\n\ubbfc\uc218: \ub9de\uc544\uc694. \ubb38\ud654 \ucf58\ud150\uce20\ub97c \uc62c\ubc14\ub974\uac8c \uc774\uc6a9\ud558\ub294 \uac83\ub3c4 \uc911\uc694\ud574\uc694.\n","Minsu: V\xec sao An b\u1eaft \u0111\u1ea7u h\u1ecdc ti\u1ebfng H\xe0n?\n\nAn: Ban \u0111\u1ea7u t\xf4i th\xedch phim H\xe0n n\xean b\u1eaft \u0111\u1ea7u h\u1ecdc.\n\nMinsu: Anh xem nhi\u1ec1u phim H\xe0n \xe0?\n\nAn: V\xe2ng. Khi xem phim, t\xf4i c\u0169ng b\u1eaft \u0111\u1ea7u quan t\xe2m \u0111\u1ebfn \u0111\u1ed3 \u0103n v\xe0 v\u0103n h\xf3a H\xe0n Qu\u1ed1c.\n\nMinsu: Ng\xe0y nay \u1edf n\u01b0\u1edbc ngo\xe0i c\u0169ng c\xf3 th\u1ec3 d\u1ec5 d\xe0ng xem n\u1ed9i dung H\xe0n Qu\u1ed1c nh\u1ec9.\n\nAn: \u0110\xfang v\u1eady. C\xf3 th\u1ec3 xem ngay th\xf4ng qua m\u1ea1ng x\xe3 h\u1ed9i ho\u1eb7c d\u1ecbch v\u1ee5 video.\n\nMinsu: Anh c\xf2n th\xedch v\u0103n h\xf3a H\xe0n Qu\u1ed1c n\xe0o kh\xe1c kh\xf4ng?\n\nAn: T\xf4i c\u0169ng th\xedch \xe2m nh\u1ea1c v\xe0 th\u1ec9nh tho\u1ea3ng \u0111\u1ecdc webtoon.\n\nMinsu: C\xf3 v\u1ebb Hallyu th\u1eadt s\u1ef1 \u1ea3nh h\u01b0\u1edfng \u0111\u1ebfn nhi\u1ec1u l\u0129nh v\u1ef1c.\n\nAn: V\xe2ng. Nh\u01b0ng khi s\u1eed d\u1ee5ng n\u1ed9i dung tr\xean Internet c\u0169ng ph\u1ea3i ch\xfa \xfd \u0111\u1ebfn b\u1ea3n quy\u1ec1n.\n\nMinsu: \u0110\xfang v\u1eady. S\u1eed d\u1ee5ng n\u1ed9i dung v\u0103n h\xf3a \u0111\xfang c\xe1ch c\u0169ng r\u1ea5t quan tr\u1ecdng.\n",A.iXx,A.jiW,A.isp,A.iWq)
A.iR_=s(["Bi\u1ebft m\u1ed9t s\u1ed1 nh\xe2n v\u1eadt ti\xeau bi\u1ec3u c\u1ee7a phong tr\xe0o gi\xe0nh \u0111\u1ed9c l\u1eadp H\xe0n Qu\u1ed1c.","Hi\u1ec3u ho\u1ea1t \u0111\u1ed9ng c\u1ee7a \uc548\uc911\uadfc v\xe0 s\u1ef1 ki\u1ec7n t\u1ea1i Harbin n\u0103m 1909.","Bi\u1ebft \uc720\uad00\uc21c v\xe0 m\u1ed1i li\xean h\u1ec7 v\u1edbi phong tr\xe0o 3\xb71 \uc6b4\ub3d9.","Hi\u1ec3u vai tr\xf2 c\u1ee7a \uae40\uad6c trong \ub300\ud55c\ubbfc\uad6d \uc784\uc2dc\uc815\ubd80.","Bi\u1ebft \uc548\ucc3d\ud638 v\xe0 c\xe1c ho\u1ea1t \u0111\u1ed9ng gi\xe1o d\u1ee5c, t\u1ed5 ch\u1ee9c phong tr\xe0o \u0111\u1ed9c l\u1eadp.","Hi\u1ec3u ho\u1ea1t \u0111\u1ed9ng c\u1ee7a \uc724\ubd09\uae38 t\u1ea1i Th\u01b0\u1ee3ng H\u1ea3i n\u0103m 1932.","Bi\u1ebft c\xe1c phong tr\xe0o \u0111\u1ed9c l\u1eadp c\xf3 nhi\u1ec1u h\xecnh th\u1ee9c nh\u01b0 bi\u1ec3u t\xecnh, gi\xe1o d\u1ee5c, ngo\u1ea1i giao v\xe0 \u0111\u1ea5u tranh v\u0169 trang.","Luy\u1ec7n li\xean k\u1ebft t\xean nh\xe2n v\u1eadt v\u1edbi s\u1ef1 ki\u1ec7n v\xe0 th\xe0nh t\u1ef1u t\u01b0\u01a1ng \u1ee9ng."],t.s)
A.htg=s(["\uc77c\uc81c\uac15\uc810\uae30 \uc804\ud6c4 \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc774 \ud55c\uad6d\uc758 \ub3c5\ub9bd\uc744 \uc704\ud574 \ud65c\ub3d9\ud588\uc2b5\ub2c8\ub2e4.","\uc548\uc911\uadfc\uc740 1909\ub144 \uc911\uad6d \ud558\uc5bc\ube48\uc5d0\uc11c \uc774\ud1a0 \ud788\ub85c\ubd80\ubbf8\ub97c \uc800\uaca9\ud55c \ub3c5\ub9bd\uc6b4\ub3d9\uac00\uc785\ub2c8\ub2e4.","\uc720\uad00\uc21c\uc740 1919\ub144 3\xb71 \uc6b4\ub3d9\uacfc \uc544\uc6b0\ub0b4 \uc7a5\ud130 \ub9cc\uc138\uc6b4\ub3d9\uc5d0 \ucc38\uc5ec\ud55c \ub300\ud45c\uc801\uc778 \ub3c5\ub9bd\uc6b4\ub3d9\uac00\uc785\ub2c8\ub2e4.","\uae40\uad6c\ub294 \ub300\ud55c\ubbfc\uad6d \uc784\uc2dc\uc815\ubd80\uc5d0\uc11c \ud65c\ub3d9\ud55c \ub300\ud45c\uc801\uc778 \ub3c5\ub9bd\uc6b4\ub3d9 \uc9c0\ub3c4\uc790\uc785\ub2c8\ub2e4.","\uae40\uad6c\uc758 \ud638\ub294 \ubc31\ubc94\uc785\ub2c8\ub2e4.","\uc548\ucc3d\ud638\ub294 \uad50\uc721\uacfc \uc0ac\ud68c\uc6b4\ub3d9\uc744 \ud1b5\ud574 \ubbfc\uc871\uc758 \ud798\uc744 \ud0a4\uc6b0\ub824\uace0 \ub178\ub825\ud55c \ub3c5\ub9bd\uc6b4\ub3d9\uac00\uc785\ub2c8\ub2e4.","\uc548\ucc3d\ud638\ub294 \ud765\uc0ac\ub2e8\uc744 \uc870\uc9c1\ud558\uc5ec \uc778\uc7ac \uc591\uc131\uacfc \ub3c5\ub9bd\uc6b4\ub3d9\uc5d0 \ud798\uc37c\uc2b5\ub2c8\ub2e4.","\uc724\ubd09\uae38\uc740 1932\ub144 \uc911\uad6d \uc0c1\ud558\uc774 \ud6d9\ucee4\uc6b0\uacf5\uc6d0\uc5d0\uc11c \uc758\uac70\ub97c \uc77c\uc73c\ud0a8 \ub3c5\ub9bd\uc6b4\ub3d9\uac00\uc785\ub2c8\ub2e4.","\ud55c\uad6d\uc758 \ub3c5\ub9bd\uc6b4\ub3d9\uc740 \ub9cc\uc138\uc6b4\ub3d9, \uad50\uc721\uc6b4\ub3d9, \uc678\uad50\ud65c\ub3d9, \ubb34\uc7a5\ud22c\uc7c1 \ub4f1 \ub2e4\uc591\ud55c \ud615\ud0dc\ub85c \uc774\ub8e8\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.","\uc5ed\uc0ac \uc778\ubb3c\uc744 \uacf5\ubd80\ud560 \ub54c\uc5d0\ub294 \uc778\ubb3c, \uc0ac\uac74, \uc5f0\ub3c4, \uad00\ub828 \uc7a5\uc18c\ub97c \ud568\uaed8 \uc5f0\uacb0\ud558\uc5ec \uae30\uc5b5\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4."],t.s)
