A.fI0=new B.O("\ub192\uc740 \uad50\uc721\uc5f4\uc758 \uae0d\uc815\uc801\uc778 \uba74\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110\xe2u l\xe0 m\u1ed9t m\u1eb7t t\xedch c\u1ef1c c\u1ee7a vi\u1ec7c coi tr\u1ecdng gi\xe1o d\u1ee5c?",A.hNY,0,"Quan t\xe2m \u0111\u1ebfn gi\xe1o d\u1ee5c c\xf3 th\u1ec3 gi\xfap t\u0103ng c\xe1c c\u01a1 h\u1ed9i h\u1ecdc t\u1eadp.")
A.iFS=s(["\uc131\uc801\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc801\uc131\uacfc \uc9c4\ub85c\ub3c4 \uace0\ub824\ud55c\ub2e4.","\uc131\uc801\ub9cc \ubcf4\uace0 \ubaa8\ub4e0 \uac83\uc744 \uacb0\uc815\ud55c\ub2e4.","\uc544\uc774\uc640 \uc804\ud600 \ub300\ud654\ud558\uc9c0 \uc54a\ub294\ub2e4.","\ud56d\uc0c1 \ub2e4\ub978 \ud559\uc0dd\uacfc \ube44\uad50\ud55c\ub2e4."],t.s)
A.fDV=new B.O("\uc790\ub140\uc758 \uad50\uc721\uc744 \uc704\ud574 \ubc14\ub78c\uc9c1\ud55c \ud0dc\ub3c4\ub294 \ubb34\uc5c7\uc785\ub2c8\uae4c?","Th\xe1i \u0111\u1ed9 n\xe0o ph\xf9 h\u1ee3p \u0111\u1ed1i v\u1edbi vi\u1ec7c gi\xe1o d\u1ee5c con?",A.iFS,0,"N\xean c\xe2n nh\u1eafc c\u1ea3 \u0111i\u1ec3m s\u1ed1, n\u0103ng khi\u1ebfu v\xe0 \u0111\u1ecbnh h\u01b0\u1edbng c\u1ee7a tr\u1ebb.")
A.hnD=s(["\ud559\uc6d0 \uc218\uc5c5","\ud559\uad50 \uc815\uaddc \uc218\uc5c5","\ud559\uad50 \uc6b4\ub3d9\ud68c","\ud559\uad50 \uae09\uc2dd"],t.s)
A.fGw=new B.O("\ub2e4\uc74c \uc911 \uc0ac\uad50\uc721\uc5d0 \ud574\ub2f9\ud558\ub294 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110\xe2u l\xe0 m\u1ed9t h\xecnh th\u1ee9c gi\xe1o d\u1ee5c ngo\xe0i tr\u01b0\u1eddng?",A.hnD,0,"\ud559\uc6d0 \uc218\uc5c5 l\xe0 m\u1ed9t h\xecnh th\u1ee9c \uc0ac\uad50\uc721.")
A.hcz=s(["\uc131\uc801\ub9cc \uc911\uc694\ud558\uace0 \uc801\uc131\uc740 \uc911\uc694\ud558\uc9c0 \uc54a\ub2e4.","\uad50\uc721\uc5d0 \ub300\ud55c \ub192\uc740 \uad00\uc2ec\uc740 \ud56d\uc0c1 \ub098\uc05c \uacb0\uacfc\ub9cc \ub9cc\ub4e0\ub2e4.","\uc9c0\ub098\uce5c \uacbd\uc7c1\uc740 \ud559\uc0dd\uc5d0\uac8c \uc2a4\ud2b8\ub808\uc2a4\ub97c \uc904 \uc218 \uc788\ub2e4.","\ud55c\uad6d\uc5d0\ub294 \uc0ac\uad50\uc721\uc774 \uc5c6\ub2e4."],t.s)
A.fDr=new B.O("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.hcz,2,"B\xe0i \u0111\u1ecdc n\xf3i r\u1eb1ng c\u1ea1nh tranh qu\xe1 m\u1ee9c c\xf3 th\u1ec3 g\xe2y \xe1p l\u1ef1c v\xe0 c\u0103ng th\u1eb3ng cho h\u1ecdc sinh.")
A.iJj=s([A.fD_,A.fBn,A.fFf,A.fHk,A.fCw,A.fFk,A.fI0,A.fDV,A.fGw,A.fDr],t.h)
A.je4=s(["\uad50\uc721\uc5f4 = s\u1ef1 coi tr\u1ecdng v\xe0 quan t\xe2m cao \u0111\u1ebfn gi\xe1o d\u1ee5c.",u.bH,"\uc0ac\uad50\uc721 = gi\xe1o d\u1ee5c ngo\xe0i tr\u01b0\u1eddng.","\ud559\uc6d0 = trung t\xe2m h\u1ecdc th\xeam.","\uacfc\uc678 = h\u1ecdc gia s\u01b0 ri\xeang.","\uc131\uc801 = \u0111i\u1ec3m s\u1ed1/th\xe0nh t\xedch.","\uc785\uc2dc = tuy\u1ec3n sinh.","\uc801\uc131 = n\u0103ng khi\u1ebfu v\xe0 kh\u1ea3 n\u0103ng ph\xf9 h\u1ee3p.","\uc9c4\ub85c = \u0111\u1ecbnh h\u01b0\u1edbng t\u01b0\u01a1ng lai.","Gi\xe1o d\u1ee5c c\xf3 th\u1ec3 t\u1ea1o th\xeam c\u01a1 h\u1ed9i h\u1ecdc t\u1eadp.","C\u1ea1nh tranh qu\xe1 m\u1ee9c c\xf3 th\u1ec3 g\xe2y \ubd80\ub2f4 v\xe0 \uc2a4\ud2b8\ub808\uc2a4.","\uc131\uc801\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc801\uc131\uacfc \uc9c4\ub85c\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4."],t.s)
A.fAE=new B.dJ(11,"\uc0ac\ud68c 2","\ud55c\uad6d\uc758 \uad50\uc721\uc5f4","S\u1ef1 coi tr\u1ecdng gi\xe1o d\u1ee5c \u1edf H\xe0n Qu\u1ed1c",A.hZb,A.iPU,A.iWe,A.jDN,"\ud55c\uad6d \uc0ac\ud68c\uc758 \uad50\uc721\uc5f4","\ud55c\uad6d \uc0ac\ud68c\uc5d0\uc11c\ub294 \uad50\uc721\uc744 \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud558\ub294 \uc0ac\ub78c\uc774 \ub9ce\uc2b5\ub2c8\ub2e4. \uc774\ub7ec\ud55c \ub192\uc740 \uad00\uc2ec\uc744 \ud754\ud788 \uad50\uc721\uc5f4\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4.\n\n\ub9ce\uc740 \ubd80\ubaa8\ub294 \uc790\ub140\uac00 \uc88b\uc740 \uad50\uc721\uc744 \ubc1b\uace0 \uc790\uc2e0\uc758 \ub2a5\ub825\uc744 \ubc1c\uc804\uc2dc\ud0a4\uae30\ub97c \ubc14\ub78d\ub2c8\ub2e4. \uadf8\ub798\uc11c \ud559\uad50\uc0dd\ud65c\uacfc \uc131\uc801, \uc9c4\ub85c \ub4f1\uc5d0 \uad00\uc2ec\uc744 \uac00\uc9c0\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.\n\n\ud559\uad50\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c0\ub294 \uad50\uc721\uc744 \uacf5\uad50\uc721\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4. \ud55c\ud3b8 \ud559\uc6d0\uc774\ub098 \uac1c\uc778 \uacfc\uc678\ucc98\ub7fc \ud559\uad50 \ubc16\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c0\ub294 \uad50\uc721\uc744 \uc0ac\uad50\uc721\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4.\n\n\uad50\uc721\uc5d0 \ub300\ud55c \ub192\uc740 \uad00\uc2ec\uc740 \ud559\uc0dd\uc5d0\uac8c \ub2e4\uc591\ud55c \ud559\uc2b5 \uae30\ud68c\ub97c \uc81c\uacf5\ud55c\ub2e4\ub294 \uc7a5\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uadf8\ub7ec\ub098 \uc9c0\ub098\uce5c \uacbd\uc7c1\uc774\ub098 \uc131\uc801\uc5d0 \ub300\ud55c \ubd80\ub2f4\uc740 \ud559\uc0dd\uc5d0\uac8c \uc2a4\ud2b8\ub808\uc2a4\ub97c \uc904 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ub530\ub77c\uc11c \uc131\uc801\ub9cc \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud558\uae30\ubcf4\ub2e4 \ud559\uc0dd\uc758 \uc801\uc131, \uad00\uc2ec, \uc9c4\ub85c\ub97c \ud568\uaed8 \uace0\ub824\ud558\ub294 \uac83\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.\n\n\ud559\uc0dd\uc774 \uac74\uac15\ud558\uac8c \uc131\uc7a5\ud558\uba74\uc11c \uc790\uc2e0\uc758 \ub2a5\ub825\uc744 \ubc1c\uc804\uc2dc\ud0ac \uc218 \uc788\ub3c4\ub85d \uac00\uc815\uacfc \ud559\uad50\uac00 \ud568\uaed8 \ub178\ub825\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.\n","Trong x\xe3 h\u1ed9i H\xe0n Qu\u1ed1c c\xf3 nhi\u1ec1u ng\u01b0\u1eddi coi gi\xe1o d\u1ee5c l\xe0 \u0111i\u1ec1u quan tr\u1ecdng. S\u1ef1 quan t\xe2m m\u1ea1nh m\u1ebd n\xe0y th\u01b0\u1eddng \u0111\u01b0\u1ee3c g\u1ecdi l\xe0 gi\xe1o d\u1ee5c nhi\u1ec7t, t\u1ee9c \uad50\uc721\uc5f4.\n\nNhi\u1ec1u cha m\u1eb9 mong mu\u1ed1n con m\xecnh nh\u1eadn \u0111\u01b0\u1ee3c n\u1ec1n gi\xe1o d\u1ee5c t\u1ed1t v\xe0 ph\xe1t tri\u1ec3n n\u0103ng l\u1ef1c c\u1ee7a b\u1ea3n th\xe2n. V\xec v\u1eady h\u1ecd th\u01b0\u1eddng quan t\xe2m \u0111\u1ebfn \u0111\u1eddi s\u1ed1ng tr\u01b0\u1eddng h\u1ecdc, th\xe0nh t\xedch v\xe0 \u0111\u1ecbnh h\u01b0\u1edbng t\u01b0\u01a1ng lai c\u1ee7a con.\n\nGi\xe1o d\u1ee5c \u0111\u01b0\u1ee3c th\u1ef1c hi\u1ec7n trong tr\u01b0\u1eddng h\u1ecdc \u0111\u01b0\u1ee3c g\u1ecdi l\xe0 gi\xe1o d\u1ee5c c\xf4ng. Trong khi \u0111\xf3, vi\u1ec7c h\u1ecdc \u1edf trung t\xe2m ho\u1eb7c h\u1ecdc gia s\u01b0 ri\xeang ngo\xe0i tr\u01b0\u1eddng \u0111\u01b0\u1ee3c g\u1ecdi l\xe0 gi\xe1o d\u1ee5c t\u01b0.\n\nS\u1ef1 quan t\xe2m cao \u0111\u1ed1i v\u1edbi gi\xe1o d\u1ee5c c\xf3 \u01b0u \u0111i\u1ec3m l\xe0 t\u1ea1o ra nhi\u1ec1u c\u01a1 h\u1ed9i h\u1ecdc t\u1eadp cho h\u1ecdc sinh.\n\nTuy nhi\xean, c\u1ea1nh tranh qu\xe1 m\u1ee9c ho\u1eb7c \xe1p l\u1ef1c v\u1ec1 \u0111i\u1ec3m s\u1ed1 c\u0169ng c\xf3 th\u1ec3 g\xe2y c\u0103ng th\u1eb3ng cho h\u1ecdc sinh.\n\nV\xec v\u1eady, thay v\xec ch\u1ec9 coi tr\u1ecdng \u0111i\u1ec3m s\u1ed1, c\u1ea7n xem x\xe9t c\u1ea3 n\u0103ng khi\u1ebfu, s\u1edf th\xedch v\xe0 \u0111\u1ecbnh h\u01b0\u1edbng t\u01b0\u01a1ng lai c\u1ee7a h\u1ecdc sinh.\n\n\u0110i\u1ec1u quan tr\u1ecdng l\xe0 gia \u0111\xecnh v\xe0 nh\xe0 tr\u01b0\u1eddng c\xf9ng n\u1ed7 l\u1ef1c \u0111\u1ec3 h\u1ecdc sinh c\xf3 th\u1ec3 ph\xe1t tri\u1ec3n n\u0103ng l\u1ef1c trong khi v\u1eabn tr\u01b0\u1edfng th\xe0nh m\u1ed9t c\xe1ch kh\u1ecfe m\u1ea1nh.\n","\uc544\uc774\uc758 \uc9c4\ub85c\uc5d0 \ub300\ud574 \uc0c1\ub2f4\ud558\uae30","\ud559\ubd80\ubaa8: \uc120\uc0dd\ub2d8, \uc544\uc774\uc758 \uc131\uc801\uc774 \uc870\uae08 \ub5a8\uc5b4\uc838\uc11c \uac71\uc815\uc774\uc5d0\uc694.\n\n\uad50\uc0ac: \ucd5c\uadfc\uc5d0 \uacf5\ubd80 \ub54c\ubb38\uc5d0 \uc2a4\ud2b8\ub808\uc2a4\ub97c \ub9ce\uc774 \ubc1b\ub294 \uac83 \uac19\uc544\uc694.\n\n\ud559\ubd80\ubaa8: \ud559\uc6d0\uc744 \ub354 \ubcf4\ub0b4\uc57c \ud560\uae4c\uc694?\n\n\uad50\uc0ac: \uacf5\ubd80 \uc2dc\uac04\uc744 \ub298\ub9ac\ub294 \uac83\ub9cc\uc774 \ud574\uacb0 \ubc29\ubc95\uc740 \uc544\ub2d0 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ud559\ubd80\ubaa8: \uadf8\ub7ec\uba74 \uc5b4\ub5bb\uac8c \ud558\ub294 \uac83\uc774 \uc88b\uc744\uae4c\uc694?\n\n\uad50\uc0ac: \uba3c\uc800 \uc544\uc774\uac00 \uc5b4\ub5a4 \uacfc\ubaa9\uc5d0 \uad00\uc2ec\uc774 \uc788\uace0 \uc5b4\ub5a4 \uc801\uc131\uc774 \uc788\ub294\uc9c0 \uc54c\uc544\ubcf4\ub294 \uac83\uc774 \uc88b\uaca0\uc2b5\ub2c8\ub2e4.\n\n\ud559\ubd80\ubaa8: \uc131\uc801\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc801\uc131\uacfc \uc9c4\ub85c\ub3c4 \ubd10\uc57c\uaca0\ub124\uc694.\n\n\uad50\uc0ac: \ub124. \uc544\uc774\uc640 \ucda9\ubd84\ud788 \ub300\ud654\ud558\uba74\uc11c \ud568\uaed8 \uc9c4\ub85c\ub97c \uc0dd\uac01\ud574 \uc8fc\uc138\uc694.\n\n\ud559\ubd80\ubaa8: \uc54c\uaca0\uc2b5\ub2c8\ub2e4. \uc544\uc774\uc640 \uba3c\uc800 \uc774\uc57c\uae30\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4.\n\n\uad50\uc0ac: \ud559\uc0dd\uc774 \ub108\ubb34 \ud070 \ubd80\ub2f4\uc744 \ub290\ub07c\uc9c0 \uc54a\ub3c4\ub85d \ub3c4\uc640\uc8fc\ub294 \uac83\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4.\n","Ph\u1ee5 huynh: Th\u1ea7y/c\xf4, g\u1ea7n \u0111\xe2y \u0111i\u1ec3m c\u1ee7a ch\xe1u h\u01a1i gi\u1ea3m n\xean t\xf4i lo.\n\nGi\xe1o vi\xean: G\u1ea7n \u0111\xe2y c\xf3 v\u1ebb ch\xe1u \u0111ang b\u1ecb kh\xe1 nhi\u1ec1u c\u0103ng th\u1eb3ng v\xec vi\u1ec7c h\u1ecdc.\n\nPh\u1ee5 huynh: T\xf4i c\xf3 n\xean cho ch\xe1u h\u1ecdc th\xeam nhi\u1ec1u h\u01a1n kh\xf4ng?\n\nGi\xe1o vi\xean: Ch\u1ec9 t\u0103ng th\u1eddi gian h\u1ecdc ch\u01b0a ch\u1eafc \u0111\xe3 l\xe0 c\xe1ch gi\u1ea3i quy\u1ebft.\n\nPh\u1ee5 huynh: V\u1eady t\xf4i n\xean l\xe0m th\u1ebf n\xe0o?\n\nGi\xe1o vi\xean: Tr\u01b0\u1edbc ti\xean n\xean t\xecm hi\u1ec3u ch\xe1u quan t\xe2m \u0111\u1ebfn m\xf4n n\xe0o v\xe0 c\xf3 n\u0103ng khi\u1ebfu g\xec.\n\nPh\u1ee5 huynh: V\u1eady kh\xf4ng ch\u1ec9 \u0111i\u1ec3m s\u1ed1 m\xe0 c\xf2n ph\u1ea3i xem n\u0103ng khi\u1ebfu v\xe0 \u0111\u1ecbnh h\u01b0\u1edbng n\u1eefa.\n\nGi\xe1o vi\xean: \u0110\xfang v\u1eady. H\xe3y tr\xf2 chuy\u1ec7n \u0111\u1ea7y \u0111\u1ee7 v\u1edbi ch\xe1u v\xe0 c\xf9ng suy ngh\u0129 v\u1ec1 t\u01b0\u01a1ng lai.\n\nPh\u1ee5 huynh: T\xf4i hi\u1ec3u r\u1ed3i. Tr\u01b0\u1edbc ti\xean t\xf4i s\u1ebd n\xf3i chuy\u1ec7n v\u1edbi ch\xe1u.\n\nGi\xe1o vi\xean: Gi\xfap h\u1ecdc sinh kh\xf4ng c\u1ea3m th\u1ea5y \xe1p l\u1ef1c qu\xe1 l\u1edbn c\u0169ng r\u1ea5t quan tr\u1ecdng.\n",A.j09,A.h9w,A.iJj,A.je4)
A.iWF=s(["Hi\u1ec3u \xfd ngh\u0129a c\u1ee7a vi\u1ec7c \u0111\u1ecbnh c\u01b0 \u1ed5n \u0111\u1ecbnh trong x\xe3 h\u1ed9i H\xe0n Qu\u1ed1c.","Bi\u1ebft vai tr\xf2 c\u1ee7a vi\u1ec7c h\u1ecdc ti\u1ebfng H\xe0n v\xe0 hi\u1ec3u v\u0103n h\xf3a H\xe0n Qu\u1ed1c.","Bi\u1ebft m\u1ed9t s\u1ed1 c\u01a1 quan v\xe0 ch\u01b0\u01a1ng tr\xecnh c\xf3 th\u1ec3 h\u1ed7 tr\u1ee3 ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i.","Hi\u1ec3u \xfd ngh\u0129a c\u1ee7a \uc9c0\uc5ed\uc0ac\ud68c \ucc38\uc5ec.","Bi\u1ebft c\xe1c h\xecnh th\u1ee9c tham gia nh\u01b0 t\xecnh nguy\u1ec7n, giao l\u01b0u v\xe0 ho\u1ea1t \u0111\u1ed9ng c\u1ed9ng \u0111\u1ed3ng.","Hi\u1ec3u t\u1ea7m quan tr\u1ecdng c\u1ee7a giao ti\u1ebfp v\xe0 t\xf4n tr\u1ecdng s\u1ef1 kh\xe1c bi\u1ec7t.","Luy\u1ec7n \u0111\u1ecdc hi\u1ec3u v\xe0 c\xe2u h\u1ecfi th\u1ef1c t\u1ebf v\u1ec1 \u0111\u1eddi s\u1ed1ng \u0111\u1ecbnh c\u01b0 t\u1ea1i H\xe0n Qu\u1ed1c."],t.s)
A.iRW=s(["\uc678\uad6d\uc778\uc774 \ud55c\uad6d \uc0ac\ud68c\uc5d0 \uc548\uc815\uc801\uc73c\ub85c \uc815\ucc29\ud558\ub824\uba74 \uc5b8\uc5b4, \uc0dd\ud65c\uc815\ubcf4, \ubc95\uacfc \uc81c\ub3c4 \ub4f1\uc744 \uc774\ud574\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\ud55c\uad6d\uc5b4 \ub2a5\ub825\uc740 \uc9c1\uc7a5\uc0dd\ud65c\uacfc \uc77c\uc0c1\uc0dd\ud65c, \uc9c0\uc5ed\uc0ac\ud68c \ucc38\uc5ec\uc5d0 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.","\uc678\uad6d\uc778\uc744 \uc704\ud55c \uc0c1\ub2f4\uae30\uad00\uc774\ub098 \uc9c0\uc6d0\uc13c\ud130\uc5d0\uc11c\ub294 \uc0dd\ud65c, \uad50\uc721, \ucde8\uc5c5 \ub4f1\uc5d0 \uad00\ud55c \uc815\ubcf4\ub97c \uc81c\uacf5\ud558\uae30\ub3c4 \ud569\ub2c8\ub2e4.","\uc9c0\uc5ed\uc0ac\ud68c \ud65c\ub3d9\uc5d0 \ucc38\uc5ec\ud558\uba74 \uc774\uc6c3\uacfc \uad00\uacc4\ub97c \ub9cc\ub4e4\uace0 \ud55c\uad6d \uc0ac\ud68c\ub97c \ub354 \uc798 \uc774\ud574\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ubd09\uc0ac\ud65c\ub3d9, \uc8fc\ubbfc \ud589\uc0ac, \ubb38\ud654\uad50\ub958 \ud504\ub85c\uadf8\ub7a8 \ub4f1\uc740 \uc9c0\uc5ed\uc0ac\ud68c \ucc38\uc5ec\uc758 \ud55c \ubc29\ubc95\uc774 \ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ub2e4\ub978 \ubb38\ud654\uc640 \uc0dd\ud65c\ubc29\uc2dd\uc744 \uc11c\ub85c \uc874\uc911\ud558\ub294 \ud0dc\ub3c4\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc5b4\ub824\uc6c0\uc774 \uc788\uc744 \ub54c \ud63c\uc790 \ud574\uacb0\ud558\uae30\ubcf4\ub2e4 \uad00\ub828 \uae30\uad00\uc774\ub098 \uc8fc\ubcc0 \uc0ac\ub78c\uc5d0\uac8c \ub3c4\uc6c0\uc744 \uc694\uccad\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc0ac\ud68c \ucc38\uc5ec\ub294 \uc790\uc2e0\uc758 \uad8c\ub9ac\ubfd0 \uc544\ub2c8\ub77c \uacf5\ub3d9\uccb4\uc758 \ucc45\uc784\ub3c4 \ud568\uaed8 \uc0dd\uac01\ud558\ub294 \uacfc\uc815\uc785\ub2c8\ub2e4."],t.s)
