A.j5n=s(["\uc815\ucc29 = \u1ed5n \u0111\u1ecbnh cu\u1ed9c s\u1ed1ng/\u0111\u1ecbnh c\u01b0; \uc801\uc751 = th\xedch nghi v\u1edbi m\xf4i tr\u01b0\u1eddng m\u1edbi.","\uc9c0\uc5ed\uc0ac\ud68c = c\u1ed9ng \u0111\u1ed3ng \u0111\u1ecba ph\u01b0\u01a1ng; \uacf5\ub3d9\uccb4 l\xe0 kh\xe1i ni\u1ec7m r\u1ed9ng v\u1ec1 c\u1ed9ng \u0111\u1ed3ng.","\ucc38\uc5ec\ud558\ub2e4 = tham gia; \uc9c0\uc6d0\ud558\ub2e4 c\xf3 th\u1ec3 mang ngh\u0129a h\u1ed7 tr\u1ee3 ho\u1eb7c \u1ee9ng tuy\u1ec3n t\xf9y ng\u1eef c\u1ea3nh.","\ubd09\uc0ac\ud65c\ub3d9 = ho\u1ea1t \u0111\u1ed9ng t\xecnh nguy\u1ec7n.","\uc0c1\ub2f4 = nh\u1eadn t\u01b0 v\u1ea5n; \ubb38\uc758 = h\u1ecfi ho\u1eb7c li\xean h\u1ec7 \u0111\u1ec3 l\u1ea5y th\xf4ng tin.","\uc0ac\ud68c \ucc38\uc5ec kh\xf4ng ch\u1ec9 l\xe0 ho\u1ea1t \u0111\u1ed9ng ch\xednh tr\u1ecb m\xe0 c\xf2n c\xf3 ho\u1ea1t \u0111\u1ed9ng c\u1ed9ng \u0111\u1ed3ng, t\xecnh nguy\u1ec7n v\xe0 giao l\u01b0u.","\ub2e4\ubb38\ud654 \uc0ac\ud68c\uc5d0\uc11c\ub294 \uc11c\ub85c \ub2e4\ub978 \ubb38\ud654\ub97c \uc874\uc911\ud558\ub294 \ud0dc\ub3c4\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc5b4\ub824\uc6c0\uc774 \uc788\uc744 \ub54c\uc5d0\ub294 \uc815\ud655\ud55c \uc815\ubcf4\ub97c \uc5bb\uae30 \uc704\ud574 \uad00\ub828 \uae30\uad00\uc5d0 \ubb38\uc758\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4."],t.s)
A.hBs=s(["\uc815\ucc29 \u2192 \u1ed5n \u0111\u1ecbnh cu\u1ed9c s\u1ed1ng trong x\xe3 h\u1ed9i.","\uc801\uc751 \u2192 th\xedch nghi.","\uc9c0\uc5ed\uc0ac\ud68c \u2192 c\u1ed9ng \u0111\u1ed3ng \u0111\u1ecba ph\u01b0\u01a1ng.","\uc0ac\ud68c \ucc38\uc5ec \u2192 tham gia c\xe1c ho\u1ea1t \u0111\u1ed9ng x\xe3 h\u1ed9i.","\ubd09\uc0ac\ud65c\ub3d9 \u2192 ho\u1ea1t \u0111\u1ed9ng t\xecnh nguy\u1ec7n.","\ubb38\ud654\uad50\ub958 \u2192 giao l\u01b0u v\u0103n h\xf3a.","\ud55c\uad6d\uc5b4 \ub2a5\ub825\uc740 \uc0dd\ud65c\uacfc \uc9c1\uc7a5, \uc0ac\ud68c \ucc38\uc5ec\uc5d0 \ub3c4\uc6c0\uc774 \ub41c\ub2e4.","\uc9c0\uc6d0\uc13c\ud130\uc640 \uc0c1\ub2f4\uae30\uad00\uc744 \ud1b5\ud574 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \uc5bb\uc744 \uc218 \uc788\ub2e4.","\uc9c0\uc5ed\uc0ac\ud68c \ud65c\ub3d9\uc5d0 \ucc38\uc5ec\ud558\uba74 \uc774\uc6c3\uacfc \uc18c\ud1b5\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4.","\ub2e4\ub978 \ubb38\ud654\uc640 \uc0dd\ud65c\ubc29\uc2dd\uc744 \uc874\uc911\ud558\ub294 \ud0dc\ub3c4\uac00 \uc911\uc694\ud558\ub2e4.","\uc815\ucc29\uc740 \ub2e8\uc21c\ud788 \uc624\ub798 \uac70\uc8fc\ud558\ub294 \uac83\ubfd0 \uc544\ub2c8\ub77c \uacf5\ub3d9\uccb4\uc640 \uc18c\ud1b5\ud558\uba70 \uc0b4\uc544\uac00\ub294 \uacfc\uc815\uc774\ub2e4."],t.s)
A.i4R=s(["\ud55c\uad6d\uc5b4\uc640 \uc0dd\ud65c\uc815\ubcf4\ub97c \ubc30\uc6b4\ub2e4.","\ud544\uc694\ud55c \uc815\ubcf4\ub97c \uc804\ud600 \ucc3e\uc9c0 \uc54a\ub294\ub2e4.","\uc8fc\ubcc0 \uc0ac\ub78c\uacfc \ub300\ud654\ud558\uc9c0 \uc54a\ub294\ub2e4.","\ubaa8\ub4e0 \uc9c0\uc5ed \ud65c\ub3d9\uc744 \ud53c\ud55c\ub2e4."],t.s)
A.fFY=new B.O("\uc678\uad6d\uc778\uc774 \ud55c\uad6d \uc0ac\ud68c\uc5d0 \uc815\ucc29\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub418\ub294 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110i\u1ec1u g\xec gi\xfap ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i \u1ed5n \u0111\u1ecbnh cu\u1ed9c s\u1ed1ng trong x\xe3 h\u1ed9i H\xe0n Qu\u1ed1c?",A.i4R,0,"H\u1ecdc ti\u1ebfng H\xe0n v\xe0 t\xecm hi\u1ec3u th\xf4ng tin \u0111\u1eddi s\u1ed1ng gi\xfap \xedch cho qu\xe1 tr\xecnh \u0111\u1ecbnh c\u01b0.")
A.iiJ=s(["\uc9c0\uc5ed \ubd09\uc0ac\ud65c\ub3d9\uc5d0 \ucc38\uc5ec\ud55c\ub2e4.","\ubaa8\ub4e0 \uc774\uc6c3\uacfc \uad00\uacc4\ub97c \ub04a\ub294\ub2e4.","\uc0dd\ud65c\uc815\ubcf4\ub97c \ud655\uc778\ud558\uc9c0 \uc54a\ub294\ub2e4.","\uc9c0\uc5ed \ud589\uc0ac\ub97c \ubb34\uc870\uac74 \ud53c\ud55c\ub2e4."],t.s)
A.fFc=new B.O("\uc9c0\uc5ed\uc0ac\ud68c \ucc38\uc5ec\uc758 \uc608\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110\xe2u l\xe0 v\xed d\u1ee5 ph\xf9 h\u1ee3p v\u1ec1 tham gia c\u1ed9ng \u0111\u1ed3ng \u0111\u1ecba ph\u01b0\u01a1ng?",A.iiJ,0,"Tham gia t\xecnh nguy\u1ec7n \u0111\u1ecba ph\u01b0\u01a1ng l\xe0 m\u1ed9t h\xecnh th\u1ee9c tham gia c\u1ed9ng \u0111\u1ed3ng.")
A.hy3=s(["\uad00\ub828 \uc9c0\uc6d0\uc13c\ud130\uc640 \uacf5\uacf5\uae30\uad00","\uadfc\uac70\uac00 \uc5c6\ub294 \uc18c\ubb38\ub9cc","\ubaa8\ub974\ub294 \uc0ac\ub78c\uc758 \uba54\uc2dc\uc9c0\ub9cc","\uc544\ubb34 \uc815\ubcf4\ub3c4 \uc5c6\ub294 \uacf3"],t.s)
A.fH7=new B.O("\ud55c\uad6d \uc0dd\ud65c\uc5d0 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \uc5bb\uc744 \uc218 \uc788\ub294 \uacf3\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740?","N\u01a1i n\xe0o ph\xf9 h\u1ee3p \u0111\u1ec3 nh\u1eadn th\xf4ng tin c\u1ea7n thi\u1ebft cho cu\u1ed9c s\u1ed1ng t\u1ea1i H\xe0n Qu\u1ed1c?",A.hy3,0,"C\xf3 th\u1ec3 t\xecm th\xf4ng tin t\u1eeb c\xe1c trung t\xe2m h\u1ed7 tr\u1ee3 v\xe0 c\u01a1 quan c\xf4ng li\xean quan.")
A.jAE=s(["\ub2e4\ub978 \uc0ac\ub78c\uc774\ub098 \uc9c0\uc5ed\uc0ac\ud68c\ub97c \ub3d5\ub294 \ud65c\ub3d9","\ubb3c\uac74\uc744 \uc218\uc785\ud558\ub294 \ud65c\ub3d9","\uc740\ud589\uc5d0\uc11c \ub3c8\uc744 \ube4c\ub9ac\ub294 \ud65c\ub3d9","\ud68c\uc0ac\uc5d0 \uc9c0\uc6d0\ud558\ub294 \ud65c\ub3d9"],t.s)
A.fGK=new B.O("\ubd09\uc0ac\ud65c\ub3d9\uc758 \ub73b\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\ubd09\uc0ac\ud65c\ub3d9 c\xf3 ngh\u0129a l\xe0 g\xec?",A.jAE,0,"\ubd09\uc0ac\ud65c\ub3d9 = ho\u1ea1t \u0111\u1ed9ng t\xecnh nguy\u1ec7n gi\xfap \u0111\u1ee1 ng\u01b0\u1eddi kh\xe1c ho\u1eb7c c\u1ed9ng \u0111\u1ed3ng.")
A.hls=s(["\uc11c\ub85c\uc758 \ubb38\ud654\ub97c \uc774\ud574\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4.","\ub2e4\ub978 \ubb38\ud654\ub97c \ubb34\uc2dc\ud558\uac8c \ub41c\ub2e4.","\uc0ac\ub78c\ub4e4 \uc0ac\uc774\uc758 \uc18c\ud1b5\uc744 \uc904\uc778\ub2e4.","\ubaa8\ub4e0 \ubb38\ud654\uac00 \uac19\ub2e4\uace0 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4."],t.s)
A.fCz=new B.O("\ubb38\ud654\uad50\ub958\uc758 \uc7a5\uc810\uc73c\ub85c \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110\xe2u l\xe0 l\u1ee3i \xedch c\u1ee7a giao l\u01b0u v\u0103n h\xf3a?",A.hls,0,"Giao l\u01b0u v\u0103n h\xf3a gi\xfap hi\u1ec3u v\u0103n h\xf3a c\u1ee7a nhau.")
A.iAE=s(["\uc11c\ub85c \ub2e4\ub978 \ubb38\ud654\ub97c \uc874\uc911\ud55c\ub2e4.","\uc790\uc2e0\uc758 \ubb38\ud654\ub9cc \uc633\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4.","\ub2e4\ub978 \uc0ac\ub78c\uc758 \uc0dd\ud65c\ubc29\uc2dd\uc744 \ubb34\uc870\uac74 \ube44\ub09c\ud55c\ub2e4.","\ub2e4\ub978 \ubb38\ud654\uc640 \ub300\ud654\ud558\uc9c0 \uc54a\ub294\ub2e4."],t.s)
