A.j20=s(["\uc9c1\uc7a5\uc0dd\ud65c\uacfc \uc77c\uc0c1\uc0dd\ud65c","\uc544\ubb34 \ubd84\uc57c\uc5d0\ub3c4 \ub3c4\uc6c0\uc774 \ub418\uc9c0 \uc54a\ub294\ub2e4.","\ud55c\uad6d \ubc16\uc5d0\uc11c\ub9cc \ud544\uc694\ud558\ub2e4.","\uc5ec\ud589\ud560 \ub54c\ub9cc \ud544\uc694\ud558\ub2e4."],t.s)
A.fD5=new B.O("\ud55c\uad6d\uc5b4 \ub2a5\ub825\uc774 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\ub294 \ubd84\uc57c\ub85c \uc54c\ub9de\uc740 \uac83\uc740?","Kh\u1ea3 n\u0103ng ti\u1ebfng H\xe0n c\xf3 th\u1ec3 gi\xfap \xedch trong l\u0129nh v\u1ef1c n\xe0o?",A.j20,0,"Ti\u1ebfng H\xe0n c\xf3 \xedch cho c\xf4ng vi\u1ec7c, \u0111\u1eddi s\u1ed1ng v\xe0 tham gia c\u1ed9ng \u0111\u1ed3ng.")
A.hlP=s(["\uad00\ub828 \uae30\uad00\uc5d0 \uc0c1\ub2f4\ud558\uac70\ub098 \ub3c4\uc6c0\uc744 \uc694\uccad\ud55c\ub2e4.","\ud56d\uc0c1 \ud63c\uc790 \ud574\uacb0\ud574\uc57c \ud55c\ub2e4.","\uc815\ud655\ud55c \uc815\ubcf4\ub97c \ud655\uc778\ud558\uc9c0 \uc54a\ub294\ub2e4.","\ubb38\uc81c\ub97c \uacc4\uc18d \ubb34\uc2dc\ud55c\ub2e4."],t.s)
A.fFg=new B.O("\ud55c\uad6d \uc0dd\ud65c \uc911 \uc5b4\ub824\uc6c0\uc774 \uc0dd\uacbc\uc744 \ub54c \ubc14\ub78c\uc9c1\ud55c \ud589\ub3d9\uc740?","Khi g\u1eb7p kh\xf3 kh\u0103n trong cu\u1ed9c s\u1ed1ng \u1edf H\xe0n Qu\u1ed1c, h\xe0nh \u0111\u1ed9ng ph\xf9 h\u1ee3p l\xe0 g\xec?",A.hlP,0,"C\xf3 th\u1ec3 y\xeau c\u1ea7u t\u01b0 v\u1ea5n ho\u1eb7c h\u1ed7 tr\u1ee3 t\u1eeb c\xe1c c\u01a1 quan li\xean quan.")
A.j7O=s(["\uc774\uc6c3\uacfc \uc18c\ud1b5\ud558\uace0 \uc0c8\ub85c\uc6b4 \uad00\uacc4\ub97c \ub9cc\ub4e4 \uc218 \uc788\ub2e4.","\ubaa8\ub4e0 \uc0ac\ub78c\uacfc \uad00\uacc4\uac00 \ub098\ube60\uc9c4\ub2e4.","\ud55c\uad6d \uc0dd\ud65c\uc744 \uc774\ud574\ud558\uae30 \ub354 \uc5b4\ub824\uc6cc\uc9c4\ub2e4.","\uc544\ubb34\ub3c4 \ub9cc\ub0a0 \uc218 \uc5c6\ub2e4."],t.s)
A.fBv=new B.O("\uc9c0\uc5ed\uc0ac\ud68c \ud65c\ub3d9\uc5d0 \ucc38\uc5ec\ud588\uc744 \ub54c \uc5bb\uc744 \uc218 \uc788\ub294 \ud6a8\uacfc\ub294?","Tham gia ho\u1ea1t \u0111\u1ed9ng c\u1ed9ng \u0111\u1ed3ng c\xf3 th\u1ec3 mang l\u1ea1i l\u1ee3i \xedch g\xec?",A.j7O,0,"Tham gia c\u1ed9ng \u0111\u1ed3ng gi\xfap giao ti\u1ebfp v\u1edbi h\xe0ng x\xf3m v\xe0 x\xe2y d\u1ef1ng quan h\u1ec7.")
A.hRs=s(["\uc9c0\uc5ed\uc0ac\ud68c \ucc38\uc5ec\ub294 \uc678\uad6d\uc778\uc758 \uc815\ucc29\uc5d0 \ub3c4\uc6c0\uc774 \ub420 \uc218 \uc788\ub2e4.","\uc678\uad6d\uc778\uc740 \uc9c0\uc5ed\uc0ac\ud68c \ud65c\ub3d9\uc5d0 \ucc38\uc5ec\ud558\uba74 \uc548 \ub41c\ub2e4.","\ud55c\uad6d\uc5b4\ub294 \ud55c\uad6d \uc0dd\ud65c\uacfc \uad00\uacc4\uac00 \uc5c6\ub2e4.","\ub2e4\ub978 \ubb38\ud654\ub97c \uc874\uc911\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4."],t.s)
A.fHy=new B.O("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.hRs,0,"Tham gia c\u1ed9ng \u0111\u1ed3ng c\xf3 th\u1ec3 gi\xfap ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i th\xedch nghi v\xe0 \u1ed5n \u0111\u1ecbnh cu\u1ed9c s\u1ed1ng.")
A.i3K=s([A.fFY,A.fFc,A.fH7,A.fGK,A.fCz,A.fEb,A.fD5,A.fFg,A.fBv,A.fHy],t.h)
A.j9l=s(["\uc815\ucc29 = \u0111\u1ecbnh c\u01b0/\u1ed5n \u0111\u1ecbnh cu\u1ed9c s\u1ed1ng.","\uc801\uc751 = th\xedch nghi.","\uc9c0\uc5ed\uc0ac\ud68c = c\u1ed9ng \u0111\u1ed3ng \u0111\u1ecba ph\u01b0\u01a1ng.","\uc0ac\ud68c \ucc38\uc5ec = tham gia x\xe3 h\u1ed9i.","\ubd09\uc0ac\ud65c\ub3d9 = ho\u1ea1t \u0111\u1ed9ng t\xecnh nguy\u1ec7n.","\ubb38\ud654\uad50\ub958 = giao l\u01b0u v\u0103n h\xf3a.","\uc18c\ud1b5 = giao ti\u1ebfp.","\uc874\uc911 = t\xf4n tr\u1ecdng.","\ud55c\uad6d\uc5b4\uc640 \uc0dd\ud65c\uc815\ubcf4\ub294 \uc548\uc815\uc801\uc778 \uc815\ucc29\uc5d0 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.","\uc9c0\uc6d0\uc13c\ud130\ub098 \uc0c1\ub2f4\uae30\uad00\uc744 \ud1b5\ud574 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc9c0\uc5ed\uc0ac\ud68c \ud65c\ub3d9\uc5d0 \ucc38\uc5ec\ud558\uba74 \uc774\uc6c3\uacfc \uad00\uacc4\ub97c \ub9cc\ub4e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc11c\ub85c \ub2e4\ub978 \ubb38\ud654\uc640 \uc0dd\ud65c\ubc29\uc2dd\uc744 \uc874\uc911\ud558\ub294 \ud0dc\ub3c4\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc815\ucc29\uc740 \uacf5\ub3d9\uccb4\uc640 \uc18c\ud1b5\ud558\uba70 \ud568\uaed8 \uc0b4\uc544\uac00\ub294 \uacfc\uc815\uc774\uae30\ub3c4 \ud569\ub2c8\ub2e4."],t.s)
A.fAF=new B.dJ(31,"\ubc95","\uc678\uad6d\uc778\uc758 \uc815\ucc29\uacfc \ucc38\uc5ec","\u0110\u1ecbnh c\u01b0 v\xe0 tham gia x\xe3 h\u1ed9i c\u1ee7a ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i",A.iWF,A.iRW,A.izj,A.iqG,"\ud55c\uad6d \uc0ac\ud68c\uc5d0 \uc815\ucc29\ud558\uace0 \ucc38\uc5ec\ud558\uae30","\uc678\uad6d\uc778\uc774 \uc0c8\ub85c\uc6b4 \ub098\ub77c\uc5d0\uc11c \uc0dd\ud65c\uc744 \uc2dc\uc791\ud558\uba74 \uc5b8\uc5b4, \ubb38\ud654, \uc81c\ub3c4 \ub4f1\uc758 \ucc28\uc774 \ub54c\ubb38\uc5d0 \uc5b4\ub824\uc6c0\uc744 \ub290\ub084 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ud55c\uad6d \uc0ac\ud68c\uc5d0 \uc548\uc815\uc801\uc73c\ub85c \uc815\ucc29\ud558\uae30 \uc704\ud574\uc11c\ub294 \uba3c\uc800 \uc77c\uc0c1\uc0dd\ud65c\uc5d0 \ud544\uc694\ud55c \ud55c\uad6d\uc5b4\ub97c \ubc30\uc6b0\uace0 \uc0dd\ud65c\uc815\ubcf4\ub97c \uc54c\uc544 \ub450\ub294 \uac83\uc774 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.\n\n\uc740\ud589, \ubcd1\uc6d0, \uc9c1\uc7a5, \ud559\uad50, \uacf5\uacf5\uae30\uad00 \ub4f1\uc744 \uc774\uc6a9\ud560 \ub54c \ud55c\uad6d\uc5b4\ub97c \uc774\ud574\ud560 \uc218 \uc788\uc73c\uba74 \ud544\uc694\ud55c \uc77c\uc744 \ub354 \ud3b8\ub9ac\ud558\uac8c \ucc98\ub9ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ud55c\uad6d\uc5d0\ub294 \uc678\uad6d\uc778\uc758 \uc0dd\ud65c\uc744 \ub3d5\uae30 \uc704\ud55c \uc5ec\ub7ec \uc0c1\ub2f4\uae30\uad00\uacfc \uc9c0\uc6d0 \ud504\ub85c\uadf8\ub7a8\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uacf3\uc5d0\uc11c\ub294 \ud55c\uad6d\uc5b4 \uad50\uc721, \uc0dd\ud65c \uc0c1\ub2f4, \uac00\uc871\uc0dd\ud65c, \ucde8\uc5c5 \ub4f1 \uc5ec\ub7ec \ubd84\uc57c\uc758 \uc815\ubcf4\ub97c \uc81c\uacf5\ud558\uae30\ub3c4 \ud569\ub2c8\ub2e4.\n\n\uc9c0\uc5ed\uc0ac\ud68c\uc5d0 \ucc38\uc5ec\ud558\ub294 \uac83\ub3c4 \uc815\ucc29\uc5d0 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4. \uc9c0\uc5ed \ucd95\uc81c\ub098 \uc8fc\ubbfc \ud589\uc0ac\uc5d0 \ucc38\uc5ec\ud558\uac70\ub098 \ubd09\uc0ac\ud65c\ub3d9\uc744 \ud558\uba74\uc11c \uc774\uc6c3\uc744 \ub9cc\ub098\uace0 \uc0c8\ub85c\uc6b4 \uad00\uacc4\ub97c \ub9cc\ub4e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ubb38\ud654\uad50\ub958 \ud65c\ub3d9\uc5d0 \ucc38\uc5ec\ud558\uba74 \uc790\uc2e0\uc758 \ubb38\ud654\ub97c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc18c\uac1c\ud558\uace0 \ud55c\uad6d\uc758 \ubb38\ud654\ub3c4 \ubc30\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ud55c\uad6d \uc0ac\ud68c\uc5d0\ub294 \uc11c\ub85c \ub2e4\ub978 \uc5b8\uc5b4\uc640 \ubb38\ud654\ub97c \uac00\uc9c4 \uc0ac\ub78c\ub4e4\uc774 \ud568\uaed8 \uc0b4\uc544\uac00\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc790\uc2e0\uc758 \ubb38\ud654\ub97c \uc18c\uc911\ud788 \uc0dd\uac01\ud558\ub294 \uac83\uacfc \ub3d9\uc2dc\uc5d0 \ub2e4\ub978 \uc0ac\ub78c\uc758 \ubb38\ud654\uc640 \uc0dd\ud65c\ubc29\uc2dd\uc744 \uc874\uc911\ud558\ub294 \ud0dc\ub3c4\ub3c4 \ud544\uc694\ud569\ub2c8\ub2e4.\n\n\uc0ac\ud68c\uc5d0 \uc798 \uc815\ucc29\ud55c\ub2e4\ub294 \uac83\uc740 \ub2e8\uc21c\ud788 \uc624\ub798 \uc0ac\ub294 \uac83\ub9cc\uc744 \uc758\ubbf8\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc9c0\uc5ed\uc0ac\ud68c \uc0ac\ub78c\ub4e4\uacfc \uc18c\ud1b5\ud558\uace0 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \ucc3e\uc73c\uba70 \uacf5\ub3d9\uccb4\uc758 \uad6c\uc131\uc6d0\uc73c\ub85c \ud568\uaed8 \uc0b4\uc544\uac00\ub294 \uac83\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4.\n","Khi ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i b\u1eaft \u0111\u1ea7u s\u1ed1ng \u1edf m\u1ed9t qu\u1ed1c gia m\u1edbi, h\u1ecd c\xf3 th\u1ec3 g\u1eb7p kh\xf3 kh\u0103n do s\u1ef1 kh\xe1c bi\u1ec7t v\u1ec1 ng\xf4n ng\u1eef, v\u0103n h\xf3a v\xe0 h\u1ec7 th\u1ed1ng x\xe3 h\u1ed9i.\n\n\u0110\u1ec3 \u1ed5n \u0111\u1ecbnh cu\u1ed9c s\u1ed1ng trong x\xe3 h\u1ed9i H\xe0n Qu\u1ed1c, vi\u1ec7c h\u1ecdc ti\u1ebfng H\xe0n c\u1ea7n thi\u1ebft cho \u0111\u1eddi s\u1ed1ng h\u1eb1ng ng\xe0y v\xe0 t\xecm hi\u1ec3u c\xe1c th\xf4ng tin sinh ho\u1ea1t s\u1ebd r\u1ea5t h\u1eefu \xedch.\n\nN\u1ebfu hi\u1ec3u ti\u1ebfng H\xe0n khi s\u1eed d\u1ee5ng ng\xe2n h\xe0ng, b\u1ec7nh vi\u1ec7n, n\u01a1i l\xe0m vi\u1ec7c, tr\u01b0\u1eddng h\u1ecdc hay c\u01a1 quan c\xf4ng, ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i c\xf3 th\u1ec3 x\u1eed l\xfd nh\u1eefng c\xf4ng vi\u1ec7c c\u1ea7n thi\u1ebft thu\u1eadn ti\u1ec7n h\u01a1n.\n\nT\u1ea1i H\xe0n Qu\u1ed1c c\u0169ng c\xf3 nhi\u1ec1u c\u01a1 quan t\u01b0 v\u1ea5n v\xe0 ch\u01b0\u01a1ng tr\xecnh h\u1ed7 tr\u1ee3 \u0111\u1eddi s\u1ed1ng cho ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i. Nh\u1eefng n\u01a1i n\xe0y c\xf3 th\u1ec3 cung c\u1ea5p th\xf4ng tin trong nhi\u1ec1u l\u0129nh v\u1ef1c nh\u01b0 h\u1ecdc ti\u1ebfng H\xe0n, t\u01b0 v\u1ea5n \u0111\u1eddi s\u1ed1ng, gia \u0111\xecnh v\xe0 vi\u1ec7c l\xe0m.\n\nTham gia c\u1ed9ng \u0111\u1ed3ng \u0111\u1ecba ph\u01b0\u01a1ng c\u0169ng gi\xfap \xedch cho qu\xe1 tr\xecnh \u0111\u1ecbnh c\u01b0. Khi tham gia l\u1ec5 h\u1ed9i \u0111\u1ecba ph\u01b0\u01a1ng, ho\u1ea1t \u0111\u1ed9ng c\u01b0 d\xe2n ho\u1eb7c t\xecnh nguy\u1ec7n, c\xf3 th\u1ec3 g\u1eb7p g\u1ee1 h\xe0ng x\xf3m v\xe0 x\xe2y d\u1ef1ng nh\u1eefng m\u1ed1i quan h\u1ec7 m\u1edbi.\n\nTham gia c\xe1c ho\u1ea1t \u0111\u1ed9ng giao l\u01b0u v\u0103n h\xf3a gi\xfap ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i gi\u1edbi thi\u1ec7u v\u0103n h\xf3a c\u1ee7a m\xecnh v\u1edbi ng\u01b0\u1eddi kh\xe1c v\xe0 \u0111\u1ed3ng th\u1eddi t\xecm hi\u1ec3u v\u0103n h\xf3a H\xe0n Qu\u1ed1c.\n\nTrong x\xe3 h\u1ed9i H\xe0n Qu\u1ed1c c\xf3 nh\u1eefng ng\u01b0\u1eddi v\u1edbi nhi\u1ec1u ng\xf4n ng\u1eef v\xe0 n\u1ec1n v\u0103n h\xf3a kh\xe1c nhau c\xf9ng sinh s\u1ed1ng. V\xec v\u1eady, b\xean c\u1ea1nh vi\u1ec7c coi tr\u1ecdng v\u0103n h\xf3a c\u1ee7a m\xecnh, c\u0169ng c\u1ea7n c\xf3 th\xe1i \u0111\u1ed9 t\xf4n tr\u1ecdng v\u0103n h\xf3a v\xe0 l\u1ed1i s\u1ed1ng c\u1ee7a ng\u01b0\u1eddi kh\xe1c.\n\n\u0110\u1ecbnh c\u01b0 t\u1ed1t trong x\xe3 h\u1ed9i kh\xf4ng ch\u1ec9 \u0111\u01a1n gi\u1ea3n l\xe0 s\u1ed1ng \u1edf \u0111\xf3 trong th\u1eddi gian d\xe0i. Vi\u1ec7c giao ti\u1ebfp v\u1edbi ng\u01b0\u1eddi d\xe2n \u0111\u1ecba ph\u01b0\u01a1ng, t\xecm ki\u1ebfm th\xf4ng tin c\u1ea7n thi\u1ebft v\xe0 s\u1ed1ng c\xf9ng nhau v\u1edbi t\u01b0 c\xe1ch th\xe0nh vi\xean c\u1ee7a c\u1ed9ng \u0111\u1ed3ng c\u0169ng r\u1ea5t quan tr\u1ecdng.\n","\uc9c0\uc5ed\uc0ac\ud68c \ud504\ub85c\uadf8\ub7a8\uc5d0 \ucc38\uc5ec\ud558\uae30","\uc548: \uc548\ub155\ud558\uc138\uc694. \uc774 \ub3d9\ub124\uc5d0 \uc774\uc0ac \uc628 \uc9c0 \uc5bc\ub9c8 \uc548 \ub410\ub294\ub370 \ucc38\uc5ec\ud560 \uc218 \uc788\ub294 \ud504\ub85c\uadf8\ub7a8\uc774 \uc788\ub098\uc694?\n\n\uc9c1\uc6d0: \ub124. \uc8fc\ubbfc\ub4e4\uc744 \uc704\ud55c \uc5ec\ub7ec \ud504\ub85c\uadf8\ub7a8\uc774 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc548: \uc678\uad6d\uc778\ub3c4 \ucc38\uc5ec\ud560 \uc218 \uc788\uc5b4\uc694?\n\n\uc9c1\uc6d0: \ud504\ub85c\uadf8\ub7a8\ub9c8\ub2e4 \uc870\uac74\uc774 \ub2e4\ub97c \uc218 \uc788\uc9c0\ub9cc \ucc38\uc5ec\ud560 \uc218 \uc788\ub294 \ud504\ub85c\uadf8\ub7a8\uc774 \ub9ce\uc774 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc548: \uc5b4\ub5a4 \ud504\ub85c\uadf8\ub7a8\uc774 \uc788\uc5b4\uc694?\n\n\uc9c1\uc6d0: \ud55c\uad6d\uc5b4 \uc218\uc5c5, \ubb38\ud654\uad50\ub958 \ud589\uc0ac, \ubd09\uc0ac\ud65c\ub3d9, \uc0dd\ud65c\uc815\ubcf4 \uad50\uc721 \ub4f1\uc774 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc548: \uc800\ub294 \ud55c\uad6d \uc0ac\ub78c\ub4e4\uacfc \uc774\uc57c\uae30\ud560 \uae30\ud68c\uac00 \ub9ce\uc9c0 \uc54a\uc544\uc11c \ud55c\uad6d\uc5b4 \uc5f0\uc2b5\ub3c4 \ud558\uace0 \uc2f6\uc5b4\uc694.\n\n\uc9c1\uc6d0: \uadf8\ub7ec\uba74 \ubb38\ud654\uad50\ub958 \ud504\ub85c\uadf8\ub7a8\uc774\ub098 \uc8fc\ubbfc \ubaa8\uc784\uc5d0 \ucc38\uc5ec\ud574 \ubcf4\uc138\uc694.\n\n\uc548: \ubd09\uc0ac\ud65c\ub3d9\ub3c4 \ud574 \ubcf4\uace0 \uc2f6\uc740\ub370\uc694.\n\n\uc9c1\uc6d0: \uc9c0\uc5ed \ud658\uacbd \uc815\ub9ac\ub098 \ud589\uc0ac \uc9c0\uc6d0 \uac19\uc740 \ubd09\uc0ac\ud65c\ub3d9\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc548: \ucc38\uc5ec\ud558\ub824\uba74 \uc5b4\ub5bb\uac8c \uc2e0\uccad\ud574\uc694?\n\n\uc9c1\uc6d0: \uc774 \uc2e0\uccad\uc11c\ub97c \uc791\uc131\ud558\uc2dc\uac70\ub098 \ud648\ud398\uc774\uc9c0\uc5d0\uc11c \uc2e0\uccad\ud558\uc2dc\uba74 \ub429\ub2c8\ub2e4.\n\n\uc548: \ub124. \uc9c0\uc5ed \uc0ac\ub78c\ub4e4\ub3c4 \ub9cc\ub098\uace0 \ud55c\uad6d \uc0dd\ud65c\ub3c4 \ub354 \ubc30\uc6b0\uace0 \uc2f6\uc5b4\uc694.\n\n\uc9c1\uc6d0: \uc88b\uc740 \uc0dd\uac01\uc774\uc5d0\uc694. \uc9c0\uc5ed\uc0ac\ud68c \ud65c\ub3d9\uc5d0 \ucc38\uc5ec\ud558\uba74 \uc0c8\ub85c\uc6b4 \uc0ac\ub78c\ub4e4\uacfc \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc18c\ud1b5\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n","An: Xin ch\xe0o. T\xf4i m\u1edbi chuy\u1ec3n \u0111\u1ebfn khu v\u1ef1c n\xe0y ch\u01b0a l\xe2u. C\xf3 ch\u01b0\u01a1ng tr\xecnh n\xe0o t\xf4i c\xf3 th\u1ec3 tham gia kh\xf4ng?\n\nNh\xe2n vi\xean: C\xf3. C\xf3 nhi\u1ec1u ch\u01b0\u01a1ng tr\xecnh d\xe0nh cho c\u01b0 d\xe2n.\n\nAn: Ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i c\u0169ng c\xf3 th\u1ec3 tham gia \xe0?\n\nNh\xe2n vi\xean: \u0110i\u1ec1u ki\u1ec7n c\xf3 th\u1ec3 kh\xe1c nhau t\xf9y ch\u01b0\u01a1ng tr\xecnh, nh\u01b0ng c\xf3 nhi\u1ec1u ch\u01b0\u01a1ng tr\xecnh ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i c\xf3 th\u1ec3 tham gia.\n\nAn: C\xf3 nh\u1eefng ch\u01b0\u01a1ng tr\xecnh g\xec?\n\nNh\xe2n vi\xean: C\xf3 l\u1edbp ti\u1ebfng H\xe0n, ho\u1ea1t \u0111\u1ed9ng giao l\u01b0u v\u0103n h\xf3a, t\xecnh nguy\u1ec7n v\xe0 gi\xe1o d\u1ee5c th\xf4ng tin \u0111\u1eddi s\u1ed1ng.\n\nAn: T\xf4i kh\xf4ng c\xf3 nhi\u1ec1u c\u01a1 h\u1ed9i n\xf3i chuy\u1ec7n v\u1edbi ng\u01b0\u1eddi H\xe0n n\xean c\u0169ng mu\u1ed1n luy\u1ec7n ti\u1ebfng H\xe0n.\n\nNh\xe2n vi\xean: V\u1eady anh h\xe3y th\u1eed tham gia ch\u01b0\u01a1ng tr\xecnh giao l\u01b0u v\u0103n h\xf3a ho\u1eb7c c\xe1c bu\u1ed5i sinh ho\u1ea1t c\u01b0 d\xe2n.\n\nAn: T\xf4i c\u0169ng mu\u1ed1n th\u1eed l\xe0m t\xecnh nguy\u1ec7n.\n\nNh\xe2n vi\xean: C\xf3 c\xe1c ho\u1ea1t \u0111\u1ed9ng nh\u01b0 d\u1ecdn v\u1ec7 sinh khu v\u1ef1c ho\u1eb7c h\u1ed7 tr\u1ee3 c\xe1c s\u1ef1 ki\u1ec7n \u0111\u1ecba ph\u01b0\u01a1ng.\n\nAn: T\xf4i ph\u1ea3i \u0111\u0103ng k\xfd th\u1ebf n\xe0o?\n\nNh\xe2n vi\xean: Anh c\xf3 th\u1ec3 \u0111i\u1ec1n \u0111\u01a1n n\xe0y ho\u1eb7c \u0111\u0103ng k\xfd tr\xean trang web.\n\nAn: V\xe2ng. T\xf4i mu\u1ed1n g\u1eb7p g\u1ee1 ng\u01b0\u1eddi d\xe2n \u0111\u1ecba ph\u01b0\u01a1ng v\xe0 hi\u1ec3u th\xeam v\u1ec1 cu\u1ed9c s\u1ed1ng H\xe0n Qu\u1ed1c.\n\nNh\xe2n vi\xean: \u0110\xf3 l\xe0 \xfd hay. Tham gia c\xe1c ho\u1ea1t \u0111\u1ed9ng c\u1ed9ng \u0111\u1ed3ng gi\xfap anh giao ti\u1ebfp t\u1ef1 nhi\xean v\u1edbi nh\u1eefng ng\u01b0\u1eddi m\u1edbi.\n",A.j5n,A.hBs,A.i3K,A.j9l)
A.hgY=s(["Bi\u1ebft m\u1ed9t s\u1ed1 nh\xe2n v\u1eadt ti\xeau bi\u1ec3u trong l\u1ecbch s\u1eed H\xe0n Qu\u1ed1c.","Hi\u1ec3u th\xe0nh t\u1ef1u c\u1ee7a \uc138\uc885\ub300\uc655 v\xe0 \xfd ngh\u0129a c\u1ee7a \ud6c8\ubbfc\uc815\uc74c.","Bi\u1ebft \uc7a5\uc601\uc2e4 v\xe0 s\u1ef1 ph\xe1t tri\u1ec3n khoa h\u1ecdc k\u1ef9 thu\u1eadt th\u1eddi Joseon.","Hi\u1ec3u vai tr\xf2 c\u1ee7a \uc774\uc21c\uc2e0 trong cu\u1ed9c chi\u1ebfn ch\u1ed1ng Nh\u1eadt cu\u1ed1i th\u1ebf k\u1ef7 XVI.","Bi\u1ebft \uc2e0\uc0ac\uc784\ub2f9 l\xe0 nh\xe2n v\u1eadt ti\xeau bi\u1ec3u v\u1ec1 ngh\u1ec7 thu\u1eadt v\xe0 gi\xe1o d\u1ee5c.","Bi\u1ebft \ud5c8\uc900 v\xe0 t\xe1c ph\u1ea9m \ub3d9\uc758\ubcf4\uac10.","Bi\u1ebft \uc815\uc57d\uc6a9 v\xe0 t\u01b0 t\u01b0\u1edfng c\u1ea3i c\xe1ch cu\u1ed1i th\u1eddi Joseon.","Luy\u1ec7n li\xean k\u1ebft nh\xe2n v\u1eadt v\u1edbi th\xe0nh t\u1ef1u t\u01b0\u01a1ng \u1ee9ng trong c\xe2u h\u1ecfi KIIP."],t.s)
A.juJ=s(["\uc138\uc885\ub300\uc655\uc740 \ud6c8\ubbfc\uc815\uc74c\uc744 \ucc3d\uc81c\ud558\uace0 \ud559\ubb38, \ubb38\ud654, \uacfc\ud559\uc758 \ubc1c\uc804\uc744 \uc774\ub048 \uc655\uc785\ub2c8\ub2e4.","\ud6c8\ubbfc\uc815\uc74c\uc740 \ubc31\uc131\uc774 \uc27d\uac8c \uae00\uc744 \ubc30\uc6b0\uace0 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \ub9cc\ub4e4\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.","\uc7a5\uc601\uc2e4\uc740 \uc138\uc885 \uc2dc\ub300\uc5d0 \ud65c\ub3d9\ud55c \ub300\ud45c\uc801\uc778 \uacfc\ud559 \uae30\uc220\uc790\uc785\ub2c8\ub2e4.","\uc774\uc21c\uc2e0\uc740 \uc784\uc9c4\uc65c\ub780 \ub54c \uc870\uc120 \uc218\uad70\uc744 \uc774\ub04c\uace0 \uc77c\ubcf8\uad70\uc5d0 \ub9de\uc11c \uc2f8\uc6b4 \uc7a5\uad70\uc785\ub2c8\ub2e4.","\uac70\ubd81\uc120\uc740 \uc774\uc21c\uc2e0\uacfc \uad00\ub828\ud558\uc5ec \uc798 \uc54c\ub824\uc9c4 \uc870\uc120\uc758 \uc804\ud22c\uc120\uc785\ub2c8\ub2e4.","\uc2e0\uc0ac\uc784\ub2f9\uc740 \uc870\uc120 \uc2dc\ub300\uc758 \ub300\ud45c\uc801\uc778 \uc608\uc220\uac00\ub85c \uadf8\ub9bc\uacfc \uae00\uc528 \ub4f1\uc5d0 \ub6f0\uc5b4\ub0ac\uc2b5\ub2c8\ub2e4.","\ud5c8\uc900\uc740 \uc870\uc120 \uc2dc\ub300\uc758 \uc758\ud559\uc790\ub85c \ub3d9\uc758\ubcf4\uac10\uc744 \ud3b8\ucc2c\ud55c \uc778\ubb3c\uc785\ub2c8\ub2e4.","\uc815\uc57d\uc6a9\uc740 \uc870\uc120 \ud6c4\uae30\uc758 \uc2e4\ud559\uc790\ub85c \uc0ac\ud68c\uc640 \uc81c\ub3c4\ub97c \uac1c\uc120\ud558\uae30 \uc704\ud55c \uc5ec\ub7ec \uc0dd\uac01\uc744 \uc81c\uc2dc\ud588\uc2b5\ub2c8\ub2e4.","\uc5ed\uc0ac \uc778\ubb3c\uc744 \uacf5\ubd80\ud560 \ub54c\uc5d0\ub294 \uc774\ub984\uacfc \ub300\ud45c \uc5c5\uc801\uc744 \uc5f0\uacb0\ud558\uc5ec \uae30\uc5b5\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4."],t.s)
