A.hb5=s(["\uccb4\ub958 \uad00\ub828 \uaddc\uc815\uc744 \uc900\uc218\ud55c\ub2e4.","\ubc95\uc744 \uc9c0\ud0a4\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4.","\uc2e0\uace0 \uc808\ucc28\ub97c \ubaa8\ub450 \ubb34\uc2dc\ud55c\ub2e4.","\uc5b4\ub5a4 \uc77c\ub3c4 \ud5c8\uac00 \uc5c6\uc774 \ud560 \uc218 \uc788\ub2e4."],t.s)
A.fHC=new B.O("\uc678\uad6d\uc778\uc758 \uc758\ubb34\uc640 \uad00\ub828\uc774 \uc788\ub294 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","\u0110i\u1ec1u n\xe0o li\xean quan \u0111\u1ebfn ngh\u0129a v\u1ee5 c\u1ee7a ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i?",A.hb5,0,"Tu\xe2n th\u1ee7 c\xe1c quy \u0111\u1ecbnh c\u01b0 tr\xfa l\xe0 m\u1ed9t ngh\u0129a v\u1ee5 quan tr\u1ecdng.")
A.hO7=s(["\uad00\ub828 \uae30\uad00\uc5d0 \uc2e0\uace0\ud558\uac70\ub098 \ub3c4\uc6c0\uc744 \uc694\uccad\ud55c\ub2e4.","\ubb34\uc870\uac74 \ud63c\uc790 \ud574\uacb0\ud55c\ub2e4.","\uc544\ubb34\uc5d0\uac8c\ub3c4 \uc54c\ub9ac\uc9c0 \uc54a\ub294\ub2e4.","\ubaa8\ub4e0 \uc99d\uac70\ub97c \ubc84\ub9b0\ub2e4."],t.s)
A.fFT=new B.O("\ud3ed\ub825\uc774\ub098 \uc0ac\uae30 \ud53c\ud574\ub97c \uc785\uc5c8\uc744 \ub54c \ubc14\ub78c\uc9c1\ud55c \ud589\ub3d9\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?","N\u1ebfu b\u1ecb b\u1ea1o l\u1ef1c ho\u1eb7c l\u1eeba \u0111\u1ea3o, h\xe0nh \u0111\u1ed9ng ph\xf9 h\u1ee3p l\xe0 g\xec?",A.hO7,0,"Khi b\u1ecb thi\u1ec7t h\u1ea1i n\xean li\xean h\u1ec7 c\u01a1 quan c\xf3 th\u1ea9m quy\u1ec1n \u0111\u1ec3 \u0111\u01b0\u1ee3c gi\xfap \u0111\u1ee1.")
A.i6S=s(["\ud544\uc694\ud55c \uc2e0\uace0 \uc808\ucc28\uac00 \uc788\ub294\uc9c0 \ud655\uc778\ud55c\ub2e4.","\ubb34\uc870\uac74 \uc544\ubb34\uac83\ub3c4 \ud558\uc9c0 \uc54a\ub294\ub2e4.","\ubc95\uacfc \uad00\uacc4\uac00 \uc5c6\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4.","\ub2e4\ub978 \uc0ac\ub78c\uc758 \uccb4\ub958\uc790\uaca9\uc744 \uc0ac\uc6a9\ud55c\ub2e4."],t.s)
A.fHx=new B.O("\uccb4\ub958 \uad00\ub828 \uc815\ubcf4\uac00 \ubcc0\uacbd\ub41c \uacbd\uc6b0 \uc5b4\ub5bb\uac8c \ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\uae4c?","N\u1ebfu th\xf4ng tin li\xean quan \u0111\u1ebfn c\u01b0 tr\xfa thay \u0111\u1ed5i th\xec n\xean l\xe0m g\xec?",A.i6S,0,"Khi th\xf4ng tin c\u01b0 tr\xfa thay \u0111\u1ed5i c\u1ea7n ki\u1ec3m tra ngh\u0129a v\u1ee5 khai b\xe1o t\u01b0\u01a1ng \u1ee9ng.")
A.ihi=s(["\uc678\uad6d\uc778\uc740 \uad8c\ub9ac\ub97c \ubcf4\ud638\ubc1b\uc744 \uc218 \uc788\uc73c\uba70 \ud544\uc694\ud55c \uc758\ubb34\ub3c4 \uc9c0\ucf1c\uc57c \ud55c\ub2e4.","\uc678\uad6d\uc778\uc740 \ud55c\uad6d\uc758 \ubc95\uc744 \uc9c0\ud0a4\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4.","\uccb4\ub958\uc790\uaca9\uc740 \ucde8\uc5c5\uacfc \uc804\ud600 \uad00\uacc4\uac00 \uc5c6\ub2e4.","\ubb38\uc81c\uac00 \uc0dd\uaca8\ub3c4 \uad00\ub828 \uae30\uad00\uc5d0 \ub3c4\uc6c0\uc744 \uc694\uccad\ud560 \uc218 \uc5c6\ub2e4."],t.s)
A.fFz=new B.O("\uae00\uc758 \ub0b4\uc6a9\uacfc \uac19\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.","Ch\u1ecdn n\u1ed9i dung ph\xf9 h\u1ee3p v\u1edbi b\xe0i \u0111\u1ecdc.",A.ihi,0,"Ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i v\u1eeba c\xf3 quy\u1ec1n \u0111\u01b0\u1ee3c b\u1ea3o v\u1ec7, v\u1eeba c\xf3 ngh\u0129a v\u1ee5 tu\xe2n th\u1ee7 c\xe1c quy \u0111\u1ecbnh c\u1ea7n thi\u1ebft.")
A.jlL=s([A.fI7,A.fD8,A.fCA,A.fFQ,A.fEL,A.fGz,A.fHC,A.fFT,A.fHx,A.fFz],t.h)
A.iWP=s(["\uc678\uad6d\uc778 = ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i.","\uad8c\ub9ac = quy\u1ec1n.","\uc758\ubb34 = ngh\u0129a v\u1ee5.","\uccb4\ub958\uc790\uaca9 = t\u01b0 c\xe1ch l\u01b0u tr\xfa.","\uccb4\ub958\uae30\uac04 = th\u1eddi h\u1ea1n l\u01b0u tr\xfa.","\ucd9c\uc785\uad6d = xu\u1ea5t nh\u1eadp c\u1ea3nh.","\uc2e0\uace0 = khai b\xe1o/tr\xecnh b\xe1o.","\uc784\uae08\uccb4\ubd88 = n\u1ee3/ch\u1eadm tr\u1ea3 l\u01b0\u01a1ng.","\uc678\uad6d\uc778\ub3c4 \ubc95\uc5d0 \ub530\ub77c \uad8c\ub9ac\ub97c \ubcf4\ud638\ubc1b\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ud55c\uad6d\uc5d0\uc11c \uc0dd\ud65c\ud560 \ub54c\uc5d0\ub294 \ud55c\uad6d\uc758 \ubc95\uacfc \uc9c8\uc11c\ub97c \uc9c0\ucf1c\uc57c \ud569\ub2c8\ub2e4.","\ucde8\uc5c5 \uc804\uc5d0\ub294 \uc790\uc2e0\uc758 \uccb4\ub958\uc790\uaca9\uc73c\ub85c \uac00\ub2a5\ud55c \ud65c\ub3d9\uc778\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.","\ud53c\ud574\ub098 \ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \uad00\ub828 \uae30\uad00\uc5d0 \uc0c1\ub2f4\ud558\uac70\ub098 \ub3c4\uc6c0\uc744 \uc694\uccad\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc548\uc815\uc801\uc778 \uc0dd\ud65c\uc744 \uc704\ud574 \uad8c\ub9ac\uc640 \uc758\ubb34\ub97c \ud568\uaed8 \uc774\ud574\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4."],t.s)
A.fAI=new B.dJ(30,"\ubc95","\uc678\uad6d\uc778\uc758 \uad8c\ub9ac\uc640 \uc758\ubb34","Quy\u1ec1n v\xe0 ngh\u0129a v\u1ee5 c\u1ee7a ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i",A.h5i,A.iru,A.jHG,A.iES,"\ud55c\uad6d\uc5d0\uc11c \uc0dd\ud65c\ud558\ub294 \uc678\uad6d\uc778\uc758 \uad8c\ub9ac\uc640 \uc758\ubb34","\ud55c\uad6d\uc5d0\uc11c \uc0dd\ud65c\ud558\ub294 \uc678\uad6d\uc778\uc740 \ubc95\uc5d0 \ub530\ub77c \uc5ec\ub7ec \uad8c\ub9ac\ub97c \ubcf4\ud638\ubc1b\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc608\ub97c \ub4e4\uc5b4 \uc77c\uc744 \ud558\ub294 \uc678\uad6d\uc778\uc740 \uadfc\ub85c\uc790\ub85c\uc11c \uc815\ub2f9\ud55c \uc784\uae08\uc744 \ubc1b\uace0 \uc548\uc804\ud55c \ud658\uacbd\uc5d0\uc11c \uc77c\ud560 \uad8c\ub9ac\ub97c \uac00\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud3ed\ub825\uc774\ub098 \uc0ac\uae30 \ub4f1\uc73c\ub85c \ud53c\ud574\ub97c \uc785\uc740 \uacbd\uc6b0\uc5d0\ub3c4 \uad00\ub828 \uae30\uad00\uc5d0 \uc2e0\uace0\ud558\uac70\ub098 \uc0c1\ub2f4\uc744 \uc694\uccad\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ud558\uc9c0\ub9cc \uad8c\ub9ac\uc640 \ud568\uaed8 \uc9c0\ucf1c\uc57c \ud560 \uc758\ubb34\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ud55c\uad6d\uc5d0 \uccb4\ub958\ud558\ub294 \ub3d9\uc548\uc5d0\ub294 \ud55c\uad6d\uc758 \ubc95\uacfc \uc9c8\uc11c\ub97c \uc9c0\ucf1c\uc57c \ud569\ub2c8\ub2e4. \ub610\ud55c \uc790\uc2e0\uc758 \uccb4\ub958\uc790\uaca9\uacfc \uccb4\ub958\uae30\uac04\uc744 \ud655\uc778\ud558\uace0 \ucd9c\uc785\uad6d \uad00\ub828 \uaddc\uc815\uc744 \uc900\uc218\ud574\uc57c \ud569\ub2c8\ub2e4.\n\n\uc678\uad6d\uc778\uc774 \ucde8\uc5c5\ud558\ub824\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc790\uc2e0\uc758 \uccb4\ub958\uc790\uaca9\uc73c\ub85c \ud574\ub2f9 \uc77c\uc744 \ud560 \uc218 \uc788\ub294\uc9c0 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4. \ud544\uc694\ud55c \ud5c8\uac00\ub098 \uc808\ucc28\uac00 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc774\ub97c \uc9c0\ucf1c\uc57c \ud569\ub2c8\ub2e4.\n\n\uc8fc\uc18c\ub098 \uccb4\ub958 \uad00\ub828 \uc815\ubcf4\uac00 \ubcc0\uacbd\ub41c \uacbd\uc6b0\uc5d0\ub3c4 \uc0c1\ud669\uc5d0 \ub530\ub77c \ud544\uc694\ud55c \uc2e0\uace0 \uc808\ucc28\uac00 \uc788\uc744 \uc218 \uc788\uc73c\ubbc0\ub85c \uad00\ub828 \uae30\uad00\uc758 \uc548\ub0b4\ub97c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.\n\n\uc9c1\uc7a5\uc5d0\uc11c \uc784\uae08\uc744 \ubc1b\uc9c0 \ubabb\ud558\uac70\ub098 \ubd80\ub2f9\ud55c \ub300\uc6b0\ub97c \ubc1b\ub294 \ub4f1 \ubb38\uc81c\uac00 \uc0dd\uae30\uba74 \ud63c\uc790 \ud574\uacb0\ud558\ub824\uace0 \ud558\uae30\ubcf4\ub2e4 \uad00\ub828 \uae30\uad00\uc774\ub098 \uc0c1\ub2f4\uae30\uad00\uc5d0 \ub3c4\uc6c0\uc744 \uc694\uccad\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ud55c\uad6d \uc0ac\ud68c\uc5d0\uc11c \uc548\uc815\uc801\uc73c\ub85c \uc0dd\ud65c\ud558\uae30 \uc704\ud574\uc11c\ub294 \uc790\uc2e0\uc758 \uad8c\ub9ac\ub97c \uc54c\uace0 \ubcf4\ud638\ubc1b\ub294 \uac83\uacfc \ub3d9\uc2dc\uc5d0 \ubc95\uacfc \uaddc\uce59\uc744 \uc9c0\ud0a4\uace0 \ud544\uc694\ud55c \uc808\ucc28\ub97c \uc900\uc218\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.\n","Ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i sinh s\u1ed1ng t\u1ea1i H\xe0n Qu\u1ed1c c\xf3 th\u1ec3 \u0111\u01b0\u1ee3c b\u1ea3o v\u1ec7 nhi\u1ec1u quy\u1ec1n l\u1ee3i theo ph\xe1p lu\u1eadt.\n\nV\xed d\u1ee5, ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i \u0111ang l\xe0m vi\u1ec7c c\xf3 th\u1ec3 c\xf3 quy\u1ec1n \u0111\u01b0\u1ee3c nh\u1eadn m\u1ee9c l\u01b0\u01a1ng h\u1ee3p l\xfd v\xe0 l\xe0m vi\u1ec7c trong m\xf4i tr\u01b0\u1eddng an to\xe0n v\u1edbi t\u01b0 c\xe1ch l\xe0 ng\u01b0\u1eddi lao \u0111\u1ed9ng. N\u1ebfu b\u1ecb thi\u1ec7t h\u1ea1i do b\u1ea1o l\u1ef1c ho\u1eb7c l\u1eeba \u0111\u1ea3o, h\u1ecd c\u0169ng c\xf3 th\u1ec3 tr\xecnh b\xe1o ho\u1eb7c y\xeau c\u1ea7u t\u01b0 v\u1ea5n t\u1eeb c\u01a1 quan li\xean quan.\n\nTuy nhi\xean, c\xf9ng v\u1edbi quy\u1ec1n l\u1ee3i c\u0169ng c\xf3 nh\u1eefng ngh\u0129a v\u1ee5 ph\u1ea3i th\u1ef1c hi\u1ec7n.\n\nTrong th\u1eddi gian c\u01b0 tr\xfa t\u1ea1i H\xe0n Qu\u1ed1c, ph\u1ea3i tu\xe2n th\u1ee7 ph\xe1p lu\u1eadt v\xe0 tr\u1eadt t\u1ef1 c\u1ee7a H\xe0n Qu\u1ed1c. \u0110\u1ed3ng th\u1eddi c\u1ea7n ki\u1ec3m tra t\u01b0 c\xe1ch l\u01b0u tr\xfa v\xe0 th\u1eddi h\u1ea1n l\u01b0u tr\xfa c\u1ee7a b\u1ea3n th\xe2n, c\u0169ng nh\u01b0 tu\xe2n th\u1ee7 c\xe1c quy \u0111\u1ecbnh li\xean quan \u0111\u1ebfn xu\u1ea5t nh\u1eadp c\u1ea3nh.\n\nN\u1ebfu ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i mu\u1ed1n l\xe0m vi\u1ec7c, \u0111i\u1ec1u quan tr\u1ecdng l\xe0 ph\u1ea3i ki\u1ec3m tra c\xf4ng vi\u1ec7c \u0111\xf3 c\xf3 \u0111\u01b0\u1ee3c ph\xe9p theo t\u01b0 c\xe1ch l\u01b0u tr\xfa c\u1ee7a m\xecnh hay kh\xf4ng. N\u1ebfu c\xf3 gi\u1ea5y ph\xe9p ho\u1eb7c th\u1ee7 t\u1ee5c c\u1ea7n thi\u1ebft th\xec ph\u1ea3i th\u1ef1c hi\u1ec7n theo quy \u0111\u1ecbnh.\n\nKhi \u0111\u1ecba ch\u1ec9 ho\u1eb7c th\xf4ng tin li\xean quan \u0111\u1ebfn c\u01b0 tr\xfa thay \u0111\u1ed5i, t\xf9y t\u1eebng tr\u01b0\u1eddng h\u1ee3p c\xf3 th\u1ec3 c\xf3 th\u1ee7 t\u1ee5c khai b\xe1o c\u1ea7n th\u1ef1c hi\u1ec7n, v\xec v\u1eady n\xean ki\u1ec3m tra h\u01b0\u1edbng d\u1eabn c\u1ee7a c\u01a1 quan li\xean quan.\n\nN\u1ebfu g\u1eb7p v\u1ea5n \u0111\u1ec1 t\u1ea1i n\u01a1i l\xe0m vi\u1ec7c nh\u01b0 kh\xf4ng \u0111\u01b0\u1ee3c tr\u1ea3 l\u01b0\u01a1ng ho\u1eb7c b\u1ecb \u0111\u1ed1i x\u1eed kh\xf4ng ph\xf9 h\u1ee3p, thay v\xec c\u1ed1 gi\u1ea3i quy\u1ebft m\u1ed9t m\xecnh c\xf3 th\u1ec3 y\xeau c\u1ea7u s\u1ef1 h\u1ed7 tr\u1ee3 t\u1eeb c\u01a1 quan li\xean quan ho\u1eb7c trung t\xe2m t\u01b0 v\u1ea5n.\n\n\u0110\u1ec3 sinh s\u1ed1ng \u1ed5n \u0111\u1ecbnh trong x\xe3 h\u1ed9i H\xe0n Qu\u1ed1c, \u0111i\u1ec1u quan tr\u1ecdng l\xe0 v\u1eeba bi\u1ebft v\xe0 b\u1ea3o v\u1ec7 quy\u1ec1n l\u1ee3i c\u1ee7a m\xecnh, v\u1eeba tu\xe2n th\u1ee7 ph\xe1p lu\u1eadt, quy t\u1eafc v\xe0 c\xe1c th\u1ee7 t\u1ee5c c\u1ea7n thi\u1ebft.\n","\uccb4\ub958\uc640 \uadfc\ub85c \ubb38\uc81c \uc0c1\ub2f4\ud558\uae30","\uc548: \uc548\ub155\ud558\uc138\uc694. \ud55c\uad6d\uc5d0\uc11c \uc77c\ud558\uace0 \uc788\ub294\ub370 \uad81\uae08\ud55c \uac83\uc774 \uc788\uc5b4\uc11c \uc654\uc2b5\ub2c8\ub2e4.\n\n\uc0c1\ub2f4\uc6d0: \ub124. \uc5b4\ub5a4 \ub0b4\uc6a9\uc774 \uad81\uae08\ud558\uc138\uc694?\n\n\uc548: \uc9c0\uae08 \uac00\uc9c4 \uccb4\ub958\uc790\uaca9\uc73c\ub85c \ub2e4\ub978 \ud68c\uc0ac\uc5d0\uc11c\ub3c4 \uc77c\ud560 \uc218 \uc788\ub294\uc9c0 \uc54c\uace0 \uc2f6\uc2b5\ub2c8\ub2e4.\n\n\uc0c1\ub2f4\uc6d0: \uccb4\ub958\uc790\uaca9\uc5d0 \ub530\ub77c \uac00\ub2a5\ud55c \ud65c\ub3d9\uacfc \uc808\ucc28\uac00 \ub2e4\ub97c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc815\ud655\ud55c \uccb4\ub958\uc790\uaca9\uc744 \ud655\uc778\ud574 \ubd10\uc57c \ud569\ub2c8\ub2e4.\n\n\uc548: \uadf8\ub7ec\uba74 \ud68c\uc0ac\ub97c \uc62e\uae30\uae30 \uc804\uc5d0 \uba3c\uc800 \ud655\uc778\ud574\uc57c\uaca0\ub124\uc694.\n\n\uc0c1\ub2f4\uc6d0: \ub124. \uc77c\uc744 \uc2dc\uc791\ud558\uae30 \uc804\uc5d0 \ud544\uc694\ud55c \ud5c8\uac00\ub098 \uc2e0\uace0\uac00 \uc788\ub294\uc9c0 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.\n\n\uc548: \uadf8\ub9ac\uace0 \ud68c\uc0ac\uc5d0\uc11c \uc784\uae08\uc744 \uc81c\ub300\ub85c \ubc1b\uc9c0 \ubabb\ud558\uba74 \uc5b4\ub5bb\uac8c \ud574\uc57c \ud574\uc694?\n\n\uc0c1\ub2f4\uc6d0: \uc784\uae08\uccb4\ubd88 \ubb38\uc81c\uac00 \uc788\uc73c\uba74 \uad00\ub828 \ub178\ub3d9\uae30\uad00\uc5d0 \uc0c1\ub2f4\ud558\uac70\ub098 \ub3c4\uc6c0\uc744 \uc694\uccad\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc548: \uc8fc\uc18c\uac00 \ubc14\ub010 \uacbd\uc6b0\uc5d0\ub3c4 \uc2e0\uace0\ud574\uc57c \ud574\uc694?\n\n\uc0c1\ub2f4\uc6d0: \uccb4\ub958\uc640 \uad00\ub828\ub41c \ubcc0\uacbd \uc0ac\ud56d\uc740 \ud544\uc694\ud55c \uc2e0\uace0\uac00 \uc788\ub294\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.\n\n\uc548: \uc5b4\ub514\uc5d0\uc11c \uc815\ud655\ud55c \uc815\ubcf4\ub97c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc88b\uc544\uc694?\n\n\uc0c1\ub2f4\uc6d0: \ucd9c\uc785\uad6d\uc774\ub098 \ub178\ub3d9 \uad00\ub828 \uacf5\uc2dd \uae30\uad00\uc758 \uc548\ub0b4\ub97c \ud655\uc778\ud558\ub294 \uac83\uc774 \uac00\uc7a5 \uc88b\uc2b5\ub2c8\ub2e4.\n\n\uc548: \ub124. \uc55e\uc73c\ub85c\ub294 \uba3c\uc800 \ud655\uc778\ud558\uace0 \ucc98\ub9ac\ud558\uaca0\uc2b5\ub2c8\ub2e4.\n\n\uc0c1\ub2f4\uc6d0: \ub124. \uc790\uc2e0\uc758 \uad8c\ub9ac\ubfd0\ub9cc \uc544\ub2c8\ub77c \ud544\uc694\ud55c \uc808\ucc28\uc640 \uc758\ubb34\ub3c4 \ud568\uaed8 \uc54c\uc544 \ub450\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.\n","An: Xin ch\xe0o. T\xf4i \u0111ang l\xe0m vi\u1ec7c t\u1ea1i H\xe0n Qu\u1ed1c v\xe0 c\xf3 v\xe0i \u0111i\u1ec1u mu\u1ed1n h\u1ecfi.\n\nNh\xe2n vi\xean t\u01b0 v\u1ea5n: V\xe2ng. Anh mu\u1ed1n h\u1ecfi n\u1ed9i dung g\xec?\n\nAn: T\xf4i mu\u1ed1n bi\u1ebft v\u1edbi t\u01b0 c\xe1ch l\u01b0u tr\xfa hi\u1ec7n t\u1ea1i th\xec t\xf4i c\xf3 th\u1ec3 l\xe0m vi\u1ec7c \u1edf m\u1ed9t c\xf4ng ty kh\xe1c kh\xf4ng.\n\nNh\xe2n vi\xean: T\xf9y theo t\u01b0 c\xe1ch l\u01b0u tr\xfa m\xe0 ho\u1ea1t \u0111\u1ed9ng \u0111\u01b0\u1ee3c ph\xe9p v\xe0 th\u1ee7 t\u1ee5c c\xf3 th\u1ec3 kh\xe1c nhau. C\u1ea7n ki\u1ec3m tra ch\xednh x\xe1c lo\u1ea1i t\u01b0 c\xe1ch l\u01b0u tr\xfa c\u1ee7a anh.\n\nAn: V\u1eady tr\u01b0\u1edbc khi chuy\u1ec3n c\xf4ng ty t\xf4i n\xean ki\u1ec3m tra tr\u01b0\u1edbc.\n\nNh\xe2n vi\xean: \u0110\xfang v\u1eady. Tr\u01b0\u1edbc khi b\u1eaft \u0111\u1ea7u c\xf4ng vi\u1ec7c, vi\u1ec7c ki\u1ec3m tra xem c\xf3 gi\u1ea5y ph\xe9p ho\u1eb7c khai b\xe1o c\u1ea7n thi\u1ebft hay kh\xf4ng r\u1ea5t quan tr\u1ecdng.\n\nAn: N\u1ebfu c\xf4ng ty kh\xf4ng tr\u1ea3 l\u01b0\u01a1ng \u0111\u1ea7y \u0111\u1ee7 th\xec t\xf4i ph\u1ea3i l\xe0m th\u1ebf n\xe0o?\n\nNh\xe2n vi\xean: N\u1ebfu c\xf3 v\u1ea5n \u0111\u1ec1 n\u1ee3 l\u01b0\u01a1ng, anh c\xf3 th\u1ec3 t\u01b0 v\u1ea5n ho\u1eb7c y\xeau c\u1ea7u h\u1ed7 tr\u1ee3 t\u1eeb c\u01a1 quan lao \u0111\u1ed9ng li\xean quan.\n\nAn: N\u1ebfu \u0111\u1ecba ch\u1ec9 thay \u0111\u1ed5i th\xec c\u0169ng ph\u1ea3i khai b\xe1o \xe0?\n\nNh\xe2n vi\xean: \u0110\u1ed1i v\u1edbi c\xe1c thay \u0111\u1ed5i li\xean quan \u0111\u1ebfn c\u01b0 tr\xfa, c\u1ea7n ki\u1ec3m tra xem c\xf3 ngh\u0129a v\u1ee5 khai b\xe1o hay kh\xf4ng.\n\nAn: T\xf4i n\xean ki\u1ec3m tra th\xf4ng tin ch\xednh x\xe1c \u1edf \u0111\xe2u?\n\nNh\xe2n vi\xean: T\u1ed1t nh\u1ea5t n\xean ki\u1ec3m tra h\u01b0\u1edbng d\u1eabn t\u1eeb c\xe1c c\u01a1 quan ch\xednh th\u1ee9c v\u1ec1 xu\u1ea5t nh\u1eadp c\u1ea3nh ho\u1eb7c lao \u0111\u1ed9ng.\n\nAn: V\xe2ng. T\u1eeb gi\u1edd t\xf4i s\u1ebd ki\u1ec3m tra tr\u01b0\u1edbc r\u1ed3i m\u1edbi x\u1eed l\xfd.\n\nNh\xe2n vi\xean: V\xe2ng. N\xean bi\u1ebft c\u1ea3 quy\u1ec1n l\u1ee3i c\u1ee7a m\xecnh l\u1eabn c\xe1c th\u1ee7 t\u1ee5c v\xe0 ngh\u0129a v\u1ee5 c\u1ea7n th\u1ef1c hi\u1ec7n.\n",A.idN,A.hpK,A.jlL,A.iWP)
A.ijI=s(["Hi\u1ec3u kh\xe1i ni\u1ec7m \uc218\ub3c4\uad8c.","Bi\u1ebft \uc218\ub3c4\uad8c g\u1ed3m \uc11c\uc6b8\ud2b9\ubcc4\uc2dc, \uc778\ucc9c\uad11\uc5ed\uc2dc v\xe0 \uacbd\uae30\ub3c4.","Hi\u1ec3u vai tr\xf2 c\u1ee7a Seoul l\xe0 th\u1ee7 \u0111\xf4 v\xe0 trung t\xe2m ch\xednh tr\u1ecb, kinh t\u1ebf, v\u0103n h\xf3a.","Bi\u1ebft \u0111\u1eb7c \u0111i\u1ec3m c\u01a1 b\u1ea3n c\u1ee7a Incheon v\xe0 Gyeonggi-do.","Hi\u1ec3u h\u1ec7 th\u1ed1ng giao th\xf4ng ph\xe1t tri\u1ec3n c\u1ee7a v\xf9ng th\u1ee7 \u0111\xf4.","Bi\u1ebft m\u1ed9t s\u1ed1 \u01b0u \u0111i\u1ec3m v\xe0 v\u1ea5n \u0111\u1ec1 do t\u1eadp trung d\xe2n s\u1ed1 v\xe0 ch\u1ee9c n\u0103ng \u0111\xf4 th\u1ecb.","Nh\u1eadn bi\u1ebft \ud55c\uac15 v\xe0 \uc778\ucc9c\uad6d\uc81c\uacf5\ud56d.","Luy\u1ec7n c\xe1c c\xe2u h\u1ecfi \u0111\u1ecba l\xfd th\u01b0\u1eddng g\u1eb7p trong KIIP."],t.s)
A.ijw=s(["\uc218\ub3c4\uad8c\uc740 \uc11c\uc6b8\ud2b9\ubcc4\uc2dc, \uc778\ucc9c\uad11\uc5ed\uc2dc, \uacbd\uae30\ub3c4\ub97c \ud3ec\ud568\ud558\ub294 \uc9c0\uc5ed\uc785\ub2c8\ub2e4.","\uc11c\uc6b8\uc740 \ub300\ud55c\ubbfc\uad6d\uc758 \uc218\ub3c4\uc774\uba70 \uc815\uce58, \uacbd\uc81c, \ubb38\ud654\uc758 \uc911\uc694\ud55c \uc911\uc2ec\uc9c0\uc785\ub2c8\ub2e4.","\uc11c\uc6b8\uc5d0\ub294 \uad6d\ud68c, \uc815\ubd80 \uad00\ub828 \uae30\uad00, \uae30\uc5c5, \ub300\ud559, \ubb38\ud654\uc2dc\uc124 \ub4f1\uc774 \ub9ce\uc774 \ubaa8\uc5ec \uc788\uc2b5\ub2c8\ub2e4.","\ud55c\uac15\uc740 \uc11c\uc6b8\uc744 \uac00\ub85c\uc9c8\ub7ec \ud750\ub974\ub294 \ub300\ud45c\uc801\uc778 \uac15\uc785\ub2c8\ub2e4.","\uc778\ucc9c\uc740 \uc11c\ud574\uc640 \uc811\ud574 \uc788\uc73c\uba70 \ud56d\uad6c\uc640 \uad6d\uc81c\uacf5\ud56d\uc774 \ubc1c\ub2ec\ud55c \ub3c4\uc2dc\uc785\ub2c8\ub2e4.","\uc778\ucc9c\uad6d\uc81c\uacf5\ud56d\uc740 \ud55c\uad6d\uacfc \uc138\uacc4 \uc5ec\ub7ec \uc9c0\uc5ed\uc744 \uc5f0\uacb0\ud558\ub294 \uc911\uc694\ud55c \uad6d\uc81c\uad50\ud1b5 \uc2dc\uc124\uc785\ub2c8\ub2e4.","\uacbd\uae30\ub3c4\ub294 \uc11c\uc6b8\uacfc \uc778\ucc9c\uc744 \ub458\ub7ec\uc2f8\uace0 \uc788\uc73c\uba70 \ub9ce\uc740 \ub3c4\uc2dc\uc640 \uc0b0\uc5c5\uc9c0\uc5ed\uc774 \ubc1c\ub2ec\ud574 \uc788\uc2b5\ub2c8\ub2e4.","\uc218\ub3c4\uad8c\uc740 \uc9c0\ud558\ucca0, \ubc84\uc2a4, \ucca0\ub3c4, \uace0\uc18d\ub3c4\ub85c \ub4f1 \uad50\ud1b5\ub9dd\uc774 \uc798 \ubc1c\ub2ec\ud574 \uc788\uc2b5\ub2c8\ub2e4.","\ub9ce\uc740 \uc778\uad6c\uc640 \uae30\ub2a5\uc774 \uc218\ub3c4\uad8c\uc5d0 \uc9d1\uc911\ub418\uba74\uc11c \uad50\ud1b5 \ud63c\uc7a1, \ub192\uc740 \uc8fc\uac70\ube44 \ub4f1 \uc5ec\ub7ec \ub3c4\uc2dc \ubb38\uc81c\uac00 \ub098\ud0c0\ub098\uae30\ub3c4 \ud569\ub2c8\ub2e4.","\uc218\ub3c4\uad8c\uacfc \uc9c0\ubc29\uc774 \uade0\ud615 \uc788\uac8c \ubc1c\uc804\ud558\ub294 \uac83\uc740 \ud55c\uad6d\uc758 \uc911\uc694\ud55c \uc9c0\uc5ed \ubb38\uc81c \uc911 \ud558\ub098\uc785\ub2c8\ub2e4."],t.s)
