A.ixq=s(["\ud6a8 = l\xf2ng hi\u1ebfu th\u1ea3o; kh\xf4ng \u0111\u01a1n gi\u1ea3n ch\u1ec9 l\xe0 nghe l\u1eddi ng\u01b0\u1eddi l\u1edbn.","\uc815 = t\xecnh c\u1ea3m g\u1eafn b\xf3 \u0111\u01b0\u1ee3c h\xecnh th\xe0nh trong quan h\u1ec7 gi\u1eefa con ng\u01b0\u1eddi.","\uc5f0\uace0 = m\u1ed1i li\xean h\u1ec7 \u0111\u01b0\u1ee3c h\xecnh th\xe0nh qua gia \u0111\xecnh, qu\xea qu\xe1n, tr\u01b0\u1eddng h\u1ecdc ho\u1eb7c c\xe1c m\u1ed1i quan h\u1ec7 kh\xe1c.","\ud608\uc5f0 = quan h\u1ec7 huy\u1ebft th\u1ed1ng.","\uc9c0\uc5f0 = quan h\u1ec7 d\u1ef1a tr\xean qu\xea qu\xe1n ho\u1eb7c khu v\u1ef1c.","\ud559\uc5f0 = quan h\u1ec7 d\u1ef1a tr\xean tr\u01b0\u1eddng h\u1ecdc.","\uc778\ub9e5 = m\u1ea1ng l\u01b0\u1edbi c\xe1c m\u1ed1i quan h\u1ec7 c\xe1 nh\xe2n, kh\xf4ng ho\xe0n to\xe0n gi\u1ed1ng \uc5f0\uace0.","C\xf3 quan h\u1ec7 x\xe3 h\u1ed9i kh\xf4ng ph\u1ea3i l\xe0 \u0111i\u1ec1u x\u1ea5u; v\u1ea5n \u0111\u1ec1 ph\xe1t sinh khi quan h\u1ec7 \u0111\u01b0\u1ee3c s\u1eed d\u1ee5ng \u0111\u1ec3 t\u1ea1o l\u1ee3i \xedch kh\xf4ng c\xf4ng b\u1eb1ng.","\uacf5\uc815\ud558\ub2e4 = c\xf4ng b\u1eb1ng; \uacf5\uc815\uc131 = t\xednh c\xf4ng b\u1eb1ng."],t.s)
A.hLd=s(["\ud6a8 \u2192 l\xf2ng hi\u1ebfu th\u1ea3o.","\uc815 \u2192 t\xecnh c\u1ea3m, s\u1ef1 g\u1eafn b\xf3 gi\u1eefa ng\u01b0\u1eddi v\u1edbi ng\u01b0\u1eddi.","\uacf5\ub3d9\uccb4 \uc758\uc2dd \u2192 \xfd th\u1ee9c c\u1ed9ng \u0111\u1ed3ng.","\uc5f0\uace0 \u2192 m\u1ed1i li\xean h\u1ec7 ho\u1eb7c quan h\u1ec7 g\u1eafn k\u1ebft.","\ud608\uc5f0 \u2192 quan h\u1ec7 huy\u1ebft th\u1ed1ng.","\uc9c0\uc5f0 \u2192 quan h\u1ec7 d\u1ef1a tr\xean \u0111\u1ecba ph\u01b0\u01a1ng ho\u1eb7c qu\xea qu\xe1n.","\ud559\uc5f0 \u2192 quan h\u1ec7 d\u1ef1a tr\xean tr\u01b0\u1eddng h\u1ecdc.","\uc5f0\uace0 \uad00\uacc4\ub294 \uc11c\ub85c \ub3d5\ub294 \ub370 \uae0d\uc815\uc801\uc778 \uc5ed\ud560\uc744 \ud560 \uc218\ub3c4 \uc788\ub2e4.","\uc5f0\uace0\ub97c \uc9c0\ub098\uce58\uac8c \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud558\uba74 \uacf5\uc815\uc131\uc744 \ud574\uce60 \uc218 \uc788\ub2e4.","\ud604\ub300 \uc0ac\ud68c\uc5d0\uc11c\ub294 \ub2a5\ub825\uacfc \uacf5\uc815\ud55c \uc808\ucc28\ub97c \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4."],t.s)
