A.i1h=s(["\uba85\uc808 = ng\xe0y l\u1ec5 truy\u1ec1n th\u1ed1ng.","\uc124\ub0a0 = m\xf9ng 1 th\xe1ng 1 \xe2m l\u1ecbch.","\ucd94\uc11d = ng\xe0y 15 th\xe1ng 8 \xe2m l\u1ecbch.","\uc138\ubc30 = l\u1ec5 ch\xe0o ng\u01b0\u1eddi l\u1edbn d\u1ecbp Seollal.","\uc138\ubc43\ub3c8 = ti\u1ec1n m\u1eebng tu\u1ed5i.","\ub5a1\uad6d = m\xf3n th\u01b0\u1eddng g\u1eafn v\u1edbi Seollal.","\uc1a1\ud3b8 = m\xf3n th\u01b0\u1eddng g\u1eafn v\u1edbi Chuseok.","\uc131\ubb18 = vi\u1ebfng m\u1ed9 t\u1ed5 ti\xean.","\uadc0\uc131 = v\u1ec1 qu\xea d\u1ecbp l\u1ec5.","\uc5f0\ud734 = k\u1ef3 ngh\u1ec9 nhi\u1ec1u ng\xe0y.","\uba85\uc808\uc5d0\ub294 \uac00\uc871\uacfc \uce5c\ucc99\uc774 \ud568\uaed8 \uc2dc\uac04\uc744 \ubcf4\ub0b4\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.","\uba85\uc808\uc744 \ubcf4\ub0b4\ub294 \ubc29\uc2dd\uc740 \uac00\uc815\uacfc \uc9c0\uc5ed\uc5d0 \ub530\ub77c \ub2e4\ub97c \uc218 \uc788\uc2b5\ub2c8\ub2e4."],t.s)
A.fAM=new B.dJ(14,"\ubb38\ud654","\ud55c\uad6d\uc758 \uba85\uc808","C\xe1c ng\xe0y l\u1ec5 truy\u1ec1n th\u1ed1ng H\xe0n Qu\u1ed1c",A.jke,A.iR3,A.haK,A.h6s,"\ud55c\uad6d\uc758 \ub300\ud45c\uc801\uc778 \uba85\uc808","\ud55c\uad6d\uc758 \ub300\ud45c\uc801\uc778 \uc804\ud1b5 \uba85\uc808\uc5d0\ub294 \uc124\ub0a0\uacfc \ucd94\uc11d\uc774 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc124\ub0a0\uc740 \uc74c\ub825 1\uc6d4 1\uc77c\uc785\ub2c8\ub2e4. \uc124\ub0a0\uc5d0\ub294 \uac00\uc871\uc774 \ubaa8\uc5ec \uc0c8\ud574 \uc778\uc0ac\ub97c \ud558\uace0 \uc5b4\ub978\ub4e4\uaed8 \uc138\ubc30\ub97c \ud558\uae30\ub3c4 \ud569\ub2c8\ub2e4. \uc544\uc774\ub4e4\uc740 \uc138\ubc30\ub97c \ud55c \ud6c4 \uc138\ubc43\ub3c8\uc744 \ubc1b\uae30\ub3c4 \ud569\ub2c8\ub2e4. \ub610\ud55c \ub5a1\uad6d\uc744 \uba39\ub294 \ud48d\uc2b5\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.\n\n\ucd94\uc11d\uc740 \uc74c\ub825 8\uc6d4 15\uc77c\uc785\ub2c8\ub2e4. \ucd94\uc11d\uc5d0\ub294 \uac00\uc871\uacfc \uce5c\ucc99\uc774 \ubaa8\uc774\uace0 \uc870\uc0c1\uc744 \uc0dd\uac01\ud558\uba70 \uc131\ubb18\ub97c \uac00\uae30\ub3c4 \ud569\ub2c8\ub2e4. \ub610\ud55c \uc1a1\ud3b8\uc744 \ub9cc\ub4e4\uc5b4 \uba39\ub294 \ud48d\uc2b5\ub3c4 \uc798 \uc54c\ub824\uc838 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uacfc\uac70\uc5d0\ub294 \ub9ce\uc740 \uc0ac\ub78c\uc774 \uba85\uc808\uc5d0 \uace0\ud5a5\uc73c\ub85c \uac00\uc11c \uac00\uc871\uacfc \uc2dc\uac04\uc744 \ubcf4\ub0c8\uc2b5\ub2c8\ub2e4. \uc624\ub298\ub0a0\uc5d0\ub3c4 \uba85\uc808\uc5d0 \uace0\ud5a5\uc744 \ucc3e\ub294 \uc0ac\ub78c\uc774 \ub9ce\uc9c0\ub9cc \uc5ec\ud589\uc744 \uac00\uac70\ub098 \uc9d1\uc5d0\uc11c \uc26c\ub294 \ub4f1 \ub2e4\uc591\ud55c \ubc29\ubc95\uc73c\ub85c \uba85\uc808\uc744 \ubcf4\ub0b4\ub294 \uc0ac\ub78c\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uba85\uc808\uc744 \ubcf4\ub0b4\ub294 \ubc29\uc2dd\uc740 \uac00\uc815\uacfc \uc9c0\uc5ed\uc5d0 \ub530\ub77c \ub2e4\ub97c \uc218 \uc788\uc9c0\ub9cc \uac00\uc871\uacfc \ud568\uaed8 \uc2dc\uac04\uc744 \ubcf4\ub0b4\uace0 \uc11c\ub85c\uc758 \uc548\ubd80\ub97c \ubb3b\ub294 \uac83\uc740 \uc911\uc694\ud55c \uc758\ubbf8\ub97c \uac00\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.\n","Hai ng\xe0y l\u1ec5 truy\u1ec1n th\u1ed1ng ti\xeau bi\u1ec3u c\u1ee7a H\xe0n Qu\u1ed1c l\xe0 Seollal v\xe0 Chuseok.\n\nSeollal l\xe0 ng\xe0y m\xf9ng 1 th\xe1ng 1 \xe2m l\u1ecbch. V\xe0o Seollal, gia \u0111\xecnh t\u1ee5 h\u1ecdp, ch\xfac m\u1eebng n\u0103m m\u1edbi v\xe0 c\xf3 th\u1ec3 th\u1ef1c hi\u1ec7n l\u1ec5 Sebae v\u1edbi ng\u01b0\u1eddi l\u1edbn tu\u1ed5i. Tr\u1ebb em sau khi Sebae c\u0169ng c\xf3 th\u1ec3 nh\u1eadn ti\u1ec1n m\u1eebng tu\u1ed5i. Ngo\xe0i ra c\xf2n c\xf3 phong t\u1ee5c \u0103n canh b\xe1nh g\u1ea1o.\n\nChuseok l\xe0 ng\xe0y 15 th\xe1ng 8 \xe2m l\u1ecbch. V\xe0o Chuseok, gia \u0111\xecnh v\xe0 h\u1ecd h\xe0ng t\u1ee5 h\u1ecdp, t\u01b0\u1edfng nh\u1edb t\u1ed5 ti\xean v\xe0 c\xf3 th\u1ec3 \u0111i vi\u1ebfng m\u1ed9. Phong t\u1ee5c l\xe0m v\xe0 \u0103n Songpyeon c\u0169ng r\u1ea5t n\u1ed5i ti\u1ebfng.\n\nTr\u01b0\u1edbc \u0111\xe2y c\xf3 nhi\u1ec1u ng\u01b0\u1eddi v\u1ec1 qu\xea v\xe0o ng\xe0y l\u1ec5 \u0111\u1ec3 d\xe0nh th\u1eddi gian v\u1edbi gia \u0111\xecnh. Ng\xe0y nay v\u1eabn c\xf3 nhi\u1ec1u ng\u01b0\u1eddi v\u1ec1 qu\xea, nh\u01b0ng c\u0169ng c\xf3 ng\u01b0\u1eddi \u0111i du l\u1ecbch ho\u1eb7c ngh\u1ec9 \u1edf nh\xe0 trong k\u1ef3 ngh\u1ec9 l\u1ec5.\n\nC\xe1ch \u0111\xf3n ng\xe0y l\u1ec5 c\xf3 th\u1ec3 kh\xe1c nhau t\xf9y gia \u0111\xecnh v\xe0 khu v\u1ef1c, nh\u01b0ng vi\u1ec7c d\xe0nh th\u1eddi gian c\xf9ng gia \u0111\xecnh v\xe0 h\u1ecfi th\u0103m nhau v\u1eabn c\xf3 \xfd ngh\u0129a quan tr\u1ecdng.\n","\ucd94\uc11d \uacc4\ud68d \uc774\uc57c\uae30\ud558\uae30","\ubbfc\uc218: \uc548 \uc528, \uc774\ubc88 \ucd94\uc11d\uc5d0 \ubb50 \ud560 \uac70\uc608\uc694?\n\n\uc548: \uac00\uc871\ud558\uace0 \uac19\uc774 \uc2dc\uac04\uc744 \ubcf4\ub0b4\ub824\uace0 \ud574\uc694.\n\n\ubbfc\uc218: \uace0\ud5a5\uc5d0 \uac00\uc694?\n\n\uc548: \ub124. \uc5f0\ud734 \uccab\ub0a0\uc5d0 \uace0\ud5a5\uc5d0 \ub0b4\ub824\uac08 \uc608\uc815\uc774\uc5d0\uc694.\n\n\ubbfc\uc218: \ucd94\uc11d\uc5d0\ub294 \ubcf4\ud1b5 \ubb50 \ud574\uc694?\n\n\uc548: \uac00\uc871\uc774 \uac19\uc774 \uc2dd\uc0ac\ud558\uace0 \uce5c\ucc99\ub4e4\ub3c4 \ub9cc\ub098\uc694. \ubbfc\uc218 \uc528\ub294\uc694?\n\n\ubbfc\uc218: \uc800\ub294 \uac00\uc871\uacfc \uc131\ubb18\ub97c \ub2e4\ub140\uc624\uace0 \uc1a1\ud3b8\ub3c4 \uba39\uc744 \uac70\uc608\uc694.\n\n\uc548: \uc1a1\ud3b8\uc744 \uc9c1\uc811 \ub9cc\ub4e4\uc5b4\uc694?\n\n\ubbfc\uc218: \uc608\uc804\uc5d0\ub294 \ud560\uba38\ub2c8\uc640 \uac19\uc774 \ub9cc\ub4e4\uc5c8\ub294\ub370 \uc694\uc998\uc740 \uc0ac\uc11c \uba39\uae30\ub3c4 \ud574\uc694.\n\n\uc548: \uadf8\ub807\uad70\uc694. \uba85\uc808 \ubcf4\ub0b4\ub294 \ubc29\ubc95\ub3c4 \ub9ce\uc774 \ub2ec\ub77c\uc9c0\ub294 \uac83 \uac19\uc544\uc694.\n\n\ubbfc\uc218: \ub9de\uc544\uc694. \uadf8\ub798\ub3c4 \uac00\uc871\uacfc \ud568\uaed8 \uc2dc\uac04\uc744 \ubcf4\ub0b4\ub294 \uac74 \uc5ec\uc804\ud788 \uc911\uc694\ud55c \uac83 \uac19\uc544\uc694.\n","Minsu: An, Chuseok l\u1ea7n n\xe0y anh s\u1ebd l\xe0m g\xec?\n\nAn: T\xf4i \u0111\u1ecbnh d\xe0nh th\u1eddi gian c\xf9ng gia \u0111\xecnh.\n\nMinsu: Anh v\u1ec1 qu\xea \xe0?\n\nAn: V\xe2ng. T\xf4i d\u1ef1 \u0111\u1ecbnh v\u1ec1 qu\xea v\xe0o ng\xe0y \u0111\u1ea7u k\u1ef3 ngh\u1ec9.\n\nMinsu: V\xe0o Chuseok th\u01b0\u1eddng l\xe0m g\xec?\n\nAn: Gia \u0111\xecnh \u0103n c\xf9ng nhau v\xe0 g\u1eb7p h\u1ecd h\xe0ng. C\xf2n Minsu?\n\nMinsu: T\xf4i s\u1ebd \u0111i vi\u1ebfng m\u1ed9 c\xf9ng gia \u0111\xecnh v\xe0 \u0103n Songpyeon.\n\nAn: Anh t\u1ef1 l\xe0m Songpyeon \xe0?\n\nMinsu: Tr\u01b0\u1edbc \u0111\xe2y t\xf4i l\xe0m c\xf9ng b\xe0, nh\u01b0ng ng\xe0y nay c\u0169ng c\xf3 khi mua v\u1ec1 \u0103n.\n\nAn: Ra v\u1eady. C\xf3 v\u1ebb c\xe1ch \u0111\xf3n ng\xe0y l\u1ec5 c\u0169ng thay \u0111\u1ed5i nhi\u1ec1u.\n\nMinsu: \u0110\xfang v\u1eady. Nh\u01b0ng t\xf4i ngh\u0129 d\xe0nh th\u1eddi gian c\xf9ng gia \u0111\xecnh v\u1eabn r\u1ea5t quan tr\u1ecdng.\n",A.heU,A.iae,A.j9Q,A.i1h)
A.iRR=s(["Hi\u1ec3u kh\xe1i ni\u1ec7m \ub300\uc911\ub9e4\uccb4 v\xe0 vai tr\xf2 c\u1ee7a truy\u1ec1n th\xf4ng trong x\xe3 h\u1ed9i.","Bi\u1ebft c\xe1c lo\u1ea1i ph\u01b0\u01a1ng ti\u1ec7n truy\u1ec1n th\xf4ng nh\u01b0 \uc2e0\ubb38, \ubc29\uc1a1, \uc778\ud130\ub137 v\xe0 SNS.","H\u1ecdc t\u1eeb v\u1ef1ng th\u01b0\u1eddng g\u1eb7p khi \u0111\u1ecdc tin t\u1ee9c b\u1eb1ng ti\u1ebfng H\xe0n.","Bi\u1ebft ph\xe2n bi\u1ec7t \uc0ac\uc2e4, \uc758\uacac v\xe0 \uad11\uace0.","Hi\u1ec3u t\u1ea7m quan tr\u1ecdng c\u1ee7a vi\u1ec7c ki\u1ec3m tra ngu\u1ed3n th\xf4ng tin.","C\xf3 th\u1ec3 \u0111\u1ecdc hi\u1ec3u m\u1ed9t \u0111o\u1ea1n tin t\u1ee9c ng\u1eafn.","Luy\u1ec7n c\xe2u h\u1ecfi li\xean quan \u0111\u1ebfn truy\u1ec1n th\xf4ng v\xe0 s\u1eed d\u1ee5ng th\xf4ng tin."],t.s)
A.jz5=s(["\ub300\uc911\ub9e4\uccb4\ub294 \ub9ce\uc740 \uc0ac\ub78c\uc5d0\uac8c \uc815\ubcf4\uc640 \uc18c\uc2dd\uc744 \uc804\ub2ec\ud558\ub294 \uc218\ub2e8\uc785\ub2c8\ub2e4.","\uc2e0\ubb38, \ud154\ub808\ube44\uc804, \ub77c\ub514\uc624, \uc778\ud130\ub137 \ub4f1\uc740 \ub300\ud45c\uc801\uc778 \ub300\uc911\ub9e4\uccb4\uc785\ub2c8\ub2e4.","\ucd5c\uadfc\uc5d0\ub294 \uc2a4\ub9c8\ud2b8\ud3f0\uacfc SNS\ub97c \ud1b5\ud574 \uc815\ubcf4\ub97c \uc5bb\ub294 \uc0ac\ub78c\uc774 \ub9ce\uc2b5\ub2c8\ub2e4.","\ub274\uc2a4\ub97c \ubcfc \ub54c \uc0ac\uc2e4\uacfc \uc758\uacac\uc744 \uad6c\ubd84\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc778\ud130\ub137\uc5d0 \uc788\ub294 \ubaa8\ub4e0 \uc815\ubcf4\uac00 \uc815\ud655\ud55c \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.","\uc815\ubcf4\ub97c \uc774\uc6a9\ud558\uae30 \uc804\uc5d0 \ucd9c\ucc98\uc640 \ub0b4\uc6a9\uc744 \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.","\ub300\uc911\ub9e4\uccb4\ub294 \uc815\ubcf4 \uc804\ub2ec\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc0ac\ud68c\uc758 \uc5ec\ub860 \ud615\uc131\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],t.s)
