n=B.a([B.dn("\uc0c8 \uacc4\uc88c\ub97c \uac1c\uc124\ud558\ub824\uace0 \uc654\uc5b4\uc694.",i,"T\xf4i \u0111\u1ebfn \u0111\u1ec3 m\u1edf t\xe0i kho\u1ea3n m\u1edbi."),B.dn("\uc678\uad6d\uc778\ub4f1\ub85d\uc99d\uacfc \ud734\ub300\uc804\ud654\uac00 \uc788\uc73c\uc138\uc694?",h,"B\u1ea1n c\xf3 th\u1ebb \u0111\u0103ng k\xfd ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i v\xe0 \u0111i\u1ec7n tho\u1ea1i kh\xf4ng?"),B.dn("\ub124, \uadf8\ub9ac\uace0 \uc778\ud130\ub137\ubc45\ud0b9\ub3c4 \uc2e0\uccad\ud558\uace0 \uc2f6\uc5b4\uc694.",i,"C\xf3, v\xe0 t\xf4i c\u0169ng mu\u1ed1n \u0111\u0103ng k\xfd Internet Banking."),B.dn("\uba3c\uc800 \ubcf8\uc778 \ud655\uc778\uc744 \ud55c \ud6c4 \ube44\ubc00\ubc88\ud638\ub97c \uc124\uc815\ud574 \uc8fc\uc138\uc694.",h,"Tr\u01b0\u1edbc ti\xean h\xe3y x\xe1c minh danh t\xednh r\u1ed3i \u0111\u1eb7t m\u1eadt kh\u1ea9u."),B.dn("\ud558\ub8e8 \uc774\uccb4 \ud55c\ub3c4\ub294 \uc5bc\ub9c8\uc608\uc694?",i,"H\u1ea1n m\u1ee9c chuy\u1ec3n kho\u1ea3n m\u1ed9t ng\xe0y l\xe0 bao nhi\xeau?"),B.dn("\uae30\ubcf8 \ud55c\ub3c4\ub294 \ubc31\ub9cc \uc6d0\uc774\uace0 \ub098\uc911\uc5d0 \ubcc0\uacbd\ud560 \uc218 \uc788\uc5b4\uc694.",h,"H\u1ea1n m\u1ee9c m\u1eb7c \u0111\u1ecbnh l\xe0 m\u1ed9t tri\u1ec7u won v\xe0 c\xf3 th\u1ec3 thay \u0111\u1ed5i sau.")],a4)
q=B.uU(B.a(["\uc1a1\uae08\ud558\ub2e4 th\u01b0\u1eddng nh\u1ea5n m\u1ea1nh g\u1eedi ti\u1ec1n; \uc774\uccb4\ud558\ub2e4 l\xe0 chuy\u1ec3n ti\u1ec1n gi\u1eefa c\xe1c t\xe0i kho\u1ea3n.","\ube44\ubc00\ubc88\ud638\ub294 \ub9d0\ud558\uba74 \uc548 \ub3fc\uc694: kh\xf4ng cung c\u1ea5p m\u1eadt kh\u1ea9u cho ng\u01b0\u1eddi g\u1ecdi \u0111i\u1ec7n ho\u1eb7c nh\u1eafn tin.","\uc794\uc561 l\xe0 s\u1ed1 ti\u1ec1n c\xf2n l\u1ea1i; \uac70\ub798 \ub0b4\uc5ed l\xe0 danh s\xe1ch c\xe1c giao d\u1ecbch \u0111\xe3 ph\xe1t sinh."],c),n,24,a2,p,B.a([B.dT(0,"\uacc4\uc88c\ub97c \uac1c\uc124\ud558\ub2e4 ngh\u0129a l\xe0 m\u1edf t\xe0i kho\u1ea3n ng\xe2n h\xe0ng.",B.a(["\uacc4\uc88c\ub97c \uac1c\uc124\ud569\ub2c8\ub2e4.","\ud0dd\ubc30\ub97c \ubcf4\ub0c5\ub2c8\ub2e4.","\uc9c4\ub8cc\ub97c \ubc1b\uc2b5\ub2c8\ub2e4.","\uc774\uc0ac\ub97c \ud569\ub2c8\ub2e4."],c),"\uc0c8 \ud1b5\uc7a5\uc744 \ub9cc\ub4e4\uae30 \uc704\ud574 \ud558\ub294 \uc77c\uc744 \uace0\ub974\uc2ed\uc2dc\uc624."),B.dT(1,"\uc790\ub3d9\uc774\uccb4 t\u1ef1 \u0111\u1ed9ng chuy\u1ec3n ho\u1eb7c thanh to\xe1n v\xe0o th\u1eddi \u0111i\u1ec3m \u0111\xe3 \u0111\u0103ng k\xfd.",B.a(["\uac70\ub798 \ub0b4\uc5ed","\uc790\ub3d9\uc774\uccb4","\ucd9c\uae08 \ud55c\ub3c4","\ube44\ubc00\ubc88\ud638"],c),"\ub9e4\ub2ec \uac19\uc740 \ub0a0 \uc6d4\uc138\uac00 \uc790\ub3d9\uc73c\ub85c \ub098\uac00\uac8c \ud558\ub294 \uc11c\ube44\uc2a4\ub294 \ubb34\uc5c7\uc785\ub2c8\uae4c?"),B.dT(2,"\ub9cc\ub4e4\ub824\uba74 ngh\u0129a l\xe0 n\u1ebfu mu\u1ed1n m\u1edf ho\u1eb7c t\u1ea1o.",B.a(["\uc9c0\ub9cc","\uc5b4\uc11c","\ub824\uba74","\uac70\ub098"],c),"\ube48\uce78\uc5d0 \uc54c\ub9de\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\uacc4\uc88c\ub97c \ub9cc\ub4e4___ \uc2e0\ubd84\uc99d\uc774 \ud544\uc694\ud574\uc694."),B.dT(3,"Ng\xe2n h\xe0ng kh\xf4ng y\xeau c\u1ea7u cung c\u1ea5p to\xe0n b\u1ed9 m\u1eadt kh\u1ea9u qua \u0111i\u1ec7n tho\u1ea1i.",B.a(["\ubc14\ub85c \uc54c\ub824 \uc90d\ub2c8\ub2e4.","\ubb38\uc790\ub85c \ubcf4\ub0c5\ub2c8\ub2e4.","\uce5c\uad6c\uc5d0\uac8c \ub300\uc2e0 \ub9d0\ud569\ub2c8\ub2e4.","\uc54c\ub824 \uc8fc\uc9c0 \uc54a\uace0 \uc740\ud589\uc5d0 \uc9c1\uc811 \ud655\uc778\ud569\ub2c8\ub2e4."],c),"\uc740\ud589 \uc9c1\uc6d0\uc774\ub77c\uace0 \uc804\ud654\ud55c \uc0ac\ub78c\uc774 \ube44\ubc00\ubc88\ud638\ub97c \ubb3c\uc744 \ub54c \uc5b4\ub5bb\uac8c \ud574\uc57c \ud569\ub2c8\uae4c?"),B.dT(1,"Nh\xe2n vi\xean n\xf3i h\u1ea1n m\u1ee9c c\xf3 th\u1ec3 thay \u0111\u1ed5i n\u1ebfu \u0111\u0103ng k\xfd.",B.a(["\ud55c\ub3c4\ub294 \uc808\ub300 \ubc14\uafc0 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.","\uc2e0\uccad\ud558\uba74 \ud55c\ub3c4\ub97c \ubcc0\uacbd\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uacc4\uc88c\ub97c \uac1c\uc124\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.","\uc1a1\uae08 \uc218\uc218\ub8cc\uac00 \ubc31\ub9cc \uc6d0\uc785\ub2c8\ub2e4."],c),"\ub300\ud654\ub97c \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\uc9c1\uc6d0: \uae30\ubcf8 \uc774\uccb4 \ud55c\ub3c4\ub294 \ubc31\ub9cc \uc6d0\uc774\uc9c0\ub9cc \uc2e0\uccad\ud558\uba74 \ubcc0\uacbd\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.")],a6),"\u0110\xf3ng vai m\u1edf t\xe0i kho\u1ea3n: n\xeau m\u1ee5c \u0111\xedch, h\u1ecfi gi\u1ea5y t\u1edd, Internet Banking, ph\xed v\xe0 h\u1ea1n m\u1ee9c chuy\u1ec3n kho\u1ea3n.",o,q,"Vi\u1ebft 5\u20136 c\xe2u h\u01b0\u1edbng d\u1eabn m\u1ed9t ng\u01b0\u1eddi m\u1edbi m\u1edf t\xe0i kho\u1ea3n v\xe0 s\u1eed d\u1ee5ng chuy\u1ec3n kho\u1ea3n an to\xe0n.")
o=B.a(["Ch\u1ecdn \u0111\u01b0\u1ee3c lo\u1ea1i g\u1eedi th\u01b0\u1eddng, chuy\u1ec3n ph\xe1t nhanh ho\u1eb7c b\u1ea3o \u0111\u1ea3m.","Ghi v\xe0 x\xe1c nh\u1eadn \u0111\u01b0\u1ee3c th\xf4ng tin ng\u01b0\u1eddi g\u1eedi, ng\u01b0\u1eddi nh\u1eadn.","H\u1ecfi \u0111\u01b0\u1ee3c ph\xed, th\u1eddi gian giao v\xe0 c\xe1ch theo d\xf5i b\u01b0u ki\u1ec7n.","X\u1eed l\xfd \u0111\u01b0\u1ee3c t\xecnh hu\u1ed1ng giao ch\u1eadm ho\u1eb7c sai \u0111\u1ecba ch\u1ec9."],c)
p=B.a([B.dp("\uc911\uc694\ud55c \uc11c\ub958\ub97c \ub4f1\uae30\ub85c \ubcf4\ub0c8\uc5b4\uc694.",u.iE,"\ub4f1\uae30","Th\u01b0/b\u01b0u ki\u1ec7n b\u1ea3o \u0111\u1ea3m"),B.dp("\uc0c1\uc790 \uc704\uc5d0 \uc1a1\uc7a5\uc744 \ubd99\uc5ec \uc8fc\uc138\uc694.","H\xe3y d\xe1n phi\u1ebfu v\u1eadn chuy\u1ec3n l\xean th\xf9ng.","\uc1a1\uc7a5","Phi\u1ebfu v\u1eadn chuy\u1ec3n"),B.dp("\uc6b4\uc1a1\uc7a5 \ubc88\ud638\ub85c \ubc30\uc1a1 \uc870\ud68c\ub97c \ud588\uc5b4\uc694.","T\xf4i \u0111\xe3 tra c\u1ee9u b\u1eb1ng m\xe3 v\u1eadn \u0111\u01a1n.","\ubc30\uc1a1 \uc870\ud68c","Tra c\u1ee9u v\u1eadn chuy\u1ec3n"),B.dp("\uae68\uc9c0\uc9c0 \uc54a\ub3c4\ub85d \ud3ec\uc7a5\uc744 \uc798\ud588\uc5b4\uc694.","T\xf4i \u0111\xe3 \u0111\xf3ng g\xf3i k\u1ef9 \u0111\u1ec3 \u0111\u1ed3 kh\xf4ng v\u1ee1.","\ud3ec\uc7a5","Vi\u1ec7c \u0111\xf3ng g\xf3i"),B.dp("\ubb34\uac8c\uc5d0 \ub530\ub77c \ubc30\uc1a1\ube44\uac00 \ub2ec\ub77c\uc838\uc694.","Ph\xed giao h\xe0ng kh\xe1c nhau t\xf9y tr\u1ecdng l\u01b0\u1ee3ng.","\ubb34\uac8c","Tr\u1ecdng l\u01b0\u1ee3ng"),B.dp("\uc18c\ud3ec\uac00 \ub0b4\uc77c \ub3c4\ucc29\ud560 \uc608\uc815\uc774\uc5d0\uc694.","B\u01b0u ki\u1ec7n d\u1ef1 ki\u1ebfn \u0111\u1ebfn v\xe0o ng\xe0y mai.","\ub3c4\ucc29\ud558\ub2e4","\u0110\u1ebfn n\u01a1i")],a)
a2=B.a([B.tF("\uc18c\ud3ec\ub294 \uae08\uc694\uc77c\uc5d0 \ub3c4\ucc29\ud560 \uc608\uc815\uc774\uc5d0\uc694.","D\xf9ng \u0111\u1ec3 n\xf3i k\u1ebf ho\u1ea1ch ho\u1eb7c th\u1eddi \u0111i\u1ec3m d\u1ef1 ki\u1ebfn trong t\u01b0\u01a1ng lai.","D\u1ef1 ki\u1ebfn s\u1ebd V","V-(\uc73c)\u3139 \uc608\uc815\uc774\uc5d0\uc694","B\u01b0u ki\u1ec7n d\u1ef1 ki\u1ebfn s\u1ebd \u0111\u1ebfn v\xe0o th\u1ee9 S\xe1u.")],a1)
n=B.a(["\uc6b4\uc1a1\uc7a5 \ubc88\ud638 = m\xe3 v\u1eadn \u0111\u01a1n","\ubc30\uc1a1 \uc9c0\uc5f0 = giao h\xe0ng ch\u1eadm"],c)
m=B.a([B.dn("\uc774 \uc11c\ub958\ub97c \ubca0\ud2b8\ub0a8\uc73c\ub85c \ubcf4\ub0b4\uace0 \uc2f6\uc5b4\uc694.",i,"T\xf4i mu\u1ed1n g\u1eedi gi\u1ea5y t\u1edd n\xe0y v\u1ec1 Vi\u1ec7t Nam."),B.dn("\uc77c\ubc18 \uc6b0\ud3b8\uacfc \ub4f1\uae30 \uc911\uc5d0\uc11c \uc5b4\ub5a4 \uac83\uc73c\ub85c \ubcf4\ub0b4\uc2e4 \uac70\uc608\uc694?",h,"B\u1ea1n mu\u1ed1n g\u1eedi th\u01b0\u1eddng hay g\u1eedi b\u1ea3o \u0111\u1ea3m?"),B.dn("\uc911\uc694\ud55c \uc11c\ub958\ub77c\uc11c \ub4f1\uae30\ub85c \ubcf4\ub0b4 \uc8fc\uc138\uc694.",i,"V\xec l\xe0 gi\u1ea5y t\u1edd quan tr\u1ecdng n\xean h\xe3y g\u1eedi b\u1ea3o \u0111\u1ea3m."),B.dn("\ubc1b\ub294 \ubd84\uc758 \uc8fc\uc18c\uc640 \uc804\ud654\ubc88\ud638\ub97c \uc5ec\uae30\uc5d0 \uc368 \uc8fc\uc138\uc694.",h,"H\xe3y vi\u1ebft \u0111\u1ecba ch\u1ec9 v\xe0 s\u1ed1 \u0111i\u1ec7n tho\u1ea1i ng\u01b0\u1eddi nh\u1eadn v\xe0o \u0111\xe2y."),B.dn("\ub3c4\ucc29\ud558\ub294 \ub370 \uc5bc\ub9c8\ub098 \uac78\ub824\uc694?",i,"M\u1ea5t bao l\xe2u \u0111\u1ec3 \u0111\u1ebfn n\u01a1i?"),B.dn("\ubcf4\ud1b5 \uc77c\uc8fc\uc77c \uc815\ub3c4 \uac78\ub9ac\uace0 \ubc30\uc1a1 \uc870\ud68c\ub3c4 \uac00\ub2a5\ud569\ub2c8\ub2e4.",h,"Th\xf4ng th\u01b0\u1eddng m\u1ea5t kho\u1ea3ng m\u1ed9t tu\u1ea7n v\xe0 c\xf3 th\u1ec3 tra c\u1ee9u v\u1eadn chuy\u1ec3n.")],a4)
p=B.uU(B.a([u.ng,"\uc8fc\uc18c\ub97c \ubcf4\ub0b4\ub2e4 l\xe0 g\u1eedi \u0111\u1ecba ch\u1ec9; \uc8fc\uc18c\ub85c \ubcf4\ub0b4\ub2e4 l\xe0 g\u1eedi \u0111\u1ebfn \u0111\u1ecba ch\u1ec9 \u0111\xf3.","\uac78\ub9ac\ub2e4 d\xf9ng cho th\u1eddi gian c\u1ea7n thi\u1ebft: \ub3c4\ucc29\ud558\ub294 \ub370 \uc0bc \uc77c\uc774 \uac78\ub824\uc694."],c),m,24,a2,o,B.a([B.dT(1,"\ub4f1\uae30 cho ph\xe9p ghi nh\u1eadn v\xe0 theo d\xf5i qu\xe1 tr\xecnh g\u1eedi gi\u1ea5y t\u1edd quan tr\u1ecdng.",B.a(["\uc77c\ubc18 \uc6b0\ud3b8","\ub4f1\uae30","\ube48 \uc0c1\uc790","\ubc88\ud638\ud45c"],c),"\uc911\uc694\ud55c \uc11c\ub958\ub97c \ubcf4\ub0b8 \uc0ac\uc2e4\uacfc \uc804\ub2ec \uacfc\uc815\uc744 \ud655\uc778\ud558\uace0 \uc2f6\uc744 \ub54c \uc54c\ub9de\uc740 \ubc29\ubc95\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?"),B.dT(2,"\ubc30\uc1a1 \uc870\ud68c ngh\u0129a l\xe0 tra c\u1ee9u tr\u1ea1ng th\xe1i v\xe0 v\u1ecb tr\xed v\u1eadn chuy\u1ec3n.",B.a(["\uc8fc\uc18c \uc791\uc131","\ubc30\uc1a1\ube44 \uacc4\uc0b0","\ubc30\uc1a1 \uc870\ud68c","\uc9d0 \uc815\ub9ac"],c),"\ud0dd\ubc30\uc758 \ud604\uc7ac \uc704\uce58\ub97c \ud655\uc778\ud558\ub294 \ud589\ub3d9\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?"),B.dT(0,"\ub3c4\ucc29\ud560 \uc608\uc815\uc774\uc5d0\uc694 di\u1ec5n \u0111\u1ea1t th\u1eddi \u0111i\u1ec3m d\u1ef1 ki\u1ebfn \u0111\u1ebfn.",B.a(["\uc608\uc815\uc774\uc5d0\uc694","\uc218\uc218\ub8cc\uc608\uc694","\uc8fc\uc18c\uc608\uc694","\ubb34\uac8c\uc608\uc694"],c),"\ube48\uce78\uc5d0 \uc54c\ub9de\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\uc18c\ud3ec\ub294 \ub0b4\uc77c \ub3c4\ucc29\ud560 ___."),B.dT(3,"Ph\xed th\u01b0\u1eddng ph\u1ee5 thu\u1ed9c tr\u1ecdng l\u01b0\u1ee3ng v\xe0 n\u01a1i \u0111\u1ebfn.",B.a(["\ubc1b\ub294 \uc0ac\ub78c\uc758 \ucde8\ubbf8","\uc0c1\uc790\uc758 \uc0c9","\ubcf4\ub0b4\ub294 \uc0ac\ub78c\uc758 \uc9c1\uc5c5","\uc18c\ud3ec\uc758 \ubb34\uac8c\uc640 \ubaa9\uc801\uc9c0"],c),"\ubc30\uc1a1\ube44\ub97c \uacc4\uc0b0\ud560 \ub54c \uc601\ud5a5\uc744 \uc8fc\ub294 \uc815\ubcf4\ub85c \uac00\uc7a5 \uc54c\ub9de\uc740 \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?"),B.dT(1,"C\xf3 th\u1ec3 d\xf9ng m\xe3 v\u1eadn \u0111\u01a1n \u0111\u1ec3 ki\u1ec3m tra t\xecnh tr\u1ea1ng giao h\xe0ng.",B.a(["\uc624\ub298 \ubc14\ub85c \ub3c4\ucc29\ud569\ub2c8\ub2e4.","\ubc30\uc1a1 \uc0c1\ud669\uc744 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc8fc\uc18c\uac00 \ud544\uc694 \uc5c6\uc2b5\ub2c8\ub2e4.","\ud574\uc678\ub85c \ubcf4\ub0bc \uc218 \uc5c6\uc2b5\ub2c8\ub2e4."],c),"\ub300\ud654\ub97c \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\uc9c1\uc6d0: \uc77c\uc8fc\uc77c \uc815\ub3c4 \uac78\ub9ac\uace0 \uc6b4\uc1a1\uc7a5 \ubc88\ud638\ub85c \uc704\uce58\ub97c \ud655\uc778\ud560 \uc218 \uc788\uc5b4\uc694.")],a6),"\u0110\xf3ng vai g\u1eedi b\u01b0u ki\u1ec7n: n\xf3i v\u1eadt c\u1ea7n g\u1eedi, n\u01a1i nh\u1eadn, lo\u1ea1i d\u1ecbch v\u1ee5 r\u1ed3i h\u1ecfi ph\xed v\xe0 th\u1eddi gian giao.",n,p,"Vi\u1ebft 5 c\xe2u h\u01b0\u1edbng d\u1eabn \u0111\xf3ng g\xf3i v\xe0 ghi th\xf4ng tin ng\u01b0\u1eddi nh\u1eadn tr\u01b0\u1edbc khi g\u1eedi m\u1ed9t b\u01b0u ki\u1ec7n qu\u1ed1c t\u1ebf.")
n=B.a(["X\xe1c \u0111\u1ecbnh \u0111\u01b0\u1ee3c lo\u1ea1i gi\u1ea5y t\u1edd c\u1ea7n xin t\u1ea1i trung t\xe2m h\xe0nh ch\xednh.","H\u1ecfi \u0111\u01b0\u1ee3c h\u1ed3 s\u01a1, l\u1ec7 ph\xed v\xe0 th\u1eddi gian x\u1eed l\xfd.","\u0110i\u1ec1n v\xe0 n\u1ed9p \u0111\u01b0\u1ee3c m\u1ed9t m\u1eabu \u0111\u01a1n c\u01a1 b\u1ea3n.","Hi\u1ec3u \u0111\u01b0\u1ee3c h\u01b0\u1edbng d\u1eabn \u0111\u1eb7t l\u1ecbch ho\u1eb7c nh\u1eadn k\u1ebft qu\u1ea3."],c)
o=B.a([B.dp("\ud68c\uc0ac\uc5d0\uc11c \uc8fc\ubbfc\ub4f1\ub85d\ub4f1\ubcf8\uc744 \uc81c\ucd9c\ud558\ub77c\uace0 \ud588\uc5b4\uc694.","C\xf4ng ty y\xeau c\u1ea7u t\xf4i n\u1ed9p b\u1ea3n sao \u0111\u0103ng k\xfd c\u01b0 tr\xfa.","\uc8fc\ubbfc\ub4f1\ub85d\ub4f1\ubcf8","B\u1ea3n sao \u0111\u0103ng k\xfd c\u01b0 tr\xfa"),B.dp("\uc678\uad6d\uc778\ub4f1\ub85d\uc99d\uc744 \uaf2d \uac00\uc838\uc624\uc138\uc694.","Nh\u1ea5t \u0111\u1ecbnh h\xe3y mang theo th\u1ebb \u0111\u0103ng k\xfd ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i.","\uc678\uad6d\uc778\ub4f1\ub85d\uc99d","Th\u1ebb \u0111\u0103ng k\xfd ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i"),B.dp("\uc99d\uba85\uc11c \ubc1c\uae09 \uc218\uc218\ub8cc\ub294 \ucc9c \uc6d0\uc774\uc5d0\uc694.","L\u1ec7 ph\xed c\u1ea5p gi\u1ea5y ch\u1ee9ng nh\u1eadn l\xe0 1.000 won.","\uc218\uc218\ub8cc","L\u1ec7 ph\xed"),B.dp("\uc2e0\uccad\uc11c\ub97c \uba3c\uc800 \uc791\uc131\ud574 \uc8fc\uc138\uc694.","Tr\u01b0\u1edbc ti\xean h\xe3y \u0111i\u1ec1n \u0111\u01a1n \u0111\u0103ng k\xfd.","\uc791\uc131\ud558\ub2e4","\u0110i\u1ec1n, so\u1ea1n"),B.dp("\ucc98\ub9ac \uae30\uac04\uc740 \ubcf4\ud1b5 \uc0bc \uc77c\uc785\ub2c8\ub2e4.","Th\u1eddi gian x\u1eed l\xfd th\u01b0\u1eddng l\xe0 ba ng\xe0y.","\ucc98\ub9ac \uae30\uac04","Th\u1eddi gian x\u1eed l\xfd"),B.dp("\ubc29\ubb38\ud558\uae30 \uc804\uc5d0 \uc628\ub77c\uc778\uc73c\ub85c \uc608\uc57d\ud588\uc5b4\uc694.","T\xf4i \u0111\xe3 \u0111\u1eb7t l\u1ecbch tr\u1ef1c tuy\u1ebfn tr\u01b0\u1edbc khi \u0111\u1ebfn.","\uc608\uc57d",g)],a)
