l=B.a([B.dn("\uc774\uc0ac\ud574\uc11c \uc8fc\uc18c\ub97c \ubcc0\uacbd\ud558\ub824\uace0 \uc654\uc5b4\uc694.",i,"T\xf4i chuy\u1ec3n nh\xe0 n\xean \u0111\u1ebfn \u0111\u1ec3 thay \u0111\u1ed5i \u0111\u1ecba ch\u1ec9."),B.dn("\uc678\uad6d\uc778\ub4f1\ub85d\uc99d\uacfc \uc9d1 \uacc4\uc57d\uc11c\ub97c \uac00\uc838\uc624\uc168\uc5b4\uc694?",h,"B\u1ea1n c\xf3 mang th\u1ebb \u0111\u0103ng k\xfd ng\u01b0\u1eddi n\u01b0\u1edbc ngo\xe0i v\xe0 h\u1ee3p \u0111\u1ed3ng nh\xe0 kh\xf4ng?"),B.dn("\uc678\uad6d\uc778\ub4f1\ub85d\uc99d\uc740 \uc788\ub294\ub370 \uacc4\uc57d\uc11c\ub97c \uc548 \uac00\uc838\uc654\uc5b4\uc694.",i,"T\xf4i c\xf3 th\u1ebb \u0111\u0103ng k\xfd nh\u01b0ng kh\xf4ng mang h\u1ee3p \u0111\u1ed3ng."),B.dn("\uc8fc\uc18c\ub97c \ubcc0\uacbd\ud558\ub824\uba74 \ub450 \uc11c\ub958\uac00 \ubaa8\ub450 \ud544\uc694\ud569\ub2c8\ub2e4.",h,"N\u1ebfu mu\u1ed1n \u0111\u1ed5i \u0111\u1ecba ch\u1ec9 th\xec c\u1ea7n c\u1ea3 hai gi\u1ea5y t\u1edd."),B.dn("\uc628\ub77c\uc778\uc73c\ub85c\ub3c4 \uc2e0\uccad\ud560 \uc218 \uc788\uc5b4\uc694?",i,"T\xf4i c\xf3 th\u1ec3 \u0111\u0103ng k\xfd tr\u1ef1c tuy\u1ebfn kh\xf4ng?"),B.dn("\ub124, \uc815\ubd80 \uc0ac\uc774\ud2b8\uc5d0\uc11c \ubcf8\uc778 \uc778\uc99d \ud6c4 \uc2e0\uccad\ud560 \uc218 \uc788\uc5b4\uc694.",h,"C\xf3, b\u1ea1n c\xf3 th\u1ec3 \u0111\u0103ng k\xfd tr\xean trang ch\xednh ph\u1ee7 sau khi x\xe1c minh danh t\xednh.")],a4)
o=B.uU(B.a(["\uc2e0\uccad\ud558\ub2e4 l\xe0 n\u1ed9p y\xeau c\u1ea7u; \ubc1c\uae09\ubc1b\ub2e4 l\xe0 \u0111\u01b0\u1ee3c c\u01a1 quan c\u1ea5p gi\u1ea5y t\u1edd.","\uc11c\ub958\ub97c \uc4f0\ub2e4 c\xf3 th\u1ec3 hi\u1ec3u nh\u01b0ng \uc2e0\uccad\uc11c\ub97c \uc791\uc131\ud558\ub2e4 trang tr\u1ecdng v\xe0 t\u1ef1 nhi\xean h\u01a1n.","V-(\uc73c)\ub7ec \uac00\ub2e4 n\xf3i m\u1ee5c \u0111\xedch di chuy\u1ec3n; V-(\uc73c)\ub824\uba74 n\xf3i \u0111i\u1ec1u ki\u1ec7n \u0111\u1ec3 th\u1ef1c hi\u1ec7n."],c),l,25,a2,n,B.a([B.dT(0,"\uc791\uc131\ud558\ub2e4 l\xe0 \u0111i\u1ec1n ho\u1eb7c so\u1ea1n n\u1ed9i dung v\xe0o gi\u1ea5y t\u1edd.",B.a(["\uc791\uc131\ud558\ub2e4","\ucd9c\uae08\ud558\ub2e4","\ud3ec\uc7a5\ud558\ub2e4","\ud658\uc2b9\ud558\ub2e4"],c),"\uc2e0\uccad\uc11c\uc758 \ube48\uce78\uc5d0 \uc815\ubcf4\ub97c \uc801\ub294 \ud589\ub3d9\uc744 \uace0\ub974\uc2ed\uc2dc\uc624."),B.dT(1,"\uc218\uc218\ub8cc l\xe0 l\u1ec7 ph\xed tr\u1ea3 cho vi\u1ec7c x\u1eed l\xfd ho\u1eb7c c\u1ea5p gi\u1ea5y t\u1edd.",B.a(["\ubcf4\uc99d\uae08","\uc218\uc218\ub8cc","\uc6d4\uc138","\ubc30\uc1a1\ube44"],c),"\uc99d\uba85\uc11c\ub97c \ubc1c\uae09\ubc1b\uae30 \uc704\ud574 \ub0b4\ub294 \ub3c8\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?"),B.dT(2,"\ubcc0\uacbd\ud558\ub824\uba74 ngh\u0129a l\xe0 n\u1ebfu mu\u1ed1n thay \u0111\u1ed5i.",B.a(["\uc9c0\ub9cc","\uac70\ub098","\ub824\uba74","\ub294\ub370"],c),"\ube48\uce78\uc5d0 \uc54c\ub9de\uc740 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\uc8fc\uc18c\ub97c \ubcc0\uacbd\ud558___ \uacc4\uc57d\uc11c\uac00 \ud544\uc694\ud574\uc694."),B.dT(3,"B\u1ed9 phim y\xeau th\xedch kh\xf4ng li\xean quan \u0111\u1ebfn th\u1ee7 t\u1ee5c h\xe0nh ch\xednh.",B.a(["\uad6c\ube44 \uc11c\ub958","\uc6b4\uc601 \uc2dc\uac04","\uc608\uc57d \ud544\uc694 \uc5ec\ubd80","\uc88b\uc544\ud558\ub294 \uc601\ud654"],c),"\uc8fc\ubbfc\uc13c\ud130\ub97c \ubc29\ubb38\ud558\uae30 \uc804\uc5d0 \ud655\uc778\ud560 \ub0b4\uc6a9\uc774 \uc544\ub2cc \uac83\uc740 \ubb34\uc5c7\uc785\ub2c8\uae4c?"),B.dT(0,"Nh\xe2n vi\xean n\xf3i c\u1ea7n mang c\u1ea3 hai gi\u1ea5y t\u1edd.",B.a(["\ub450 \uc11c\ub958\uac00 \ubaa8\ub450 \ud544\uc694\ud569\ub2c8\ub2e4.","\uacc4\uc57d\uc11c\ub294 \ud544\uc694 \uc5c6\uc2b5\ub2c8\ub2e4.","\uc5ec\uad8c\ub9cc \uc788\uc73c\uba74 \ub429\ub2c8\ub2e4.","\uc2e0\uccad\ud560 \uc218 \uc5c6\ub294 \uc5c5\ubb34\uc785\ub2c8\ub2e4."],c),"\ub300\ud654\ub97c \uc77d\uace0 \ub9de\ub294 \uac83\uc744 \uace0\ub974\uc2ed\uc2dc\uc624.\n\n\uc9c1\uc6d0: \uc678\uad6d\uc778\ub4f1\ub85d\uc99d\uacfc \uacc4\uc57d\uc11c\ub97c \ubaa8\ub450 \uac00\uc838\uc624\uc154\uc57c \ud569\ub2c8\ub2e4.")],a6),"\u0110\xf3ng vai l\xe0m th\u1ee7 t\u1ee5c \u0111\u1ed5i \u0111\u1ecba ch\u1ec9: n\xf3i m\u1ee5c \u0111\xedch r\u1ed3i h\u1ecfi h\u1ed3 s\u01a1, l\u1ec7 ph\xed, th\u1eddi gian x\u1eed l\xfd v\xe0 c\xe1ch nh\u1eadn k\u1ebft qu\u1ea3.",m,o,"L\u1eadp danh s\xe1ch 5\u20136 b\u01b0\u1edbc chu\u1ea9n b\u1ecb cho m\u1ed9t th\u1ee7 t\u1ee5c t\u1ea1i \uc8fc\ubbfc\uc13c\ud130, t\u1eeb \u0111\u1eb7t l\u1ecbch \u0111\u1ebfn nh\u1eadn gi\u1ea5y t\u1edd.")
m=B.a(["Hi\u1ec3u v\xe0 x\xe1c nh\u1eadn \u0111\u01b0\u1ee3c ch\u1ec9 th\u1ecb c\xf4ng vi\u1ec7c c\u01a1 b\u1ea3n.","N\xf3i \u0111\u01b0\u1ee3c nhi\u1ec7m v\u1ee5 m\xecnh ph\u1ee5 tr\xe1ch c\xf9ng th\u1eddi h\u1ea1n ho\xe0n th\xe0nh.","B\xe1o c\xe1o \u0111\u01b0\u1ee3c ti\u1ebfn \u0111\u1ed9, v\u1ea5n \u0111\u1ec1 v\xe0 n\u1ed9i dung c\u1ea7n s\u1eeda.","Ph\u1ed1i h\u1ee3p \u0111\u01b0\u1ee3c v\u1edbi \u0111\u1ed3ng nghi\u1ec7p khi th\u1ef1c hi\u1ec7n nhi\u1ec7m v\u1ee5 chung."],c)
